// v10.6: apply accessibility settings live
function applyAccessibilitySettings() {
    const fs = localStorage.getItem('a11y_font_size');
    if (fs) document.body.style.fontSize = fs + 'px';
    const hc = localStorage.getItem('a11y_high_contrast') === '1';
    document.body.classList.toggle('a11y-high-contrast', hc);
    const rm = localStorage.getItem('a11y_reduce_motion') === '1';
    document.body.classList.toggle('a11y-reduce-motion', rm);
    const dy = localStorage.getItem('a11y_dyslexic_font') === '1';
    document.body.classList.toggle('a11y-dyslexic-font', dy);
    const compact = localStorage.getItem('ui_compact') === '1';
    document.body.classList.toggle('ui-compact', compact);
}

// v10.6: data export / import
function exportSettings() {
    const dump = {};
    const keys = ['user_history','user_inventory','user_loadout','user_credits','recent_activities',
        'ai_response_length','ai_tone','ai_temperature','ai_model','math_notation',
        'notify_toasts','notify_quests','notify_achievements','study_reminder_time',
        'a11y_font_size','a11y_high_contrast','a11y_reduce_motion','a11y_dyslexic_font',
        'companion_autospawn','companion_hide_typing','companion_walk_speed','companion_emote_freq','companion_sprite_size',
        'wallpaper_auto_rotate','ui_compact','shortcuts_enabled','default_subject','daily_goal',
        'leaderboard_optin','streak_protection','store_history','store_images','share_anon_stats',
        'difficulty_mode','typing_assist','history_limit','quest_state','total_xp','vocabulary_words',
        'auth_user'];
    keys.forEach(k => { const v = localStorage.getItem(k); if (v !== null) dump[k] = v; });
    const blob = new Blob([JSON.stringify(dump, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url; a.download = 'nexus-backup-' + new Date().toISOString().slice(0,10) + '.json';
    a.click();
    URL.revokeObjectURL(url);
    showToast('Settings exported.', 'success');
}

function importSettings(event) {
    const file = event.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (e) => {
        try {
            const data = JSON.parse(e.target.result);
            if (typeof data !== 'object' || !data) throw new Error('Invalid file');
            showConfirm('Import Settings', 'This will overwrite your current settings, history, and inventory. Continue?', () => {
                Object.entries(data).forEach(([k, v]) => localStorage.setItem(k, v));
                showToast('Imported. Reloading…', 'success', 2000);
                setTimeout(() => location.reload(), 1500);
            });
        } catch (err) {
            showToast('Import failed: ' + err.message, 'error');
        }
    };
    reader.readAsText(file);
}

// v10.6: enable browser study reminder
function enableStudyReminder() {
    if (!('Notification' in window)) { showToast('Notifications not supported in this browser.', 'error'); return; }
    Notification.requestPermission().then(perm => {
        if (perm === 'granted') showToast('Notifications enabled. Set a time and Save Settings.', 'success');
        else showToast('Notification permission denied.', 'info');
    });
}

// ============================================
// DIFFICULTY MODE SYSTEM (v8.0)
// ============================================
function getDifficultyMode() {
    // v10.5: Access tier locked to Tutor Mode (step-by-step). Pro can pick Casual or Tutor.
    if (!hasPro()) return 'tutor';
    let mode = localStorage.getItem('difficulty_mode') || 'casual';
    // Migrate legacy "hard" mode to "tutor"
    if (mode === 'hard') { mode = 'tutor'; localStorage.setItem('difficulty_mode', 'tutor'); }
    return mode;
}

function updateModePreview() {
    const labels = ['casual', 'tutor', 'hard'];
    const colors = { casual: '#00cec9', tutor: '#a855f7', hard: '#e84118' };
    labels.forEach(m => {
        const label = document.getElementById('mode-' + m + '-label');
        const radio = document.getElementById('mode-' + m);
        if (label && radio) {
            label.style.borderColor = radio.checked ? colors[m] : 'transparent';
        }
    });
}

// ── v234 · D-1 — MODE POLICY REGISTRY ────────────────────────────────────
// Casual/Tutor is a TEACHING preference — "show me the answer" vs "walk me
// through it". It is not a "refuse to write my essay" preference. Before v234
// each feature decided by hand whether to append getModeSystemPrompt(), at
// eight separate call sites, and two of them were wrong: the English Generator
// and all seven English Aid tools were being told, in Tutor mode, "Do NOT solve
// it — reply with a concept blurb and a guiding question." So "write my essay"
// answered with a question, and "fix my grammar" was told not to give the fix.
//
//   'full' — this tool teaches; the mode block applies.
//   'none' — this tool performs a job; mode is irrelevant to the deliverable.
//
// Adding a tool here is deliberate. modePromptFor() warns loudly on an unknown
// tool rather than silently guessing, so the bug class can't come back quietly.
const TOOL_MODE_POLICY = {
    math: 'full', science: 'full', social: 'full', liveVision: 'full', tutorChat: 'full',
    englishGenerator: 'none', englishAid: 'none', promptGen: 'none',
    quiz: 'none', practiceTest: 'none', flashcards: 'none', conceptMap: 'none',
    notebookGrammar: 'none', debate: 'none', historyTimeline: 'none', dictionary: 'none'
};

function modePromptFor(tool, subject, requestText) {
    const policy = TOOL_MODE_POLICY[tool];
    if (policy === undefined) {
        console.warn('[NEXUS] No TOOL_MODE_POLICY entry for "' + tool + '" — defaulting to none. Add it to the registry.');
        return '';
    }
    if (policy === 'none') return '';
    return getModeSystemPrompt(subject, requestText);
}

// ── v234 · D-2 — an explicit length spec outranks the brevity clause ──────
// Casual mode used to end every prompt with "1-3 sentences max… keep total
// response short and punchy" — the LAST line the model reads, so it wins.
// That silently truncated anything with a real length requirement: a "write a
// 100 word message" request came back at 78 words, and Region Explorer's five
// ~90-word sections were being squeezed into a couple of sentences. When the
// request states a length, brevity yields; the casual TONE stays.
function _hasExplicitLengthSpec(text) {
    if (!text) return false;
    const t = String(text);
    return /\b\d{2,4}\s*[-–—]?\s*words?\b/i.test(t)
        || /\b\d+\s*[-–—]?\s*(paragraphs?|sentences?|pages?|bullet points?)\b/i.test(t)
        || /~\s*\d+\s*words?/i.test(t)
        || /<h3>/i.test(t);
}

function getModeSystemPrompt(subject, requestText) {
    const mode = getDifficultyMode();
    if (mode === 'tutor') {
        const subjLower = (subject || '').toLowerCase();

        // v12.0 — SOCIAL STUDIES: drops Socratic mode (these are factual questions).
        // Structured 4-block answer with timeline + cause/effect reasoning baked in.
        if (subjLower.includes('social')) {
            return `

═══════════════════════════════════════════════════════════════
[TUTOR MODE — SOCIAL STUDIES · structured 4-block answer]
═══════════════════════════════════════════════════════════════
ROLE: You are a sharp social studies / history tutor. For factual questions, structure the response as FOUR labeled cards in this exact order:

1. <div class="tutor-block tutor-block-facts">
     <h3>📌 Key facts</h3>
     <ul> 3 to 5 short bullet points — names, dates, places, terms. No fluff. </ul>
   </div>

2. <div class="tutor-block tutor-block-timeline">
     <h3>📅 Timeline</h3>
     <ol> Dated events in chronological order. Format each line as <strong>YEAR</strong> · short event description. 3–6 entries max. </ol>
   </div>

3. <div class="tutor-block tutor-block-causeeffect">
     <h3>🔁 Cause → Effect</h3>
     <p> 2–4 sentences explaining the WHY. Use the form: "Because [cause], [effect happened]. This led to [next consequence]." Make the chain feel inevitable, not memorized. </p>
   </div>

4. <div class="tutor-block tutor-block-answer">
     <h3>✅ Final answer</h3>
     <p> The direct answer to the student's question in 1–3 sentences. State it plainly and confidently. </p>
   </div>

ABSOLUTE RULES:
- All FOUR sections must be present, in that order, even for short questions (compress, don't skip).
- Use the exact <div class="tutor-block tutor-block-X"> wrappers shown — the front-end styles them as colored cards.
- If the question is about an interpretation rather than a fact (e.g. "Was X justified?"), the "Final answer" section gives YOUR reasoned position, then notes the strongest counter-argument in one sentence.
- Stay neutral and source-anchored. If you're not certain about a specific date, say "circa" rather than guess.
- Never markdown. Never asterisks. Clean HTML only.`;
        }

        // v12.0 — MATH: polished visual structure with formula card, strategy line,
        // and a single guiding question. Strictly Socratic — never solves the problem.
        if (subjLower.includes('math')) {
            return `

═══════════════════════════════════════════════════════════════
[TUTOR MODE — MATH · concept · strategy · your turn]
═══════════════════════════════════════════════════════════════
ROLE: You are an elite math tutor who teaches by guiding, never by handing over answers. Build the answer as THREE clearly-styled blocks:

1. <div class="tutor-block tutor-block-concept">
     <h3>💡 The concept</h3>
     <p> Name the concept by its proper term and explain it in 2–3 sentences with ONE concrete hook (analogy, real-world frame, or worked example with DIFFERENT numbers). Make it sound like a tutor who finds this interesting, not a textbook. </p>
     <div class="tutor-formula"> <code>The relevant formula, identity, or rule as a single highlighted line.</code> </div>
   </div>

2. <div class="tutor-block tutor-block-strategy">
     <h3>🧭 Strategy for this problem</h3>
     <p> 1–2 sentences outlining the SHAPE of the solution — what to isolate, what to factor, what to substitute — without doing any arithmetic from their problem. Think "the move is to..." not "the answer is...". </p>
   </div>

3. <div class="tutor-block tutor-block-question">
     <h3>🎯 Your turn — first step</h3>
     <p> Exactly ONE precise, answerable guiding question that asks the student to take the FIRST move themselves. Examples: "Subtract 5 from both sides — what do you get on each side?" / "Which differentiation rule fits f(x) = x²sin(x) — product, quotient, or chain?" </p>
   </div>

ABSOLUTE RULES:
- Do NOT reveal the final answer. Do NOT walk through every step. Do NOT solve it.
- The worked example in section 1, if used, must use DIFFERENT numbers — never the student's actual problem.
- The formula in <div class="tutor-formula"> must be a single line of <code>. Write fractions as a/b. Never raw \\[ \\] or \\frac{}.
- On the student's next turn, confirm or correct ONE step, then pose the next guiding question. One step at a time.
- If asked "just give me the answer" — decline politely, mention Casual Mode in Settings.
- Never markdown. Never asterisks. Clean HTML only. End on the guiding question. STOP.`;
        }

        // v12.0 — SCIENCE: parallel polished structure with a "key terms" mini-card.
        if (subjLower.includes('science')) {
            return `

═══════════════════════════════════════════════════════════════
[TUTOR MODE — SCIENCE · concept · key terms · your turn]
═══════════════════════════════════════════════════════════════
ROLE: You are a sharp science tutor (biology, chemistry, physics — match the question). Teach by guiding. Build the answer as THREE clearly-styled blocks:

1. <div class="tutor-block tutor-block-concept">
     <h3>⚗️ The concept</h3>
     <p> Name the principle by its proper term (e.g., "Le Chatelier's principle", "Newton's second law", "photosynthesis light reactions"). Explain in 2–3 sentences with ONE concrete hook — analogy, everyday example, or quick worked case with DIFFERENT numbers. </p>
     <div class="tutor-formula"> <code>The relevant equation, law statement, or balanced reaction template if applicable.</code> </div>
   </div>

2. <div class="tutor-block tutor-block-terms">
     <h3>🔑 Key terms in play</h3>
     <ul> 2–4 short bullets, each: <strong>term</strong> — one-line plain-English definition. These are the terms the student must know to answer the question. </ul>
   </div>

3. <div class="tutor-block tutor-block-question">
     <h3>🎯 Your turn — first step</h3>
     <p> Exactly ONE precise, answerable guiding question that asks the student to take the FIRST move. Examples: "Count the atoms of oxygen on the reactant side of this equation — how many are there?" / "Which form of energy is the cart gaining as it rolls downhill?" </p>
   </div>

ABSOLUTE RULES:
- Do NOT reveal the final answer. Do NOT walk through every step. Do NOT solve it.
- The example in section 1, if used, must use DIFFERENT specifics — never the student's actual problem.
- Equations: write H2O (no subscripts), use ->  for reaction arrows, write balanced coefficients explicitly. Never raw \\[ \\].
- On the student's next turn, confirm or correct ONE step, then pose the next guiding question.
- If asked "just give me the answer" — decline politely, mention Casual Mode in Settings.
- SAFETY: refuse procedural detail on dangerous syntheses. Redirect to the underlying principle.
- Never markdown. Never asterisks. Clean HTML only. End on the guiding question. STOP.`;
        }

        // v12.0 — ENGLISH / default: the previous polished 2-section format.
        return `

═══════════════════════════════════════════════════════════════
[TUTOR MODE — ${subject || 'GENERAL'} · concept · your turn]
═══════════════════════════════════════════════════════════════
ROLE: You are a great ${subject} tutor. The kind who makes hard things click, not the kind who lectures. You do NOT solve the problem outright — you teach the student to solve it themselves through a single guided step.

REQUIRED RESPONSE — exactly TWO sections wrapped in styled blocks, in this order:

1. <div class="tutor-block tutor-block-concept">
     <h3>💡 The concept behind this</h3>
     <p> Explain the underlying idea in 2–4 sentences. Name the concept by its proper term. Use ONE concrete hook — analogy, real-world example, or worked example with DIFFERENT specifics. Vary your opener each time. </p>
   </div>

2. <div class="tutor-block tutor-block-question">
     <h3>🎯 Your turn — first step</h3>
     <p> Exactly ONE precise, answerable guiding question. The question should ask the student to take the very FIRST move themselves. End on the question. STOP. </p>
   </div>

ABSOLUTE RULES:
- Do NOT reveal the final answer. Do NOT walk through every step. Do NOT solve it.
- The worked example, if used, must be a DIFFERENT problem from theirs.
- On the student's next turn, confirm or correct ONE step, then pose the next guiding question.
- If asked "just give me the answer" — decline politely, mention Casual Mode in Settings.
- Clean HTML only. Allowed: <div class="tutor-block ...">, <h3>, <p>, <strong>, <em>, <code>, <ul>, <li>.
- Never markdown. Never asterisks for emphasis.`;
    }
    // Casual mode — instant direct answer, minimal explanation
    if (mode === 'casual') {
        // v234 — when the request carries a real length spec (a word count, a
        // paragraph count, an <h3> section layout), drop the brevity rules and
        // keep only the "lead with the answer" posture. Otherwise the length
        // spec loses to whichever instruction lands last, which is this one.
        if (_hasExplicitLengthSpec(requestText)) {
            return `

═══════════════════════════════════════════════════════════════
[CASUAL MODE — INSTANT ANSWER · explicit length requested]
═══════════════════════════════════════════════════════════════
- Lead with the answer. No preamble, no throat-clearing.
- Skip the hand-holding — don't narrate every step unless asked.
- THE REQUESTED LENGTH IS A HARD REQUIREMENT. The request specifies a word
  count, paragraph count, or section layout: deliver it in full and at that
  length. Do NOT shorten, compress, or summarise to be "punchy". Brevity does
  NOT override a stated length.`;
        }
        return `

═══════════════════════════════════════════════════════════════
[CASUAL MODE — INSTANT ANSWER]
═══════════════════════════════════════════════════════════════
- Lead with the answer in the first 1-2 sentences.
- Give the bare minimum supporting reasoning (1-3 sentences max).
- DO NOT walk through every step. Skip the hand-holding.
- Aim for fast, clean, direct answers — like a quick reference.
- For numerical problems, show the answer, the formula used, and the substitution. That's it.
- For essay prompts, give the answer / thesis / conclusion directly.
- Keep total response short and punchy.`;
    }
    return '';
}

