// ── DEEP DIVE — expand the most recent AI answer into a full conceptual explanation ──
async function triggerDeepDive() {
    const target = document.getElementById('deep-dive-content');
    const btn = document.getElementById('deep-dive-btn');
    const answerEl = document.getElementById('ai-answer-text');
    const explainEl = document.getElementById('ai-explanation-text');
    if (!target) return;

    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add your API key in Settings to use Deep Dive.', 'error'); return; }

    const answer = (answerEl && answerEl.innerText) || '';
    const shortExplain = (explainEl && explainEl.innerText) || '';
    const topic = currentTopic || 'general';
    if (!answer.trim() || answer.trim() === '...') {
        showToast('Solve a problem first, then Deep Dive can expand on it.', 'info');
        return;
    }

    target.classList.remove('hidden');
    target.innerHTML = '<i class="ph ph-spinner ph-spin" style="color:var(--accent);"></i> Going deeper into the concept...';
    if (btn) btn.disabled = true;

    try {
        const sys = `You are a NEXUS tutor giving a "Deep Dive" expansion on a problem the student just solved. They already have the short answer. Your job: explain the underlying concept in depth (3–5 short paragraphs), connect to prerequisite knowledge, point out one common mistake, and end with a related question they could try next. Use clean HTML only — <p>, <strong>, <em>, <ul>, <li>, <code>. Never markdown. Never asterisks for emphasis.`;
        const usr = `TOPIC: ${topic}\n\nSHORT ANSWER ALREADY GIVEN:\n${answer}\n\nSHORT EXPLANATION ALREADY GIVEN:\n${shortExplain}\n\nNow give the Deep Dive.`;

        // v10.7 — STREAM the Deep Dive
        target.innerHTML = '<span class="streaming-content"></span><span class="streaming-cursor">▍</span>';
        const contentEl = target.querySelector('.streaming-content');
        const cursorEl = target.querySelector('.streaming-cursor');
        await streamChat({
            apiKey,
            model: localStorage.getItem('ai_model') || 'gpt-4o',
            messages: [{ role: 'system', content: sys }, { role: 'user', content: usr }],
            temperature: 0.5,
            onChunk: (delta, full) => { contentEl.textContent = stripHtmlForStream(full); },
            onDone: (full) => {
                if (cursorEl) cursorEl.remove();
                let html = (full || '').trim();
                if (typeof convertMarkdownLeaks === 'function') html = convertMarkdownLeaks(html);
                target.innerHTML = (typeof sanitizeHTML === 'function') ? sanitizeHTML(html) : html;
            },
            onError: (err) => { target.innerHTML = `<span style="color:#ff6b6b;">Deep Dive failed: ${err.message}</span>`; }
        });
    } catch (err) {
        target.innerHTML = `<span style="color:#ff6b6b;">Deep Dive failed: ${err.message}</span>`;
    } finally {
        if (btn) btn.disabled = false;
    }
}

// ── RULER — v10.6 REBUILD ──────────────────────────────────────────────
// Real measuring ruler: tick marks + numbered units (px / cm / mm / in),
// drag to move, resize from the right handle, rotate to vertical, unit dropdown.
// Calibration: ~96 CSS pixels per inch (the CSS standard).
const RULER_PX_PER_INCH = 96;
const RULER_PX_PER_CM = RULER_PX_PER_INCH / 2.54;
const RULER_PX_PER_MM = RULER_PX_PER_CM / 10;

function toggleRuler() {
    const ruler = document.getElementById('screen-ruler');
    if (!ruler) { showToast('Ruler element not found.', 'error'); return; }
    const isHidden = ruler.classList.contains('hidden') || ruler.style.display === 'none';
    if (isHidden) {
        ruler.classList.remove('hidden');
        ruler.style.display = 'block';
        attachRulerInteractions(ruler);
        renderRulerCanvas();
        showToast('Ruler shown. Pick a unit above. Drag the body to move, the right handle to resize.', 'info', 3000);
    } else {
        ruler.classList.add('hidden');
        ruler.style.display = 'none';
    }
}

function rotateRuler() {
    const ruler = document.getElementById('screen-ruler');
    if (!ruler) return;
    ruler.classList.toggle('rotated');
}

function renderRulerCanvas() {
    const ruler = document.getElementById('screen-ruler');
    const canvas = document.getElementById('ruler-canvas');
    const unitSel = document.getElementById('ruler-unit');
    if (!ruler || !canvas || !unitSel) return;

    const cssW = parseFloat(getComputedStyle(ruler).width);
    const cssH = parseFloat(getComputedStyle(ruler).height);
    const dpr = window.devicePixelRatio || 1;
    canvas.width = Math.max(1, Math.round(cssW * dpr));
    canvas.height = Math.max(1, Math.round(cssH * dpr));
    canvas.style.width = cssW + 'px';
    canvas.style.height = cssH + 'px';

    const ctx = canvas.getContext('2d');
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.clearRect(0, 0, cssW, cssH);

    const unit = unitSel.value;
    const ppu = unit === 'px' ? 1 : (unit === 'cm' ? RULER_PX_PER_CM : (unit === 'mm' ? RULER_PX_PER_MM : RULER_PX_PER_INCH));

    // Tick spacing in px between MAJOR ticks
    let majorEveryUnits, minorPerMajor, labelEveryMajor;
    if (unit === 'px')      { majorEveryUnits = 50; minorPerMajor = 5;  labelEveryMajor = 1; }
    else if (unit === 'mm') { majorEveryUnits = 10; minorPerMajor = 10; labelEveryMajor = 1; }   // every 10 mm = 1 cm major
    else if (unit === 'cm') { majorEveryUnits = 1;  minorPerMajor = 10; labelEveryMajor = 1; }   // major every 1 cm, minor mm
    else                    { majorEveryUnits = 1;  minorPerMajor = 16; labelEveryMajor = 1; }   // inches with 16ths

    const majorPxStep = majorEveryUnits * ppu;
    const minorPxStep = majorPxStep / minorPerMajor;

    // Body fill
    ctx.fillStyle = 'rgba(245,240,220,0.0)'; // CSS already paints; clear was enough
    ctx.fillRect(0, 0, cssW, cssH);

    // Top edge dark bar
    ctx.fillStyle = 'rgba(120,100,60,0.4)';
    ctx.fillRect(0, 0, cssW, 2);

    ctx.font = '10px Inter, system-ui, sans-serif';
    ctx.fillStyle = '#3a2f10';
    ctx.strokeStyle = '#3a2f10';
    ctx.lineWidth = 1;

    // Draw ticks from x=0 along the top edge.
    let majorIndex = 0;
    for (let x = 0; x <= cssW; x += minorPxStep) {
        const isMajor = Math.abs((x / majorPxStep) - Math.round(x / majorPxStep)) < 0.001;
        const isHalf = !isMajor && Math.abs((x / (majorPxStep / 2)) - Math.round(x / (majorPxStep / 2))) < 0.001;
        const tickH = isMajor ? cssH * 0.55 : isHalf ? cssH * 0.35 : cssH * 0.22;
        ctx.beginPath();
        ctx.moveTo(Math.round(x) + 0.5, 0);
        ctx.lineTo(Math.round(x) + 0.5, tickH);
        ctx.stroke();
        if (isMajor) {
            const label = (majorIndex * majorEveryUnits).toString();
            if ((majorIndex % labelEveryMajor) === 0 && x > 1 && x < cssW - 6) {
                ctx.fillText(label, Math.round(x) + 3, cssH - 6);
            }
            majorIndex++;
        }
    }

    // Unit chip in the right side
    ctx.fillStyle = 'rgba(0,206,201,0.85)';
    ctx.font = 'bold 11px Inter, system-ui, sans-serif';
    const totalUnits = (cssW / ppu).toFixed(unit === 'px' ? 0 : 1);
    const chip = `${totalUnits} ${unit}`;
    const cw = ctx.measureText(chip).width + 12;
    ctx.fillRect(cssW - cw - 18, cssH - 22, cw, 18);
    ctx.fillStyle = '#08171b';
    ctx.fillText(chip, cssW - cw - 12, cssH - 9);
}

function attachRulerInteractions(ruler) {
    if (ruler._v106Attached) return;
    ruler._v106Attached = true;

    let startX, startY, startLeft, startTop, startWidth, mode = null;
    const handle = ruler.querySelector('.ruler-handle');

    function onDown(e) {
        // Ignore if click is in toolbar (so the dropdown/buttons work)
        if (e.target.closest('#ruler-toolbar')) return;
        const rect = ruler.getBoundingClientRect();
        const onHandle = e.target === handle || (rect.right - e.clientX) < 14;
        mode = onHandle ? 'resize' : 'drag';
        startX = e.clientX; startY = e.clientY;
        startLeft = rect.left; startTop = rect.top; startWidth = rect.width;
        e.preventDefault();
    }
    function onMove(e) {
        if (!mode) return;
        if (mode === 'drag') {
            ruler.style.left = (startLeft + (e.clientX - startX)) + 'px';
            ruler.style.top = (startTop + (e.clientY - startY)) + 'px';
        } else if (mode === 'resize') {
            const w = Math.max(120, startWidth + (e.clientX - startX));
            ruler.style.width = w + 'px';
            renderRulerCanvas();
        }
    }
    function onUp() { mode = null; }

    ruler.addEventListener('mousedown', onDown);
    document.addEventListener('mousemove', onMove);
    document.addEventListener('mouseup', onUp);

    const unitSel = document.getElementById('ruler-unit');
    if (unitSel) unitSel.addEventListener('change', renderRulerCanvas);
    window.addEventListener('resize', renderRulerCanvas);
}

// Global state
