// --- WPM Game ---
// --- WPM Game ---
const WPM_TEXTS = {
    easy: [
        "The sun is shining today.",
        "A quick cat runs fast.",
        "I like to read small books.",
        "Water is very good for you.",
        "He went to the park to play."
    ],
    normal: [
        "The quick brown fox jumps over the lazy dog.",
        "Artificial intelligence is transforming the way we study and understand the world around us.",
        "Success is not final, failure is not fatal: it is the courage to continue that counts.",
        "Grade nine is a pivotal year for building strong academic foundations.",
        "In the deep silence of the library, the only sound was the turning of old paper pages."
    ],
    hard: [
        "To be, or not to be, that is the question: whether 'tis nobler in the mind to suffer the slings and arrows of outrageous fortune.",
        "The industrial revolution initiated a rapid transition from hand production methods to machines, new chemical manufacturing and iron production processes.",
        "Photosynthesis is a process used by plants and other organisms to convert light energy into chemical energy that can later be released to fuel the organisms' activities.",
        "A right-angled triangle is a triangle in which one angle is a right angle, and the relation between the sides and angles is the basis for trigonometry.",
        "Algorithmic efficiency is a property of an algorithm which relates to the number of computational resources used by the algorithm."
    ],
    nightmare: [
        "Incomprehensible machinations of extraterrestrial civilizations fundamentally challenge anthropocentric paradigms of the cosmos.",
        "Schrödinger's cat is a thought experiment that illustrates a paradox of quantum superposition, wherein a hypothetical cat may be considered simultaneously both alive and dead.",
        "The Riemann hypothesis implies results about the distribution of prime numbers in mathematics: the non-trivial zeros of the Riemann zeta function all have real part one-half.",
        "Syntactic ambiguity arises when a sentence may be interpreted in more than one way due to ambiguous sentence structure, rather than the ambiguity of the individual words.",
        "Electroencephalography is an electrophysiological monitoring method to record electrical activity of the brain, typically noninvasive, with the electrodes placed along the scalp."
    ],
    impossible: [
        "Supercalifragilisticexpialidocious! Exacerbating juxtapositions sequentially circumvent unparalleled idiosyncrasies yielding ostentatious verisimilitude.",
        "Pneumonoultramicroscopicsilicovolcanoconiosis is arguably the longest word in the English language, referring to a lung disease caused by silica dust inhalation.",
        "Floccinaucinihilipilification is the act or habit of estimating or describing something as worthless, or the state of being considered worthless.",
        "Antidisestablishmentarianism originated as a political stance opposing the removal of the Anglican Church's status as the state church of England, Ireland, and Wales.",
        "Hippopotomonstrosesquippedaliophobia literally translates to the fear of long words, which is highly ironic given the composition of the term itself."
    ]
};

const BOT_SPEEDS = {
    easy: 25,
    normal: 50,
    hard: 85,
    nightmare: 120,
    impossible: 160
};

let wpmStartTime = null;
let currentWpmText = "";
let wpmGameInterval = null;
let wpmTimeLeft = 60;
let wpmCorrectChars = 0;
let wpmTotalTyped = 0;
let currentBotWpm = 0;
let botCorrectChars = 0;

function startWpmGame() {
    document.getElementById('wpm-start-screen').classList.add('hidden');
    document.getElementById('wpm-result-screen').classList.remove('show');
    document.getElementById('wpm-game-screen').classList.remove('hidden');

    const difficulty = document.getElementById('wpm-difficulty').value || 'normal';
    const texts = WPM_TEXTS[difficulty];
    currentWpmText = texts[Math.floor(Math.random() * texts.length)];
    currentBotWpm = BOT_SPEEDS[difficulty] || 50;

    renderWpmPassage('');

    const input = document.getElementById('wpm-input');
    input.value = "";
    input.disabled = false;
    input.focus();

    wpmTimeLeft = 60;
    wpmCorrectChars = 0;
    wpmTotalTyped = 0;
    botCorrectChars = 0;
    wpmStartTime = null;

    document.getElementById('wpm-timer').textContent = wpmTimeLeft;
    document.getElementById('wpm-live-wpm').textContent = '0';
    document.getElementById('wpm-accuracy').textContent = '100';
    document.getElementById('wpm-progress-bar').style.width = '0%';
    document.getElementById('wpm-bot-progress-bar').style.width = '0%';

    clearInterval(wpmGameInterval);
}

function handleWpmInput() {
    if (!wpmStartTime) {
        wpmStartTime = Date.now();
        wpmGameInterval = setInterval(updateWpmLoop, 1000);
    }

    const inputVal = document.getElementById('wpm-input').value;
    wpmTotalTyped = inputVal.length;

    // Calculate Correct Chars
    wpmCorrectChars = 0;
    for (let i = 0; i < inputVal.length; i++) {
        if (inputVal[i] === currentWpmText[i]) wpmCorrectChars++;
    }

    renderWpmPassage(inputVal);

    // End match instantly when user finishes typing perfectly
    if (wpmCorrectChars === currentWpmText.length && inputVal === currentWpmText) {
        endWpmGame();
    }
}

function renderWpmPassage(typed) {
    let html = '';
    for (let i = 0; i < currentWpmText.length; i++) {
        const char = currentWpmText[i];
        if (i < typed.length) {
            if (typed[i] === char) {
                html += `<span class="char-correct">${char}</span>`;
            } else {
                html += `<span class="char-wrong">${char}</span>`;
            }
        } else if (i === typed.length) {
            html += `<span class="char-current">${char}</span>`;
        } else {
            html += `<span>${char}</span>`;
        }
    }
    document.getElementById('wpm-passage-display').innerHTML = html;

    // Progress bar
    const progress = Math.min(100, (typed.length / currentWpmText.length) * 100);
    document.getElementById('wpm-progress-bar').style.width = `${progress}%`;
}

function updateWpmLoop() {
    wpmTimeLeft--;
    document.getElementById('wpm-timer').textContent = wpmTimeLeft;

    const timeElapsedMins = (60 - wpmTimeLeft) / 60;
    const wordsTyped = wpmCorrectChars / 5; // Standard WPM calc
    const liveWpm = timeElapsedMins > 0 ? Math.round(wordsTyped / timeElapsedMins) : 0;

    document.getElementById('wpm-live-wpm').textContent = liveWpm;

    const accuracy = wpmTotalTyped > 0 ? Math.round((wpmCorrectChars / wpmTotalTyped) * 100) : 100;
    document.getElementById('wpm-accuracy').textContent = accuracy;

    // Bot progress
    const charsPerSec = (currentBotWpm * 5) / 60;
    botCorrectChars += charsPerSec;
    const botProgress = Math.min(100, (botCorrectChars / currentWpmText.length) * 100);
    document.getElementById('wpm-bot-progress-bar').style.width = `${botProgress}%`;

    if (wpmTimeLeft <= 0 || botProgress >= 100) {
        if (botProgress >= 100) {
            // Give user a split second to finish if it's a tie, but mostly bot wins
            setTimeout(() => {
                if(wpmGameInterval) endWpmGame(true);
            }, 100);
        } else {
            endWpmGame(false);
        }
    }
}

function checkWpmCooldown() {
    const cd = localStorage.getItem('wpm_cooldown');
    const badge = document.getElementById('wpm-reward-badge');
    if (!badge) return; // Prevent error if badge not in DOM
    if (cd && Date.now() < parseInt(cd)) {
        badge.innerHTML = 'Practice Mode (Reward Cooldown)';
        badge.style.background = 'rgba(255,255,255,0.1)';
    } else {
        badge.innerHTML = '<i class="ph ph-coins"></i> Rewards Active';
        badge.style.background = 'rgba(0,184,148,0.2)';
    }
}

function endWpmGame(botWon = false) {
    clearInterval(wpmGameInterval);
    wpmGameInterval = null;
    document.getElementById('wpm-input').disabled = true;

    const timeElapsedMins = (60 - wpmTimeLeft) / 60 || (1 / 60); // avoid div 0
    const wordsTyped = wpmCorrectChars / 5;
    const finalWpm = Math.round(wordsTyped / timeElapsedMins);

    document.getElementById('wpm-game-screen').classList.add('hidden');
    document.getElementById('wpm-result-screen').classList.add('show');
    document.getElementById('wpm-final-score').textContent = finalWpm;

    const outElem = document.getElementById('wpm-credits-earned');

    if (botWon && wpmCorrectChars < currentWpmText.length) {
        outElem.textContent = `Bot finished first! You lost.`;
        outElem.style.color = '#d63031';
        return;
    }

    // Check Cooldown
    const cooldown = localStorage.getItem('wpm_cooldown');

    if (!cooldown || Date.now() > parseInt(cooldown)) {
        const reward = parseInt(finalWpm.toString()[0]) || 0; // First digit of WPM
        if (reward > 0) {
            updateCredits(reward);
            outElem.textContent = `+${reward} Credits Earned!`;
            outElem.style.color = '#00b894';
            localStorage.setItem('wpm_cooldown', (Date.now() + 300000).toString()); // 5 mins
        } else {
            outElem.textContent = `0 Credits (Too Slow)`;
            outElem.style.color = 'var(--text-muted)';
        }
    } else {
        outElem.textContent = `Practice Mode (Reward on cooldown)`;
        outElem.style.color = 'var(--text-muted)';
    }
}

function resetWpmToStart() {
    document.getElementById('wpm-result-screen').classList.remove('show');
    document.getElementById('wpm-game-screen').classList.add('hidden');
    document.getElementById('wpm-start-screen').classList.remove('hidden');
    checkWpmCooldown();
}

// --- Dictionary ---
// v12.1 — Two-source lookup: try the free dictionaryapi.dev first (instant, no
// tokens, covers ~99% of standard English). If it returns nothing, fall back to
// the OpenAI path with a strict JSON schema. This is way faster on common words
// AND fixes the "missing words" problem on technical/slang/proper-noun lookups
// because OpenAI is asked explicitly to NEVER return empty definitions — instead
// it must give a best-effort definition or explain why the word can't be found.
let currentSynonymTarget = "";
async function lookupWord() {
    const word = document.getElementById('dict-word-input').value.trim();
    if (!word) return;

    document.getElementById('dict-loading').classList.remove('hidden');
    document.getElementById('dict-output').classList.add('hidden');

    // Try free dictionary API first
    let entry = await _lookupWordFreeApi(word);
    // Fall back to OpenAI if free API has nothing
    if (!entry || !entry.definitions || entry.definitions.length === 0) {
        entry = await _lookupWordOpenAI(word);
    }
    document.getElementById('dict-loading').classList.add('hidden');
    if (!entry) {
        showToast(`Couldn't find "${word}". Try a different spelling.`, 'error');
        return;
    }
    document.getElementById('dict-output').classList.remove('hidden');
    document.getElementById('dict-word-heading').textContent = entry.word;
    document.getElementById('dict-phonetic').textContent = entry.phonetic || '';

    let defHtml = '';
    if (entry.definitions && entry.definitions.length) {
        entry.definitions.forEach(d => {
            const example = d.example ? `<div class="def-example" style="margin-top:6px;color:var(--text-muted);font-style:italic;font-size:0.86rem;">"${escapeHtmlSafe(d.example)}"</div>` : '';
            defHtml += `<div class="def-card"><div class="def-num">${escapeHtmlSafe(d.pos || '')}</div><div class="def-sentence">${escapeHtmlSafe(d.def)}${example}</div></div>`;
        });
    } else {
        defHtml = '<div class="def-card"><div class="def-sentence" style="color:var(--text-muted);">No definitions found.</div></div>';
    }
    document.getElementById('definition-cards').innerHTML = defHtml;

    const synBox = document.getElementById('synonym-challenge');
    if (entry.synonyms && entry.synonyms.length > 0) {
        synBox.classList.remove('hidden');
        setupSynonymChallenge(entry.synonyms);
    } else {
        synBox.classList.add('hidden');
    }
}

async function _lookupWordFreeApi(word) {
    try {
        const res = await fetch(`https://api.dictionaryapi.dev/api/v2/entries/en/${encodeURIComponent(word)}`);
        if (!res.ok) return null;
        const data = await res.json();
        if (!Array.isArray(data) || data.length === 0) return null;
        const e = data[0];
        const phonetic = e.phonetic ||
            (Array.isArray(e.phonetics) ? (e.phonetics.find(p => p.text) || {}).text : '') || '';
        const definitions = [];
        const synonyms = new Set();
        (e.meanings || []).forEach(m => {
            (m.definitions || []).forEach(d => {
                definitions.push({ pos: m.partOfSpeech || '', def: d.definition || '', example: d.example || '' });
                (d.synonyms || []).forEach(s => synonyms.add(s));
            });
            (m.synonyms || []).forEach(s => synonyms.add(s));
        });
        return { word: e.word || word, phonetic, definitions: definitions.slice(0, 5), synonyms: Array.from(synonyms).slice(0, 8) };
    } catch (_) { return null; }
}

async function _lookupWordOpenAI(word) {
    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add API key in Settings.', 'error'); return null; }
    try {
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o-mini',
                response_format: { type: 'json_object' },
                messages: [
                    { role: 'system', content: `You are a dictionary. Return STRICT JSON with this exact schema:
{
  "word": "the headword as the user typed it (corrected spelling if obvious typo)",
  "phonetic": "IPA pronunciation in slashes, e.g. /wɜːrd/",
  "definitions": [{"pos":"noun|verb|adjective|adverb|...", "def":"clear definition", "example":"one short example sentence"}, ...],
  "synonyms": ["synonym1", "synonym2", ...]
}

NEVER return an empty definitions array. Even for:
 - Technical / scientific / medical terms — give the field's standard definition.
 - Proper nouns (people, places, brands) — define as the entity (e.g., "A city in...", "An American author...", "A multinational corporation...").
 - Slang / contemporary / informal usage — label as "slang" or "informal".
 - Old / archaic / rare words — label "archaic" or "rare".
 - Hyphenated compounds, prefixes, suffixes — define what they form.
If a word is truly unrecognizable (random letters), return ONE entry: {"pos":"unknown","def":"This doesn't appear to be a word. Did you mean: [closest 1-2 candidates]?","example":""}.

Return 2-4 definitions for common words, 1-2 for niche words. Include examples where useful.` },
                    { role: 'user', content: word }
                ]
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message);
        const entry = JSON.parse(data.choices[0].message.content);
        return entry;
    } catch (e) {
        return null;
    }
}

// v13.1 — Synonym challenge with contextually plausible distractors.
// We pick 3 decoy words from the OTHER synonyms pool (so they're real words
// related to the same vocabulary space) rather than random common words.
// If the synonyms list is too short we pad from a POS-stratified fallback pool
// that actually looks plausible (words ≥ 5 letters, mix of adjectives / verbs /
// nouns so the quiz isn't trivially easy).
function setupSynonymChallenge(synonyms) {
    // Pick a random correct answer
    const shuffled = synonyms.slice().sort(() => Math.random() - 0.5);
    const correct = shuffled[0];
    // Decoys: use other synonyms first (they look similar enough to be tricky)
    const pool = shuffled.slice(1).filter(s => s !== correct);
    // Backup decoy pool — real English words that aren't obviously "wrong"
    const backupDecoys = [
        'amplify','diminish','resolve','obscure','invoke','subtle','dormant',
        'vibrant','tranquil','rigid','volatile','acute','benign','abstract',
        'coherent','divert','suppress','elevate','comply','refine','derive',
        'concede','manifest','disperse','transmit','sustain','alleviate','converge'
    ];
    while (pool.length < 3) {
        const d = backupDecoys[Math.floor(Math.random() * backupDecoys.length)];
        if (!pool.includes(d) && d !== correct) pool.push(d);
    }
    const options = [correct, ...pool.slice(0, 3)].sort(() => Math.random() - 0.5);

    document.getElementById('synonym-question').textContent =
        `Which word is a synonym of "${document.getElementById('dict-word-heading').textContent}"?`;
    const optsDiv = document.getElementById('synonym-options');
    optsDiv.innerHTML = '';
    // Reset any previous result message
    const resultEl = document.getElementById('synonym-result');
    if (resultEl) resultEl.remove();

    optsDiv._correctWord = correct; // store for post-answer highlight
    options.forEach(opt => {
        const btn = document.createElement('button');
        btn.className = 'synonym-option';
        btn.textContent = opt;
        btn.onclick = () => checkDictSynonym(btn, opt === correct, optsDiv);
        optsDiv.appendChild(btn);
    });
}

function checkDictSynonym(btn, isCorrect, container) {
    // Disable all buttons
    container.querySelectorAll('.synonym-option').forEach(b => {
        b.disabled = true;
        b.style.cursor = 'default';
    });
    if (isCorrect) {
        btn.classList.add('correct');
        updateCredits(5);
        if (typeof awardXP === 'function') awardXP(5);
        showToast('✓ Correct! +5 Credits', 'success');
    } else {
        btn.classList.add('wrong');
        // Highlight the correct button green so the user learns
        container.querySelectorAll('.synonym-option').forEach(b => {
            if (b.textContent === container._correctWord) b.classList.add('correct');
        });
        showToast('Incorrect — the correct synonym is highlighted.', 'error', 3000);
    }
    // Show a "Try another word" nudge below the challenge
    const synBox = document.getElementById('synonym-challenge');
    if (synBox && !document.getElementById('synonym-result')) {
        const msg = document.createElement('div');
        msg.id = 'synonym-result';
        msg.style.cssText = 'margin-top:10px;font-size:0.9rem;color:var(--text-muted);text-align:center;';
        msg.textContent = isCorrect ? '🎉 Well done! Look up another word to keep practicing.' : '📖 Look up more words to build vocabulary and earn credits.';
        synBox.appendChild(msg);
    }
}


// ============================================================
// VOCABULARY BUILDER
// ============================================================
let currentDictWord = null; // Store current word data for saving

function saveWordToVocab() {
    const word = document.getElementById('dict-word-heading').textContent;
    const phonetic = document.getElementById('dict-phonetic').textContent;
    const definitionCards = document.getElementById('definition-cards').innerHTML;

    if (!word) {
        showToast('No word to save', 'warning');
        return;
    }

    // Get vocabulary list from localStorage
    const vocab = JSON.parse(localStorage.getItem('vocabulary') || '[]');

    // Check if word already exists
    if (vocab.some(v => v.word.toLowerCase() === word.toLowerCase())) {
        showToast('Word already in your vocabulary!', 'info', 2000);
        return;
    }

    // Add new word
    vocab.push({
        word,
        phonetic,
        definitions: definitionCards,
        dateAdded: new Date().toISOString()
    });

    localStorage.setItem('vocabulary', JSON.stringify(vocab));
    showToast(`"${word}" saved to vocabulary!`, 'success', 2000);
    logActivity('english', `Saved word to vocabulary: ${word}`);
    refreshSavedWordsCount();
}

// ── DICTIONARY UPGRADE: saved-words drawer + count ──
function refreshSavedWordsCount() {
    const vocab = JSON.parse(localStorage.getItem('vocabulary') || '[]');
    const el = document.getElementById('dict-saved-count');
    if (el) el.textContent = vocab.length;
}
function showSavedWords() {
    const drawer = document.getElementById('dict-saved-drawer');
    const list = document.getElementById('dict-saved-list');
    if (!drawer || !list) return;
    const vocab = JSON.parse(localStorage.getItem('vocabulary') || '[]');
    if (vocab.length === 0) {
        list.innerHTML = '<div style="grid-column:1/-1;color:var(--text-muted);font-size:0.85rem;text-align:center;padding:14px;">No saved words yet. Look up a word and click the Save Word button.</div>';
    } else {
        list.innerHTML = vocab.map(v => `<button onclick="document.getElementById('dict-word-input').value='${v.word.replace(/'/g, "\\'")}';lookupWord();document.getElementById('dict-saved-drawer').style.display='none';" style="padding:8px 10px;background:rgba(0,206,201,0.1);border:1px solid rgba(0,206,201,0.3);border-radius:8px;color:white;cursor:pointer;font-size:0.85rem;text-align:center;font-weight:600;transition:all 0.15s;" onmouseover="this.style.background='rgba(0,206,201,0.25)'" onmouseout="this.style.background='rgba(0,206,201,0.1)'">${v.word}</button>`).join('');
    }
    drawer.style.display = 'block';
}

function openVocabularyBuilder() {
    document.getElementById('vocabulary-modal').classList.remove('hidden');
    renderVocabularyList();
}

function closeVocabularyBuilder() {
    document.getElementById('vocabulary-modal').classList.add('hidden');
    document.getElementById('vocab-quiz-panel').classList.add('hidden');
}

function renderVocabularyList() {
    const vocab = JSON.parse(localStorage.getItem('vocabulary') || '[]');
    const container = document.getElementById('vocab-word-list');
    const totalCount = document.getElementById('vocab-total-count');

    totalCount.textContent = vocab.length;

    if (vocab.length === 0) {
        container.innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-muted);"><i class="ph ph-bookmark-simple" style="font-size:1.25rem;display:block;margin-bottom:12px;"></i><p>No words saved yet. Look up words in the Dictionary and click "Save Word"!</p></div>';
        return;
    }

    let html = '<div style="display:grid;gap:12px;">';
    vocab.reverse().forEach((item, index) => {
        const actualIndex = vocab.length - 1 - index; // Reverse index for deletion
        html += `
            <div style="background:rgba(0,0,0,0.3);padding:16px;border-radius:8px;border-left:3px solid var(--accent);">
                <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:8px;">
                    <div>
                        <h3 style="margin:0;color:white;font-size:1.3rem;">${item.word}</h3>
                        ${item.phonetic ? `<p style="margin:4px 0 0;color:var(--text-muted);font-style:italic;font-size:0.9rem;">${item.phonetic}</p>` : ''}
                    </div>
                    <button class="btn-icon" onclick="removeVocabWord(${actualIndex})" title="Remove word">
                        <i class="ph ph-trash"></i>
                    </button>
                </div>
                ${item.definitions}
                <p style="margin:12px 0 0;color:var(--text-muted);font-size:0.85rem;">
                    <i class="ph ph-calendar"></i> Added ${new Date(item.dateAdded).toLocaleDateString()}
                </p>
            </div>
        `;
    });
    html += '</div>';
    container.innerHTML = html;
}

function removeVocabWord(index) {
    const vocab = JSON.parse(localStorage.getItem('vocabulary') || '[]');
    const word = vocab[index].word;
    vocab.splice(index, 1);
    localStorage.setItem('vocabulary', JSON.stringify(vocab));
    showToast(`"${word}" removed`, 'info', 2000);
    renderVocabularyList();
}

function clearVocabulary() {
    if (!confirm('Are you sure you want to clear all saved words?')) return;
    localStorage.setItem('vocabulary', '[]');
    renderVocabularyList();
    showToast('Vocabulary cleared', 'success');
}

let currentVocabQuiz = null;

function startVocabQuiz() {
    const vocab = JSON.parse(localStorage.getItem('vocabulary') || '[]');

    if (vocab.length < 4) {
        showToast('You need at least 4 saved words to start a quiz', 'warning', 3000);
        return;
    }

    // Initialize quiz
    currentVocabQuiz = {
        questions: vocab.slice(),
        currentIndex: 0,
        correct: 0,
        total: Math.min(10, vocab.length)
    };

    // Shuffle questions
    currentVocabQuiz.questions.sort(() => Math.random() - 0.5);
    currentVocabQuiz.questions = currentVocabQuiz.questions.slice(0, currentVocabQuiz.total);

    document.getElementById('vocab-quiz-panel').classList.remove('hidden');
    showVocabQuestion();
}

function showVocabQuestion() {
    if (currentVocabQuiz.currentIndex >= currentVocabQuiz.total) {
        finishVocabQuiz();
        return;
    }

    const vocab = JSON.parse(localStorage.getItem('vocabulary') || '[]');
    const question = currentVocabQuiz.questions[currentVocabQuiz.currentIndex];
    const questionDiv = document.getElementById('vocab-quiz-question');
    const optionsDiv = document.getElementById('vocab-quiz-options');
    const resultDiv = document.getElementById('vocab-quiz-result');

    resultDiv.classList.add('hidden');

    // Extract first definition from HTML
    const tempDiv = document.createElement('div');
    tempDiv.innerHTML = question.definitions;
    const firstDef = tempDiv.querySelector('.def-sentence')?.textContent || 'Definition';

    questionDiv.innerHTML = `
        <p style="color:var(--text-muted);font-size:0.9rem;">Question ${currentVocabQuiz.currentIndex + 1} of ${currentVocabQuiz.total}</p>
        <h3 style="color:white;margin:8px 0;">What does this word mean?</h3>
        <p style="font-size:1.5rem;color:var(--accent);font-weight:700;margin:12px 0;">${question.word}</p>
    `;

    // Create options (1 correct + 3 wrong)
    const options = [{ text: firstDef, correct: true }];

    // Get 3 random wrong answers from other vocab words
    const otherWords = vocab.filter(w => w.word !== question.word);
    while (options.length < 4 && otherWords.length > 0) {
        const randomIndex = Math.floor(Math.random() * otherWords.length);
        const wrongWord = otherWords.splice(randomIndex, 1)[0];
        const tempDiv2 = document.createElement('div');
        tempDiv2.innerHTML = wrongWord.definitions;
        const wrongDef = tempDiv2.querySelector('.def-sentence')?.textContent || 'Definition';
        options.push({ text: wrongDef, correct: false });
    }

    // Shuffle options
    options.sort(() => Math.random() - 0.5);

    // Render options
    optionsDiv.innerHTML = '';
    options.forEach(opt => {
        const btn = document.createElement('button');
        btn.className = 'btn-secondary';
        btn.style.textAlign = 'left';
        btn.style.padding = '12px 16px';
        btn.textContent = opt.text;
        btn.onclick = () => checkVocabAnswer(opt.correct, btn, optionsDiv);
        optionsDiv.appendChild(btn);
    });
}

function checkVocabAnswer(isCorrect, btn, container) {
    // Disable all buttons
    container.querySelectorAll('button').forEach(b => b.disabled = true);

    const resultDiv = document.getElementById('vocab-quiz-result');
    resultDiv.classList.remove('hidden');

    if (isCorrect) {
        btn.style.background = 'linear-gradient(135deg, rgba(0, 184, 148, 0.3), rgba(0, 206, 201, 0.3))';
        btn.style.borderColor = '#00b894';
        resultDiv.innerHTML = '<div style="color:#00b894;"><i class="ph ph-check-circle"></i> Correct!</div>';
        resultDiv.style.background = 'rgba(0, 184, 148, 0.2)';
        resultDiv.style.borderLeft = '3px solid #00b894';
        currentVocabQuiz.correct++;
    } else {
        btn.style.background = 'linear-gradient(135deg, rgba(214, 48, 49, 0.3), rgba(255, 118, 117, 0.3))';
        btn.style.borderColor = '#d63031';
        resultDiv.innerHTML = '<div style="color:#d63031;"><i class="ph ph-x-circle"></i> Incorrect</div>';
        resultDiv.style.background = 'rgba(214, 48, 49, 0.2)';
        resultDiv.style.borderLeft = '3px solid #d63031';
    }

    // Next question button
    setTimeout(() => {
        resultDiv.innerHTML += '<button class="btn-primary" onclick="nextVocabQuestion()" style="margin-top:12px;">Next Question</button>';
    }, 500);
}

function nextVocabQuestion() {
    currentVocabQuiz.currentIndex++;
    showVocabQuestion();
}

function finishVocabQuiz() {
    const percentage = Math.round((currentVocabQuiz.correct / currentVocabQuiz.total) * 100);
    const questionDiv = document.getElementById('vocab-quiz-question');
    const optionsDiv = document.getElementById('vocab-quiz-options');
    const resultDiv = document.getElementById('vocab-quiz-result');

    questionDiv.innerHTML = `
        <div style="text-align:center;">
            <i class="ph ph-trophy" style="font-size:1.4rem;color:var(--accent);display:block;margin-bottom:16px;"></i>
            <h2 style="color:white;">Quiz Complete!</h2>
        </div>
    `;

    optionsDiv.innerHTML = '';
    resultDiv.classList.remove('hidden');
    resultDiv.style.background = 'linear-gradient(135deg, rgba(0, 206, 201, 0.2), rgba(108, 92, 231, 0.2))';
    resultDiv.style.borderLeft = '3px solid var(--accent)';
    resultDiv.innerHTML = `
        <div style="text-align:center;">
            <p style="font-size:1.2rem;margin-bottom:8px;">You scored:</p>
            <p style="font-size:1.5rem;font-weight:700;color:var(--accent);margin:0;">${currentVocabQuiz.correct}/${currentVocabQuiz.total}</p>
            <p style="font-size:1.5rem;color:white;margin-top:8px;">${percentage}%</p>
            <button class="btn-primary" onclick="startVocabQuiz()" style="margin-top:16px;">
                <i class="ph ph-arrow-clockwise"></i> Try Again
            </button>
        </div>
    `;

    // Update quiz score display
    document.getElementById('vocab-quiz-score').textContent = `${percentage}%`;

    // Award credits
    const creditsEarned = currentVocabQuiz.correct * 3;
    updateCredits(creditsEarned);
    showToast(`+${creditsEarned} Credits! (${currentVocabQuiz.correct} correct × 3)`, 'success', 3000);

    // Track activity
    logActivity('english', `Vocabulary quiz: ${currentVocabQuiz.correct}/${currentVocabQuiz.total} (${percentage}%)`);
    updateStudyStats('problem_solved');
    updateStudyStats('daily_goal', 33);
}

// ============================================================
// QUICK QUIZ
// ============================================================
function startQuiz() {
    document.getElementById('quiz-modal').classList.remove('hidden');
    document.getElementById('quiz-setup').style.display = 'block';
    document.getElementById('quiz-content').classList.add('hidden');
}

// Store quiz state for grading (fixes the all-incorrect bug)
let _currentQuizData = null;
let _quizAnswered = [];

async function generateQuiz() {
    const diff = document.getElementById('quiz-difficulty').value;
    const content = document.getElementById('quiz-content');
    const setup = document.getElementById('quiz-setup');
    const apiKey = getApiKey();

    if (!apiKey) { showToast('Please add API key in Settings.', 'error'); return; }

    setup.style.display = 'none';
    content.classList.remove('hidden');
    content.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-muted);"><i class="ph ph-spinner ph-spin" style="font-size:1.35rem;"></i><p>Generating Quiz...</p></div>';

    try {
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o',
                response_format: { type: 'json_object' },
                messages: [
                    { role: 'system', content: `Generate a 3-question multiple-choice math quiz for Grade ${diff}.

Return STRICT JSON in this exact format:
{
  "questions": [
    {
      "q": "What is 2 + 2?",
      "work": "2 + 2 = 4",
      "options": ["3", "4", "5", "6"],
      "answerIndex": 1
    }
  ]
}

CRITICAL RULES:
- FIRST solve the question step by step in the "work" field, THEN write the options.
- "options" must be the actual answer text (numbers, words, expressions) — NOT letters like "A","B","C","D".
- "answerIndex" is the 0-based index of the option that EXACTLY matches the final result in "work" (0, 1, 2, or 3). If they disagree, redo the work — never guess the index.
- Each question must have exactly 4 options with exactly one correct answer.
- Re-check the arithmetic in "work" digit by digit before responding; a wrong answer key tells a student their correct math is wrong.` },
                    { role: 'user', content: 'Generate quiz.' }
                ]
            })
        });
        const data = await res.json();
        const quizData = JSON.parse(data.choices[0].message.content);

        // Normalize: handle both new (answerIndex) and legacy (answer) formats
        quizData.questions.forEach(q => {
            if (typeof q.answerIndex !== 'number') {
                if (typeof q.answer === 'string') {
                    // Try LETTER format first ("A", "B", etc.)
                    const letterMatch = q.answer.trim().toUpperCase().match(/^[A-D]$/);
                    if (letterMatch) {
                        q.answerIndex = q.answer.trim().toUpperCase().charCodeAt(0) - 65;
                    } else {
                        // Try TEXT match — find the option whose text matches
                        const idx = q.options.findIndex(o => String(o).trim() === String(q.answer).trim());
                        q.answerIndex = idx >= 0 ? idx : 0;
                    }
                } else {
                    q.answerIndex = 0;
                }
            }
        });
        // v19.4 — reconcile the key against the model's own worked solution
        // before shuffling (it sometimes derives the right value but keys the
        // wrong option).
        quizData.questions.forEach(q => {
            if (!Array.isArray(q.options) || q.options.length < 2) return;
            const fixed = _reconcileAnswerIndex(q.options, q.work);
            if (fixed >= 0 && fixed !== q.answerIndex) q.answerIndex = fixed;
        });

        // v19.1 — shuffle options so the correct answer isn't predictably the
        // first choice (the model heavily favored index 0).
        quizData.questions.forEach(q => {
            if (!Array.isArray(q.options) || q.options.length < 2) return;
            const correctText = q.options[q.answerIndex] ?? q.options[0];
            for (let i = q.options.length - 1; i > 0; i--) {
                const j = Math.floor(Math.random() * (i + 1));
                [q.options[i], q.options[j]] = [q.options[j], q.options[i]];
            }
            const idx = q.options.indexOf(correctText);
            if (idx >= 0) q.answerIndex = idx;
        });

        _currentQuizData = quizData;
        _quizAnswered = quizData.questions.map(() => false);

        let html = '<div>';
        quizData.questions.forEach((q, qi) => {
            html += `<div style="margin-bottom:20px;background:rgba(255,255,255,0.05);padding:15px;border-radius:10px;">
                <p style="margin-bottom:10px;color:white;"><strong>Q${qi + 1}:</strong> ${q.q}</p>
                <div style="display:flex;flex-direction:column;gap:12px;" data-quiz-q="${qi}">`;
            q.options.forEach((opt, oi) => {
                html += `<button class="btn-secondary quiz-option" data-q="${qi}" data-o="${oi}" style="text-align:left;padding:10px;" onclick="answerQuiz(${qi}, ${oi})">${opt}</button>`;
            });
            html += `</div></div>`;
        });
        html += `<button class="btn-primary" style="width:100%" onclick="startQuiz()">Generate Another</button></div>`;
        content.innerHTML = html;

    } catch (err) {
        content.innerHTML = `<p style="color:#d63031">Error: ${err.message}</p><button class="btn-secondary" onclick="startQuiz()">Try Again</button>`;
    }
}

// Grade a quiz answer at click time using stored quiz data (no boolean baked into HTML)
function answerQuiz(qi, oi) {
    if (!_currentQuizData || !_currentQuizData.questions[qi]) return;
    if (_quizAnswered[qi]) return;
    _quizAnswered[qi] = true;
    const q = _currentQuizData.questions[qi];
    const isCorrect = oi === q.answerIndex;
    const wrap = document.querySelector(`[data-quiz-q="${qi}"]`);
    if (wrap) {
        wrap.querySelectorAll('.quiz-option').forEach(btn => {
            const btnIdx = parseInt(btn.getAttribute('data-o'));
            if (btnIdx === q.answerIndex) {
                btn.style.background = '#00b894';
                btn.style.color = 'white';
            } else if (btnIdx === oi && !isCorrect) {
                btn.style.background = '#d63031';
                btn.style.color = 'white';
            }
            btn.style.opacity = '0.85';
            btn.disabled = true;
        });
    }
    if (isCorrect) {
        showToast('Correct!', 'success', 2500);
        updateCredits(2);
    } else {
        showToast('Incorrect — the right answer is highlighted in green.', 'error', 3500);
    }
    // v19.3 — show the worked solution under the question so a miss teaches
    // something (the model already returns its step-by-step in q.work).
    if (wrap && q.work && !wrap.querySelector('.quiz-explanation')) {
        const ex = document.createElement('div');
        ex.className = 'quiz-explanation';
        ex.style.cssText = 'margin-top:10px;padding:10px 12px;border-radius:8px;font-size:0.88rem;line-height:1.5;color:#d8dce5;background:rgba(255,255,255,0.05);border-left:3px solid ' + (isCorrect ? '#00b894' : '#fdcb6e') + ';';
        ex.textContent = (isCorrect ? '✓ Why: ' : '💡 How to get it: ') + q.work;
        wrap.appendChild(ex);
    }
}

