function openShop() {
    switchTab('shop');
}

// Shop Page Tab System (full page)
function switchShopPageTab(tab) {
    // Update tab button states
    const shopView = document.getElementById('view-shop');
    if (shopView) {
        shopView.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
        const activeBtn = shopView.querySelector(`[onclick="switchShopPageTab('${tab}')"]`);
        if (activeBtn) activeBtn.classList.add('active');
    }

    const container = document.getElementById('shop-page-content');
    if (!container) return;

    if (tab === 'gamble') {
        renderGambleTab(container);
        return;
    }

    renderShopContent(tab, container);
}

function initShopPage() {
    // Update credit display
    const creds = document.getElementById('shop-page-credits');
    if (creds) creds.textContent = userCredits.toLocaleString();

    // Check daily reward
    const today = new Date().toISOString().split('T')[0];
    const lastClaim = localStorage.getItem('last_daily_claim');
    const banner = document.getElementById('shop-page-daily-banner');
    if (banner) {
        if (lastClaim !== today) banner.classList.remove('hidden');
        else banner.classList.add('hidden');
    }

    // Pro upgrade banner for Access tier — shop is preview-only
    const shopView = document.getElementById('view-shop');
    if (shopView) {
        let proBanner = shopView.querySelector('.shop-pro-preview-banner');
        if (!hasPro()) {
            if (!proBanner) {
                proBanner = document.createElement('div');
                proBanner.className = 'shop-pro-preview-banner';
                proBanner.style.cssText = 'background:linear-gradient(135deg, rgba(108,92,231,0.18), rgba(0,206,201,0.12));border:1px solid rgba(255,215,0,0.35);border-radius:14px;padding:18px 22px;margin-bottom:20px;display:flex;align-items:center;gap:18px;flex-wrap:wrap;';
                proBanner.innerHTML = `
                    <i class="ph ph-eye" style="font-size:1.35rem;color:#FFD700;"></i>
                    <div style="flex:1;min-width:240px;">
                        <div style="color:white;font-weight:700;font-size:1.05rem;margin-bottom:4px;">Preview Mode &mdash; Upgrade to Unlock the Shop</div>
                        <div style="color:var(--text-muted);font-size:0.85rem;line-height:1.5;">You're browsing the full shop catalog. NEXUS Access can preview every theme, wallpaper, cursor, badge, and effect &mdash; but only Pro can purchase and equip them.</div>
                    </div>
                    <button onclick="openPaymentModal('pro')" style="padding:11px 20px;background:linear-gradient(135deg, #6C5CE7, #00CEC9);border:none;border-radius:10px;color:white;font-weight:700;font-size:0.92rem;cursor:pointer;white-space:nowrap;box-shadow:0 4px 14px rgba(108,92,231,0.3);">
                        <i class="ph ph-star"></i> Upgrade for $1.50/mo
                    </button>`;
                const inner = shopView.querySelector('.main-content > div, .glass-panel') || shopView.firstElementChild;
                if (inner && inner.firstElementChild) inner.insertBefore(proBanner, inner.firstElementChild);
                else shopView.insertBefore(proBanner, shopView.firstElementChild);
            }
        } else if (proBanner) {
            proBanner.remove();
        }
    }

    switchShopPageTab('themes');
}

// Inventory Page (full page)
let currentInventoryFilter = 'all';

function filterInventory(category) {
    currentInventoryFilter = category;

    // Update tab buttons
    const invView = document.getElementById('view-inventory');
    if (invView) {
        invView.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
        const activeBtn = invView.querySelector(`[onclick="filterInventory('${category}')"]`);
        if (activeBtn) activeBtn.classList.add('active');
    }

    renderInventoryPage();
}

// v12.1 — used to auto-grant every common item to new accounts. Removed per user
// request: signing up should feel like a clean inventory you build up by earning
// credits, not a pre-stocked shelf. Function kept as a no-op so legacy callers
// don't crash, but it only grants the bare-minimum "none" sentinels for each
// category (the items that mean "no theme equipped", "no cursor equipped", etc.)
// so the shop equip-flow still works on a fresh account.
function grantCommonClassics() {
    // v19.1 — merge in the localStorage copy first. If the in-memory array is
    // stale (e.g. zeroed by signOut before a restore), saving below would
    // otherwise overwrite the user's real inventory with just the sentinels.
    try {
        const stored = JSON.parse(localStorage.getItem('user_inventory') || '[]');
        if (Array.isArray(stored) && stored.length) {
            userInventory = Array.from(new Set([...userInventory, ...stored]));
        }
    } catch (_) { /* ignore corrupted JSON */ }
    const sentinelIds = ['default', 'none']; // sentinel "no-op" item ids
    let added = 0;
    const cats = ['themes', 'cursors', 'fonts', 'wallpapers', 'badges', 'effects', 'companions'];
    cats.forEach(cat => {
        const list = (SHOP_ITEMS && SHOP_ITEMS[cat]) || [];
        list.forEach(item => {
            if (sentinelIds.includes(item.id) && !userInventory.includes(item.id)) {
                userInventory.push(item.id);
                added++;
            }
        });
    });
    if (added > 0) {
        localStorage.setItem('user_inventory', JSON.stringify(userInventory));
    }
    return added;
}

function renderInventoryPage() {
    const container = document.getElementById('inventory-page-content');
    if (!container) return;

    // v10.6: ensure classics are present every time inventory opens
    grantCommonClassics();

    // Update item count
    const countEl = document.getElementById('inventory-item-count');
    if (countEl) countEl.textContent = userInventory.length;

    // Get all items from all categories
    const allItems = [
        ...SHOP_ITEMS.themes.map(i => ({ ...i, category: 'theme', catPlural: 'themes' })),
        ...SHOP_ITEMS.cursors.map(i => ({ ...i, category: 'cursor', catPlural: 'cursors' })),
        ...SHOP_ITEMS.fonts.map(i => ({ ...i, category: 'font', catPlural: 'fonts' })),
        ...SHOP_ITEMS.wallpapers.map(i => ({ ...i, category: 'wallpaper', catPlural: 'wallpapers' })),
        ...SHOP_ITEMS.badges.map(i => ({ ...i, category: 'badge', catPlural: 'badges' })),
        ...SHOP_ITEMS.effects.map(i => ({ ...i, category: 'effect', catPlural: 'effects' })),
        ...SHOP_ITEMS.companions.map(i => ({ ...i, category: 'companion', catPlural: 'companions' }))
    ];

    // Filter to owned items
    let ownedItems = allItems.filter(i => userInventory.includes(i.id));

    // Apply category filter
    if (currentInventoryFilter !== 'all') {
        ownedItems = ownedItems.filter(i => i.catPlural === currentInventoryFilter);
    }

    // Sort: equipped first, then by rarity (legendary > epic > rare > common)
    // v10.6 fix: match equip per-category. Cross-category id collisions (e.g. theme/cursor/font all
    // having an id "default") were making everything look equipped at once.
    const rarityOrder = { legendary: 0, epic: 1, rare: 2, common: 3 };
    ownedItems.sort((a, b) => {
        const aEquipped = (userLoadout[a.category] === a.id) ? 0 : 1;
        const bEquipped = (userLoadout[b.category] === b.id) ? 0 : 1;
        if (aEquipped !== bEquipped) return aEquipped - bEquipped;
        return (rarityOrder[a.rarity] || 3) - (rarityOrder[b.rarity] || 3);
    });

    if (ownedItems.length === 0) {
        container.innerHTML = `
            <div style="text-align:center;padding:60px 20px;">
                <div style="font-size:1.4rem;margin-bottom:16px;opacity:0.3;">📦</div>
                <h3 style="margin-bottom:8px;color:var(--text-muted);">${currentInventoryFilter === 'all' ? 'Your Inventory is Empty' : 'No items in this category'}</h3>
                <p style="color:var(--text-muted);font-size:0.9rem;">Visit the <a href="#" onclick="switchTab('shop');return false;" style="color:var(--accent);">Shop</a> to purchase items!</p>
            </div>`;
        return;
    }

    const rarityColors = { common: '#9ca3af', rare: '#60a5fa', epic: '#a855f7', legendary: '#fbbf24', nexus: '#00fff5', mythic: '#ff4d8d' };

    let html = '<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:16px;">';
    ownedItems.forEach(item => {
        const isEquipped = userLoadout[item.category] === item.id;
        const rc = rarityColors[item.rarity] || rarityColors.common;

        html += `
        <div class="glass-panel" style="padding:16px;border:2px solid ${rc};transition:all 0.3s;cursor:pointer;${isEquipped ? 'box-shadow:0 0 20px ' + rc + '40;' : ''}"
            onmouseover="this.style.transform='translateY(-3px)'"
            onmouseout="this.style.transform='translateY(0)'">
            <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;">
                <span style="background:${rc};color:#000;font-size:0.88rem;font-weight:700;padding:3px 8px;border-radius:4px;text-transform:uppercase;">${item.rarity}</span>
                <span style="font-size:0.85rem;color:var(--text-muted);text-transform:uppercase;">${item.category}</span>
            </div>
            ${isEquipped ? '<div style="color:#00b894;font-size:0.85rem;font-weight:600;margin-bottom:6px;">✓ EQUIPPED</div>' : ''}
            <h4 style="color:${rc};margin:0 0 4px;font-size:1rem;">${item.name}</h4>
            <p style="font-size:0.9rem;color:var(--text-muted);margin:0 0 12px;">${item.desc}</p>
            <button class="btn-primary" onclick="equipItem('${item.category}','${item.id}')" ${isEquipped ? 'disabled' : ''}
                style="width:100%;font-size:0.85rem;padding:8px;${isEquipped ? 'background:#00b894;cursor:default;opacity:0.7;' : ''}">
                ${isEquipped ? '✓ Equipped' : 'Equip'}
            </button>
        </div>`;
    });
    html += '</div>';
    container.innerHTML = html;
}

// Process refunds for removed pre-v7 items
function processV7Refunds() {
    const refundKey = 'v7_refunds_processed';
    if (localStorage.getItem(refundKey)) return; // Already processed

    let totalRefund = 0;
    const refundedItems = [];

    for (const [itemId, price] of Object.entries(REMOVED_ITEMS)) {
        if (userInventory.includes(itemId)) {
            totalRefund += price;
            refundedItems.push(itemId);
            // Remove from inventory
            userInventory = userInventory.filter(id => id !== itemId);
            // Reset loadout if equipped
            for (const [slot, equipped] of Object.entries(userLoadout)) {
                if (equipped === itemId) {
                    userLoadout[slot] = slot === 'theme' ? 'default' : (slot === 'cursor' ? 'default' : 'default');
                }
            }
        }
    }

    if (totalRefund > 0) {
        userCredits += totalRefund;
        localStorage.setItem('user_credits', userCredits);
        localStorage.setItem('user_inventory', JSON.stringify(userInventory));
        localStorage.setItem('user_loadout', JSON.stringify(userLoadout));

        // Show refund notification
        setTimeout(() => {
            showToast(`🔄 v7.0 Shop Cleanup: ${refundedItems.length} old items removed. You received ${totalRefund} credits back!`, 'success', 6000);
        }, 2000);
    }

    localStorage.setItem(refundKey, 'true');
}

// Daily Reward System
function checkDailyReward() {
    const today = new Date().toISOString().split('T')[0];
    const lastClaim = localStorage.getItem('last_daily_claim');
    const banner = document.getElementById('daily-reward-banner');

    if (lastClaim !== today && banner) {
        banner.style.display = 'block';
    } else if (banner) {
        banner.style.display = 'none';
    }
}

function claimDailyReward() {
    const today = new Date().toISOString().split('T')[0];
    // Guard: one claim per day (the home button + banner both call this).
    if (localStorage.getItem('last_daily_claim') === today) {
        if (typeof showToast === 'function') showToast('Daily reward already claimed — come back tomorrow.', 'info');
        return;
    }
    const stats = getStudyStats();

    // Base reward + streak bonus
    const baseReward = 50;
    const streakBonus = Math.min(stats.currentStreak * 10, 200); // Max 200 bonus
    const totalReward = baseReward + streakBonus;

    userCredits += totalReward;
    localStorage.setItem('user_credits', userCredits);
    localStorage.setItem('last_daily_claim', today);
    if (typeof awardXP === 'function') awardXP(40, 'daily'); // daily reward also grants XP

    // Update displays
    const _cd = document.getElementById('credit-display');
    if (_cd) _cd.innerText = `Credits: ${userCredits}`;
    const shopCreditEl = document.getElementById('shop-credit-display');
    if (shopCreditEl) shopCreditEl.textContent = userCredits.toLocaleString();
    const shopPageCreditEl = document.getElementById('shop-page-credits');
    if (shopPageCreditEl) shopPageCreditEl.textContent = userCredits.toLocaleString();
    const dailyBanner = document.getElementById('daily-reward-banner');
    if (dailyBanner) dailyBanner.style.display = 'none';
    const shopPageBanner = document.getElementById('shop-page-daily-banner');
    if (shopPageBanner) shopPageBanner.classList.add('hidden');

    // Track and notify
    logActivity('shop', `Claimed daily reward: ${totalReward} credits (${streakBonus} streak bonus)`);
    showToast(`🎁 +${totalReward} Credits! (${baseReward} base + ${streakBonus} streak bonus)`, 'success', 4000);
}

function switchShopTab(tab) {
    document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));
    const activeBtn = document.querySelector(`[onclick="switchShopTab('${tab}')"]`);
    if (activeBtn) activeBtn.classList.add('active');
    renderShopContent(tab);
}

let previewItemCache = null;

function previewItem(id, type) {
    const item = SHOP_ITEMS[type].find(i => i.id === id);
    if (!item) return;

    previewItemCache = { id, type, item };
    const categorySingular = type.slice(0, -1);

    // v10.10 — NO whole-UI live preview anymore. Render the item into the mini mockup instead.
    document.getElementById('preview-item-type').textContent = categorySingular;
    document.getElementById('preview-item-name').textContent = item.name;
    document.getElementById('preview-desc').textContent = item.desc || '';
    document.getElementById('preview-price').textContent = item.price || 0;

    // Rarity badge
    const rarityColors = { common: '#9ca3af', rare: '#60a5fa', epic: '#a855f7', legendary: '#fbbf24', nexus: '#00fff5', mythic: '#ff4d8d' };
    const rb = document.getElementById('preview-rarity-badge');
    if (rb) {
        if (item.rarity) {
            rb.textContent = item.rarity;
            rb.style.background = rarityColors[item.rarity] || '#9ca3af';
            rb.style.color = '#000';
            rb.style.display = 'inline-block';
        } else {
            rb.style.display = 'none';
        }
    }

    // Render the item into the mockup — never let a per-category render error
    // stop the modal from opening (that would make previews silently "not work").
    try { renderPreviewMockup(categorySingular, item); } catch (e) { console.warn('preview mockup error:', e); }

    const owned = userInventory.includes(id);
    const equipped = Object.values(userLoadout).includes(id);
    const buyBtn = document.getElementById('preview-buy-btn');
    const equipBtn = document.getElementById('preview-equip-btn');

    // Map category to loadout key
    const categoryMap = {
        themes: 'theme',
        cursors: 'cursor',
        fonts: 'font',
        wallpapers: 'wallpaper',
        badges: 'badge',
        effects: 'effect',
        companions: 'companion'
    };

    if (equipped) {
        buyBtn.style.display = 'none';
        equipBtn.style.display = 'none';
    } else if (owned) {
        buyBtn.style.display = 'none';
        equipBtn.style.display = 'inline-flex';
        // v10.9 — clear preview snapshot BEFORE closing so endLivePreview won't undo the equip
        equipBtn.onclick = () => {
            equipItem(categoryMap[type], id);
            _livePreviewSnapshot = null;
            closeShopPreview();
        };
    } else {
        buyBtn.style.display = 'inline-flex';
        buyBtn.onclick = () => {
            _livePreviewSnapshot = null;
            buyItem(id, type, item.price);
        };
        equipBtn.style.display = 'none';
    }

    // Force it visible above every other layer (was z-index 9998 — could end up
    // behind other stacking contexts, which is the likeliest reason "none worked").
    const _pm = document.getElementById('shop-preview-modal');
    if (_pm) { _pm.classList.remove('hidden'); _pm.style.display = 'flex'; _pm.style.zIndex = '1000050'; }
}

function closeShopPreview() {
    const _pmc = document.getElementById('shop-preview-modal');
    if (_pmc) { _pmc.classList.add('hidden'); _pmc.style.display = 'none'; }
    previewItemCache = null;
    // Stop the mockup wallpaper canvas if it was running
    if (window._previewMockupAnimFrame) {
        cancelAnimationFrame(window._previewMockupAnimFrame);
        clearTimeout(window._previewMockupAnimFrame);
        window._previewMockupAnimFrame = null;
    }
    const __oldEffectLayer = document.getElementById('preview-effect-layer');
    if (__oldEffectLayer) __oldEffectLayer.remove();
}

// v10.10 — render the item into the contained mini-mockup (NOT the whole app)
function renderPreviewMockup(category, item) {
    const mockup = document.getElementById('preview-mockup');
    const sidebar = document.getElementById('preview-mockup-sidebar');
    const content = document.getElementById('preview-mockup-content');
    const heading = document.getElementById('preview-mockup-heading');
    const text = document.getElementById('preview-mockup-text');
    const bar1 = document.getElementById('preview-mockup-bar-1');
    const bar2 = document.getElementById('preview-mockup-bar-2');
    const navBars = [1, 2, 3, 4].map(n => document.getElementById('preview-mockup-nav-' + n));
    const wallpaperCanvas = document.getElementById('preview-mockup-wallpaper-canvas');
    const cursorEl = document.getElementById('preview-mockup-cursor');
    const badgeEl = document.getElementById('preview-mockup-badge');
    const hint = document.getElementById('preview-mockup-hint');
    if (!mockup) return;

    // Reset mockup to current loadout defaults
    mockup.style.background = '#0B0E1A';
    sidebar.style.display = '';
    content.style.display = '';
    content.style.padding = ''; // v12.2 — reset font-preview padding
    sidebar.style.background = 'rgba(10,13,23,0.85)';
    content.style.background = '#0B0E1A';
    heading.style.color = '#ffffff';
    // v12.1 — also reset font-family + sizing + letter-spacing so old font
    // preview values don't leak into the next item
    heading.style.fontFamily = '';
    heading.style.fontSize = '';
    heading.style.letterSpacing = '';
    heading.style.lineHeight = '';
    heading.style.marginBottom = '';
    text.style.fontFamily = '';
    text.style.fontSize = '';
    text.style.letterSpacing = '';
    text.style.lineHeight = '';
    text.style.color = '#c8ccd8';
    text.textContent = 'The quick brown fox jumps over the lazy dog.';
    heading.textContent = 'Sample Heading';
    bar1.style.background = 'rgba(108,92,231,0.6)';
    bar2.style.background = 'rgba(0,206,201,0.5)';
    navBars[0].style.background = 'rgba(255,255,255,0.18)';
    if (wallpaperCanvas) { wallpaperCanvas.style.display = 'none'; }
    if (cursorEl) { cursorEl.style.display = 'none'; cursorEl.innerHTML = ''; }
    if (badgeEl) { badgeEl.style.display = 'none'; badgeEl.innerHTML = ''; }
    if (window._previewMockupAnimFrame) {
        cancelAnimationFrame(window._previewMockupAnimFrame);
        clearTimeout(window._previewMockupAnimFrame);
        window._previewMockupAnimFrame = null;
    }
    const __oldEffectLayer = document.getElementById('preview-effect-layer');
    if (__oldEffectLayer) __oldEffectLayer.remove();

    // Apply user's CURRENT loadout to mockup first (so they see THEIR setup + the new item)
    const currentTheme = (userLoadout && userLoadout.theme) || 'default';
    const themeObj = (SHOP_ITEMS && SHOP_ITEMS.themes) ? SHOP_ITEMS.themes.find(t => t.id === currentTheme) : null;
    if (themeObj && themeObj.accent && themeObj.grad) {
        // Apply current theme accent to mockup elements
        bar1.style.background = `linear-gradient(90deg, ${themeObj.accent}, ${themeObj.grad})`;
        bar2.style.background = themeObj.accent;
        navBars[0].style.background = themeObj.accent;
    }

    if (category === 'theme') {
        // Overwrite with PREVIEW theme's colors
        if (item.accent && item.grad) {
            bar1.style.background = `linear-gradient(90deg, ${item.accent}, ${item.grad})`;
            bar2.style.background = item.accent;
            navBars[0].style.background = `linear-gradient(90deg, ${item.accent}, ${item.grad})`;
            sidebar.style.background = `linear-gradient(180deg, rgba(10,13,23,0.95), ${item.grad}22)`;
        }
        hint.textContent = `${item.name} accent applied to sidebar, buttons, and highlights.`;
    } else if (category === 'wallpaper') {
        // v11.0 — fixed canvas size (modal isn't visible yet so clientWidth was 0,
        // which broke the wallpaper preview entirely). Aspect-ratio matches mockup 16:9.
        if (wallpaperCanvas) {
            wallpaperCanvas.style.display = 'block';
            wallpaperCanvas.width = 480;
            wallpaperCanvas.height = 270;
            renderMiniWallpaper(wallpaperCanvas, item.id);
            // Make panels semi-transparent so wallpaper shows through
            sidebar.style.background = 'rgba(10,13,23,0.55)';
            content.style.background = 'rgba(11,14,26,0.45)';
        }
        hint.textContent = `${item.name} wallpaper rendered behind your panels.`;
    } else if (category === 'cursor') {
        // v11.0 — hide the mockup chrome for cursor previews; show ONLY the magnified
        // cursor on a clean dark background so nothing overlaps the SVG art.
        sidebar.style.display = 'none';
        content.style.display = 'none';
        mockup.style.background = 'radial-gradient(circle at 50% 50%, #1a1f33 0%, #05060d 100%)';
        if (cursorEl) {
            cursorEl.style.display = 'block';
            cursorEl.innerHTML = getCursorPreviewSVG(item.id, 200);
        }
        hint.textContent = `${item.name} cursor (shown magnified for detail).`;
    } else if (category === 'font') {
        const fontFamilies = {
            default:     "'Inter', system-ui, sans-serif",
            mono:        "'Fira Code', 'Cascadia Code', monospace",
            serif:       "'Cormorant Garamond', Georgia, serif",
            rounded:     "'Quicksand', system-ui, sans-serif",
            condensed:   "'Oswald', 'Arial Narrow', sans-serif",
            handwriting: "'Dancing Script', cursive",
            typewriter:  "'Courier Prime', 'Courier New', monospace",
            newspaper:   "'Playfair Display', serif",
            pixel:       "'Press Start 2P', monospace",
            futuristic:  "'Orbitron', 'Arial Black', sans-serif",
            gothic:      "'UnifrakturMaguntia', serif",
            elegant:     "'Playfair Display', serif",
            chalk:       "'Caveat', cursive",
            'comic-pro': "'Bangers', cursive"
        };
        const fam = fontFamilies[item.id] || 'inherit';
        // v12.2 — Font previews were still too cramped. Now: heading goes BIG
        // (3rem) with generous letter-spacing, body bumps to 1.4rem with 1.9
        // line-height. Pixel/Gothic/Comic display fonts get an extra +0.5rem
        // bump because their default sizes render small. Hide the mockup
        // sidebar/chrome so the font has the entire panel as a stage.
        sidebar.style.display = 'none';
        const tinyDisplayFonts = new Set(['pixel', 'gothic', 'comic-pro', 'chalk']);
        const headingSize = tinyDisplayFonts.has(item.id) ? '3.6rem' : '3rem';
        const bodySize    = tinyDisplayFonts.has(item.id) ? '1.55rem' : '1.4rem';
        heading.style.fontFamily = fam;
        heading.style.fontSize = headingSize;
        heading.style.letterSpacing = '1px';
        heading.style.lineHeight = '1.2';
        heading.style.marginBottom = '20px';
        heading.style.color = '#ffffff';
        text.style.fontFamily = fam;
        text.style.color = '#ffffff';
        text.style.fontSize = bodySize;
        text.style.lineHeight = '1.9';
        text.style.letterSpacing = '0.5px';
        heading.textContent = 'Sample Heading';
        text.textContent = 'The quick brown fox jumps over the lazy dog. 1234567890';
        // Restyle the content container so the font takes the whole stage
        content.style.padding = '40px';
        content.style.background = 'linear-gradient(135deg, #0B0E1A 0%, #16193a 100%)';
        hint.textContent = `${item.name} — applied to every heading and body line in the app.`;
    } else if (category === 'badge') {
        const badgeEmojis = {
            'night-owl': '🌙', 'speedster': '⚡', 'quiz-master': '🏆', 'streak-king': '🔥',
            'scholar': '🎓', 'diamond': '💎', 'champion': '👑', 'nexus-emblem': '🔮'
        };
        if (badgeEl) {
            badgeEl.style.display = 'block';
            badgeEl.innerHTML = badgeEmojis[item.id] || '🏅';
        }
        hint.textContent = `${item.name} pinned next to your profile.`;
    } else if (category === 'effect') {
        // v12.0 — real effect preview: simulate clicks/cursor sweeps inside the mockup
        // so the user can see what they're buying instead of just reading copy.
        const isTrail = ['particles','fire-trail','sparkle-trail','petal-trail','butterfly-trail','nexus-aura'].includes(item.id);
        const isContinuous = item.id === 'snowfall' || item.id === 'glow';
        text.textContent = isTrail ? '(cursor trail enabled — move your mouse)' : isContinuous ? `(${item.id === 'glow' ? 'hover halo' : 'continuous ambient'})` : '(click animation enabled)';
        hint.textContent = isTrail
            ? `${item.name} follows your cursor as you move.`
            : isContinuous
                ? `${item.name} runs continuously in the background.`
                : `${item.name} fires on every click anywhere in the app.`;
        // Run a looping demo INSIDE the mockup frame
        const demoLayer = document.createElement('div');
        demoLayer.id = 'preview-effect-layer';
        demoLayer.style.cssText = 'position:absolute;inset:0;pointer-events:none;overflow:hidden;border-radius:8px;';
        mockup.style.position = 'relative';
        const old = document.getElementById('preview-effect-layer');
        if (old) old.remove();
        mockup.appendChild(demoLayer);

        function fakeClick(x, y) {
            // Spawn a small dot to mark the click site
            const dot = document.createElement('div');
            dot.style.cssText = `position:absolute;left:${x-4}px;top:${y-4}px;width:8px;height:8px;border-radius:50%;background:rgba(255,255,255,0.55);box-shadow:0 0 10px rgba(255,255,255,0.7);transition:opacity 0.6s;`;
            demoLayer.appendChild(dot);
            setTimeout(() => { dot.style.opacity = '0'; }, 250);
            setTimeout(() => dot.remove(), 700);
            // Emit effect-specific particles from x,y
            _spawnEffectParticles(item.id, x, y, demoLayer);
        }
        function fakeTrail(x, y) {
            _spawnTrailParticles(item.id, x, y, demoLayer);
        }

        const tick = () => {
            const rect = mockup.getBoundingClientRect();
            const w = rect.width, h = rect.height;
            const t = performance.now() / 1000;
            if (isTrail) {
                // Cursor traces a slow figure-8
                const cx = w/2 + Math.sin(t * 1.1) * (w * 0.32);
                const cy = h/2 + Math.sin(t * 1.7) * (h * 0.28);
                fakeTrail(cx, cy);
            } else if (item.id === 'snowfall') {
                const flake = document.createElement('div');
                const size = Math.random() * 6 + 3;
                flake.style.cssText = `position:absolute;left:${Math.random()*w}px;top:-8px;width:${size}px;height:${size}px;background:radial-gradient(circle,#fff,rgba(220,230,255,0.4));border-radius:50%;box-shadow:0 0 4px rgba(255,255,255,0.6);transition:top 4s linear, opacity 4s linear;`;
                demoLayer.appendChild(flake);
                requestAnimationFrame(() => { flake.style.top = (h + 10) + 'px'; flake.style.opacity = '0.4'; });
                setTimeout(() => flake.remove(), 4200);
            } else if (item.id === 'glow') {
                // Pulse a soft halo in the middle
                const halo = document.createElement('div');
                halo.style.cssText = `position:absolute;left:${w/2 - 60}px;top:${h/2 - 60}px;width:120px;height:120px;border-radius:50%;background:radial-gradient(circle, rgba(0,206,201,0.4) 0%, transparent 70%);transition:opacity 1.2s ease-in-out, transform 1.2s;`;
                demoLayer.appendChild(halo);
                requestAnimationFrame(() => { halo.style.opacity = '0'; halo.style.transform = 'scale(1.6)'; });
                setTimeout(() => halo.remove(), 1400);
            } else {
                // Click demo: random spot inside the mockup
                const x = w * (0.18 + Math.random() * 0.64);
                const y = h * (0.22 + Math.random() * 0.55);
                fakeClick(x, y);
            }
            window._previewMockupAnimFrame = setTimeout(tick, isTrail ? 80 : 1100);
        };
        tick();
    } else if (category === 'companion') {
        const svg = (typeof getCompanionAvatarSVG === 'function') ? getCompanionAvatarSVG(item.id, 110) : '';
        if (cursorEl) {
            cursorEl.style.display = 'block';
            cursorEl.style.filter = '';
            cursorEl.innerHTML = svg || '🤖';
        }
        hint.textContent = `${item.name} will walk across your dashboard.`;
    }
}

// v12.0 — particle spawners used by the EFFECT preview demo inside the mockup.
// These render into the demoLayer (absolutely positioned inside the mockup),
// so coordinates are LOCAL to the mockup, not viewport.
function _spawnEffectParticles(id, x, y, layer) {
    const addEl = (cssText, removeMs) => {
        const el = document.createElement('div');
        el.style.cssText = cssText;
        layer.appendChild(el);
        setTimeout(() => el.remove(), removeMs);
        return el;
    };
    if (id === 'ripple') {
        const r = addEl(`position:absolute;left:${x-10}px;top:${y-10}px;width:20px;height:20px;border:2px solid rgba(0,206,201,0.6);border-radius:50%;transition:all 0.6s ease-out;`, 700);
        requestAnimationFrame(() => { r.style.width = '80px'; r.style.height = '80px'; r.style.left = (x-40)+'px'; r.style.top = (y-40)+'px'; r.style.opacity = '0'; });
        return;
    }
    if (id === 'sparkle' || id === 'confetti') {
        const colors = id === 'confetti' ? ['#ff0','#f0f','#0ff','#f00','#0f0','#00f','#ff6b6b','#ffd700'] : ['#fff','#ffd700','#00cec9','#a29bfe'];
        const count = id === 'confetti' ? 10 : 6;
        for (let i = 0; i < count; i++) {
            const p = addEl(`position:absolute;left:${x}px;top:${y}px;width:5px;height:5px;background:${colors[Math.floor(Math.random()*colors.length)]};border-radius:50%;transition:all 0.8s ease-out;`, 900);
            requestAnimationFrame(() => { p.style.left = (x + (Math.random()-0.5)*80) + 'px'; p.style.top = (y + (Math.random()-0.5)*80 - 20) + 'px'; p.style.opacity = '0'; p.style.transform = 'scale(0)'; });
        }
        return;
    }
    if (id === 'bubbles') {
        for (let i = 0; i < 6; i++) {
            const size = Math.random() * 10 + 5;
            const b = addEl(`position:absolute;left:${x}px;top:${y}px;width:${size}px;height:${size}px;background:radial-gradient(circle at 30% 30%, rgba(255,255,255,0.8), rgba(150,220,255,0.3));border:1px solid rgba(200,240,255,0.5);border-radius:50%;transition:all 1.2s cubic-bezier(0.25,0.46,0.45,0.94);`, 1300);
            requestAnimationFrame(() => { b.style.top = (y - 80 - Math.random()*30) + 'px'; b.style.left = (x + (Math.random()-0.5)*40) + 'px'; b.style.opacity = '0'; });
        }
        return;
    }
    if (id === 'cherry-blossom') {
        const colors = ['#FFB6C1','#FF91A4','#FFC0CB','#FFD1DC'];
        for (let i = 0; i < 8; i++) {
            const p = addEl(`position:absolute;left:${x}px;top:${y}px;width:7px;height:4px;background:${colors[i%4]};border-radius:50% 0 50% 0;transition:all 1.2s ease-out;transform:rotate(${Math.random()*360}deg);`, 1300);
            const ang = Math.random() * Math.PI * 2;
            const dist = Math.random() * 60 + 20;
            requestAnimationFrame(() => { p.style.left = (x + Math.cos(ang)*dist) + 'px'; p.style.top = (y + Math.sin(ang)*dist + 30) + 'px'; p.style.opacity = '0'; p.style.transform = `rotate(${Math.random()*720}deg)`; });
        }
        return;
    }
    if (id === 'ink-splatter') {
        for (let i = 0; i < 7; i++) {
            const size = Math.random() * 10 + 4;
            const d = addEl(`position:absolute;left:${x}px;top:${y}px;width:${size}px;height:${size}px;background:#0a0a14;border-radius:${Math.random() > 0.5 ? '50%' : '40% 60% 50% 30%'};transition:all 0.6s cubic-bezier(0.25,0.46,0.45,0.94);`, 700);
            const ang = (Math.PI * 2 / 7) * i + Math.random()*0.4;
            const dist = Math.random() * 40 + 14;
            requestAnimationFrame(() => { d.style.left = (x + Math.cos(ang)*dist) + 'px'; d.style.top = (y + Math.sin(ang)*dist) + 'px'; d.style.opacity = '0.85'; });
            setTimeout(() => { d.style.opacity = '0'; }, 350);
        }
        return;
    }
    if (id === 'starburst') {
        for (let i = 0; i < 8; i++) {
            const angle = (Math.PI * 2 / 8) * i;
            const ray = addEl(`position:absolute;left:${x}px;top:${y}px;width:2px;height:36px;background:linear-gradient(to bottom,#FFD700,transparent);transform-origin:top center;transform:rotate(${angle*180/Math.PI}deg);box-shadow:0 0 8px #FFD700;transition:all 0.5s ease-out;`, 550);
            requestAnimationFrame(() => { ray.style.height = '60px'; ray.style.opacity = '0'; });
        }
        return;
    }
    if (id === 'shockwave') {
        for (let i = 0; i < 2; i++) {
            const ring = addEl(`position:absolute;left:${x-5}px;top:${y-5}px;width:10px;height:10px;border:2px solid rgba(0,206,201,0.85);border-radius:50%;box-shadow:0 0 12px #00cec9;transition:all 0.6s ease-out;`, 700 + i*150);
            const delay = i * 130;
            setTimeout(() => { ring.style.width = '110px'; ring.style.height = '110px'; ring.style.left = (x - 55) + 'px'; ring.style.top = (y - 55) + 'px'; ring.style.opacity = '0'; ring.style.borderWidth = '1px'; }, delay);
        }
        return;
    }
    if (id === 'butterflies') {
        const colors = ['#FFD700','#FF69B4','#7c4dff','#00cec9'];
        for (let i = 0; i < 3; i++) {
            const b = addEl(`position:absolute;left:${x}px;top:${y}px;font-size:14px;transition:all 1.3s cubic-bezier(0.25,0.46,0.45,0.94);color:${colors[i]};`, 1400);
            b.textContent = '🦋';
            const ang = Math.random() * Math.PI * 2;
            const dist = Math.random() * 70 + 30;
            requestAnimationFrame(() => { b.style.left = (x + Math.cos(ang)*dist) + 'px'; b.style.top = (y + Math.sin(ang)*dist - 20) + 'px'; b.style.opacity = '0'; b.style.transform = `rotate(${Math.random()*360}deg)`; });
        }
        return;
    }
    if (id === 'aurora-veil') {
        const hues = ['#00ff88','#00cec9','#7c4dff','#bb99ff','#ff6b9d'];
        for (let i = 0; i < 5; i++) {
            const r = addEl(`position:absolute;left:${x-30}px;top:${y-20}px;width:60px;height:5px;background:linear-gradient(90deg,transparent,${hues[i%5]},transparent);border-radius:3px;filter:blur(1.5px);transition:all 1.1s cubic-bezier(0.25,0.46,0.45,0.94);transform:rotate(${Math.random()*40-20}deg);`, 1200);
            requestAnimationFrame(() => { r.style.left = (x - 30 + (Math.random()-0.5)*60) + 'px'; r.style.top = (y - 40 - i*8) + 'px'; r.style.opacity = '0'; r.style.width = '120px'; });
        }
        return;
    }
    if (id === 'galaxy-burst') {
        const colors = ['#aa77ff','#7c4dff','#bb99ff','#ffffff'];
        for (let i = 0; i < 12; i++) {
            const p = addEl(`position:absolute;left:${x}px;top:${y}px;width:4px;height:4px;background:${colors[i%4]};border-radius:50%;box-shadow:0 0 6px currentColor;transition:all 1.1s cubic-bezier(0.25,0.46,0.45,0.94);`, 1200);
            const ang = (Math.PI * 2 / 12) * i + i * 0.3;
            const dist = 24 + i * 4;
            requestAnimationFrame(() => { p.style.left = (x + Math.cos(ang)*dist) + 'px'; p.style.top = (y + Math.sin(ang)*dist) + 'px'; p.style.opacity = '0'; p.style.transform = 'scale(0)'; });
        }
        return;
    }
    if (id === 'phoenix-flame') {
        const hues = ['#FFD700','#ff8800','#ff3300','#aa0000'];
        for (let i = 0; i < 8; i++) {
            const f = addEl(`position:absolute;left:${x}px;top:${y}px;width:6px;height:9px;background:${hues[i%4]};border-radius:50% 0 50% 0;box-shadow:0 0 6px ${hues[i%4]};transition:all 1.3s cubic-bezier(0.25,0.46,0.45,0.94);transform:rotate(${Math.random()*360}deg);`, 1400);
            const drift = (Math.random()-0.5) * 80;
            requestAnimationFrame(() => { f.style.left = (x + drift) + 'px'; f.style.top = (y - 80 - Math.random()*40) + 'px'; f.style.opacity = '0'; f.style.transform = `rotate(${Math.random()*720}deg)`; });
        }
        return;
    }
    if (id === 'lightning') {
        for (let i = 0; i < 3; i++) {
            const angle = Math.random() * 360, length = Math.random() * 45 + 30;
            const bolt = addEl(`position:absolute;left:${x}px;top:${y}px;width:2px;height:${length}px;background:linear-gradient(to bottom,#00ffff,#7c4dff);transform-origin:top center;transform:rotate(${angle}deg);border-radius:2px;box-shadow:0 0 6px #00ffff,0 0 12px #7c4dff;transition:opacity 0.4s;`, 500);
            setTimeout(() => { bolt.style.opacity = '0'; }, 100);
        }
        return;
    }
    if (id === 'nexus-aura') {
        const colors = ['#00fff5','#7c4dff','#bb99ff','#00cec9'];
        for (let i = 0; i < 8; i++) {
            const p = addEl(`position:absolute;left:${x}px;top:${y}px;width:5px;height:5px;background:${colors[Math.floor(Math.random()*colors.length)]};border-radius:50%;box-shadow:0 0 6px currentColor;transition:all 0.8s cubic-bezier(0.25,0.46,0.45,0.94);`, 900);
            const angle = (Math.PI * 2 / 8) * i;
            const dist = Math.random() * 60 + 30;
            requestAnimationFrame(() => { p.style.left = (x + Math.cos(angle)*dist) + 'px'; p.style.top = (y + Math.sin(angle)*dist) + 'px'; p.style.opacity = '0'; p.style.transform = 'scale(0)'; });
        }
        return;
    }
}

function _spawnTrailParticles(id, x, y, layer) {
    const addEl = (cssText, removeMs) => {
        const el = document.createElement('div');
        el.style.cssText = cssText;
        layer.appendChild(el);
        setTimeout(() => el.remove(), removeMs);
        return el;
    };
    if (id === 'sparkle-trail') {
        if (Math.random() > 0.5) return;
        const colors = ['#ffffff','#ffd700','#a29bfe','#74b9ff'];
        const size = Math.random() * 4 + 3;
        const s = addEl(`position:absolute;left:${x}px;top:${y}px;width:${size}px;height:${size}px;background:${colors[Math.floor(Math.random()*colors.length)]};border-radius:50%;box-shadow:0 0 6px currentColor;transition:all 0.6s cubic-bezier(0.25,0.46,0.45,0.94);`, 700);
        requestAnimationFrame(() => { s.style.opacity = '0'; s.style.transform = `translate(${(Math.random()-0.5)*30}px,${(Math.random()-0.5)*30 - 6}px) scale(0)`; });
        return;
    }
    if (id === 'petal-trail') {
        if (Math.random() > 0.55) return;
        const colors = ['#FFB6C1','#FF91A4','#FFC0CB','#FFD1DC'];
        const p = addEl(`position:absolute;left:${x}px;top:${y}px;width:7px;height:4px;background:${colors[Math.floor(Math.random()*4)]};border-radius:50% 0 50% 0;transition:all 1.2s ease-out;transform:rotate(${Math.random()*360}deg);`, 1300);
        const drift = (Math.random()-0.5) * 40;
        requestAnimationFrame(() => { p.style.left = (x + drift) + 'px'; p.style.top = (y + 40 + Math.random()*20) + 'px'; p.style.opacity = '0'; p.style.transform = `rotate(${Math.random()*720}deg)`; });
        return;
    }
    if (id === 'butterfly-trail') {
        if (Math.random() > 0.8) return;
        const colors = ['#FFD700','#FF69B4','#7c4dff','#00cec9'];
        const b = addEl(`position:absolute;left:${x}px;top:${y}px;font-size:13px;transition:all 1.2s cubic-bezier(0.25,0.46,0.45,0.94);color:${colors[Math.floor(Math.random()*4)]};`, 1300);
        b.textContent = '🦋';
        const ang = Math.random() * Math.PI * 2;
        const dist = Math.random() * 50 + 20;
        requestAnimationFrame(() => { b.style.left = (x + Math.cos(ang)*dist) + 'px'; b.style.top = (y + Math.sin(ang)*dist - 14) + 'px'; b.style.opacity = '0'; b.style.transform = `rotate(${Math.random()*360}deg)`; });
        return;
    }
    if (id === 'particles') {
        if (Math.random() > 0.6) return;
        const p = addEl(`position:absolute;left:${x}px;top:${y}px;width:4px;height:4px;background:#a29bfe;border-radius:50%;transition:all 0.5s ease-out;`, 600);
        requestAnimationFrame(() => { p.style.opacity = '0'; p.style.transform = 'translateY(-20px) scale(0)'; });
        return;
    }
    if (id === 'fire-trail') {
        for (let i = 0; i < 2; i++) {
            const hue = Math.random() * 40 + 5;
            const size = Math.random() * 8 + 4;
            const ox = (Math.random()-0.5) * 8, oy = (Math.random()-0.5) * 8;
            const p = addEl(`position:absolute;left:${x+ox}px;top:${y+oy}px;width:${size}px;height:${size}px;background:hsl(${hue},100%,55%);border-radius:50%;box-shadow:0 0 ${size}px hsl(${hue},100%,50%);transition:all 0.8s ease-out;`, 900);
            const rise = -20 - Math.random() * 30;
            requestAnimationFrame(() => { p.style.opacity = '0'; p.style.transform = `translateY(${rise}px) scale(0)`; });
        }
        return;
    }
    if (id === 'nexus-aura') {
        if (Math.random() > 0.6) return;
        const colors = ['#00fff5','#7c4dff','#bb99ff'];
        const p = addEl(`position:absolute;left:${x + (Math.random()-0.5)*14}px;top:${y + (Math.random()-0.5)*14}px;width:3px;height:3px;background:${colors[Math.floor(Math.random()*colors.length)]};border-radius:50%;box-shadow:0 0 6px currentColor;transition:all 0.7s ease-out;`, 800);
        requestAnimationFrame(() => { p.style.opacity = '0'; p.style.transform = `translateY(${(Math.random()-0.5)*30}px) scale(0)`; });
        return;
    }
}

// Mini wallpaper renderer — lightweight static representations (NOT the full animations)
function renderMiniWallpaper(canvas, id) {
    const ctx = canvas.getContext('2d');
    const W = canvas.width, H = canvas.height;
    ctx.clearRect(0, 0, W, H);
    if (id === 'ocean-deep') id = 'underwater'; // v17.3 — merged
    if (id === 'gradient1') {
        const g = ctx.createLinearGradient(0, 0, W, H);
        g.addColorStop(0, '#1a0533'); g.addColorStop(0.5, '#2d1b69'); g.addColorStop(1, '#0a0a1a');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    } else if (id === 'gradient2') {
        const g = ctx.createLinearGradient(0, 0, W, H);
        g.addColorStop(0, '#1a0a00'); g.addColorStop(0.4, '#4a1a2e'); g.addColorStop(1, '#2d1b00');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    } else if (id === 'underwater') {
        // v12.1 — accurate-ish: actual has fish + bubbles + caustic light from above
        const g = ctx.createLinearGradient(0, 0, 0, H);
        g.addColorStop(0, '#1a4a7a'); g.addColorStop(1, '#000d1f');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
        // light caustics shimmer at top
        for (let i = 0; i < 8; i++) {
            const x = (i / 8) * W, y = H * 0.12 + Math.sin(i) * 6;
            const cg = ctx.createRadialGradient(x, y, 0, x, y, 24);
            cg.addColorStop(0, 'rgba(180,240,255,0.22)'); cg.addColorStop(1, 'transparent');
            ctx.fillStyle = cg; ctx.fillRect(x - 24, y - 24, 48, 48);
        }
        // 3 little fish silhouettes
        const fishColors = ['#ffd166', '#ff7a59', '#8de1ff'];
        fishColors.forEach((col, i) => {
            const fx = W * (0.2 + i * 0.3), fy = H * (0.4 + Math.sin(i) * 0.15);
            ctx.fillStyle = col;
            ctx.beginPath();
            ctx.ellipse(fx, fy, 8, 4, 0, 0, Math.PI * 2);
            ctx.fill();
            // tail
            ctx.beginPath();
            ctx.moveTo(fx - 8, fy);
            ctx.lineTo(fx - 13, fy - 4);
            ctx.lineTo(fx - 13, fy + 4);
            ctx.closePath();
            ctx.fill();
            // eye
            ctx.fillStyle = '#000';
            ctx.beginPath(); ctx.arc(fx + 4, fy - 1, 0.8, 0, Math.PI * 2); ctx.fill();
        });
        // bubbles
        for (let i = 0; i < 18; i++) { ctx.fillStyle = `rgba(150,220,255,${Math.random() * 0.5 + 0.2})`; ctx.beginPath(); ctx.arc(Math.random() * W, Math.random() * H, Math.random() * 2.5 + 0.8, 0, Math.PI * 2); ctx.fill(); }
    } else if (id === 'ocean-deep') {
        // v16.5 — deep abyss: dark gradient, a god ray, a glowing jellyfish, bioluminescent motes
        const g = ctx.createLinearGradient(0, 0, 0, H);
        g.addColorStop(0, '#062a4a'); g.addColorStop(0.4, '#03162e'); g.addColorStop(1, '#00040c');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
        // god ray
        const rg = ctx.createLinearGradient(0, 0, 0, H * 0.7); rg.addColorStop(0, 'rgba(90,180,230,0.14)'); rg.addColorStop(1, 'transparent');
        ctx.fillStyle = rg;
        ctx.beginPath(); ctx.moveTo(W * 0.32, 0); ctx.lineTo(W * 0.42, 0); ctx.lineTo(W * 0.5, H * 0.7); ctx.lineTo(W * 0.3, H * 0.7); ctx.closePath(); ctx.fill();
        // jellyfish
        const jx = W * 0.66, jy = H * 0.42, js = 16;
        const jg = ctx.createRadialGradient(jx, jy, 0, jx, jy, js * 2);
        jg.addColorStop(0, 'hsla(280,90%,70%,0.30)'); jg.addColorStop(1, 'transparent');
        ctx.fillStyle = jg; ctx.beginPath(); ctx.arc(jx, jy, js * 2, 0, Math.PI * 2); ctx.fill();
        ctx.fillStyle = 'hsla(280,90%,78%,0.55)';
        ctx.beginPath(); ctx.ellipse(jx, jy, js, js * 0.8, 0, Math.PI, 0); ctx.fill();
        ctx.strokeStyle = 'hsla(280,80%,75%,0.5)'; ctx.lineWidth = 1;
        for (let k = -2; k <= 2; k++) {
            ctx.beginPath(); ctx.moveTo(jx + k * 3, jy + js * 0.4);
            for (let s = 1; s <= 3; s++) ctx.lineTo(jx + k * 3 + Math.sin(k + s) * 3, jy + js * 0.4 + s * 6);
            ctx.stroke();
        }
        // bioluminescent motes
        for (let i = 0; i < 26; i++) {
            const mx = Math.random() * W, my = Math.random() * H, mr = Math.random() * 1.4 + 0.5;
            const hue = [180, 190, 200, 160][i % 4];
            const a = Math.random() * 0.5 + 0.3;
            const mg = ctx.createRadialGradient(mx, my, 0, mx, my, mr * 4);
            mg.addColorStop(0, `hsla(${hue},100%,78%,${a})`); mg.addColorStop(1, 'transparent');
            ctx.fillStyle = mg; ctx.beginPath(); ctx.arc(mx, my, mr * 4, 0, Math.PI * 2); ctx.fill();
        }
    } else if (id === 'neon-city') {
        var ng = ctx.createLinearGradient(0, 0, 0, H); ng.addColorStop(0, '#1a0b2e'); ng.addColorStop(1, '#05030f'); ctx.fillStyle = ng; ctx.fillRect(0, 0, W, H);
        var ncCols = ['#0b1530', '#0e1838', '#0a1226'];
        for (var nci = 0; nci < 9; nci++) {
            var nbw = W / 9, nbh = H * (0.3 + Math.random() * 0.5);
            ctx.fillStyle = ncCols[nci % 3]; ctx.fillRect(nci * nbw, H - nbh, nbw - 2, nbh);
            for (var nwy = H - nbh + 4; nwy < H - 3; nwy += 7) for (var nwx = nci * nbw + 3; nwx < nci * nbw + nbw - 4; nwx += 6) if (Math.random() > 0.45) { ctx.fillStyle = 'rgba(255,' + (180 + Math.random() * 60 | 0) + ',120,' + (Math.random() * 0.6 + 0.3) + ')'; ctx.fillRect(nwx, nwy, 2, 3); }
        }
        ctx.fillStyle = '#ff3df0'; ctx.fillRect(W * 0.15, H * 0.42, 18, 5); ctx.fillStyle = '#3df0ff'; ctx.fillRect(W * 0.62, H * 0.3, 14, 4);
        ctx.strokeStyle = 'rgba(150,200,255,0.25)'; ctx.lineWidth = 0.6;
        for (var nr = 0; nr < 30; nr++) { var nrx = Math.random() * W, nry = Math.random() * H; ctx.beginPath(); ctx.moveTo(nrx, nry); ctx.lineTo(nrx - 2, nry + 8); ctx.stroke(); }
    } else if (id === 'space-station') {
        ctx.fillStyle = '#02030a'; ctx.fillRect(0, 0, W, H);
        for (var ssi = 0; ssi < 60; ssi++) { ctx.fillStyle = 'rgba(255,255,255,' + Math.random() + ')'; ctx.beginPath(); ctx.arc(Math.random() * W, Math.random() * H * 0.85, Math.random() * 1.1 + 0.2, 0, Math.PI * 2); ctx.fill(); }
        var eg = ctx.createRadialGradient(W * 0.5, H * 1.25, H * 0.4, W * 0.5, H * 1.25, H * 0.95); eg.addColorStop(0, '#4aa3ff'); eg.addColorStop(0.6, '#1d5fae'); eg.addColorStop(1, '#0a2a55');
        ctx.fillStyle = eg; ctx.beginPath(); ctx.arc(W * 0.5, H * 1.25, H * 0.9, Math.PI, 2 * Math.PI); ctx.fill();
        ctx.strokeStyle = 'rgba(120,200,255,0.4)'; ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(W * 0.5, H * 1.25, H * 0.9, Math.PI, 2 * Math.PI); ctx.stroke();
        ctx.fillStyle = '#cfd8e3'; ctx.fillRect(W * 0.7, H * 0.25, 6, 3); ctx.fillStyle = '#3df0ff'; ctx.fillRect(W * 0.7 - 5, H * 0.24, 4, 5); ctx.fillRect(W * 0.7 + 7, H * 0.24, 4, 5);
    } else if (id === 'anime-library') {
        var lg = ctx.createLinearGradient(0, 0, 0, H); lg.addColorStop(0, '#2a1c0e'); lg.addColorStop(1, '#120a04'); ctx.fillStyle = lg; ctx.fillRect(0, 0, W, H);
        var moong = ctx.createRadialGradient(W * 0.5, H * 0.24, 2, W * 0.5, H * 0.24, 22); moong.addColorStop(0, '#ffe9a8'); moong.addColorStop(1, 'rgba(255,200,120,0.1)'); ctx.fillStyle = moong; ctx.beginPath(); ctx.arc(W * 0.5, H * 0.24, 20, 0, Math.PI * 2); ctx.fill();
        for (var lc = 0; lc < W; lc += 22) {
            ctx.fillStyle = '#3a2614'; ctx.fillRect(lc, H * 0.45, 20, H * 0.55);
            for (var lby = H * 0.46; lby < H - 2; lby += 10) { ctx.fillStyle = 'hsl(' + (Math.random() * 60 + 10) + ',50%,' + (30 + Math.random() * 25) + '%)'; ctx.fillRect(lc + 1, lby, 18, 8); }
        }
        for (var lk = 0; lk < 4; lk++) { var lcx = W * (0.2 + lk * 0.2); var cg = ctx.createRadialGradient(lcx, H * 0.4, 0, lcx, H * 0.4, 10); cg.addColorStop(0, 'rgba(255,200,120,0.6)'); cg.addColorStop(1, 'transparent'); ctx.fillStyle = cg; ctx.beginPath(); ctx.arc(lcx, H * 0.4, 10, 0, Math.PI * 2); ctx.fill(); }
    } else if (id === 'matrix') {
        ctx.fillStyle = '#000'; ctx.fillRect(0, 0, W, H);
        ctx.font = '8px monospace';
        for (let x = 0; x < W; x += 6) for (let y = 8; y < H; y += 10) {
            ctx.fillStyle = `rgba(0,${100 + Math.random() * 155},0,${Math.random() * 0.8 + 0.2})`;
            ctx.fillText(String.fromCharCode(0x30A0 + Math.random() * 96), x, y);
        }
    } else if (id === 'starfield') {
        // v12.1 — accurate-ish: matches the actual starfield (stars + ringed planet + a ship silhouette)
        ctx.fillStyle = '#02020a'; ctx.fillRect(0, 0, W, H);
        // nebula wisp
        const ng = ctx.createRadialGradient(W * 0.3, H * 0.4, 0, W * 0.3, H * 0.4, 80);
        ng.addColorStop(0, 'rgba(60,20,120,0.18)'); ng.addColorStop(1, 'transparent');
        ctx.fillStyle = ng; ctx.fillRect(0, 0, W, H);
        // ringed planet
        ctx.fillStyle = '#dcb670';
        ctx.beginPath(); ctx.arc(W * 0.78, H * 0.7, 18, 0, Math.PI * 2); ctx.fill();
        ctx.strokeStyle = '#e8c98e'; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.ellipse(W * 0.78, H * 0.7, 30, 7, 0.3, 0, Math.PI * 2); ctx.stroke();
        // small earth-like planet
        ctx.fillStyle = '#5d8aa8';
        ctx.beginPath(); ctx.arc(W * 0.18, H * 0.25, 10, 0, Math.PI * 2); ctx.fill();
        // tiny X-Wing silhouette
        ctx.fillStyle = '#cccccc';
        ctx.fillRect(W * 0.42, H * 0.55, 14, 2);
        ctx.fillRect(W * 0.48, H * 0.51, 2, 10);
        ctx.fillRect(W * 0.43, H * 0.5, 2, 12);
        ctx.fillRect(W * 0.55, H * 0.5, 2, 12);
        // stars
        for (let i = 0; i < 70; i++) { ctx.fillStyle = `rgba(255,255,255,${Math.random()})`; ctx.beginPath(); ctx.arc(Math.random() * W, Math.random() * H, Math.random() * 1.2 + 0.3, 0, Math.PI * 2); ctx.fill(); }
    } else if (id === 'aurora-bg') {
        const sky = ctx.createLinearGradient(0, 0, 0, H);
        sky.addColorStop(0, '#020310'); sky.addColorStop(1, '#06122a');
        ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
        for (let i = 0; i < 4; i++) {
            ctx.beginPath();
            ctx.moveTo(0, H * 0.3 + i * 4);
            for (let x = 0; x <= W; x += 4) ctx.lineTo(x, H * (0.25 + i * 0.04) + Math.sin(x * 0.04 + i) * 8);
            ctx.lineTo(W, H); ctx.lineTo(0, H); ctx.closePath();
            const c = [[0, 255, 100], [100, 255, 200], [80, 120, 255], [200, 100, 255]][i];
            ctx.fillStyle = `rgba(${c.join(',')},0.18)`; ctx.fill();
        }
    } else if (id === 'nebula') {
        const g = ctx.createRadialGradient(W * 0.5, H * 0.5, 0, W * 0.5, H * 0.5, Math.max(W, H));
        g.addColorStop(0, '#7c4dff'); g.addColorStop(0.4, '#3a1d6e'); g.addColorStop(1, '#020010');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
        for (let i = 0; i < 40; i++) { ctx.fillStyle = `rgba(255,255,255,${Math.random() * 0.7})`; ctx.beginPath(); ctx.arc(Math.random() * W, Math.random() * H, Math.random() * 1.5, 0, Math.PI * 2); ctx.fill(); }
    } else if (id === 'sakura') {
        const sky = ctx.createLinearGradient(0, 0, 0, H);
        sky.addColorStop(0, '#0a0612'); sky.addColorStop(1, '#1a0a20');
        ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
        // moon
        ctx.fillStyle = 'rgba(255,240,220,0.85)';
        ctx.beginPath(); ctx.arc(W * 0.78, H * 0.18, 14, 0, Math.PI * 2); ctx.fill();
        // tree silhouette
        ctx.fillStyle = '#3a1818';
        ctx.fillRect(W * 0.42, H * 0.45, 8, H * 0.55);
        ctx.fillStyle = '#ff91a4';
        ctx.beginPath(); ctx.arc(W * 0.46, H * 0.4, 28, 0, Math.PI * 2); ctx.fill();
        for (let i = 0; i < 30; i++) { ctx.fillStyle = `rgba(255,180,210,${Math.random() * 0.8 + 0.3})`; ctx.beginPath(); ctx.ellipse(Math.random() * W, Math.random() * H, 2.5, 1.2, Math.random() * Math.PI, 0, Math.PI * 2); ctx.fill(); }
    } else if (id === 'sakura-day') {
        const sky = ctx.createLinearGradient(0, 0, 0, H);
        sky.addColorStop(0, '#ffd2e0'); sky.addColorStop(1, '#bfe2ff');
        ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = 'rgba(255,250,230,0.95)';
        ctx.beginPath(); ctx.arc(W * 0.78, H * 0.25, 20, 0, Math.PI * 2); ctx.fill();
        for (let i = 0; i < 50; i++) { ctx.fillStyle = `rgba(255,140,180,${Math.random() * 0.7 + 0.3})`; ctx.beginPath(); ctx.ellipse(Math.random() * W, Math.random() * H, 2.5, 1.2, Math.random() * Math.PI, 0, Math.PI * 2); ctx.fill(); }
    } else if (id === 'sunny-meadow') {
        const sky = ctx.createLinearGradient(0, 0, 0, H * 0.6);
        sky.addColorStop(0, '#9fcfff'); sky.addColorStop(1, '#d6ecff');
        ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H * 0.6);
        ctx.fillStyle = '#7bbf6e'; ctx.fillRect(0, H * 0.55, W, H * 0.15);
        ctx.fillStyle = '#5fae54'; ctx.fillRect(0, H * 0.65, W, H * 0.35);
        ctx.fillStyle = 'rgba(255,228,150,0.85)';
        ctx.beginPath(); ctx.arc(W * 0.18, H * 0.18, 14, 0, Math.PI * 2); ctx.fill();
        // tiny barn
        ctx.fillStyle = '#a23838'; ctx.fillRect(W * 0.6, H * 0.55, 28, 22);
        ctx.fillStyle = '#7a1f1f';
        ctx.beginPath(); ctx.moveTo(W * 0.6 - 2, H * 0.55); ctx.lineTo(W * 0.6 + 14, H * 0.5); ctx.lineTo(W * 0.6 + 30, H * 0.55); ctx.closePath(); ctx.fill();
    } else if (id === 'beach-day') {
        // v12.1 — added wave detail + small palm-tree silhouette to match the actual
        const sky = ctx.createLinearGradient(0, 0, 0, H * 0.55);
        sky.addColorStop(0, '#dcc8a8'); sky.addColorStop(1, '#a9d8e6');
        ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H * 0.55);
        const sea = ctx.createLinearGradient(0, H * 0.55, 0, H * 0.78);
        sea.addColorStop(0, '#4cb5cb'); sea.addColorStop(1, '#1d6d8a');
        ctx.fillStyle = sea; ctx.fillRect(0, H * 0.55, W, H * 0.23);
        // wave crests
        ctx.strokeStyle = 'rgba(255,255,255,0.55)';
        ctx.lineWidth = 1.2;
        for (let i = 0; i < 4; i++) {
            ctx.beginPath();
            const y = H * (0.6 + i * 0.04);
            for (let x = 0; x <= W; x += 8) {
                const yy = y + Math.sin(x * 0.1 + i) * 1.5;
                if (x === 0) ctx.moveTo(x, yy); else ctx.lineTo(x, yy);
            }
            ctx.stroke();
        }
        const sand = ctx.createLinearGradient(0, H * 0.78, 0, H);
        sand.addColorStop(0, '#f0d8a8'); sand.addColorStop(1, '#d8b070');
        ctx.fillStyle = sand; ctx.fillRect(0, H * 0.78, W, H * 0.22);
        // sun
        ctx.fillStyle = '#fff0c8';
        ctx.beginPath(); ctx.arc(W * 0.5, H * 0.18, 16, 0, Math.PI * 2); ctx.fill();
        // small palm silhouette in the corner
        ctx.fillStyle = '#3a2616';
        ctx.fillRect(W * 0.85, H * 0.55, 2, H * 0.23);
        ctx.fillStyle = '#2d6a3a';
        for (let i = 0; i < 5; i++) {
            const ang = (Math.PI / 5) * i - 0.3;
            ctx.beginPath();
            ctx.ellipse(W * 0.85 + 1, H * 0.55, 14, 3, ang, 0, Math.PI * 2);
            ctx.fill();
        }
    } else if (id === 'spring-sky') {
        const sky = ctx.createLinearGradient(0, 0, 0, H);
        sky.addColorStop(0, '#9cc8e8'); sky.addColorStop(0.6, '#bcd9ec'); sky.addColorStop(1, '#dde9f1');
        ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
        for (let i = 0; i < 6; i++) {
            const cx = W * (0.1 + i * 0.16), cy = H * (0.15 + (i % 2) * 0.18);
            ctx.fillStyle = `rgba(255,255,255,${0.7 - (i % 3) * 0.1})`;
            ctx.beginPath(); ctx.ellipse(cx, cy, 22, 7, 0, 0, Math.PI * 2);
            ctx.ellipse(cx + 12, cy - 4, 16, 6, 0, 0, Math.PI * 2);
            ctx.fill();
        }
    } else if (id === 'ghibli-forest') {
        // v12.8 — Removed from shop. Draw a placeholder.
        ctx.fillStyle = '#1a1a22'; ctx.fillRect(0, 0, W, H);
        ctx.fillStyle = 'rgba(255,255,255,0.2)'; ctx.font = `${W*0.12}px sans-serif`;
        ctx.textAlign = 'center'; ctx.fillText('Retired', W/2, H/2);
        return;
        // v12.4 — Studio Ghibli forest thumbnail. Twilight sky, moon, deep canopy, Totoro + umbrella.
        const sky = ctx.createLinearGradient(0, 0, 0, H);
        sky.addColorStop(0, '#0e0a24'); sky.addColorStop(0.15, '#2b1e52');
        sky.addColorStop(0.32, '#b56c42'); sky.addColorStop(0.48, '#7aaa60');
        sky.addColorStop(0.68, '#3d6838'); sky.addColorStop(1, '#1c2e18');
        ctx.fillStyle = sky; ctx.fillRect(0, 0, W, H);
        // moon glow
        const mR = Math.min(W, H) * 0.06, mX = W * 0.14, mY2 = H * 0.14;
        const mHalo = ctx.createRadialGradient(mX, mY2, 0, mX, mY2, mR * 4);
        mHalo.addColorStop(0, 'rgba(255,248,210,0.25)'); mHalo.addColorStop(1, 'rgba(255,248,210,0)');
        ctx.fillStyle = mHalo; ctx.fillRect(0, 0, W, H);
        const mDisc = ctx.createRadialGradient(mX - mR*0.2, mY2 - mR*0.2, 0, mX, mY2, mR);
        mDisc.addColorStop(0, '#ffffe8'); mDisc.addColorStop(1, '#e8cc60');
        ctx.fillStyle = mDisc; ctx.beginPath(); ctx.arc(mX, mY2, mR, 0, Math.PI * 2); ctx.fill();
        // stars
        for (let i = 0; i < 18; i++) {
            ctx.fillStyle = `rgba(255,252,235,${0.3 + Math.sin(i*1.7)*0.3})`;
            ctx.beginPath(); ctx.arc((W*0.08+i*W*0.05+Math.sin(i*2)*W*0.1)%(W*0.9), (H*0.02+i*H*0.014+Math.cos(i*1.9)*H*0.07)%(H*0.3), 0.9, 0, Math.PI*2); ctx.fill();
        }
        // distant hills
        ctx.fillStyle = 'rgba(55,42,85,0.35)';
        ctx.beginPath(); ctx.moveTo(0, H*0.52);
        for (let x = 0; x <= W; x += 16) ctx.lineTo(x, H*0.52 - Math.sin(x*0.012+1.4)*H*0.09 - Math.sin(x*0.028)*H*0.025);
        ctx.lineTo(W,H); ctx.lineTo(0,H); ctx.closePath(); ctx.fill();
        // far canopy
        ctx.fillStyle = 'rgba(115,165,110,0.4)';
        for (let x = -30; x < W+30; x += 36) { ctx.beginPath(); ctx.arc(x, H*0.43 + Math.sin(x*0.015)*H*0.03, H*0.12, 0, Math.PI*2); ctx.fill(); }
        // mid trees
        ctx.fillStyle = '#3a5e3c';
        for (let i = 0; i < 7; i++) {
            const tx = W*(i/6), by = H*0.52;
            ctx.fillRect(tx-4, by, 8, H*0.48);
            ctx.beginPath(); ctx.arc(tx, by, H*0.12, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = '#2c4e2e'; ctx.beginPath(); ctx.arc(tx, by+H*0.04, H*0.085, 0, Math.PI*2); ctx.fill();
            ctx.fillStyle = '#3a5e3c';
        }
        // Totoro with umbrella (static)
        const S = Math.min(W, H) * 0.072, tX = W * 0.5, tY = H * 0.82;
        const dR2 = S * 0.95, dCy2 = tY - S * 1.88;
        ctx.strokeStyle = '#1e1e26'; ctx.lineWidth = Math.max(1.5, S*0.07);
        ctx.beginPath(); ctx.moveTo(tX + S*0.1, tY - S*0.42); ctx.lineTo(tX + S*0.05, dCy2); ctx.stroke();
        ctx.fillStyle = 'rgba(24,24,38,0.88)';
        ctx.beginPath(); ctx.arc(tX, dCy2, dR2, Math.PI, 0); ctx.closePath(); ctx.fill();
        ctx.fillStyle = 'rgba(20,20,34,0.94)';
        for (let s = 0; s <= 5; s++) { const scx = (tX - dR2*0.92)+s*(dR2*1.84/5); ctx.beginPath(); ctx.arc(scx, dCy2, dR2*0.13, 0, Math.PI); ctx.closePath(); ctx.fill(); }
        ctx.fillStyle = '#2c2c34'; ctx.beginPath(); ctx.ellipse(tX, tY, S*0.8, S, 0, 0, Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.moveTo(tX-S*0.42,tY-S*0.72); ctx.lineTo(tX-S*0.24,tY-S*1.5); ctx.lineTo(tX-S*0.08,tY-S*0.78); ctx.closePath(); ctx.fill();
        ctx.beginPath(); ctx.moveTo(tX+S*0.08,tY-S*0.78); ctx.lineTo(tX+S*0.24,tY-S*1.5); ctx.lineTo(tX+S*0.42,tY-S*0.72); ctx.closePath(); ctx.fill();
        ctx.fillStyle = '#cdd1c2'; ctx.beginPath(); ctx.ellipse(tX, tY+S*0.2, S*0.47, S*0.6, 0, 0, Math.PI*2); ctx.fill();
        ctx.fillStyle = '#fff';
        ctx.beginPath(); ctx.arc(tX-S*0.27,tY-S*0.3,S*0.13,0,Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(tX+S*0.27,tY-S*0.3,S*0.13,0,Math.PI*2); ctx.fill();
        ctx.fillStyle = '#1a1a20'; ctx.beginPath(); ctx.arc(tX-S*0.25,tY-S*0.3,S*0.06,0,Math.PI*2); ctx.fill();
        ctx.beginPath(); ctx.arc(tX+S*0.25,tY-S*0.3,S*0.06,0,Math.PI*2); ctx.fill();
        // foreground trees (dark)
        ctx.fillStyle = 'rgba(14,22,13,0.95)';
        for (let i = 0; i < 5; i++) { const fx = W*(i/4); ctx.fillRect(fx-10, H*0.6, 20, H*0.4); ctx.beginPath(); ctx.arc(fx, H*0.6, H*0.2, 0, Math.PI*2); ctx.fill(); }
        // fireflies
        for (let i = 0; i < 18; i++) {
            const fx2 = (W*0.1+i*W*0.052+Math.sin(i*1.3)*W*0.15)%(W*0.95), fy = (H*0.15+i*H*0.045+Math.cos(i*2.1)*H*0.1)%(H*0.72);
            const fa2 = 0.4 + Math.sin(i*0.8)*0.35;
            const ffG2 = ctx.createRadialGradient(fx2, fy, 0, fx2, fy, 6);
            ffG2.addColorStop(0, `rgba(255,240,140,${fa2*0.6})`); ffG2.addColorStop(1, 'rgba(255,240,140,0)');
            ctx.fillStyle = ffG2; ctx.fillRect(fx2-6, fy-6, 12, 12);
            ctx.fillStyle = `rgba(255,252,180,${fa2})`; ctx.beginPath(); ctx.arc(fx2, fy, 1.4, 0, Math.PI*2); ctx.fill();
        }
    } else if (id === 'nexus-void') {
        // v12.1 — accurate: matches the v11 "Dimensional Rift" rebuild — hex portal
        // at center + drifting glyphs + cyan aurora ribbons + constellation grid
        const g = ctx.createRadialGradient(W / 2, H / 2, 0, W / 2, H / 2, Math.max(W, H));
        g.addColorStop(0, '#0a0419'); g.addColorStop(0.5, '#04031a'); g.addColorStop(1, '#01010a');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
        // cyan aurora ribbon sweeping the bg
        for (let i = 0; i < 3; i++) {
            ctx.beginPath();
            ctx.moveTo(0, H * (0.3 + i * 0.2));
            for (let x = 0; x <= W; x += 4) ctx.lineTo(x, H * (0.3 + i * 0.2) + Math.sin(x * 0.05 + i) * 6);
            ctx.lineTo(W, H * (0.4 + i * 0.2));
            ctx.lineTo(0, H * (0.4 + i * 0.2));
            ctx.closePath();
            ctx.fillStyle = `rgba(0,${100 + i * 50},${200 + i * 20},0.08)`;
            ctx.fill();
        }
        // constellation grid (faint cyan dots)
        for (let i = 0; i < 30; i++) {
            ctx.fillStyle = `rgba(0,200,200,${Math.random() * 0.3 + 0.1})`;
            ctx.beginPath(); ctx.arc(Math.random() * W, Math.random() * H, 0.8, 0, Math.PI * 2); ctx.fill();
        }
        // hexagonal portal — 4 stacked rotating layers
        const cx = W / 2, cy = H / 2;
        for (let layer = 0; layer < 3; layer++) {
            const r = 24 + layer * 6;
            const rot = layer * 0.25;
            ctx.strokeStyle = `hsla(${200 + layer * 30}, 80%, 65%, ${0.6 - layer * 0.12})`;
            ctx.lineWidth = 1.5;
            ctx.beginPath();
            for (let i = 0; i <= 6; i++) {
                const a = (Math.PI * 2 / 6) * i + rot;
                const x = cx + Math.cos(a) * r, y = cy + Math.sin(a) * r;
                if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y);
            }
            ctx.stroke();
        }
        // drifting glyphs (λ Σ π ∞)
        const glyphs = ['λ', 'Σ', 'π', '∞', '◈'];
        ctx.font = '11px monospace';
        glyphs.forEach((gl, i) => {
            ctx.fillStyle = `hsla(${180 + i * 30}, 90%, 70%, 0.55)`;
            ctx.fillText(gl, W * (0.1 + i * 0.18), H * (0.25 + Math.sin(i) * 0.4));
        });
        // center NEXUS pulse
        ctx.fillStyle = '#00fff5';
        ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
    } else {
        // Fallback — show a clean gradient
        const g = ctx.createLinearGradient(0, 0, W, H);
        g.addColorStop(0, '#0B0E1A'); g.addColorStop(1, '#1a1f33');
        ctx.fillStyle = g; ctx.fillRect(0, 0, W, H);
    }
}

