function renderInventoryTab(container) {
    if (userInventory.length === 0) {
        container.innerHTML = `
            <div style="text-align:center;padding:60px 20px;">
                <div style="font-size:1.4rem;margin-bottom:16px;opacity:0.3;">📦</div>
                <h3 style="margin-bottom:8px;color:var(--text-muted);">Your Inventory is Empty</h3>
                <p style="color:var(--text-muted);font-size:0.9rem;">Visit the shop tabs to purchase customization items!</p>
            </div>
        `;
        return;
    }

    // Get all items from all categories
    const allItems = [
        ...SHOP_ITEMS.themes,
        ...SHOP_ITEMS.cursors,
        ...SHOP_ITEMS.fonts,
        ...SHOP_ITEMS.wallpapers,
        ...SHOP_ITEMS.badges,
        ...SHOP_ITEMS.effects
    ];

    // Filter items user owns
    const ownedItems = userInventory.map(itemId => {
        const item = allItems.find(i => i.id === itemId);
        if (!item) return null;

        let category = 'theme';
        if (SHOP_ITEMS.cursors.some(i => i.id === itemId)) category = 'cursor';
        else if (SHOP_ITEMS.fonts.some(i => i.id === itemId)) category = 'font';
        else if (SHOP_ITEMS.wallpapers.some(i => i.id === itemId)) category = 'wallpaper';
        else if (SHOP_ITEMS.badges.some(i => i.id === itemId)) category = 'badge';
        else if (SHOP_ITEMS.effects.some(i => i.id === itemId)) category = 'effect';

        return { ...item, category };
    }).filter(Boolean);

    // Sort by rarity (legendary first)
    const rarityOrder = { legendary: 0, epic: 1, rare: 2, common: 3 };
    ownedItems.sort((a, b) => rarityOrder[a.rarity] - rarityOrder[b.rarity]);

    // Rarity colors
    const rarityColors = {
        common: '#9ca3af',
        rare: '#60a5fa',
        epic: '#a855f7',
        legendary: '#fbbf24',
        nexus: '#00fff5',
        mythic: '#ff4d8d'
    };

    // Create grid
    const gridContainer = document.createElement('div');
    gridContainer.style.cssText = 'display:grid;grid-template-columns:repeat(auto-fill,minmax(200px,1fr));gap:12px;padding:4px;';

    ownedItems.forEach(item => {
        const isEquipped = Object.values(userLoadout).includes(item.id);
        const rarityColor = rarityColors[item.rarity] || rarityColors.common;

        const card = document.createElement('div');
        card.style.cssText = `
            background:rgba(255,255,255,0.03);
            border:2px solid ${rarityColor};
            border-radius:10px;
            padding:12px;
            display:flex;
            flex-direction:column;
            gap:12px;
            transition:all 0.2s ease;
        `;
        card.onmouseenter = () => { card.style.transform = 'translateY(-2px)'; card.style.boxShadow = `0 4px 16px ${rarityColor}40`; };
        card.onmouseleave = () => { card.style.transform = 'translateY(0)'; card.style.boxShadow = 'none'; };

        card.innerHTML = `
            <div style="display:flex;justify-content:space-between;align-items:start;">
                <div style="background:${rarityColor};color:#000;font-size:0.88rem;font-weight:700;padding:3px 6px;border-radius:4px;text-transform:uppercase;">${item.rarity}</div>
                ${isEquipped ? '<div style="background:#00b894;color:#000;font-size:0.88rem;font-weight:700;padding:3px 6px;border-radius:4px;">✓ EQUIPPED</div>' : ''}
            </div>
            <h4 style="color:${rarityColor};margin:0;font-size:0.95rem;">${item.name}</h4>
            <p style="font-size:0.85rem;color:var(--text-muted);margin:0;flex:1;">${item.desc}</p>
            <div style="display:flex;gap:9px;">
                <button class="btn-secondary" onclick="equipItem('${item.category}', '${item.id}')" ${isEquipped ? 'disabled' : ''} style="flex:1;font-size:0.85rem;padding:6px;">
                    ${isEquipped ? 'Equipped' : 'Equip'}
                </button>
                ${item.price > 0 && refundCount < 3 ? `<button class="btn-secondary" style="background:rgba(255,0,0,0.15);color:#ff6b6b;font-size:0.85rem;padding:6px;" onclick="refundItem('${item.id}', ${item.price})">Refund</button>` : ''}
            </div>
        `;
        gridContainer.appendChild(card);
    });

    container.appendChild(gridContainer);

    // Refund counter
    const refundInfo = document.createElement('div');
    refundInfo.style.cssText = 'margin-top:16px;padding-top:16px;border-top:1px solid rgba(255,255,255,0.1);text-align:center;';
    refundInfo.innerHTML = `<p style="font-size:0.85rem;color:var(--text-muted);">Refunds Available: <strong style="color:${refundCount >= 3 ? '#ff6b6b' : 'var(--accent)'}">${3 - refundCount}/3</strong></p>`;
    container.appendChild(refundInfo);
}

// v17.1 — Reworked from "Lucky Spin" (a credits-for-chance gambling/loot-box mechanic)
// into a free Daily Mystery Box: no cost to open, no risk of loss, once per day.
function renderGambleTab(container) {
    const today = new Date().toISOString().split('T')[0];
    const canOpen = localStorage.getItem('last_mystery_box') !== today;
    container.innerHTML = `
        <div style="text-align:center;padding:30px 20px;">
            <div style="font-size:4.5rem;margin-bottom:16px;filter:drop-shadow(0 0 18px #00CEC9);">🎁</div>
            <h2 style="margin-bottom:8px;background:linear-gradient(135deg,#00CEC9,#6C5CE7);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;font-size:1.35rem;">Daily Mystery Box</h2>
            <p style="color:var(--text-muted);margin-bottom:24px;font-size:0.95rem;">A free gift every day — guaranteed credits, sometimes a bonus cosmetic. No cost, no catch.</p>
            <div style="max-width:340px;margin:0 auto 24px;background:linear-gradient(135deg,rgba(0,206,201,0.1),rgba(108,92,231,0.1));border:2px solid var(--accent);border-radius:16px;padding:24px;">
                ${canOpen ? `
                    <div style="font-size:3rem;margin-bottom:14px;">📦</div>
                    <button class="btn-primary" onclick="openMysteryBox()" style="font-size:1.1rem;padding:14px 32px;"><i class="ph ph-gift"></i> Open today's box</button>
                ` : `
                    <div style="font-size:3rem;margin-bottom:14px;">✅</div>
                    <h3 style="color:#00b894;margin-bottom:6px;">Opened today!</h3>
                    <p style="color:var(--text-muted);font-size:0.9rem;margin:0;">Come back tomorrow for another free box.</p>
                `}
            </div>
            <div id="spin-result" style="min-height:50px;font-size:1.05rem;font-weight:600;"></div>
            <div style="margin-top:20px;padding-top:20px;border-top:1px solid rgba(255,255,255,0.1);max-width:430px;margin-left:auto;margin-right:auto;">
                <p style="font-size:0.84rem;color:var(--text-muted);line-height:1.6;">Open one free box per day for <strong style="color:#fff;">75–175 credits</strong>, plus an occasional bonus cosmetic you don't already own. It never costs credits and you can't lose anything — just a daily thank-you for studying.</p>
            </div>
        </div>
    `;
}

function openMysteryBox() {
    const today = new Date().toISOString().split('T')[0];
    if (localStorage.getItem('last_mystery_box') === today) { showToast("You already opened today's box — back tomorrow!", 'info'); return; }
    localStorage.setItem('last_mystery_box', today);
    const resultDiv = document.getElementById('spin-result');
    const creditsWon = Math.floor(Math.random() * 101) + 75; // 75–175, guaranteed
    updateCredits(creditsWon);
    let bonusHtml = '';
    if (Math.random() < 0.25) {
        const pool = Object.values(SHOP_ITEMS).flat().filter(i => i && !i.secret && !i.nexus && i.price > 0 && !userInventory.includes(i.id));
        if (pool.length) {
            const gift = pool[Math.floor(Math.random() * pool.length)];
            userInventory.push(gift.id);
            localStorage.setItem('user_inventory', JSON.stringify(userInventory));
            bonusHtml = `<div style="color:#fbbf24;margin-top:8px;">🎁 Bonus cosmetic: <strong>${gift.name}</strong>!</div>`;
            showToast(`🎁 Bonus: ${gift.name} added to your inventory!`, 'success', 4000);
        }
    }
    if (resultDiv) resultDiv.innerHTML = `<div style="animation:pulse 0.5s ease-in-out;"><div style="font-size:1.5rem;">💰</div><div style="color:#00b894;font-size:1.15rem;">+${creditsWon} credits!</div>${bonusHtml}</div>`;
    if (typeof createConfetti === 'function') createConfetti();
    if (typeof logActivity === 'function') logActivity('shop', `Opened daily mystery box: +${creditsWon} credits`);
    setTimeout(() => {
        const container = document.getElementById('shop-page-content') || document.getElementById('shop-content');
        if (container) renderGambleTab(container);
    }, 2600);
}
// Back-compat: any lingering reference to the old name opens the box.
function spinLuckyWheel() { openMysteryBox(); }

// ── v12.8: NEXUS Secret Word Detection ──
// Typing "NEXUS" in all caps anywhere (not in an input/textarea) awards
// 1 random Nexus-rarity item. Only works once per account.
(function _initNexusSecretWord() {
    let _nexusBuffer = '';
    const _nexusTarget = 'NEXUS';
    document.addEventListener('keydown', (e) => {
        // Skip if focus is inside an input/textarea
        const tag = document.activeElement ? document.activeElement.tagName : '';
        if (tag === 'INPUT' || tag === 'TEXTAREA' || document.activeElement?.isContentEditable) {
            _nexusBuffer = ''; return;
        }
        // Only track uppercase letters
        if (e.key.length === 1 && /[A-Z]/.test(e.key)) {
            _nexusBuffer += e.key;
            if (_nexusBuffer.length > _nexusTarget.length) _nexusBuffer = _nexusBuffer.slice(-_nexusTarget.length);
            if (_nexusBuffer === _nexusTarget) {
                _nexusBuffer = '';
                _triggerNexusSecret();
            }
        } else if (e.key.length > 1) {
            _nexusBuffer = ''; // reset on non-letter keys
        }
    });

    function _triggerNexusSecret() {
        if (localStorage.getItem('nexus_secret_claimed') === '1') {
            showToast('✨ You already claimed your NEXUS gift!', 'info', 3000);
            return;
        }
        // Pick a random nexus-rarity item not already owned
        const nexusItems = Object.values(SHOP_ITEMS).flat().filter(i => i.rarity === 'nexus');
        const available = nexusItems.filter(i => !userInventory.includes(i.id));
        if (available.length === 0) {
            showToast('🔮 You already own all NEXUS items!', 'info', 3000);
            return;
        }
        const chosen = available[Math.floor(Math.random() * available.length)];
        userInventory.push(chosen.id);
        localStorage.setItem('user_inventory', JSON.stringify(userInventory));
        localStorage.setItem('nexus_secret_claimed', '1');
        // Show dramatic reveal
        showToast(`🔮 NEXUS SECRET UNLOCKED: "${chosen.name}" added to your collection!`, 'success', 6000);
        createConfetti();
        // Refresh shop if open
        setTimeout(() => {
            const sc = document.getElementById('shop-page-content') || document.getElementById('shop-content');
            if (sc) { const tab = localStorage.getItem('shop_page_tab') || 'themes'; renderShopPageTab(tab, sc); }
        }, 800);
    }
})();

function createConfetti() {
    const colors = ['#FFD700', '#FF6B6B', '#00CEC9', '#A855F7', '#00B894'];
    for (let i = 0; i < 50; i++) {
        setTimeout(() => {
            const confetti = document.createElement('div');
            confetti.style.cssText = `
                position:fixed;
                left:${Math.random() * 100}%;
                top:-20px;
                width:10px;
                height:10px;
                background:${colors[Math.floor(Math.random() * colors.length)]};
                border-radius:50%;
                pointer-events:none;
                z-index:9999;
                animation:fall ${2 + Math.random() * 2}s linear forwards;
            `;
            document.body.appendChild(confetti);
            setTimeout(() => confetti.remove(), 4000);
        }, i * 30);
    }
}

// Add fall animation to existing styles
if (!document.getElementById('confetti-style')) {
    const style = document.createElement('style');
    style.id = 'confetti-style';
    style.textContent = `
        @keyframes fall {
            to { transform: translateY(100vh) rotate(360deg); opacity: 0; }
        }
        @keyframes pulse {
            0%, 100% { transform: scale(1); }
            50% { transform: scale(1.05); }
        }
    `;
    document.head.appendChild(style);
}

function getThemeColor(id) {
    const colors = {
        cyan: '#00cec9',
        pink: '#fd79a8',
        green: '#00b894',
        sunset: '#e17055',
        midnight: '#636e72',
        gold: '#f1c40f',
        crimson: '#e84118'
    };
    return colors[id] || 'white';
}

function buyItem(id, type, cost) {
    if (!hasPro()) {
        showProUpgradePrompt('Shop purchases');
        return;
    }
    // Owner gets all items free — no credits deducted, no confirm needed
    if (isOwner()) {
        if (!userInventory.includes(id)) {
            userInventory.push(id);
            localStorage.setItem('user_inventory', JSON.stringify(userInventory));
            showToast("Item granted (owner privilege)!", 'success');
            equipItem(type.slice(0, -1), id);
            logActivity('shop', `Owner granted ${id} for free`);
        } else {
            equipItem(type.slice(0, -1), id);
            showToast("Item equipped!", 'success');
        }
        return;
    }
    if (userCredits >= cost) {
        showConfirm('Confirm Purchase', `Buy ${id} for ${cost} credits?`, () => {
            updateCredits(-cost);
            userInventory.push(id);
            localStorage.setItem('user_inventory', JSON.stringify(userInventory));
            showToast("Item purchased! Equipping now...", 'success');
            equipItem(type.slice(0, -1), id);
            logActivity('shop', `Purchased ${id} for ${cost} credits`);
        });
    } else {
        showToast("Not enough credits!", 'error');
    }
}

function refundItem(id, cost) {
    if (refundCount >= 3) {
        showToast("Refund limit reached (3/3).", 'warning');
        return;
    }
    showConfirm('Refund Item', `Refund ${id} for ${cost} credits? (Limit ${refundCount}/3)`, () => {
        refundCount++;
        localStorage.setItem('refund_count', refundCount);
        updateCredits(cost);
        userInventory = userInventory.filter(i => i !== id);
        localStorage.setItem('user_inventory', JSON.stringify(userInventory));
        if (userLoadout.theme === id || userLoadout.cursor === id || userLoadout.font === id) {
            // Reset to default
            if (userLoadout.theme === id) equipItem('theme', 'default');
            if (userLoadout.cursor === id) equipItem('cursor', 'default');
            if (userLoadout.font === id) equipItem('font', 'default');
        }
        renderShopContent('inventory');
        showToast("Refunded successfully.", 'success');
    });
}

function equipItem(type, value) {
    // v12.8 — Custom wallpaper: trigger file upload before equipping
    if (type === 'wallpaper' && value === 'custom-wallpaper') {
        _openCustomWallpaperUpload();
        return;
    }
    userLoadout[type] = value;
    localStorage.setItem('user_loadout', JSON.stringify(userLoadout));
    if (type === 'theme') applyTheme(value);
    if (type === 'cursor') applyCursor(value);
    if (type === 'font') applyFont(value);
    if (type === 'wallpaper') applyWallpaper(value);
    if (type === 'badge') applyBadge(value);
    if (type === 'effect') applyEffect(value);
    if (type === 'companion') applyCompanion(value);
    // Re-render whichever view is currently active
    const invView = document.getElementById('view-inventory');
    if (invView && invView.classList.contains('active')) {
        renderInventoryPage();
    } else {
        const shopView = document.getElementById('view-shop');
        if (shopView && shopView.classList.contains('active')) {
            const activeTab = shopView.querySelector('.tab-btn.active');
            if (activeTab) {
                const tabName = activeTab.getAttribute('onclick')?.match(/'(\w+)'/)?.[1];
                if (tabName) switchShopPageTab(tabName);
            }
        }
    }
    // Check Nexus achievements
    checkNexusDiscovery(type, value);
    showToast(`Equipped ${value}`, 'info', 2000);
}

// v12.8 — Custom Wallpaper Upload
// Opens a hidden <input type="file"> picker, reads the image as a dataURL,
// stores it in localStorage, then equips it as the active wallpaper.
function _openCustomWallpaperUpload() {
    // Remove any previous picker
    const old = document.getElementById('_custom-wp-input');
    if (old) old.remove();

    const input = document.createElement('input');
    input.id = '_custom-wp-input';
    input.type = 'file';
    input.accept = 'image/*';
    input.style.display = 'none';
    document.body.appendChild(input);

    input.onchange = () => {
        const file = input.files[0];
        input.remove();
        if (!file) return;

        // Warn if the file is very large (>8 MB) — localStorage has a ~5-10 MB limit
        if (file.size > 8 * 1024 * 1024) {
            showToast('⚠️ Image is very large — try a file under 8 MB to avoid storage issues.', 'info', 4000);
        }

        const reader = new FileReader();
        reader.onload = (e) => {
            const dataUrl = e.target.result;
            try {
                localStorage.setItem('custom_wallpaper_dataurl', dataUrl);
            } catch (err) {
                showToast('❌ Image too large to store locally. Try a smaller or more compressed file.', 'error', 4000);
                return;
            }
            // Now actually equip it
            userLoadout['wallpaper'] = 'custom-wallpaper';
            localStorage.setItem('user_loadout', JSON.stringify(userLoadout));
            applyWallpaper('custom-wallpaper');
            checkNexusDiscovery('wallpaper', 'custom-wallpaper');
            showToast('🖼️ Custom wallpaper applied!', 'success', 3000);
            // Refresh the active view
            const invView = document.getElementById('view-inventory');
            if (invView && invView.classList.contains('active')) renderInventoryPage();
            const shopView = document.getElementById('view-shop');
            if (shopView && shopView.classList.contains('active')) {
                const activeTab = shopView.querySelector('.tab-btn.active');
                if (activeTab) {
                    const tabName = activeTab.getAttribute('onclick')?.match(/'(\w+)'/)?.[1];
                    if (tabName) switchShopPageTab(tabName);
                }
            }
        };
        reader.onerror = () => {
            showToast('❌ Failed to read image file.', 'error', 3000);
        };
        reader.readAsDataURL(file);
    };

    input.click();
}

function applyTheme(colorName) {
    const root = document.documentElement;
    const themes = {
        default:      { accent: '#00CEC9', primary: '#6C5CE7', bg: '#05050A', panel: 'rgba(20,20,35,0.6)', muted: '#A0A0B0', border: 'rgba(255,255,255,0.1)' },
        ocean:        { accent: '#0984e3', primary: '#00b894', bg: '#020e1a', panel: 'rgba(5,30,60,0.6)', muted: '#7cb8d4', border: 'rgba(9,132,227,0.15)' },
        midnight:     { accent: '#636e72', primary: '#2d3436', bg: '#0a0a0a', panel: 'rgba(15,15,15,0.7)', muted: '#888', border: 'rgba(255,255,255,0.06)' },
        neon:         { accent: '#ff00ff', primary: '#00ffff', bg: '#05000a', panel: 'rgba(30,0,40,0.6)', muted: '#cc88ff', border: 'rgba(255,0,255,0.15)' },
        forest:       { accent: '#00b894', primary: '#55efc4', bg: '#020f08', panel: 'rgba(5,30,15,0.6)', muted: '#7ecba1', border: 'rgba(0,184,148,0.12)' },
        gold:         { accent: '#fdcb6e', primary: '#f39c12', bg: '#0f0a02', panel: 'rgba(40,25,5,0.6)', muted: '#d4a853', border: 'rgba(253,203,110,0.15)' },
        'sakura-theme': { accent: '#ff6b9d', primary: '#c44569', bg: '#0f0508', panel: 'rgba(40,10,20,0.6)', muted: '#d4849a', border: 'rgba(255,107,157,0.12)' },
        crimson:      { accent: '#e84118', primary: '#c0392b', bg: '#0f0200', panel: 'rgba(40,8,5,0.6)', muted: '#d46b5a', border: 'rgba(232,65,24,0.15)' },
        void:         { accent: '#8c7ae6', primary: '#2c2c54', bg: '#030216', panel: 'rgba(10,5,30,0.7)', muted: '#6b5eaa', border: 'rgba(140,122,230,0.12)' },
        aurora:       { accent: '#74e8c8', primary: '#a29bfe', bg: '#020a0f', panel: 'rgba(8,25,35,0.6)', muted: '#8cd4c0', border: 'rgba(116,232,200,0.12)' },
        'nexus-prime': { accent: '#00fff5', primary: '#7c4dff', bg: '#000510', panel: 'rgba(5,0,25,0.7)', muted: '#88ccff', border: 'rgba(0,255,245,0.15)' },
        'midnight-violet': { accent: '#a78bfa', primary: '#7c3aed', bg: '#0b0518', panel: 'rgba(30,16,55,0.6)', muted: '#b9a8e6', border: 'rgba(124,58,237,0.18)' }
    };
    const t = themes[colorName] || themes.default;
    root.style.setProperty('--accent', t.accent);
    root.style.setProperty('--primary', t.primary);
    root.style.setProperty('--bg-dark', t.bg);
    root.style.setProperty('--bg-panel', t.panel);
    root.style.setProperty('--text-muted', t.muted);
    root.style.setProperty('--glass-border', t.border);
    // Also update body background to match theme
    document.body.style.backgroundColor = t.bg;
    document.body.style.backgroundImage = `radial-gradient(circle at 10% 20%, ${t.primary}33 0%, transparent 40%), radial-gradient(circle at 90% 80%, ${t.accent}26 0%, transparent 40%)`;
}

