// Local profanity blacklist (light first-pass; OpenAI moderation does the heavy lifting)
const NSFW_BLACKLIST = [
    'fuck','shit','bitch','asshole','dick','pussy','cunt','cock','tits','slut','whore','retard','rape','nazi','nigger','faggot','kike',
    'porn','xxx','onlyfans','nsfw','sexy','nude','nudes','blowjob','handjob','anal','penis','vagina','orgasm','masturbat','sex'
];
const NSFW_LEET = (s) => s.toLowerCase()
    .replace(/[$5]/g, 's').replace(/0/g, 'o').replace(/1!/g, 'i').replace(/3/g, 'e').replace(/4@/g, 'a').replace(/7/g, 't')
    .replace(/[^a-z\s]/g, '');

function localNsfwCheck(text) {
    if (!text) return { ok: true };
    const norm = NSFW_LEET(text);
    for (const word of NSFW_BLACKLIST) {
        if (norm.includes(word)) return { ok: false, reason: 'blocked_local', match: word };
    }
    return { ok: true };
}

async function openaiModerationCheck(text) {
    const apiKey = getApiKey();
    if (!apiKey) return { ok: true, skipped: true };
    try {
        const res = await fetch('https://api.openai.com/v1/moderations', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({ model: 'omni-moderation-latest', input: text })
        });
        const data = await res.json();
        if (data.error) return { ok: true, skipped: true };
        const result = data.results?.[0];
        if (result && result.flagged) {
            const cats = Object.entries(result.categories).filter(([_, v]) => v).map(([k]) => k);
            return { ok: false, reason: 'blocked_moderation', categories: cats };
        }
        return { ok: true };
    } catch (_) { return { ok: true, skipped: true }; }
}

// v12.7 — Suggestions daily pool system
// Pulls 14 random suggestions from SUGGESTION_DAILY_POOL each day.
// Owner-approved suggestions persist forever. All others expire after 4 days.
// Manual-only mode (post-release): no auto-pool, only user-submitted suggestions shown.

const SUGGESTION_EXPIRY_MS = 4 * 24 * 3600 * 1000; // 4 days
const SUGGESTION_DAILY_COUNT = 14;

function _readSuggestions() {
    let stored = [];
    try {
        const raw = JSON.parse(localStorage.getItem('suggestions') || 'null');
        if (raw && Array.isArray(raw)) {
            const now = Date.now();
            stored = raw.filter(s => s.ownerApproved || s.isUserSubmitted || (now - (s.createdAt || 0)) < SUGGESTION_EXPIRY_MS);
        }
    } catch (_) {}
    // Merge owner-pinned items — always present, never from localStorage (they live in code)
    const storedIds = new Set(stored.map(s => s.id));
    const pinned = OWNER_PINNED_SUGGESTIONS.filter(p => !storedIds.has(p.id));
    return [...pinned, ...stored];
}
function _writeSuggestions(list) {
    localStorage.setItem('suggestions', JSON.stringify(list));
}

// Initialise daily pool on page load — called once from DOMContentLoaded
function _initSuggestionsDaily() {
    // Manual-only mode: skip auto-pool entirely
    if (localStorage.getItem('suggestions_manual_only') === '1') return;

    const lastRefresh = parseInt(localStorage.getItem('suggestions_last_refresh') || '0', 10);
    const todayMidnight = new Date(); todayMidnight.setHours(0, 0, 0, 0);
    const todayMs = todayMidnight.getTime();

    if (lastRefresh >= todayMs) return; // Already refreshed today

    // Flush non-approved, non-user-submitted suggestions older than 1 day
    const now = Date.now();
    const existing = _readSuggestions();
    const keepers = existing.filter(s => s.ownerApproved || s.isUserSubmitted);

    // Pick SUGGESTION_DAILY_COUNT random items from pool (avoid duplicates already kept)
    const keeperIds = new Set(keepers.map(s => s.id));
    const available = SUGGESTION_DAILY_POOL.filter(p => !keeperIds.has(p.id));
    // Shuffle
    for (let i = available.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [available[i], available[j]] = [available[j], available[i]];
    }
    const todaysPicks = available.slice(0, SUGGESTION_DAILY_COUNT);

    // Stamp them with staggered createdAt within the past 6-18 hours
    const newItems = todaysPicks.map((p, idx) => ({
        ...p,
        createdAt: now - (6 + idx * 0.85) * 3600 * 1000,
        voted: false,
        ownerApproved: false,
        isUserSubmitted: false
    }));

    _writeSuggestions([...keepers, ...newItems]);
    localStorage.setItem('suggestions_last_refresh', String(todayMs));
}

// Owner approve/star: marks suggestion as permanent (never auto-deleted)
// v12.8 — also promotes/demotes to the planning board automatically
function ownerApproveSuggestion(suggestionId) {
    if (typeof isOwner !== 'function' || !isOwner()) return;
    const list = _readSuggestions();
    const s = list.find(x => x.id === suggestionId);
    if (!s) return;
    s.ownerApproved = !s.ownerApproved;
    // Default status to 'planned' when first pinning; clear when unpinning
    if (s.ownerApproved && !s.status) s.status = 'planned';
    if (!s.ownerApproved) s.status = null;
    _writeSuggestions(list);

    // Sync to planning board
    _syncApprovedSuggestionToBoard(s);

    renderSuggestions();
    renderSuggestionsPage();
    showToast(s.ownerApproved ? `⭐ "${s.title}" pinned + added to Planning Board.` : `Unpinned "${s.title}" and removed from Planning Board.`, 'success');
}

function setSuggestionStatus(suggestionId, status) {
    if (typeof isOwner !== 'function' || !isOwner()) return;
    const list = _readSuggestions();
    const s = list.find(x => x.id === suggestionId);
    if (!s) return;
    s.status = status;
    _writeSuggestions(list);
    renderSuggestionsPage();
}

// v12.8 — Promote an ownerApproved suggestion → upcoming_plans_extra,
// or remove it when un-approved. Skips if already in UPCOMING_PLANS_SEED.
function _syncApprovedSuggestionToBoard(suggestion) {
    // Don't duplicate entries already in the seed
    const seedIds = new Set(UPCOMING_PLANS_SEED.map(p => p.id || p.title));
    if (seedIds.has(suggestion.id) || seedIds.has(suggestion.title)) return;

    let extra = [];
    try { extra = JSON.parse(localStorage.getItem('upcoming_plans_extra') || '[]'); } catch (_) {}
    if (!Array.isArray(extra)) extra = [];

    const planId = 'sg_' + suggestion.id;

    if (suggestion.ownerApproved) {
        // Add if not already there
        const alreadyThere = extra.some(p => p.id === planId);
        if (!alreadyThere) {
            extra.push({
                id: planId,
                title: suggestion.title,
                body: suggestion.body || '',
                category: suggestion.category || 'features',
                status: 'planned',
                eta: '—',
                from: '@' + (suggestion.author || 'community'),
                fromSuggestion: true
            });
        }
    } else {
        // Remove it
        extra = extra.filter(p => p.id !== planId);
    }

    localStorage.setItem('upcoming_plans_extra', JSON.stringify(extra));
}

// v12.8 — On startup, sync any already-approved suggestions that aren't in the board yet
function _syncAllApprovedSuggestionsOnLoad() {
    const list = _readSuggestions();
    list.filter(s => s.ownerApproved).forEach(s => _syncApprovedSuggestionToBoard(s));
}

function openSuggestionBox() {
    const m = document.getElementById('suggestion-modal');
    if (!m) return;
    m.classList.remove('hidden'); m.style.display = 'flex';
    switchSuggestionTab('suggestions'); // default
    renderSuggestions();
    renderUpcomingPlans();
}
function closeSuggestionBox() {
    const m = document.getElementById('suggestion-modal');
    if (!m) return;
    m.classList.add('hidden'); m.style.display = 'none';
}

// v10.9 — toggle between Community Suggestions and Upcoming Plans
function switchSuggestionTab(tab) {
    const sgTab = document.getElementById('sg-tab-suggestions');
    const plansTab = document.getElementById('sg-tab-plans');
    const sgList = document.getElementById('sg-list');
    const sgControls = document.getElementById('sg-suggestion-controls');
    const sgPlans = document.getElementById('sg-plans');
    const onSugg = (tab === 'suggestions');
    if (sgTab) {
        sgTab.style.borderBottomColor = onSugg ? 'var(--accent)' : 'transparent';
        sgTab.style.color = onSugg ? 'white' : 'var(--text-muted)';
    }
    if (plansTab) {
        plansTab.style.borderBottomColor = onSugg ? 'transparent' : 'var(--accent)';
        plansTab.style.color = onSugg ? 'var(--text-muted)' : 'white';
    }
    if (sgList) sgList.style.display = onSugg ? 'block' : 'none';
    if (sgControls) sgControls.style.display = onSugg ? 'flex' : 'none';
    if (sgPlans) sgPlans.style.display = onSugg ? 'none' : 'block';
}

