            grad.addColorStop(0.7, 'rgba(0,20,50,0.3)'); grad.addColorStop(1, 'rgba(0,10,30,0.5)');
            ctx.fillStyle = grad; ctx.fillRect(0, 0, canvas.width, canvas.height);
