            const treeGlow = ctx.createRadialGradient(canvas.width/2, canvas.height - 10, 10, canvas.width/2, canvas.height - 10, tw * 0.7);
            treeGlow.addColorStop(0, 'rgba(255,150,180,0.06)');
            treeGlow.addColorStop(1, 'rgba(255,150,180,0)');
