            ctx.fillStyle = '#4a3320';
            ctx.fillRect(benchX, benchY, 110, 6);
            // Bench legs
            ctx.fillRect(benchX + 6, benchY + 6, 4, 18);
            ctx.fillRect(benchX + 100, benchY + 6, 4, 18);
            // Bench backrest
            ctx.fillRect(benchX + 4, benchY - 22, 4, 22);
            ctx.fillRect(benchX + 4, benchY - 22, 60, 4);
