            ctx.fillStyle = '#d24c7d';
            ctx.fillRect(gx - 8, gy - 10, 18, 14);
            // Torso
            ctx.fillStyle = '#f5e3d3';
            ctx.fillRect(gx - 6, gy - 22, 14, 14);
