            ctx.fillStyle = '#2a1a14';
            ctx.fillRect(gx - 6, gy - 34, 14, 6);
            ctx.fillRect(gx - 8, gy - 30, 4, 14);
            // Legs (sitting, bent)
            ctx.fillStyle = '#f5e3d3';
            ctx.fillRect(gx - 6, gy + 4, 5, 8);
            ctx.fillRect(gx + 4, gy + 4, 5, 8);
