                ctx.fillStyle = '#d68b9a';
                ctx.beginPath(); ctx.ellipse(hx + flip * 5, hy + 1, 3, 2, 0, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = '#5a3540';
                ctx.fillRect(hx + flip * 5 - 1, hy, 1, 1); ctx.fillRect(hx + flip * 5 + 1, hy, 1, 1);
