                lg.addColorStop(1, 'rgba(255,200,100,0)');
                ctx.fillStyle = lg;
                ctx.beginPath();
                ctx.moveTo(bx, 0); ctx.lineTo(bx + bw, 0);
                ctx.lineTo(bx + W * 0.16 + bw, H * 0.85); ctx.lineTo(bx + W * 0.16, H * 0.85);
