            haze.addColorStop(0.5, 'rgba(185,215,175,0.18)');
            haze.addColorStop(1, 'rgba(185,215,175,0)');
            ctx.fillStyle = haze; ctx.fillRect(0, H * 0.32, W, H * 0.32);
            // ─── MID-GROUND TREES (gently swaying, two canopy layers) ───
            midTrees.forEach(tree => {
                tree.sway += 0.005;
                const sw = Math.sin(tree.sway) * 2.2, tx = tree.x + sw, by = H * 0.52;
                ctx.fillStyle = '#283a25';
                ctx.fillRect(tx - tree.tw * 0.5 * tree.scale, by, tree.tw * tree.scale, H * 0.48);
                ctx.fillStyle = '#3a5e3c';
                ctx.beginPath(); ctx.arc(tx, by, 60 * tree.scale, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = '#2c4e2e';
                ctx.beginPath(); ctx.arc(tx, by + 7 * tree.scale, 40 * tree.scale, 0, Math.PI * 2); ctx.fill();
                ctx.fillStyle = 'rgba(100,165,95,0.28)';
                ctx.beginPath(); ctx.arc(tx - 10 * tree.scale, by - 10 * tree.scale, 18 * tree.scale, 0, Math.PI * 2); ctx.fill();
            });
            // ─── GROUND MIST (rolling fog at forest floor) ───
            for (let mi = 0; mi < 3; mi++) {
                const mistY = H * (0.81 + mi * 0.055);
                const mistG = ctx.createLinearGradient(0, mistY - 28, 0, mistY + 36);
                mistG.addColorStop(0, 'rgba(215,230,208,0)');
                mistG.addColorStop(0.4, `rgba(215,230,208,${0.17 - mi * 0.04})`);
                mistG.addColorStop(1, 'rgba(215,230,208,0)');
                ctx.fillStyle = mistG;
                for (let x = -110; x < W + 110; x += 110) {
                    const ex = x + Math.sin(t * 0.07 + x * 0.009 + mi) * 35;
                    ctx.beginPath(); ctx.ellipse(ex, mistY, 140, 26, 0, 0, Math.PI * 2); ctx.fill();
                }
            }
            // ─── TOTORO with umbrella, walking L→R ───
            totoroX += 0.26;
            if (totoroX > W + 110) totoroX = -110;
            totoroBob.phase += 0.032;
            const S = Math.min(W, H) * 0.068;
            const tY = H * 0.845 + Math.sin(totoroBob.phase) * 1.8;
            const dR = S * 0.98, dCy = tY - S * 1.92;
            // umbrella handle (stick from paw to dome)
            ctx.strokeStyle = '#1e1e26'; ctx.lineWidth = Math.max(2, S * 0.072);
            ctx.beginPath(); ctx.moveTo(totoroX + S * 0.12, tY - S * 0.44); ctx.lineTo(totoroX + S * 0.06, dCy); ctx.stroke();
            // umbrella dome (upper semicircle)
            ctx.fillStyle = 'rgba(24,24,38,0.88)';
            ctx.beginPath(); ctx.arc(totoroX, dCy, dR, Math.PI, 0); ctx.closePath(); ctx.fill();
            // inner dome highlight (depth/gloss)
            ctx.fillStyle = 'rgba(42,40,72,0.52)';
            ctx.beginPath(); ctx.arc(totoroX - dR * 0.1, dCy - dR * 0.1, dR * 0.7, Math.PI, 0); ctx.closePath(); ctx.fill();
            // scalloped edge (small D-shape bumps hanging below dome rim)
            ctx.fillStyle = 'rgba(20,20,34,0.94)';
