// ============================================================
// HISTORY SYSTEM
// ============================================================
let userHistory = JSON.parse(localStorage.getItem('user_history') || '[]');

function addToHistory(type, question, answer, image) {
    const limit = parseInt(localStorage.getItem('history_limit') || '20');
    const entry = {
        id: Date.now(),
        type,
        question: question.substring(0, 200), // Truncate long inputs for storage
        answer: answer.substring(0, 500),
        timestamp: new Intl.DateTimeFormat('en-US', {
            month: 'short', day: '2-digit',
            hour: 'numeric', minute: '2-digit', hour12: true
        }).format(new Date())
    };
    // v10.6: Persist image (data URL) when the question included one. Downscale
    // to keep localStorage manageable.
    if (image && typeof image === 'string' && image.startsWith('data:image')) {
        try {
            entry.image = _downscaleDataUrl(image, 480) || image;
        } catch (_) { entry.image = image; }
    }
    userHistory.unshift(entry); // Add to front
    // Enforce limit
    while (userHistory.length > limit) {
        userHistory.pop();
    }
    try {
        localStorage.setItem('user_history', JSON.stringify(userHistory));
    } catch (e) {
        // Quota exceeded — drop oldest image fields and try again
        userHistory.forEach(h => { if (h.image) delete h.image; });
        try { localStorage.setItem('user_history', JSON.stringify(userHistory)); } catch (_) {}
    }
    renderHistoryList();
}

// v10.6 helper: synchronous-ish downscale of a data URL to a max width.
// Returns the downscaled data URL or null on failure.
function _downscaleDataUrl(dataUrl, maxW) {
    try {
        const img = new Image();
        img.src = dataUrl;
        // Synchronous-ish: only works if the image is already loaded/cached.
        // We use a quick check; if not loadable yet, return null and the caller falls back.
        if (!img.complete || !img.naturalWidth) return null;
        const w = img.naturalWidth, h = img.naturalHeight;
        if (w <= maxW) return dataUrl;
        const scale = maxW / w;
        const c = document.createElement('canvas');
        c.width = Math.round(w * scale);
        c.height = Math.round(h * scale);
        c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
        return c.toDataURL('image/jpeg', 0.7);
    } catch (_) { return null; }
}

function enforceHistoryLimit() {
    const limit = parseInt(localStorage.getItem('history_limit') || '20');
    while (userHistory.length > limit) {
        userHistory.pop();
    }
    localStorage.setItem('user_history', JSON.stringify(userHistory));
    renderHistoryList();
}

const TYPE_ICONS = {
    code:          'ph-code',
    math:          'ph-function',
    science:       'ph-flask',
    english:       'ph-pencil-line',
    vision:        'ph-eye',
    social:        'ph-globe-hemisphere-west',
    study:         'ph-book-open',
    homework:      'ph-clipboard-text',
    grade:         'ph-chart-bar',
    challenge:     'ph-trophy',
    achievement:   'ph-medal',
    vocabulary:    'ph-text-aa',
    flashcard:     'ph-cards',
};

const TYPE_LABELS = {
    code:          'Code Lab',
    math:          'Math Lab',
    science:       'Science',
    english:       'English',
    vision:        'Live Vision',
    social:        'Social Studies',
    study:         'Study',
    homework:      'Homework',
    grade:         'Grade Tracker',
    challenge:     'Daily Challenge',
    achievement:   'Achievement',
    vocabulary:    'Vocabulary',
    flashcard:     'Flashcards',
};

// v13.1 — Bridge: also add study-activity events (logActivity calls) into
// userHistory so the History tab shows real study events alongside AI answers.
function logStudyEvent(type, question) {
    addToHistory(type, question, '', null);
}

function renderHistoryList() {
    const list = document.getElementById('history-list');
    if (!list) return;
    // Refresh stats
    updateHistoryStats();
    // Read filter + search
    const search = (document.getElementById('hist-search')?.value || '').toLowerCase().trim();
    const filter = document.getElementById('hist-filter')?.value || 'all';
    let filtered = userHistory;
    if (filter !== 'all') filtered = filtered.filter(e => e.type === filter);
    if (search) filtered = filtered.filter(e => (e.question || '').toLowerCase().includes(search) || (e.answer || '').toLowerCase().includes(search));
    if (filtered.length === 0) {
        list.innerHTML = userHistory.length === 0
            ? '<p style="color: var(--text-muted); text-align: center; margin-top: 50px;">No history yet. Start using modules to see your activity here.</p>'
            : '<p style="color: var(--text-muted); text-align: center; margin-top: 50px;">No matches for that filter or search.</p>';
        return;
    }
    list.innerHTML = filtered.map(entry => {
        const icon = TYPE_ICONS[entry.type] || 'ph-brain';
        const label = TYPE_LABELS[entry.type] || 'AI';
        const accentColor = ({
            math: '#6c5ce7', english: '#ed64a6', science: '#00b894', social: '#fdcb6e',
            code: '#74b9ff', vision: '#00CEC9', study: '#a855f7', homework: '#fd79a8',
            grade: '#00CEC9', challenge: '#fdcb6e', achievement: '#FFD700',
            vocabulary: '#00b894', flashcard: '#a29bfe'
        })[entry.type] || 'var(--accent)';
        return `
            <div class="glass-panel" style="margin-bottom:10px;padding:14px 16px;cursor:pointer;transition:border-color 0.2s,transform 0.15s;border-left:3px solid ${accentColor};" onclick="showHistoryDetail(${entry.id})" onmouseover="this.style.borderLeftWidth='5px';this.style.transform='translateX(2px)'" onmouseout="this.style.borderLeftWidth='3px';this.style.transform=''">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;flex-wrap:wrap;gap:4px;">
                    <span style="color:${accentColor};font-size:0.88rem;font-weight:700;display:flex;align-items:center;gap:9px;letter-spacing:0.5px;">
                        <i class="ph ${icon}"></i> ${label.toUpperCase()}
                    </span>
                    <span style="color:var(--text-muted);font-size:0.9rem;">${entry.timestamp}</span>
                </div>
                <p style="color:#ddd;font-size:0.9rem;margin:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">${entry.question}</p>
            </div>
        `;
    }).join('');
}

function updateHistoryStats() {
    const total = userHistory.length;
    const now = Date.now();
    const weekAgo = now - 7 * 24 * 60 * 60 * 1000;
    const todayStart = new Date().setHours(0, 0, 0, 0);
    const weekCount = userHistory.filter(e => (e.id || 0) > weekAgo).length;
    const todayCount = userHistory.filter(e => (e.id || 0) > todayStart).length;
    const counts = userHistory.reduce((acc, e) => { acc[e.type] = (acc[e.type] || 0) + 1; return acc; }, {});
    let topType = '—', topCount = 0;
    Object.entries(counts).forEach(([k, v]) => { if (v > topCount) { topCount = v; topType = k; } });
    const topLabel = (TYPE_LABELS[topType] || topType);
    const setText = (id, val) => { const el = document.getElementById(id); if (el) el.textContent = val; };
    setText('hist-stat-total', total);
    setText('hist-stat-week', weekCount);
    setText('hist-stat-today', todayCount);
    setText('hist-stat-top', topLabel);
    setText('hist-stat-top-count', topCount + ' entries');
}

// v12.1 — History detail modal upgraded to Settings-style polish:
//   • larger centered panel with type-colored accent stripe
//   • image preview (if present)
//   • question + answer clearly separated
//   • "Explain the concept" button — re-runs Tutor Mode on the same problem
//     (Math + Science + Live Vision entries only). Opens the appropriate
//     subject view and re-asks the AI with a fresh tutor conversation.
function showHistoryDetail(id) {
    const entry = userHistory.find(e => e.id === id);
    if (!entry) return;
    const modal = document.getElementById('history-modal');
    const content = document.getElementById('history-detail-content');
    const label = TYPE_LABELS[entry.type] || 'AI';
    const accentColor = ({
        math: '#6c5ce7', english: '#ed64a6', science: '#00b894', social: '#fdcb6e',
        code: '#74b9ff', vision: '#00CEC9', study: '#a855f7', homework: '#fd79a8',
        grade: '#00CEC9', challenge: '#fdcb6e', achievement: '#FFD700',
        vocabulary: '#00b894', flashcard: '#a29bfe'
    })[entry.type] || 'var(--accent)';
    const icon = TYPE_ICONS[entry.type] || 'ph-brain';

    const imageBlock = entry.image
        ? `<div style="margin-bottom:14px;background:rgba(0,0,0,0.35);border:1px solid ${accentColor}55;border-radius:10px;padding:10px;text-align:center;">
              <div style="font-size:0.9rem;color:${accentColor};letter-spacing:1.2px;font-weight:700;margin-bottom:8px;">PROBLEM IMAGE</div>
              <img src="${entry.image}" alt="problem image" style="max-width:100%;max-height:340px;border-radius:6px;display:inline-block;">
           </div>`
        : '';

    // Show "Explain the concept" for subject entries that re-runable
    const reExplainable = ['math', 'science'].includes(entry.type) || (entry.type === 'study' && /vision/i.test(entry.question || ''));
    const reExplainBtn = reExplainable
        ? `<button class="btn-primary" onclick="reExplainHistoryEntry(${entry.id})" style="display:inline-flex;align-items:center;gap:9px;padding:9px 14px;background:linear-gradient(135deg,${accentColor},#00CEC9);border:none;border-radius:8px;color:white;cursor:pointer;font-weight:600;font-size:0.86rem;">
            <i class="ph ph-graduation-cap"></i> Explain the concept
          </button>`
        : '';
    // v12.3 — "Make flashcards" turns this history entry into a Quizlet-style
    // deck (front/back) of key terms and definitions, saved into the Flashcards tab.
    const flashcardable = ['math', 'science', 'english', 'social'].includes(entry.type);
    const flashcardBtn = flashcardable
        ? `<button class="btn-secondary" onclick="makeFlashcardsFromHistory(${entry.id})" style="display:inline-flex;align-items:center;gap:9px;padding:9px 14px;border-radius:8px;cursor:pointer;font-weight:600;font-size:0.86rem;">
            <i class="ph ph-cards"></i> Make flashcards
          </button>`
        : '';

    content.innerHTML = `
        <div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:linear-gradient(135deg, ${accentColor}22, ${accentColor}11);border-left:4px solid ${accentColor};border-radius:8px;margin-bottom:14px;">
            <i class="ph ${icon}" style="color:${accentColor};font-size:1.2rem;"></i>
            <div style="flex:1;min-width:0;">
                <div style="color:${accentColor};font-size:0.85rem;font-weight:700;letter-spacing:1px;">${label.toUpperCase()}</div>
                <div style="color:var(--text-muted);font-size:0.88rem;">${entry.timestamp || ''}</div>
            </div>
        </div>
        <div style="margin-bottom:12px;">
            <div style="color:var(--text-muted);font-size:0.9rem;font-weight:700;letter-spacing:0.8px;margin-bottom:4px;">QUESTION</div>
            <div style="color:white;font-size:0.98rem;line-height:1.45;">${escapeHtmlSafe(entry.question || '')}</div>
        </div>
        ${imageBlock}
        <div style="margin-bottom:14px;">
            <div style="color:var(--text-muted);font-size:0.9rem;font-weight:700;letter-spacing:0.8px;margin-bottom:4px;">ANSWER</div>
            <div id="history-detail-body" style="background:rgba(255,255,255,0.04); border-radius:8px; padding:14px; color:#ddd; font-size:0.9rem; line-height:1.6; max-height:50vh; overflow-y:auto; white-space:pre-wrap; word-break:break-word;">${entry.answer || ''}</div>
        </div>
        <div style="display:flex;gap:10px;justify-content:flex-end;flex-wrap:wrap;">
            <button class="btn-secondary" onclick="document.getElementById('history-modal').classList.add('hidden')" style="padding:9px 14px;font-size:0.85rem;">Close</button>
            ${flashcardBtn}
            ${reExplainBtn}
        </div>
    `;
    modal.classList.remove('hidden');
    modal.style.display = 'flex';
}

// ════════════════════════════════════════════════════════════════════
// v12.3 — FLASHCARD GENERATOR (community suggestion @mira_h)
// Turns any history entry into a Quizlet-style front/back deck and saves it
// to localStorage.flashcard_decks. Decks are reviewable in the Flashcards
// modal (opened via openFlashcards()).
// ════════════════════════════════════════════════════════════════════
function getFlashcardDecks() {
    try { return JSON.parse(localStorage.getItem('flashcard_decks') || '[]'); }
    catch { return []; }
}
function saveFlashcardDecks(decks) {
    localStorage.setItem('flashcard_decks', JSON.stringify(decks));
}

// v19.3 — export a deck as CSV (round-trips with the existing Import CSV: one
// "front,back" row per card, quotes escaped per RFC 4180). Complements import
// so decks are portable in/out of Quizlet, Anki, spreadsheets, etc.
function _csvCell(s) {
    s = String(s == null ? '' : s);
    return /[",\n\r]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
}
function exportFlashcardDeck(deckId) {
    try {
        var decks = getFlashcardDecks();
        var deck = decks.find(function (d) { return d.id === deckId; });
        if (!deck) { showToast('Deck not found.', 'error'); return; }
        var cards = deck.cards || [];
        if (!cards.length) { showToast('That deck has no cards to export.', 'info'); return; }
        var csv = 'front,back\n' + cards.map(function (c) {
            return _csvCell(c.front) + ',' + _csvCell(c.back);
        }).join('\n');
        var safeName = String(deck.title || 'deck').replace(/[^a-z0-9]+/gi, '-').replace(/^-+|-+$/g, '').toLowerCase() || 'deck';
        var blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
        var url = URL.createObjectURL(blob);
        var a = document.createElement('a');
        a.href = url; a.download = 'nexus-flashcards-' + safeName + '.csv';
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
        showToast('✓ Exported "' + deck.title + '" (' + cards.length + ' card' + (cards.length === 1 ? '' : 's') + ')', 'success');
    } catch (e) { showToast('Export failed: ' + (e && e.message), 'error'); }
}

async function makeFlashcardsFromHistory(id) {
    const entry = userHistory.find(e => e.id === id);
    if (!entry) return;
    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add API key in Settings.', 'error'); return; }
    showToast('Generating flashcards…', 'info', 2500);
    try {
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o-mini',
                response_format: { type: 'json_object' },
                messages: [
                    { role: 'system', content: `Extract the 6-10 most important study flashcards from this material. Return STRICT JSON:
{ "cards": [{ "front": "term or short question", "back": "definition or one-sentence answer" }, ...] }
Rules:
- "front" = a term, concept, formula name, person, date, or focused question. Short (1-8 words).
- "back" = its clean definition or answer. 1-2 sentences max. Plain text, no markdown.
- Focus on the most testable material. Skip trivia.
- If the material is a math/science problem, generate cards about the underlying CONCEPTS, formulas, and rules — not just the specific numbers.` },
                    { role: 'user', content: `Question: ${entry.question || '(no question)'}\n\nAnswer:\n${(entry.answer || '').replace(/<[^>]+>/g, ' ').slice(0, 6000)}` }
                ]
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message);
        const parsed = JSON.parse(data.choices[0].message.content);
        if (!parsed.cards || !Array.isArray(parsed.cards) || parsed.cards.length === 0) {
            showToast('Couldn\'t generate cards from this entry.', 'error');
            return;
        }
        const deck = {
            id: Date.now(),
            title: (entry.question || 'Study deck').slice(0, 60),
            subject: entry.type,
            createdAt: Date.now(),
            sourceHistoryId: id,
            cards: parsed.cards
        };
        const decks = getFlashcardDecks();
        decks.unshift(deck);
        saveFlashcardDecks(decks);
        showToast(`✓ Saved ${deck.cards.length} flashcards. Open the Flashcards tab.`, 'success', 4000);
        // Optionally jump to the flashcards view immediately
        document.getElementById('history-modal').classList.add('hidden');
        openFlashcards(deck.id);
    } catch (err) {
        showToast('Flashcard error: ' + err.message, 'error', 4000);
    }
}

// Flashcards modal — list decks + review one card at a time
// v12.4: mode param — 'manual' = open to create deck, 'ai' = open to AI generate, else open deck list
function openFlashcards(focusDeckId) {
    const mode = (focusDeckId === 'manual' || focusDeckId === 'ai') ? focusDeckId : null;
    const deckId = mode ? null : focusDeckId;

    let modal = document.getElementById('flashcards-modal');
    if (!modal) {
        modal = document.createElement('div');
        modal.id = 'flashcards-modal';
        modal.className = 'modal';
        modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.75);backdrop-filter:blur(6px);z-index:9999;display:flex;align-items:center;justify-content:center;padding:20px;';
        modal.innerHTML = `
            <div class="glass-panel" style="max-width:720px;width:100%;max-height:88vh;overflow-y:auto;padding:24px;border:1px solid rgba(108,92,231,0.4);">
                <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px;">
                    <h2 style="margin:0;font-size:1.2rem;color:white;"><i class="ph ph-cards"></i> Flashcards</h2>
                    <div style="display:flex;gap:12px;">
                        <button class="btn-secondary" onclick="openFlashcardCreateForm()" style="font-size:0.9rem;padding:7px 12px;"><i class="ph ph-plus"></i> New Deck</button>
                        <button class="btn-secondary" onclick="openFlashcardAIGenerate()" style="font-size:0.9rem;padding:7px 12px;background:linear-gradient(135deg,rgba(0,206,201,0.15),rgba(108,92,231,0.15));"><i class="ph ph-sparkle"></i> AI Generate</button>
                        <button class="btn-icon" onclick="document.getElementById('flashcards-modal').remove()"><i class="ph ph-x"></i></button>
                    </div>
                </div>
                <div id="flashcards-content"></div>
            </div>`;
        document.body.appendChild(modal);
    }
    if (mode === 'manual') { renderFlashcardsList(); setTimeout(openFlashcardCreateForm, 50); }
    else if (mode === 'ai') { renderFlashcardsList(); setTimeout(openFlashcardAIGenerate, 50); }
    else renderFlashcardsList(deckId);
}

// Open a simple form to create a new deck manually
function openFlashcardCreateForm() {
    const content = document.getElementById('flashcards-content');
    if (!content) return;
    content.innerHTML = `
        <button class="btn-secondary" onclick="renderFlashcardsList()" style="font-size:0.9rem;margin-bottom:14px;"><i class="ph ph-arrow-left"></i> Back</button>
        <h3 style="margin:0 0 12px;color:white;font-size:1rem;">Create a New Deck</h3>
        <input type="text" id="fc-new-deck-title" placeholder="Deck title (e.g. Biology Ch. 5)"
            style="width:100%;padding:10px;margin-bottom:10px;background:rgba(0,0,0,0.4);border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.9rem;outline:none;box-sizing:border-box;">
        <div id="fc-new-cards-list" style="display:flex;flex-direction:column;gap:12px;margin-bottom:12px;"></div>
        <button class="btn-secondary" onclick="addFlashcardRow()" style="width:100%;margin-bottom:14px;"><i class="ph ph-plus"></i> Add Card</button>
        <button class="btn-primary" onclick="saveManualFlashcardDeck()" style="width:100%;"><i class="ph ph-floppy-disk"></i> Save Deck</button>`;
    addFlashcardRow();
}

function addFlashcardRow() {
    const list = document.getElementById('fc-new-cards-list');
    if (!list) return;
    const idx = list.children.length;
    const row = document.createElement('div');
    row.style.cssText = 'display:flex;gap:12px;align-items:center;';
    row.innerHTML = `
        <input type="text" placeholder="Front (term)" style="flex:1;padding:9px;background:rgba(0,0,0,0.4);border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.84rem;outline:none;" class="fc-card-front">
        <input type="text" placeholder="Back (answer)" style="flex:1;padding:9px;background:rgba(0,0,0,0.4);border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.84rem;outline:none;" class="fc-card-back">
        <button onclick="this.parentElement.remove()" style="background:rgba(255,107,107,0.12);border:1px solid rgba(255,107,107,0.3);border-radius:6px;color:#ff6b6b;cursor:pointer;padding:6px 8px;"><i class="ph ph-trash"></i></button>`;
    list.appendChild(row);
}

function saveManualFlashcardDeck() {
    const title = (document.getElementById('fc-new-deck-title')?.value || '').trim();
    if (!title) { showToast('Enter a deck title.', 'error'); return; }
    const fronts = [...document.querySelectorAll('.fc-card-front')].map(el => el.value.trim());
    const backs  = [...document.querySelectorAll('.fc-card-back')].map(el => el.value.trim());
    const cards = fronts.map((f, i) => ({ front: f, back: backs[i] })).filter(c => c.front && c.back);
    if (cards.length === 0) { showToast('Add at least one card.', 'error'); return; }
    const deck = { id: Date.now(), title, subject: 'manual', createdAt: Date.now(), cards };
    const decks = getFlashcardDecks();
    decks.unshift(deck);
    saveFlashcardDecks(decks);
    showToast(`✓ Deck "${title}" saved with ${cards.length} card${cards.length === 1 ? '' : 's'}!`, 'success');
    _flashcardReviewIdx = 0;
    renderFlashcardsList(deck.id);
}

// AI Generate panel — give a topic/subject, or leave blank to use recent history
async function openFlashcardAIGenerate() {
    const content = document.getElementById('flashcards-content');
    if (!content) return;
    const histCount = JSON.parse(localStorage.getItem('user_history') || '[]').length;
    content.innerHTML = `
        <button class="btn-secondary" onclick="renderFlashcardsList()" style="font-size:0.9rem;margin-bottom:14px;"><i class="ph ph-arrow-left"></i> Back</button>
        <h3 style="margin:0 0 12px;color:white;font-size:1rem;"><i class="ph ph-sparkle" style="color:#00cec9;"></i> AI Generate Flashcards</h3>
        <p style="color:var(--text-muted);font-size:0.85rem;margin:0 0 14px;">Type a topic or subject to make a deck about it${histCount ? ', or leave it blank to generate from your recent study history' : ''}.</p>
        <label style="color:white;font-size:0.88rem;display:block;margin-bottom:6px;">Topic or subject</label>
        <input type="text" id="fc-ai-topic" placeholder="e.g. Cell biology, Causes of WWI, Algebra: quadratic equations"
            style="width:100%;padding:10px;margin-bottom:14px;background:rgba(0,0,0,0.4);border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.9rem;outline:none;box-sizing:border-box;">
        <div style="display:flex;align-items:center;gap:12px;margin-bottom:16px;">
            <label style="color:white;font-size:0.88rem;">Cards to generate:</label>
            <input type="number" id="fc-ai-limit" value="10" min="3" max="50" style="width:80px;padding:9px;background:rgba(0,0,0,0.4);border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.9rem;outline:none;text-align:center;">
        </div>
        <button class="btn-primary" onclick="runFlashcardAIGenerate()" style="width:100%;background:linear-gradient(135deg,#00cec9,#6c5ce7);">
            <i class="ph ph-sparkle"></i> Generate Cards
        </button>
        <div id="fc-ai-status" style="margin-top:12px;"></div>`;
}

async function runFlashcardAIGenerate() {
    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add your OpenAI API key in Settings.', 'error'); return; }
    const limit = Math.max(3, Math.min(50, parseInt(document.getElementById('fc-ai-limit')?.value || '10', 10)));
    const topic = (document.getElementById('fc-ai-topic')?.value || '').trim();
    const statusEl = document.getElementById('fc-ai-status');

    let sysPrompt, userContent;
    if (topic) {
        sysPrompt = `Generate exactly ${limit} study flashcards on the given topic. Return STRICT JSON: {"title":"short deck title","cards":[{"front":"term or question (1-8 words)","back":"clear answer (1-2 sentences, plain text)"}]}`;
        userContent = 'Topic: ' + topic;
    } else {
        const history = JSON.parse(localStorage.getItem('user_history') || '[]').slice(0, 15);
        if (history.length === 0) {
            if (statusEl) statusEl.innerHTML = `<span style="color:#ff6b6b;">Enter a topic above, or do some study sessions first.</span>`;
            return;
        }
        sysPrompt = `Generate exactly ${limit} flashcards from the following study history. Return STRICT JSON: {"title":"short deck title","cards":[{"front":"term or question (1-8 words)","back":"clear answer (1-2 sentences, plain text)"}]}`;
        userContent = history.map(h => `Q: ${h.question || ''}\nA: ${(h.answer || '').replace(/<[^>]+>/g, ' ').slice(0, 800)}`).join('\n\n---\n\n').slice(0, 8000);
    }
    if (statusEl) statusEl.innerHTML = '<span style="color:var(--text-muted);">Generating…</span>';
    try {
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o-mini',
                response_format: { type: 'json_object' },
                messages: [
                    { role: 'system', content: sysPrompt },
                    { role: 'user', content: userContent }
                ]
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message);
        const parsed = JSON.parse(data.choices[0].message.content);
        const deck = { id: Date.now(), title: parsed.title || (topic ? topic : 'AI Generated Deck'), subject: 'ai', createdAt: Date.now(), cards: parsed.cards || [] };
        const decks = getFlashcardDecks();
        decks.unshift(deck);
        saveFlashcardDecks(decks);
        showToast(`✓ ${deck.cards.length} flashcards generated!`, 'success', 4000);
        renderFlashcardsList(deck.id);
    } catch (err) {
        if (statusEl) statusEl.innerHTML = `<span style="color:#ff6b6b;">Error: ${escapeHtmlSafe(err.message)}</span>`;
    }
}
function renderFlashcardsList(focusDeckId) {
    const content = document.getElementById('flashcards-content');
    if (!content) return;
    const decks = getFlashcardDecks();
    if (decks.length === 0) {
        content.innerHTML = `
            <div style="text-align:center;padding:40px 20px;color:var(--text-muted);">
                <div style="font-size:1.25rem;opacity:0.4;margin-bottom:12px;">📇</div>
                <p style="margin:0;">No flashcard decks yet. Open a history entry and click <strong style="color:#fff;">Make flashcards</strong> to generate one.</p>
            </div>`;
        return;
    }
    if (focusDeckId) {
        const deck = decks.find(d => d.id === focusDeckId);
        if (deck) { _flashcardReviewIdx = 0; renderFlashcardReview(deck.id); return; }
    }
    content.innerHTML = decks.map(d => `
        <div class="glass-panel" style="padding:14px 16px;margin-bottom:10px;display:flex;justify-content:space-between;align-items:center;gap:10px;">
            <div style="flex:1;min-width:0;">
                <div style="color:white;font-weight:600;font-size:0.95rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtmlSafe(d.title)}</div>
                <div style="color:var(--text-muted);font-size:0.88rem;">${d.cards.length} cards · ${(d.subject || '').toUpperCase()}</div>
            </div>
            <button class="btn-secondary" onclick="_flashcardReviewIdx=0;renderFlashcardReview(${d.id})" style="padding:8px 14px;font-size:0.84rem;"><i class="ph ph-play"></i> Review</button>
            <button class="btn-secondary" onclick="deleteFlashcardDeck(${d.id})" style="padding:8px 12px;font-size:0.84rem;color:#ff6b6b;border-color:rgba(255,107,107,0.3);"><i class="ph ph-trash"></i></button>
        </div>
    `).join('');
}
// ════════════════════════════════════════════════════════════════════
// v12.3 — POMODORO TIMER (community suggestion @tomato_25)
// v12.4 — moved into companion chat; audio beep on phase end
// 25-minute focus blocks alternating with 5-minute breaks. Persists state
// in localStorage so it keeps ticking across tab switches. Auto-pauses
// companion emotes during focus blocks (via window._pomodoroFocusActive).
// ════════════════════════════════════════════════════════════════════
const POMODORO_FOCUS_MIN = 25;
const POMODORO_BREAK_MIN = 5;
let _pomodoroTimer = null;
window._pomodoroFocusActive = false;

// ── Web Audio beep on phase complete ────────────────────────────────
function _pomodoroBeep() {
    try {
        const vol = parseFloat(localStorage.getItem('sfx_volume') ?? '0.5');
        if (vol === 0) return;
        const ctx = new (window.AudioContext || window.webkitAudioContext)();
        // Three short ascending tones
        [[0, 440], [0.2, 523], [0.4, 659]].forEach(([startTime, freq]) => {
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.connect(gain); gain.connect(ctx.destination);
            osc.frequency.value = freq;
            osc.type = 'sine';
            gain.gain.setValueAtTime(vol * 0.5, ctx.currentTime + startTime);
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + startTime + 0.3);
            osc.start(ctx.currentTime + startTime);
            osc.stop(ctx.currentTime + startTime + 0.32);
        });
        // Auto-close the context after 2s
        setTimeout(() => ctx.close(), 2000);
    } catch (_) { /* AudioContext not available */ }
}

function getPomodoroState() {
    try { return JSON.parse(localStorage.getItem('pomodoro_state') || 'null'); }
    catch { return null; }
}
function setPomodoroState(s) {
    if (s) localStorage.setItem('pomodoro_state', JSON.stringify(s));
    else localStorage.removeItem('pomodoro_state');
}
function startPomodoro(phase) {
    phase = phase || 'focus';
    const durationMin = phase === 'focus' ? POMODORO_FOCUS_MIN : POMODORO_BREAK_MIN;
    setPomodoroState({
        phase,
        endsAt: Date.now() + durationMin * 60 * 1000,
        running: true
    });
    window._pomodoroFocusActive = (phase === 'focus');
    tickPomodoro();
}
function pausePomodoro() {
    const s = getPomodoroState();
    if (!s || !s.running) return;
    const remaining = s.endsAt - Date.now();
    setPomodoroState({ ...s, running: false, remaining });
    if (_pomodoroTimer) { clearInterval(_pomodoroTimer); _pomodoroTimer = null; }
    renderPomodoroWidget();
}
function resumePomodoro() {
    const s = getPomodoroState();
    if (!s || s.running) return;
    setPomodoroState({ ...s, endsAt: Date.now() + (s.remaining || 0), running: true });
    tickPomodoro();
}
function resetPomodoro() {
    if (_pomodoroTimer) { clearInterval(_pomodoroTimer); _pomodoroTimer = null; }
    setPomodoroState(null);
    window._pomodoroFocusActive = false;
    renderPomodoroWidget();
}
function tickPomodoro() {
    if (_pomodoroTimer) clearInterval(_pomodoroTimer);
    _pomodoroTimer = setInterval(() => {
        const s = getPomodoroState();
        if (!s || !s.running) { clearInterval(_pomodoroTimer); return; }
        if (Date.now() >= s.endsAt) {
            // Phase complete — beep, toast, flip phase
            _pomodoroBeep();
            const next = s.phase === 'focus' ? 'break' : 'focus';
            if (typeof showToast === 'function') {
                showToast(next === 'break' ? '🍅 Focus block done! Take a 5-minute break.' : '⚡ Break over — back to focus!', 'success', 6000);
            }
            startPomodoro(next);
            return;
        }
        renderPomodoroWidget();
        renderCompanionPomodoroBar();
    }, 1000);
    renderPomodoroWidget();
    renderCompanionPomodoroBar();
}

// v12.4 — openPomodoro() now shows the Pomodoro bar inside companion chat.
// The old floating widget is kept as a fallback when companion chat isn't open.
function openPomodoro() {
    const chatEl = document.getElementById('companion-chat');
    const barEl = document.getElementById('companion-pomodoro-bar');
    if (chatEl && chatEl.style.display !== 'none' && barEl) {
        // Companion chat is open — show bar inside it
        barEl.style.display = 'block';
        renderCompanionPomodoroBar();
    } else {
        // Companion chat not open — open it and show bar, or fall back to floating widget
        const hasCompanion = document.getElementById('companion-sprite')?.dataset?.companionId;
        if (hasCompanion) {
            openCompanionChat(hasCompanion);
            setTimeout(() => {
                const b = document.getElementById('companion-pomodoro-bar');
                if (b) { b.style.display = 'block'; renderCompanionPomodoroBar(); }
            }, 100);
        } else {
            // No companion active — use floating widget as fallback
            let widget = document.getElementById('pomodoro-widget');
            if (!widget) {
                widget = document.createElement('div');
                widget.id = 'pomodoro-widget';
                widget.style.cssText = `
                    position:fixed;bottom:24px;left:24px;z-index:9400;
                    background:rgba(10,10,20,0.96);border:1px solid rgba(255,107,107,0.4);
                    border-radius:14px;padding:16px;min-width:240px;
                    box-shadow:0 12px 36px rgba(0,0,0,0.6), 0 0 24px rgba(255,107,107,0.15);
                    backdrop-filter:blur(12px);font-family:inherit;
                `;
                document.body.appendChild(widget);
            }
            renderPomodoroWidget();
        }
    }
}
function closePomodoroWidget() {
    const w = document.getElementById('pomodoro-widget');
    if (w) w.remove();
}
function hideCompanionPomodoro() {
    const b = document.getElementById('companion-pomodoro-bar');
    if (b) b.style.display = 'none';
}

// Update the slim pomodoro bar inside companion chat
function renderCompanionPomodoroBar() {
    const bar = document.getElementById('companion-pomodoro-bar');
    if (!bar || bar.style.display === 'none') return;
    const s = getPomodoroState();
    let msLeft = 0;
    let phase = 'focus';
    if (s) {
        phase = s.phase;
        msLeft = s.running ? (s.endsAt - Date.now()) : (s.remaining || 0);
        if (msLeft < 0) msLeft = 0;
    }
    const mm = String(Math.floor(msLeft / 60000)).padStart(2, '0');
    const ss = String(Math.floor((msLeft % 60000) / 1000)).padStart(2, '0');
    const timerEl = document.getElementById('cp-timer');
    const phaseEl = document.getElementById('cp-phase-label');
    const startBtn = document.getElementById('cp-start-btn');
    const pauseBtn = document.getElementById('cp-pause-btn');
    const resumeBtn = document.getElementById('cp-resume-btn');
    const resetBtn = document.getElementById('cp-reset-btn');
    if (timerEl) timerEl.textContent = `${mm}:${ss}`;
    if (phaseEl) {
        phaseEl.textContent = phase === 'focus' ? '🍅 Focus' : '☕ Break';
        phaseEl.style.color = phase === 'focus' ? '#ff6b6b' : '#00cec9';
    }
    if (timerEl) timerEl.style.color = phase === 'focus' ? 'white' : '#7fffec';
    if (startBtn) startBtn.style.display = !s ? 'flex' : 'none';
    if (pauseBtn) pauseBtn.style.display = (s && s.running) ? 'flex' : 'none';
    if (resumeBtn) resumeBtn.style.display = (s && !s.running) ? 'flex' : 'none';
    if (resetBtn) resetBtn.style.display = s ? 'flex' : 'none';
}
function renderPomodoroWidget() {
    const widget = document.getElementById('pomodoro-widget');
    if (!widget) return;
    const s = getPomodoroState();
    let phase = s ? s.phase : 'focus';
    let msLeft = 0;
    if (s) {
        msLeft = s.running ? (s.endsAt - Date.now()) : (s.remaining || 0);
        if (msLeft < 0) msLeft = 0;
    }
    const mm = Math.floor(msLeft / 60000);
    const ss = Math.floor((msLeft % 60000) / 1000);
    const time = `${String(mm).padStart(2, '0')}:${String(ss).padStart(2, '0')}`;
    const accent = phase === 'focus' ? '#ff6b6b' : '#00cec9';
    const phaseLabel = phase === 'focus' ? '🍅 Focus' : '☕ Break';

    let buttons = '';
    if (!s) {
        buttons = `<button class="btn-primary" onclick="startPomodoro('focus')" style="flex:1;padding:8px;background:linear-gradient(135deg,#ff6b6b,#ff4757);border:none;border-radius:6px;color:white;cursor:pointer;font-weight:600;font-size:0.84rem;"><i class="ph ph-play"></i> Start 25-min focus</button>`;
    } else if (s.running) {
        buttons = `
            <button class="btn-secondary" onclick="pausePomodoro()" style="flex:1;padding:8px;font-size:0.84rem;"><i class="ph ph-pause"></i> Pause</button>
            <button class="btn-secondary" onclick="resetPomodoro()" style="padding:8px 12px;font-size:0.84rem;color:#ff6b6b;border-color:rgba(255,107,107,0.3);"><i class="ph ph-stop"></i></button>`;
    } else {
        buttons = `
            <button class="btn-primary" onclick="resumePomodoro()" style="flex:1;padding:8px;background:linear-gradient(135deg,${accent},#00cec9);border:none;border-radius:6px;color:white;cursor:pointer;font-weight:600;font-size:0.84rem;"><i class="ph ph-play"></i> Resume</button>
            <button class="btn-secondary" onclick="resetPomodoro()" style="padding:8px 12px;font-size:0.84rem;color:#ff6b6b;border-color:rgba(255,107,107,0.3);"><i class="ph ph-stop"></i></button>`;
    }

    widget.innerHTML = `
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">
            <div style="color:${accent};font-size:0.9rem;font-weight:700;letter-spacing:1px;text-transform:uppercase;">${phaseLabel}</div>
            <button onclick="closePomodoroWidget()" style="background:transparent;border:none;color:var(--text-muted);cursor:pointer;font-size:1rem;padding:0;"><i class="ph ph-x"></i></button>
        </div>
        <div style="font-family:'Fira Code', monospace;font-size:1.4rem;font-weight:700;color:white;text-align:center;margin-bottom:10px;letter-spacing:2px;">${time}</div>
        <div style="display:flex;gap:9px;">${buttons}</div>
        ${s ? `<div style="margin-top:8px;font-size:0.9rem;color:var(--text-muted);text-align:center;">${phase === 'focus' ? 'Companion auto-quieted' : 'Stretch · water · breathe'}</div>` : ''}
    `;
    // Also sync companion chat bar
    renderCompanionPomodoroBar();
}
// Resume the running timer on page load if there was one
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        const s = getPomodoroState();
        if (s && s.running) { tickPomodoro(); openPomodoro(); }
    }, 800);
});

function deleteFlashcardDeck(id) {
    if (!confirm('Delete this deck?')) return;
    saveFlashcardDecks(getFlashcardDecks().filter(d => d.id !== id));
    renderFlashcardsList();
}
let _flashcardReviewIdx = 0;
function renderFlashcardReview(deckId) {
    const deck = getFlashcardDecks().find(d => d.id === deckId);
    if (!deck) return;
    // NOTE: do NOT reset _flashcardReviewIdx here — callers that open a deck
    // for the first time must set it to 0 themselves. Resetting here would
    // undo the Prev/Next onclick handlers that increment/decrement it before
    // calling back into this function.
    const content = document.getElementById('flashcards-content');
    if (!content) return;
    function show(flipped) {
        window._fc_currentIdx = _flashcardReviewIdx; // keep SM-2 handler in sync
        const card = deck.cards[_flashcardReviewIdx];
        // SM-2 next-review badge (show days until due if card has sm2 data)
        let dueBadge = '';
        if (card.sm2 && card.sm2.nextReview) {
            const daysLeft = Math.round((card.sm2.nextReview - Date.now()) / 86400000);
            const label = daysLeft <= 0 ? 'Due now' : `Due in ${daysLeft}d`;
            const col = daysLeft <= 0 ? '#ff6b6b' : '#00cec9';
            dueBadge = `<span style="font-size:0.9rem;color:${col};background:${col}22;border:1px solid ${col}44;padding:2px 8px;border-radius:10px;margin-left:8px;">${label}</span>`;
        }
        // v12.6 — progress bar
        const _fcPct = Math.round(((_flashcardReviewIdx + 1) / deck.cards.length) * 100);
        const _fcColor = _fcPct === 100 ? '#00b894' : 'var(--accent)';
        content.innerHTML = `
            <button class="btn-secondary" onclick="renderFlashcardsList()" style="font-size:0.9rem;margin-bottom:14px;"><i class="ph ph-arrow-left"></i> All decks</button>
            <div style="height:5px;border-radius:4px;background:rgba(255,255,255,0.08);margin-bottom:10px;overflow:hidden;">
                <div style="height:100%;width:${_fcPct}%;background:linear-gradient(90deg,${_fcColor},var(--accent-glow,#00cec9));border-radius:4px;transition:width 0.3s ease;"></div>
            </div>
            <div style="color:var(--text-muted);font-size:0.9rem;margin-bottom:8px;text-align:center;">Card ${_flashcardReviewIdx + 1} / ${deck.cards.length} · ${escapeHtmlSafe(deck.title)}${dueBadge}</div>
            <div onclick="window._fcFlip(this)"
                 data-flipped="${flipped ? '1' : '0'}"
                 data-front="${escapeHtmlSafe(card.front)}" data-back="${escapeHtmlSafe(card.back)}"
                 style="background:linear-gradient(135deg, rgba(108,92,231,0.18), rgba(0,206,201,0.10));border:1px solid rgba(108,92,231,0.4);border-radius:14px;padding:50px 30px;min-height:200px;display:flex;align-items:center;justify-content:center;cursor:pointer;text-align:center;margin-bottom:14px;transition:transform 0.2s;"
                 onmouseover="this.style.transform='translateY(-2px)'" onmouseout="this.style.transform=''">
                <div class="fc-side" style="color:white;font-size:1.2rem;line-height:1.5;">${escapeHtmlSafe(flipped ? card.back : card.front)}</div>
            </div>
            <div style="text-align:center;color:var(--text-muted);font-size:0.85rem;margin-bottom:14px;"><i class="ph ph-cursor-click"></i> Click the card to reveal — then rate yourself</div>
            <div id="fc-card-actions" style="display:flex;flex-direction:column;gap:12px;">
                <div style="display:flex;gap:12px;justify-content:space-between;">
                    <button id="fc-prev-btn" class="btn-secondary" ${_flashcardReviewIdx === 0 ? 'disabled style="opacity:0.4;cursor:not-allowed;"' : ''} onclick="_flashcardReviewIdx--; renderFlashcardReview(${deckId})"><i class="ph ph-arrow-left"></i> Prev</button>
                    <button id="fc-next-btn" class="btn-primary" onclick="_flashcardReviewIdx = (_flashcardReviewIdx + 1) % ${deck.cards.length}; renderFlashcardReview(${deckId})">Next <i class="ph ph-arrow-right"></i></button>
                </div>
            </div>
        `;
        // Inject SM-2 rating buttons after render
        setTimeout(() => _injectSM2Buttons(deckId), 0);
    }
    show(false);
}

// Flip a review card. (Replaces the old inline onclick whose JSON.stringify
// injected double-quotes into a double-quoted onclick="" attribute, which broke
// the handler so "click to reveal" never worked.)
window._fcFlip = function(el) {
    if (!el) return;
    var flipped = el.dataset.flipped !== '1';
    el.dataset.flipped = flipped ? '1' : '0';
    var side = el.querySelector('.fc-side');
    if (side) side.textContent = flipped ? (el.dataset.back || '') : (el.dataset.front || '');
    if (flipped && typeof window.flipFlashcard === 'function') window.flipFlashcard();
};

// v12.1 — "Explain the concept" re-runs Tutor Mode on the original question
// from a history entry. Switches to the appropriate subject view + fills in
// the input + triggers the tutor flow.
function reExplainHistoryEntry(id) {
    const entry = userHistory.find(e => e.id === id);
    if (!entry) return;
    // Force tutor mode for this re-run
    const prevMode = localStorage.getItem('difficulty_mode');
    localStorage.setItem('difficulty_mode', 'tutor');
    document.getElementById('history-modal').classList.add('hidden');

    if (entry.type === 'math') {
        if (typeof switchTab === 'function') switchTab('math');
        const inp = document.getElementById('math-text-input');
        if (inp) inp.value = entry.question || '';
        setTimeout(() => { if (typeof processMathInput === 'function') processMathInput(); }, 350);
    } else if (entry.type === 'science') {
        if (typeof switchTab === 'function') switchTab('science');
        const inp = document.getElementById('science-input');
        if (inp) inp.value = entry.question || '';
        setTimeout(() => { if (typeof solveScience === 'function') solveScience(); }, 350);
    } else {
        showToast('Re-explain not available for this entry type.', 'info', 3000);
        if (prevMode) localStorage.setItem('difficulty_mode', prevMode);
    }
}

function clearHistory() {
    showConfirm('Clear History', 'Delete all session history?', () => {
        userHistory = [];
        localStorage.removeItem('user_history');
        renderHistoryList();
        showToast('History cleared.', 'info');
    });
}

// ============================================================
// ADVANCED AI TYPING ASSISTANT (Grammarly-Style)
// ============================================================
let typingAssistDebounce = null;
let lastCorrectedText = '';
let isApplyingCorrection = false;

function setupTypingAssist() {
    const englishInput = document.getElementById('english-input');
    if (!englishInput) return;

    // Remove any existing listeners to avoid duplicates
    englishInput.removeEventListener('input', typingAssistHandler);
    englishInput.removeEventListener('input', applyInstantCorrections);

    if (localStorage.getItem('typing_assist') === 'true') {
        englishInput.addEventListener('input', applyInstantCorrections); // Instant on every keystroke
        englishInput.addEventListener('input', typingAssistHandler); // AI corrections after pause
    }
}

// Instant corrections (capitalization, punctuation) - runs on every keystroke
function applyInstantCorrections(e) {
    if (isApplyingCorrection) return;
    const textarea = e.target;
    let text = textarea.value;
    const originalText = text;

    // Auto-capitalize first letter of sentences
    text = text.replace(/(^\w|[.!?]\s+\w)/g, match => match.toUpperCase());

    // Fix common punctuation issues
    text = text.replace(/\s+([,.!?;:])/g, '$1'); // Remove space before punctuation
    text = text.replace(/([,.!?;:])\s*([A-Za-z])/g, '$1 $2'); // Add space after punctuation
    text = text.replace(/\s{2,}/g, ' '); // Remove multiple spaces

    // Capitalize 'i' to 'I' when followed by space or punctuation
    text = text.replace(/\bi\s/gi, 'I '); // Standalone 'i'
    text = text.replace(/\bi'/gi, "I'"); // I in contractions like "i'm"
    text = text.replace(/\bi$/gi, "I"); // 'i' at end of text

    if (text !== originalText) {
        isApplyingCorrection = true;
        const cursorPos = textarea.selectionStart;
        const diff = text.length - originalText.length;
        textarea.value = text;
        textarea.setSelectionRange(cursorPos + diff, cursorPos + diff);
        isApplyingCorrection = false;
    }
}

async function typingAssistHandler(e) {
    if (isApplyingCorrection) return;

    clearTimeout(typingAssistDebounce);
    typingAssistDebounce = setTimeout(async () => {
        if (localStorage.getItem('typing_assist') !== 'true') return;

        const englishInput = document.getElementById('english-input');
        const text = englishInput ? englishInput.value.trim() : '';

        // Skip if text is too short or hasn't changed significantly
        if (!text || text.length < 15 || text === lastCorrectedText) return;

        const apiKey = getApiKey();
        if (!apiKey) return;

        try {
            const res = await fetch('https://api.openai.com/v1/chat/completions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
                body: JSON.stringify({
                    model: 'gpt-4o-mini', // Use mini for faster, cheaper corrections
                    messages: [
                        {
                            role: 'system',
                            content: `You are an advanced grammar and writing assistant like Grammarly. Fix:
- Grammar errors (subject-verb agreement, tense issues, etc.)
- Spelling mistakes
- Punctuation errors
- Capitalization
- Awkward phrasing (make it natural)

Return ONLY the corrected text with NO explanations, NO quotes, NO commentary. Preserve the user's writing style and tone. Make minimal changes - only fix clear errors.`
                        },
                        { role: 'user', content: text }
                    ],
                    max_tokens: 600,
                    temperature: 0.3 // Lower temperature for consistent corrections
                })
            });

            const data = await res.json();
            if (data.error) return;

            const corrected = data.choices[0].message.content.trim();

            // Only apply if significantly different and cursor is at end (user stopped typing)
            if (corrected !== text && englishInput && englishInput === document.activeElement) {
                const cursorAtEnd = englishInput.selectionStart === englishInput.value.length;

                if (cursorAtEnd || text.length - englishInput.selectionStart < 5) {
                    isApplyingCorrection = true;
                    const cursorPos = englishInput.selectionStart;
                    englishInput.value = corrected;
                    lastCorrectedText = corrected;

                    // Smart cursor positioning
                    const newCursorPos = Math.min(cursorPos + (corrected.length - text.length), corrected.length);
                    englishInput.setSelectionRange(newCursorPos, newCursorPos);

                    // Show subtle notification
                    showToast('✨ Grammar corrected', 'success', 2000);
                    isApplyingCorrection = false;
                }
            }
        } catch (e) {
            console.log('Typing assist error:', e);
        }
    }, 2000); // 2 second delay - wait for user to stop typing
}

