    'medieval':     { headerBg: 'linear-gradient(135deg, rgba(128,128,140,0.18), rgba(80,80,90,0.10))', headerBorder: 'rgba(150,150,170,0.45)', emoji: '⚔️', title: 'Medieval Era', tagline: 'Kings, knights, monasteries, plagues, and the slow build to a new world.' },
    'early-modern': { headerBg: 'linear-gradient(135deg, rgba(184,115,51,0.18), rgba(139,69,19,0.08))', headerBorder: 'rgba(184,115,51,0.4)', emoji: '⚓', title: 'Early Modern Period', tagline: 'Exploration, revolution, printing, gunpowder, and Enlightenment.' },
    'modern':       { headerBg: 'linear-gradient(135deg, rgba(205,127,50,0.18), rgba(150,75,0,0.08))', headerBorder: 'rgba(205,127,50,0.45)', emoji: '🏭', title: 'Modern Era', tagline: 'Industry, empire, world wars — the century the world rewrote itself.' },
    'contemporary': { headerBg: 'linear-gradient(135deg, rgba(0,255,245,0.12), rgba(124,77,255,0.10))', headerBorder: 'rgba(0,255,245,0.4)', emoji: '📡', title: 'Contemporary Era', tagline: 'Cold War, decolonization, civil rights, internet, climate, AI — the world you live in.' }
