let screenSolveStep = 1; // 1 = read instructions, 2 = analyze puzzle
let capturedInstructions = null;

async function startBlockSolverScreenShare() {
    screenSolveStep = 1; // Reset to step 1
    capturedInstructions = null;
    try {
        const video = document.getElementById('block-solver-video');
        const panel = document.getElementById('block-solver-video-panel');
        const startBtn = document.getElementById('block-solver-start-btn');
        const captureBtn = document.getElementById('block-solver-capture-btn');
        const stopBtn = document.getElementById('block-solver-stop-btn');

        blockSolverStream = await navigator.mediaDevices.getDisplayMedia({
            video: { cursor: "always" },
            audio: false
        });

        video.srcObject = blockSolverStream;
        panel.classList.remove('hidden');
        startBtn.style.display = 'none';
        captureBtn.style.display = 'block';
        stopBtn.style.display = 'block';

        blockSolverStream.getVideoTracks()[0].onended = () => {
            stopBlockSolverScreenShare();
        };

        showToast('Screen sharing started! Click "Capture & Analyze" when ready.', 'success');
    } catch (err) {
        console.error("Error starting screen share:", err);
        showToast("Could not start screen share.", 'error');
    }
}

function stopBlockSolverScreenShare() {
    const video = document.getElementById('block-solver-video');
    const panel = document.getElementById('block-solver-video-panel');
    const startBtn = document.getElementById('block-solver-start-btn');
    const captureBtn = document.getElementById('block-solver-capture-btn');
    const stopBtn = document.getElementById('block-solver-stop-btn');

    if (blockSolverStream) {
        blockSolverStream.getTracks().forEach(track => track.stop());
        blockSolverStream = null;
    }

    video.srcObject = null;
    panel.classList.add('hidden');
    startBtn.style.display = 'block';
    captureBtn.style.display = 'none';
    stopBtn.style.display = 'none';

    showToast('Screen sharing stopped.', 'info');
}

