async function solveCode(lang) {
    const inputId = `code-input-${lang}`;
    const el = document.getElementById(inputId);
    if(!el) return;
    const input = el.value.trim();
    if (!input) {
        showToast('Enter code or describe a problem to solve.', 'warning');
        return;
    }

    const output = document.getElementById('code-output');
    const outputContent = document.getElementById('code-output-content');
    output.classList.remove('hidden');
    outputContent.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-muted);"><i class="ph ph-spinner" style="font-size:1.35rem; animation: spin 1s linear infinite;"></i><p style="margin-top:10px;">Analyzing your code...</p></div>';

    const roles = {
        java: 'Java Programming Tutor who explains concepts clearly and provides working code examples',
        python: 'Python Programming Tutor who explains concepts clearly and provides working code examples',
        web: 'HTML/CSS/JavaScript Full Stack Tutor who explains concepts clearly and provides working code examples',
        general: 'Senior Software Engineer who explains programming concepts clearly across all languages'
    };

    const apiKey = getApiKey();
    if (!apiKey) {
        showToast('Add API key in Settings.', 'error');
        outputContent.innerHTML = '<div style="color:#d63031; padding:20px; text-align:center;"><i class="ph ph-key" style="font-size:1.35rem;"></i><p style="margin-top:10px;">API Key required. Please add it in Settings.</p></div>';
        return;
    }
    try {
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o',
                messages: [
                    { role: 'system', content: `You are an expert ${roles[lang] || 'Programming Tutor'}. Format your responses with clear HTML structure using <h3>, <p>, <code>, <pre>, <ul>, and <ol> tags. Do not use markdown backticks.` },
                    { role: 'user', content: input }
                ],
                max_tokens: 2000
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message);
        const answer = data.choices[0].message.content;
        outputContent.innerHTML = sanitizeHTML(answer.replace(/\n/g, '<br>'));
        addToHistory('code', `[${lang.toUpperCase()}] ${input}`, answer);
        showToast('Code analyzed successfully!', 'success');
    } catch (err) {
        outputContent.innerHTML = `<div style="color:#d63031; padding:20px; text-align:center;"><i class="ph ph-x-circle" style="font-size:1.35rem;"></i><p style="margin-top:10px;">Error: ${err.message}</p></div>`;
        showToast('Analysis failed.', 'error');
    }
}


async function genericAiCall(role, query, outputEl) {
    const apiKey = getApiKey();
    try {
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o-mini',
                messages: [{ role: 'system', content: `You are an expert ${role}.` }, { role: 'user', content: query }]
            })
        });
        const data = await res.json();
        outputEl.innerHTML = sanitizeHTML(data.choices[0].message.content.replace(/\n/g, '<br>'));
    } catch (err) { outputEl.innerHTML = `Error: ${err.message}`; }
}

