// v12.1 — show Help Me (tutor) instead of Solve This in tutor mode
function refreshLiveVisionButtons() {
    const solveBtn = document.getElementById('solve-btn');
    const helpBtn = document.getElementById('help-me-btn');
    if (!solveBtn || !helpBtn) return;
    const mode = (typeof getDifficultyMode === 'function') ? getDifficultyMode() : 'tutor';
    if (mode === 'tutor') {
        solveBtn.style.display = 'none';
        helpBtn.style.display = '';
    } else {
        solveBtn.style.display = '';
        helpBtn.style.display = 'none';
    }
}
document.addEventListener('DOMContentLoaded', () => { setTimeout(refreshLiveVisionButtons, 500); });

// v12.1 — Help Me (Live Vision tutor mode). OCRs the screen, then asks the AI
// for the polished 3-block tutor card (concept + strategy + guiding question) —
// NEVER the answer. The captured problem + guidance are stashed on window so
// the companion can link to this Live Vision session.
window._liveVisionLastProblem = '';
window._liveVisionLastGuidance = '';

async function helpMeLiveVision() {
    const video = document.getElementById('screen-video');
    const canvas = document.getElementById('screen-canvas');
    const solutionPanel = document.getElementById('solution-panel');
    // v19.4 — same mid-session teardown handling as analyzeText: distinguish a
    // stream that DIED (reconnect) from one merely paused (resume), instead of
    // the misleading "Start screen sharing first" for an already-started session.
    var _vt = mediaStream && mediaStream.getVideoTracks && mediaStream.getVideoTracks()[0];
    if (!mediaStream || mediaStream.active === false || !_vt || _vt.readyState === 'ended') {
        if (typeof stopLiveVision === 'function') { try { stopLiveVision(); } catch (_) {} }
        showToast('📺 Screen sharing stopped — tap “Share Screen” to reconnect, then try again.', 'info', 5500);
        return;
    }
    if (video && video.paused) {
        try { await video.play(); } catch (_) {}
        if (video.paused) { showToast('The shared screen is paused — click back into this tab, then try again.', 'info', 4500); return; }
    }

    // Scale canvas to max 1280px wide (proportional)
    const MAX_W = 1280;
    const vw = video.videoWidth, vh = video.videoHeight;
    if (vw > MAX_W) {
        canvas.width = MAX_W;
        canvas.height = Math.round(vh * (MAX_W / vw));
    } else {
        canvas.width = vw;
        canvas.height = vh;
    }
    canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);
    let _hmQ = 0.85;
    let imageDataUrl = canvas.toDataURL('image/jpeg', _hmQ);
    while (imageDataUrl.length > 520000 && _hmQ > 0.45) { _hmQ -= 0.12; imageDataUrl = canvas.toDataURL('image/jpeg', _hmQ); }
    // Skip OCR — GPT-4o vision reads screen text far better
    let ocrText = '';

    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add API key in Settings.', 'error'); return; }

    if (solutionPanel) {
        solutionPanel.classList.remove('hidden');
        const _topicTag = document.getElementById('ai-topic-tag');
        if (_topicTag) _topicTag.textContent = 'TUTOR MODE'; // panel content gets replaced after the first session — tag may be gone, don't crash
        // v13.1 — animated fetch status for tutor mode
        const _hmPhrases = ['Reading your screen…','Finding the concept…','Building your guidance…','Preparing the strategy…','Almost there…'];
        let _hmIdx = 0;
        const _hmAnswerEl = document.getElementById('ai-answer-text');
        const _hmExplainEl = document.getElementById('ai-explanation-text');
        if (_hmAnswerEl) _hmAnswerEl.innerHTML =
            `<span id="hm-fetch-status" style="color:var(--accent);font-size:0.88rem;display:flex;align-items:center;gap:12px;"><i class="ph ph-spinner ph-spin"></i>${_hmPhrases[0]}</span>`;
        if (_hmExplainEl) _hmExplainEl.innerHTML = '';
        window._hmPhaseTimer = setInterval(() => {
            _hmIdx = (_hmIdx + 1) % _hmPhrases.length;
            const s = document.getElementById('hm-fetch-status');
            if (s) s.innerHTML = `<i class="ph ph-spinner ph-spin"></i>${_hmPhrases[_hmIdx]}`;
        }, 1400);
    }

    // Save problem context for companion-link
    window._liveVisionLastProblem = (ocrText || '').slice(0, 800);

    // Subject detection is implicit — let the tutor prompt for math handle most
    // school work; if the problem is clearly science/history, the AI will still
    // adapt because we feed the tutor instructions for "any subject".
    const systemPrompt = `You are NEXUS Tutor analyzing a problem on the student's screen. Return a STRICT JSON object (no prose outside it) with EXACTLY these keys:

{
  "concept": "<2–3 clear sentences that actually TEACH: name the idea, explain what it means in plain language, and give the intuition for WHY it works. This is the reminder a student needs to understand the topic — make it genuinely helpful, not one dry line.>",
  "formula": "<the key rule/formula as a single line, or '' if none>",
  "strategy": "<1–2 sentences: the game plan for THIS specific problem and why that approach fits.>",
  "steps": [
    {
      "instruction": "<what the student DOES this step — a clear action/question, e.g. 'Subtract 7 from both sides.' Do NOT include the result.>",
      "hints": ["<hint 1: a gentle nudge toward the idea, does NOT restate the instruction>", "<hint 2: name the specific operation or thing to look at>", "<hint 3: almost the answer — the full setup with only the final calc left>"],
      "expect": "<the correct result of THIS step only — used to check the student's work>",
      "why": "<1–2 sentences: WHY this step works and what it accomplishes, shown after they solve it. Teach here, don't just label.>"
    }
  ],
  "answer": "<the final answer to the whole problem, as short as possible>"
}

RULES:
- READ THE IMAGE CAREFULLY FIRST. Reconstruct the EXACT problem (numbers, signs, exponents, coordinates). Most wrong answers come from misreading the screen — do not guess. If genuinely unreadable: concept="", strategy="", steps=[], answer="", and put a note in concept asking them to retype it.
- ACCURACY IS THE TOP PRIORITY. Silently SOLVE the whole problem yourself first, then build the steps to match YOUR verified solution. Recompute the final answer a second, independent way and confirm both agree. Substitute the answer back into the original problem to check it works. Watch the classic slips: SIGNS (negatives), fraction order, exponents, and units. For slope/rate: m = (y₂−y₁)/(x₂−x₁) — keep the subtraction order consistent, mind the sign, and NEVER round a fraction to a whole number. If your check fails, fix it before returning. A wrong answer is worse than no answer.
- Teaching quality matters: "concept" and each "why" should help the student actually UNDERSTAND, not just see labels. Be clear and encouraging, but keep it readable on a phone (short paragraphs, no walls of text).
- Break the solution into 2–5 real steps. Each "instruction" is a task the student performs; the RESULT goes ONLY in "expect" (hidden from them).
- "hints" MUST escalate: Hint 1 = nudge, Hint 2 = specific method, Hint 3 = near-complete. 2–3 hints per step, and they must not just restate the instruction.
- MULTIPLE CHOICE: the student clicks an option on THEIR screen, so a wrong position label makes them answer wrong even when your answer is right. In "answer", lead with the correct option's TEXT quoted verbatim. Only cite a letter/number if it is LITERALLY PRINTED next to that option on screen — copy it exactly. If no labels are printed, do NOT invent "option 2"; instead describe the position unambiguously with layout and direction ("2nd of the 4 stacked choices, top-down", "middle of the three side-by-side diagrams"). Before finalizing, re-read the option at that position and confirm its text matches your answer — if they disagree, the TEXT wins. If you can't tell the order, say so instead of guessing.
- Plain text (light inline HTML like <strong> ok). NEVER LaTeX commands — use Unicode ≥ ≤ ÷ × √ ² ³ π θ ° for math.`;

    const userParts = [
        { type: 'text', text: ocrText
            ? `OCR-EXTRACTED TEXT FROM SCREEN (may have errors — use the image as the source of truth):\n${ocrText}\n\nGive the guided step-by-step JSON.`
            : 'Read the problem in the image. Give the guided step-by-step JSON (concept, strategy, steps with escalating hints, and the final answer).' },
        { type: 'image_url', image_url: { url: imageDataUrl, detail: 'high' } }
    ];

    try {
        const _hvCtrl = new AbortController();
        const _hvTimeout = setTimeout(() => _hvCtrl.abort(), 30000);
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            signal: _hvCtrl.signal,
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o',
                messages: [
                    { role: 'system', content: systemPrompt },
                    { role: 'user', content: userParts }
                ],
                max_tokens: 1000,
                temperature: 0.4,
                response_format: { type: 'json_object' }
            })
        });
        clearTimeout(_hvTimeout);
        if (window._hmPhaseTimer) { clearInterval(window._hmPhaseTimer); window._hmPhaseTimer = null; }
        const data = await res.json();
        if (data.error) throw new Error(data.error.message);
        const raw = data.choices[0].message.content || '{}';
        let parsed = {};
        try { parsed = JSON.parse(raw); } catch (_) { parsed = {}; }
        const esc = (typeof escapeHtmlSafe === 'function') ? escapeHtmlSafe : function (s) { return String(s == null ? '' : s); };
        // Stash the guided-solve state for the stepper.
        window._lvSteps = Array.isArray(parsed.steps) ? parsed.steps : [];
        window._lvStepIdx = 0;
        window._lvHintIdx = 0;
        window._lvAnswer = String(parsed.answer || '').trim();
        // Anti-farming: the 30-credit award is once per PROBLEM (answer + steps),
        // not once per session — re-running Help Me on the same capture used to
        // re-award indefinitely. Persisted per account via lv_awarded_problems.
        window._lvProblemKey = window._lvAnswer + '::' + window._lvSteps.map(function (s) { return s.expect || ''; }).join('|');
        try {
            var _lvDone = JSON.parse(localStorage.getItem('lv_awarded_problems') || '[]');
            window._lvAwarded = _lvDone.indexOf(window._lvProblemKey) !== -1;
        } catch (_) { window._lvAwarded = false; }

        // 1) Work board (left): concept + strategy + the step INSTRUCTIONS (no results).
        const workEl = document.getElementById('vision-tutor-work');
        if (workEl) {
            // Compact: concept + strategy only. The step LIST is intentionally not
            // printed here — the interactive solver on the right walks the steps one
            // at a time, so duplicating the full list just made the panel very tall
            // (especially on tablets). Show a one-line pointer instead. (v19)
            var nSteps = window._lvSteps.length;
            workEl.innerHTML =
                (parsed.concept ? '<div class="tutor-block tutor-block-concept"><h3>💡 The concept</h3><p>' + esc(parsed.concept) + '</p>' + (parsed.formula ? '<div class="tutor-formula"><code>' + esc(parsed.formula) + '</code></div>' : '') + '</div>' : '') +
                (parsed.strategy ? '<div class="tutor-block tutor-block-strategy"><h3>🧭 Strategy</h3><p>' + esc(parsed.strategy) + '</p></div>' : '') +
                (nSteps ? '<div class="tutor-block tutor-block-steps"><p style="margin:0;font-size:0.85rem;color:var(--text-muted);"><strong style="color:#a29bfe;">🪜 ' + nSteps + (nSteps === 1 ? ' step' : ' steps') + '</strong> — solve them in the panel on the right. Hints escalate if you get stuck.</p></div>' : '') ||
                '<p style="color:var(--text-muted);">Couldn\'t read the problem clearly — try re-capturing.</p>';
        }
        if (typeof _showVisionWork === 'function') _showVisionWork();

        // 2) Answer box (right): interactive step-by-step solver.
        if (solutionPanel) {
            solutionPanel.innerHTML = `
                <div style="padding:12px 16px;background:linear-gradient(135deg, rgba(108,92,231,0.12), rgba(0,206,201,0.06));border-bottom:1px solid rgba(108,92,231,0.25);display:flex;align-items:center;gap:10px;">
                    <i class="ph ph-graduation-cap" style="color:#a29bfe;font-size:1.05rem;"></i>
                    <span style="color:#a29bfe;font-size:0.85rem;text-transform:uppercase;letter-spacing:1.3px;font-weight:700;">Solve it step by step</span>
                </div>
                <div id="lv-stepper" style="padding:14px 16px;"></div>`;
        }
        window._liveVisionLastGuidance = String((parsed.concept || '') + ' ' + (parsed.strategy || '')).trim().slice(0, 1000);
        if (typeof renderVisionStep === 'function') renderVisionStep();
        // Scroll the interactive solver into view so the student lands on the step
        // to work, not on a wall of content above it.
        try { var _solPanel = document.getElementById('solution-panel'); if (_solPanel) setTimeout(function () { _solPanel.scrollIntoView({ behavior: 'smooth', block: 'center' }); }, 120); } catch (_) {}
        logActivity('study', 'Live Vision — Help Me (tutor)');
        updateStudyStats('problem_solved');

        // Save the full worked tutorial to History (concept, steps, and answer) so
        // the student can review how to do it — not just the final answer.
        try {
            if (typeof addToHistory === 'function') {
                const _steps = (window._lvSteps || []).map(function (s, i) {
                    return (i + 1) + '. ' + (s.instruction || '') + (s.expect ? '  →  ' + s.expect : '') + (s.why ? '  (' + s.why + ')' : '');
                }).join('\n');
                const _histA = (parsed.concept ? 'Concept: ' + parsed.concept + '\n\n' : '')
                    + (parsed.strategy ? 'Strategy: ' + parsed.strategy + '\n\n' : '')
                    + (_steps ? 'Steps:\n' + _steps + '\n\n' : '')
                    + (parsed.answer ? 'Final answer: ' + parsed.answer : '');
                if (_histA.trim()) addToHistory('vision', ('Live Vision tutor — ' + (parsed.answer || 'guided solve')).substring(0, 200), _histA);
            }
        } catch (_) {}
        showToast('✓ Tutor mapped out the steps. Solve them one at a time on the right — hints escalate if you\'re stuck.', 'success', 5000);
    } catch (err) {
        if (window._hmPhaseTimer) { clearInterval(window._hmPhaseTimer); window._hmPhaseTimer = null; }
        showToast('AI Error: ' + err.message, 'error');
        if (solutionPanel) solutionPanel.innerHTML = `<p style="padding:14px;color:#ff6b6b;">Error: ${err.message}</p>`;
    }
}

// v19 — Live Vision tutor-work board helpers.
function _showVisionWork() {
    var w = document.getElementById('vision-tutor-work');
    var t = document.getElementById('vision-board-text');
    var title = document.getElementById('vision-board-title');
    var btn = document.getElementById('vision-board-toggle');
    if (w) w.style.display = 'block';
    if (t) t.style.display = 'none';
    if (title) title.innerHTML = '<i class="ph ph-chalkboard-teacher"></i> TUTOR WORK';
    if (btn) btn.innerHTML = '<i class="ph ph-pencil-simple"></i> My scratch';
}
function toggleVisionScratch() {
    var w = document.getElementById('vision-tutor-work');
    var t = document.getElementById('vision-board-text');
    var title = document.getElementById('vision-board-title');
    var btn = document.getElementById('vision-board-toggle');
    if (!w || !t) return;
    var showScratch = (w.style.display !== 'none');
    if (showScratch) {
        w.style.display = 'none'; t.style.display = 'block'; t.focus();
        if (title) title.innerHTML = '<i class="ph ph-pencil-simple"></i> MY SCRATCH';
        if (btn) btn.innerHTML = '<i class="ph ph-chalkboard-teacher"></i> Tutor work';
    } else { _showVisionWork(); }
}
// Is the student's attempt equivalent to the expected value? Strict-normalize
// first (fast/free), then an AI equivalence check for things like 12/4 == 3.
async function _lvCheckEquivalent(attempt, expected) {
    var norm = function (s) { return String(s).toLowerCase().replace(/\s+/g, '').replace(/[^\w./-]/g, ''); };
    if (!expected || !attempt) return false;
    if (norm(attempt) === norm(expected)) return true;   // exact/normalized match — no AI needed
    try {
        var apiKey = getApiKey();
        if (!apiKey) return false;
        // Use a JSON response, NOT a "yes"/"no" word. json_object mode makes the
        // app's fetch interceptor skip the language + memory injection, so the
        // reply is language-neutral and can't come back as "sí"/"oui"/extra prose
        // that the old parser mis-read as "wrong". (v19 fix)
        var r = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST', headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
            body: JSON.stringify({
                model: 'gpt-4o-mini', temperature: 0, max_tokens: 20,
                response_format: { type: 'json_object' },
                messages: [
                    { role: 'system', content: 'Decide if the student\'s answer matches the correct answer for a math/school step. Ignore formatting, spacing, order, and equivalent forms (e.g. "x=9" equals "9"; "1/2" equals "0.5"; "12 cm" equals "12"). Respond ONLY as JSON: {"equivalent": true} or {"equivalent": false}.' },
                    { role: 'user', content: 'Correct answer: ' + expected + '\nStudent answer: ' + attempt }
                ]
            })
        });
        var d = await r.json();
        var txt = (d.choices && d.choices[0] && d.choices[0].message && d.choices[0].message.content) || '{}';
        try { return JSON.parse(txt).equivalent === true; } catch (_) { return /"equivalent"\s*:\s*true/i.test(txt); }
    } catch (_) { return false; }
}
function _lvRevealAnswerBtn() {
    return '<div style="border-top:1px dashed var(--glass-border);margin-top:12px;padding-top:10px;">'
        + '<button onclick="revealVisionAnswer()" class="btn-secondary" style="width:100%;font-size:0.8rem;"><i class="ph ph-eye"></i> Stuck? Reveal the full answer</button>'
        + '<div id="lv-answer-out" style="display:none;font-size:0.95rem;color:#fff;background:rgba(0,206,201,0.10);border:1px solid rgba(0,206,201,0.3);border-radius:8px;padding:12px;font-weight:600;margin-top:8px;"></div></div>';
}
// Render the current step of the guided solver into #lv-stepper.
function renderVisionStep() {
    var box = document.getElementById('lv-stepper');
    if (!box) return;
    var steps = window._lvSteps || [];
    if (!steps.length) {   // AI gave no steps → simple final-answer-for-credits
        box.innerHTML = '<div style="font-size:0.86rem;color:var(--text-muted);margin-bottom:8px;">Type your final answer to earn 30 credits.</div>'
            + '<input id="lv-answer-input" type="text" placeholder="Your answer…" style="width:100%;box-sizing:border-box;padding:10px 12px;background:rgba(0,0,0,0.3);border:1px solid var(--glass-border);border-radius:8px;color:#fff;font-size:0.9rem;margin-bottom:8px;">'
            + '<button onclick="submitVisionFinal()" class="btn-primary" style="width:100%;"><i class="ph ph-paper-plane-tilt"></i> Submit for 30 credits</button>'
            + '<div id="lv-grade-out" style="display:none;font-size:0.86rem;margin-top:8px;padding:10px 12px;border-radius:8px;"></div>'
            + _lvRevealAnswerBtn();
        return;
    }
    var i = window._lvStepIdx || 0;
    if (i >= steps.length) { _lvFinishStepper(); return; }
    var s = steps[i];
    box.innerHTML =
        '<div style="font-size:0.78rem;font-weight:700;color:#a29bfe;letter-spacing:0.5px;margin-bottom:8px;">STEP ' + (i + 1) + ' OF ' + steps.length + '</div>'
        + '<div style="font-size:0.95rem;color:#fff;margin-bottom:10px;line-height:1.5;">' + escapeHtmlSafe(s.instruction || '') + '</div>'
        + '<input id="lv-step-input" type="text" placeholder="Your answer for this step…" style="width:100%;box-sizing:border-box;padding:10px 12px;background:rgba(0,0,0,0.3);border:1px solid var(--glass-border);border-radius:8px;color:#fff;font-size:0.9rem;margin-bottom:8px;">'
        + '<div style="display:flex;gap:8px;"><button onclick="revealStepHint()" class="btn-secondary" style="flex:1;"><i class="ph ph-lightbulb" style="color:#fdcb6e;"></i> Hint</button>'
        + '<button onclick="checkVisionStep()" class="btn-primary" style="flex:1;"><i class="ph ph-check"></i> Check</button></div>'
        + '<div id="lv-hint-out" style="display:none;font-size:0.86rem;color:#f1d59a;background:rgba(253,203,110,0.08);border:1px solid rgba(253,203,110,0.25);border-radius:8px;padding:9px 11px;margin-top:8px;"></div>'
        + '<div id="lv-step-feedback" style="display:none;font-size:0.86rem;margin-top:8px;padding:9px 11px;border-radius:8px;"></div>'
        + _lvRevealAnswerBtn();
    var inp = document.getElementById('lv-step-input');
    if (inp) inp.addEventListener('keydown', function (e) { if (e.key === 'Enter') { e.preventDefault(); checkVisionStep(); } });
}
// Reveal the NEXT (escalating) hint for the current step. When hints are
// exhausted, offer to reveal THIS step's answer so the student is never stuck.
function revealStepHint() {
    var out = document.getElementById('lv-hint-out');
    var steps = window._lvSteps || []; var s = steps[window._lvStepIdx || 0];
    if (!out || !s) return;
    var hints = Array.isArray(s.hints) ? s.hints : [];
    var idx = window._lvHintIdx || 0;
    out.style.display = 'block';
    if (idx >= hints.length) {
        out.innerHTML = (hints.length ? 'That\'s all the hints. ' : 'No more hints. ')
            + 'Still stuck? <button onclick="revealStepAnswer()" class="btn-secondary" style="margin-top:8px;width:100%;font-size:0.82rem;"><i class="ph ph-eye"></i> Show this step\'s answer &amp; continue</button>';
        return;
    }
    out.innerHTML = '<strong>Hint ' + (idx + 1) + ' of ' + hints.length + ':</strong> ' + escapeHtmlSafe(hints[idx]);
    window._lvHintIdx = idx + 1;
    // After the last hint, also surface the "show answer" escape.
    if (idx + 1 >= hints.length) {
        out.innerHTML += '<div style="margin-top:8px;"><button onclick="revealStepAnswer()" class="btn-secondary" style="width:100%;font-size:0.8rem;"><i class="ph ph-eye"></i> Show this step\'s answer &amp; continue</button></div>';
    }
}
// Reveal the current step's worked result (+ why) and let the student continue.
// No credit for a revealed step, but they're never dead-ended.
function revealStepAnswer() {
    var steps = window._lvSteps || []; var i = window._lvStepIdx || 0; var s = steps[i];
    var fb = document.getElementById('lv-step-feedback');
    if (!s || !fb) return;
    fb.style.display = 'block';
    fb.style.background = 'rgba(0,206,201,0.10)'; fb.style.color = '#fff';
    var last = (i >= steps.length - 1);
    fb.innerHTML = '<div><span style="color:#00cec9;font-weight:700;">This step:</span> ' + escapeHtmlSafe(s.expect || '(no answer)') + '</div>'
        + (s.why ? '<div style="color:#cdd2e0;font-size:0.82rem;margin-top:5px;">' + escapeHtmlSafe(s.why) + '</div>' : '')
        + (last ? '<button onclick="_lvFinishStepper()" class="btn-primary" style="margin-top:8px;width:100%;">See final answer</button>'
                : '<button onclick="nextVisionStep()" class="btn-primary" style="margin-top:8px;width:100%;">Next step →</button>');
}
async function checkVisionStep() {
    var inp = document.getElementById('lv-step-input');
    var fb = document.getElementById('lv-step-feedback');
    var steps = window._lvSteps || []; var i = window._lvStepIdx || 0; var s = steps[i];
    if (!inp || !fb || !s) return;
    var val = (inp.value || '').trim();
    if (!val) { fb.style.display = 'block'; fb.style.color = '#ff9a9a'; fb.style.background = 'transparent'; fb.textContent = 'Type your answer for this step first.'; return; }
    fb.style.display = 'block'; fb.style.color = 'var(--accent)'; fb.style.background = 'transparent'; fb.innerHTML = '<i class="ph ph-spinner ph-spin"></i> Checking…';
    var ok = await _lvCheckEquivalent(val, s.expect || '');
    // v19 — warm, varied feedback so it feels like a real tutor, not a robot
    // repeating "Correct!". Rotates through encouraging phrases.
    var _pick = function (a) { return a[Math.floor(Math.random() * a.length)]; };
    var _praise = ['Nice — that\'s right!', 'Exactly right! 🙌', 'Yes! You got it.', 'Perfect — well done.', 'That\'s it! Nice work.', 'You nailed it. 🎯'];
    var _nudge = ['Not quite — but you\'re close. Here\'s a nudge:', 'Almost! Let\'s work through it together:', 'Good try — here\'s a hint to point you the right way:', 'Not this time, and that\'s okay — here\'s a hint:'];
    if (ok) {
        fb.style.background = 'rgba(0,184,148,0.12)'; fb.style.color = '#7bed9f';
        var whyLine = s.why ? '<div style="color:#cdd2e0;font-size:0.82rem;margin-top:5px;font-weight:400;">💡 ' + escapeHtmlSafe(s.why) + '</div>' : '';
        if (i >= steps.length - 1) {
            fb.innerHTML = '<i class="ph ph-check-circle"></i> ' + _pick(_praise) + ' You worked through the whole thing yourself! 🎉' + whyLine;
            _lvAwardCredits();
            setTimeout(_lvFinishStepper, 1100);
        } else {
            fb.innerHTML = '<i class="ph ph-check-circle"></i> ' + _pick(_praise) + whyLine + '<button onclick="nextVisionStep()" class="btn-primary" style="margin-top:8px;width:100%;">Next step →</button>';
        }
    } else {
        fb.style.background = 'rgba(255,107,107,0.1)'; fb.style.color = '#ff9a9a';
        fb.innerHTML = '<i class="ph ph-x-circle"></i> ' + _pick(_nudge);
        revealStepHint();
    }
}
function nextVisionStep() {
    window._lvStepIdx = (window._lvStepIdx || 0) + 1;
    window._lvHintIdx = 0;
    renderVisionStep();
}
function _lvFinishStepper() {
    var box = document.getElementById('lv-stepper');
    if (!box) return;
    box.innerHTML = '<div style="text-align:center;padding:10px;">'
        + '<div style="font-size:2rem;">🎉</div>'
        + '<div style="font-size:0.95rem;color:#7bed9f;font-weight:700;margin:6px 0;">You solved it step by step!</div>'
        + (window._lvAnswer ? '<div style="font-size:0.9rem;color:#fff;background:rgba(0,206,201,0.10);border:1px solid rgba(0,206,201,0.3);border-radius:8px;padding:10px;margin-top:6px;">Final answer: <strong>' + escapeHtmlSafe(window._lvAnswer) + '</strong></div>' : '')
        + '</div>';
}
function _lvAwardCredits() {
    if (window._lvAwarded) return;
    window._lvAwarded = true;
    // Remember this problem was paid out so re-running Help Me can't re-award it.
    try {
        var _lvDone = JSON.parse(localStorage.getItem('lv_awarded_problems') || '[]');
        if (window._lvProblemKey && _lvDone.indexOf(window._lvProblemKey) === -1) {
            _lvDone.push(window._lvProblemKey);
            localStorage.setItem('lv_awarded_problems', JSON.stringify(_lvDone.slice(-200)));
        }
    } catch (_) {}
    if (typeof updateCredits === 'function') updateCredits(30);
    if (typeof awardXP === 'function') awardXP(15, 'Live Vision guided solve');
    if (typeof recordQuestProgress === 'function') recordQuestProgress('problem_solved');
    if (typeof showToast === 'function') showToast('🪙 +30 credits for working it out yourself!', 'success', 3500);
}
function revealVisionAnswer() {
    var out = document.getElementById('lv-answer-out');
    if (!out) return;
    if (!window._lvAnswer) { out.style.display = 'block'; out.textContent = 'No answer captured — try re-capturing the problem.'; return; }
    if (out.style.display === 'block') return;
    if (!confirm('Reveal the full answer? Working through the steps yourself earns 30 credits.')) return;
    out.style.display = 'block';
    out.innerHTML = '<span style="color:#00cec9;">Answer:</span> ' + escapeHtmlSafe(window._lvAnswer);
}
// Fallback: single final-answer submission when the AI returned no steps.
async function submitVisionFinal() {
    var inp = document.getElementById('lv-answer-input'); var out = document.getElementById('lv-grade-out');
    if (!inp || !out) return;
    var val = (inp.value || '').trim();
    if (!val) { out.style.display = 'block'; out.style.color = '#ff9a9a'; out.textContent = 'Type your answer first.'; return; }
    if (window._lvAwarded) { out.style.display = 'block'; out.style.color = '#7bed9f'; out.textContent = 'You already earned the 30 credits. 🎉'; return; }
    out.style.display = 'block'; out.style.color = 'var(--accent)'; out.innerHTML = '<i class="ph ph-spinner ph-spin"></i> Checking…';
    var ok = await _lvCheckEquivalent(val, window._lvAnswer || '');
    if (ok) { out.style.background = 'rgba(0,184,148,0.12)'; out.style.color = '#7bed9f'; out.innerHTML = '<i class="ph ph-check-circle"></i> Correct! +30 credits.'; _lvAwardCredits(); }
    else { out.style.background = 'rgba(255,107,107,0.1)'; out.style.color = '#ff9a9a'; out.innerHTML = '<i class="ph ph-x-circle"></i> Not quite — check the Tutor Work and try again.'; }
}
window.toggleVisionScratch = toggleVisionScratch;
window.renderVisionStep = renderVisionStep;
window.revealStepHint = revealStepHint;
window.revealStepAnswer = revealStepAnswer;
window.checkVisionStep = checkVisionStep;
window.nextVisionStep = nextVisionStep;
window.revealVisionAnswer = revealVisionAnswer;
window.submitVisionFinal = submitVisionFinal;

async function analyzeText() {
    const video = document.getElementById('screen-video');
    const canvas = document.getElementById('screen-canvas');
    const resultDiv = document.getElementById('ocr-result');
    const solutionPanel = document.getElementById('solution-panel');

    // v19.4 — Screen sharing frequently ends mid-session: the browser's "Stop
    // sharing" bar, switching the shared surface, tab changes, or the OS pausing
    // capture. The old guard `if (!mediaStream || video.paused) return;` did this
    // SILENTLY — so after a few questions "Solve This" looked completely broken
    // with zero feedback. Now: detect a dead stream and tell the student to
    // reconnect (resetting the panel to the Share Screen button); if the video
    // is merely paused, try to resume it before giving up.
    var _vt = mediaStream && mediaStream.getVideoTracks && mediaStream.getVideoTracks()[0];
    var _streamDead = !mediaStream || (mediaStream.active === false) || !_vt || _vt.readyState === 'ended';
    if (_streamDead) {
        if (typeof stopLiveVision === 'function') { try { stopLiveVision(); } catch (_) {} }
        if (typeof showToast === 'function') showToast('📺 Screen sharing stopped — tap “Share Screen” to reconnect, then try again.', 'info', 5500);
        return;
    }
    if (video && video.paused) {
        try { await video.play(); } catch (_) {}
        if (video.paused) {
            if (typeof showToast === 'function') showToast('The shared screen is paused — click back into this tab, then tap Solve This again.', 'info', 4500);
            return;
        }
    }
    resultDiv.innerHTML = '<div style="text-align:center;padding:10px;color:var(--accent);"><i class="ph ph-spinner ph-spin"></i> Scanning screen...</div>';
    solutionPanel.classList.add('hidden');

    // Scale canvas to max 1280px wide (proportional)
    const _MAX_W = 1280;
    const _vw = video.videoWidth, _vh = video.videoHeight;
    if (_vw > _MAX_W) {
        canvas.width = _MAX_W;
        canvas.height = Math.round(_vh * (_MAX_W / _vw));
    } else {
        canvas.width = _vw;
        canvas.height = _vh;
    }
    canvas.getContext('2d').drawImage(video, 0, 0, canvas.width, canvas.height);

    try {
        // Skip OCR — GPT-4o vision reads screen text far better than Tesseract.
        // Start at high quality (sharp graphs read better), but if the encoded image
        // is big enough to trip the proxy's size cap, step the quality down until it
        // fits. This keeps "Request too large" from ever firing on a big screenshot,
        // while keeping quality high whenever the image is a normal size.
        let _q = 0.85;
        let imageDataUrl = canvas.toDataURL('image/jpeg', _q);
        while (imageDataUrl.length > 520000 && _q > 0.45) {
            _q -= 0.12;
            imageDataUrl = canvas.toDataURL('image/jpeg', _q);
        }
        let ocrText = '';

        resultDiv.innerHTML = '<p style="color:var(--text-muted);font-size:0.9rem;">Sending image to vision AI...</p>';

        const apiKey = getApiKey();
        if (!apiKey) { showToast('Add API key in Settings.', 'error'); return; }

        // v13.1 — Animated "fetching answers" state that rotates status words
        // like Claude does, so the user knows the AI is actively working.
        // Restore the standard answer panel structure in case tutor mode replaced it
        solutionPanel.classList.remove('hidden');
        solutionPanel.innerHTML = `
            <div style="padding:10px 14px;border-bottom:1px solid var(--glass-border);display:flex;align-items:center;gap:10px;">
                <span id="ai-topic-tag" style="font-size:0.78rem;font-weight:700;color:var(--accent);letter-spacing:0.5px;">Analyzing…</span>
            </div>
            <div style="padding:12px 14px;">
                <div style="font-size:0.75rem;font-weight:700;color:var(--text-muted);letter-spacing:0.8px;margin-bottom:6px;">ANSWER</div>
                <div id="ai-answer-text" style="color:white;font-size:0.95rem;line-height:1.5;"></div>
            </div>
            <div style="padding:0 14px 14px;">
                <div style="background:rgba(108,92,231,0.06);border:1px solid rgba(108,92,231,0.22);border-radius:10px;padding:12px 14px;">
                    <div style="font-size:0.72rem;font-weight:700;color:#a29bfe;letter-spacing:0.8px;margin-bottom:8px;display:flex;align-items:center;gap:7px;"><i class="ph ph-chalkboard-teacher"></i> EXPLANATION BOARD</div>
                    <div id="ai-explanation-text" style="color:#e2e6f0;font-size:0.9rem;line-height:1.65;"></div>
                </div>
            </div>`;
        const answerEl = document.getElementById('ai-answer-text');
        const explainEl = document.getElementById('ai-explanation-text');

        const statusPhrases = [
            'Reading your screen…',
            'Identifying the question…',
            'Detecting subject & topic…',
            'Pulling relevant knowledge…',
            'Cross-checking the answer…',
            'Formatting the response…',
        ];
        let phaseIdx = 0;
        answerEl.innerHTML = `<span id="lv-fetch-status" style="color:var(--accent);font-size:0.88rem;display:flex;align-items:center;gap:12px;"><i class="ph ph-spinner ph-spin" style="font-size:1rem;"></i>${statusPhrases[0]}</span>`;
        const phaseTimer = setInterval(() => {
            phaseIdx = (phaseIdx + 1) % statusPhrases.length;
            const s = document.getElementById('lv-fetch-status');
            if (s) s.innerHTML = `<i class="ph ph-spinner ph-spin" style="font-size:1rem;"></i>${statusPhrases[phaseIdx]}`;
        }, 1200);
        explainEl.innerHTML = '<span style="color:var(--text-muted);font-size:0.9rem;">Live Vision is analyzing your screen — answer incoming…</span>';

        // v15.0 — Aggressive fill-in-the-blank detection + ultra-precise system prompt
        const systemPrompt = `You are NEXUS Live Vision — an ultra-precise AI tutor reading a student's screen. Detect the academic level from vocabulary and notation. Answer with zero filler, maximum precision.

CRITICAL — FILL-IN-THE-BLANK DETECTION: Before anything else, scan the image for: underscores (___), '[BLANK]', '(blank)', empty input boxes, or any obvious gap in a sentence. If found, this IS a fill-in-the-blank question. Answer = ONLY the exact word(s) that fill the blank — never a full sentence.

UNIVERSAL ONLINE-SCHOOL COMPREHENSION:
- This text could come from ANY online learning platform: Acellus, Edgenuity, Apex Learning, FLVS, Khan Academy, IXL, Albert.io, Quizlet, McGraw-Hill Connect, Pearson MyLab, Canvas, Schoology, Google Classroom, Moodle, Blackboard, Edmentum, Study.com, CK-12, NewsELA, NoRedInk, ALEKS, WebAssign, Mastering Physics/Chemistry/Biology, MyMathLab, ConnectED, BrainPOP, Buzz, Lincoln Learning, Calvert, K12, Connections Academy, etc. — handle them ALL identically.
- Do NOT assume any single platform. The image may have UI buttons mixed in (e.g. "Submit", "Next", "Hint"), question numbers, or multiple choices labeled A/B/C/D, 1/2/3/4, or with bullets — strip the noise and answer the actual academic question.
- Recognize common online-school question formats: multiple choice, fill-in-the-blank, drag-and-drop, matching, short answer, true/false, free response, multi-select. Always identify which format and answer accordingly.

ROLE & CAPABILITIES:
- Identify the subject domain AND course level (e.g., "Math — Calculus II: Series Convergence", "Chemistry — Organic II: SN2 Mechanism", "Physics — E&M: Gauss's Law", "English — Critical Theory: Postcolonial Reading", "History — Constitutional Law: Marbury v. Madison").
- Cover the full curriculum: Grade 9–12 + undergraduate university (Calc I–III, Linear Algebra, ODEs, Gen Chem, Org Chem, Biochem, Physics 1/2/3, Genetics, Critical Theory, US Const. Law, Macro/Micro Economics, etc.).
- Provide the canonical correct answer with calibrated confidence at the level the question is written at — do not over-simplify college problems.
- Strip all conversational filler ("Sure!", "Of course!", "Let me help!", "Great question!") — get straight to substance.

QUESTION TYPE DETECTION — match the format before answering:
FILL-IN-THE-BLANK: underscores (___), "[BLANK]", "(blank)", or empty input fields visible.
  -> "answer" = ONLY the exact word(s) that fill the blank. No full sentences.
  -> Multiple blanks: list them "1. word  2. word  3. word"
  -> Example: "The ___ War ended in 1865." -> answer: "Civil"

MULTIPLE CHOICE — ⚠️ THE #1 SOURCE OF STUDENT ERRORS. FOLLOW EXACTLY:
  The student clicks an option on THEIR screen. If you name the wrong position,
  they get the question WRONG even though you found the right answer. So:
  -> RULE 1 — THE ANSWER TEXT IS THE SOURCE OF TRUTH. Always start "answer" with
     the correct option's text QUOTED VERBATIM as it appears on screen. Never
     lead with a number or letter alone.
  -> RULE 2 — ONLY use a label (A/B/C/D, 1/2/3/4, i/ii/iii) if that label is
     LITERALLY PRINTED on screen next to that option. Copy it exactly as shown.
     If the options have NO printed labels (bare radio buttons, plain rows, a
     grid of pictures), you MUST NOT invent "option 2" / "the 3rd one" style
     numbering — you have no way to know how the student counts them.
  -> RULE 3 — WITH NO PRINTED LABELS, describe the position UNAMBIGUOUSLY with
     the layout AND direction, e.g. "3rd from the top of the 4 stacked choices",
     "the middle of the three side-by-side diagrams", "bottom-left of the 2×2
     grid". Never a bare ordinal with no orientation.
  -> RULE 4 — NEVER say a bare "Option 3" / "the third choice" without either a
     printed label or a Rule-3 description. Ambiguity here loses the student marks.
  -> RULE 5 — CROSS-CHECK before answering: re-read the option at the position
     you are about to name and confirm its text matches the answer text you
     chose. If they disagree, the TEXT wins — fix the position or drop it.
  -> RULE 6 — DIAGRAM/IMAGE OPTIONS (no text to quote): identify the correct one
     by describing what it DEPICTS distinctly (e.g. "the graph whose line slopes
     down to the right and crosses the y-axis at 4"), plus its Rule-3 position.
     Describe it well enough that the student can match it visually.
  -> RULE 7 — If you genuinely cannot tell which position the correct option
     occupies, say so plainly ("I can't reliably tell the option order from this
     capture — match by the text above") rather than guessing a number.
  -> Format: "«exact option text»" then the label/position in parentheses —
     e.g. "«6.02 × 10²³» (labeled C on screen)" or
     "«The mitochondrion» (2nd of the 4 stacked options, counting top-down)".
  -> In explanation: why correct, and why the main distractor is wrong.

TRUE/FALSE:
  -> "answer" = "True" or "False" only. Explanation gives the factual basis.

MATCHING:
  -> "answer" = "1->B, 2->D, 3->A" format for each pair.

SHORT ANSWER / FREE RESPONSE:
  -> Complete answer in 1-3 sentences. Include key terms the teacher expects.

MULTI-SELECT ("select all that apply"):
  -> List all correct options by their VERBATIM TEXT, separated by semicolons.
  -> Apply the SAME labeling rules as MULTIPLE CHOICE above: printed labels only
     if actually printed; otherwise unambiguous positions; never invented numbers.

COMPUTATION:
  -> Final value with units. Key steps in explanation (1-3 steps max).

DRAG-AND-DROP / ORDERING:
  -> Correct order as a numbered list.

DEFINITION / IDENTIFICATION:
  -> "[term] is [definition in 15 words or fewer]." One explanatory sentence in explanation.

GRAPH / CHART READING — READ IT CAREFULLY, this is where mistakes happen:
  -> FIRST, read the axes: note the x-axis and y-axis scale (how much each gridline is worth — it is often NOT 1). State the scale to yourself before reading any point.
  -> To read a point: count gridlines from the origin along x, then along y, multiplying by the scale. Name the exact coordinates you read, e.g. "the line passes through (0, 3) and (2, 7)". If a point sits between gridlines, say so and give your best read.
  -> LINEAR FUNCTION / SLOPE: pick TWO points the line clearly passes through (ideally where it crosses gridline intersections), read them exactly, then slope m = (y₂ − y₁)/(x₂ − x₁). The y-intercept b is where the line crosses the y-axis (x = 0). Write the equation y = mx + b. Double-check the sign of the slope: up-to-the-right is positive, down-to-the-right is negative.
  -> State the points you read in the explanation so the student can verify you read the graph correctly. If the graph is blurry or the scale is unclear, SAY you are unsure of the exact values rather than guessing.
  -> For bar/line charts: read the requested value, trend, max/min, or intercept the same careful way, with units.
DIAGRAM / LABELING: a labeled figure (cell, anatomy, circuit, map, molecule) with parts to identify.
  -> "answer" = the label(s) for the marked part(s), e.g. "A = nucleus, B = mitochondrion".
DATA TABLE: a table of values to read from or compute with.
  -> Pull the exact cell value(s), or compute the requested statistic, and state it with units.

REASONING (apply silently — this is where accuracy comes from; DO NOT skip it and DO NOT guess):
1. Identify the question format from the list above.
2. Strip all UI noise (buttons, progress bars) to isolate the academic question.
3. Reconstruct garbled OCR words using subject context.
4. ACTUALLY SOLVE IT — never guess or approximate. For math/science: state the correct formula/law, plug in the given values, carry the UNITS through, and compute step by step. For chemistry: balance equations, use molar masses, watch significant figures. For physics: check the formula and unit consistency. For recall: retrieve the specific fact, not a vague nearby one.
5. VERIFY before answering: recompute a second way OR substitute your answer back into the problem, and sanity-check the sign, units, and magnitude. If it doesn't check out, redo it. A wrong answer is worse than admitting uncertainty.
5b. IF MULTIPLE CHOICE: re-read the on-screen option at the exact position/label you are about to cite and confirm its text is the answer you chose. A right answer paired with a wrong option number makes the student click the wrong box — treat that as a wrong answer. If the label isn't printed on screen, do not invent one.
6. Only then write the shortest CORRECT answer in the required format. Put the real working/reasoning in "explanation" — if you couldn't verify it, say what you're unsure about instead of guessing.

MATH/SCIENCE FORMATTING: Use Unicode symbols directly — never LaTeX commands. Write ≥ not \geq, × not \times, √ not \sqrt, ÷ not \div, ² ³ for exponents, π θ α β for Greek letters. Fractions as a/b.

STRICT JSON OUTPUT (no prose outside JSON):
{
  "answer": "Exact answer in the format required by the question type. No filler phrases.",
  "explanation": "A DEEPER 'Explanation Board' — teach WHY this answer is correct so the student actually understands, not a one-line reason. Give the reasoning: the key steps or evidence, the underlying principle/rule/formula BY NAME, and the intuition for why it works. Scale the depth to the question: 3–6 sentences or short numbered steps for math/science/reasoning; keep it brief for trivial recall. For fill-in-the-blank, show the full sentence filled in, then explain why that word fits. Light inline HTML (<strong>, <br>, <ul><li>) is fine; no filler phrases.",
  "topic": "Subject + subtopic (e.g. 'Math: Factoring Quadratics', 'Biology: Mitosis Phases', 'History: Reconstruction Era')",
  "questionType": "fill-in-the-blank | multiple-choice | true-false | matching | short-answer | computation | definition | multi-select | drag-and-drop | graph-reading | diagram-labeling | data-table | other"
}

QUALITY BAR: Every answer survives teacher review. If the screen is unreadable, set "answer" to a clarification request and "topic" to "Clarification Needed".

NOW ANALYZE THE STUDENT'S SCREEN:`;

        // Build a multi-part user message: the captured image (vision) + the OCR text (hint)
        const userParts = [
            { type: 'text', text: ocrText
                ? `OCR-EXTRACTED TEXT FROM SCREEN (may have errors — use the image as the source of truth):\n${ocrText}\n\nLook at the image and answer the academic question shown.`
                : 'Look at the image and answer the academic question shown on the screen.' },
            { type: 'image_url', image_url: { url: imageDataUrl, detail: 'high' } }
        ];

        const _lvCtrl = new AbortController();
        const _lvTimeout = setTimeout(() => _lvCtrl.abort(), 30000);
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            signal: _lvCtrl.signal,
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o',
                response_format: { type: 'json_object' },
                messages: [
                    { role: 'system', content: systemPrompt },
                    { role: 'user', content: userParts }
                ],
                max_tokens: 1000,
                temperature: 0.1
            })
        });
        clearTimeout(_lvTimeout);

        const data = await res.json();
        clearInterval(phaseTimer); // stop the rotating-status animation
        if (data.error) throw new Error(data.error.message);

        const ai = JSON.parse(data.choices[0].message.content);

        // v13.1 — enhanced output with question type badge + fill-in-the-blank display
        const cleanedAnswer = (typeof convertMarkdownLeaks === 'function') ? convertMarkdownLeaks(ai.answer || '') : (ai.answer || '');
        const cleanedExplain = (typeof convertMarkdownLeaks === 'function') ? convertMarkdownLeaks(ai.explanation || '') : (ai.explanation || '');
        const qType = ai.questionType || 'other';

        // Typewriter-style reveal helper — streams plain text char-by-char into a container
        function _typewriterHTML(el, html, doneCallback) {
            // For HTML content, set it instantly but animate opacity
            el.innerHTML = html;
            el.style.opacity = '0';
            el.style.transition = 'opacity 0.35s ease';
            requestAnimationFrame(() => { el.style.opacity = '1'; });
            if (doneCallback) setTimeout(doneCallback, 360);
        }

        // Special display for fill-in-the-blank: big box with the answer word highlighted
        const answerElFinal = document.getElementById('ai-answer-text');
        const _emptyAnsMsg = '<span style="color:var(--text-muted);font-weight:400;font-size:0.9rem;">Couldn\'t read a clear answer from the screen — check the explanation below, or re-capture so the question is fully visible.</span>';
        const _hasAns = cleanedAnswer && cleanedAnswer.trim().length > 0;
        if (!_hasAns) {
            // Model returned an empty answer — show a helpful fallback instead of a blank box.
            _typewriterHTML(answerElFinal, _emptyAnsMsg);
        } else if (qType === 'multiple-choice' || qType === 'multi-select') {
            // v19.4 — SAFETY NET for the "wrong option number" bug. If the model
            // cites a bare position ("Option 3", "the third choice") without
            // anchoring it to the option's text or an explicit on-screen label,
            // the student can click the wrong box and lose the mark. Detect that
            // and tell them to match by TEXT instead of by number.
            const _bareOrdinal = /\b(option|choice|answer)\s*(?:#|number\s*)?\d\b|\b(first|second|third|fourth|last)\s+(option|choice|answer)\b/i.test(cleanedAnswer);
            const _anchored = /[«"'‘“]/.test(cleanedAnswer)                       // quoted option text
                || /\b(labeled|marked|printed)\b/i.test(cleanedAnswer)             // cites a real on-screen label
                || /\b(top|bottom|left|right|middle|row|column|grid|stacked|side-by-side|counting)\b/i.test(cleanedAnswer); // explicit layout
            _typewriterHTML(answerElFinal, cleanedAnswer + (_bareOrdinal && !_anchored
                ? '<div style="margin-top:10px;padding:9px 12px;border-radius:8px;background:rgba(253,203,110,0.12);border:1px solid rgba(253,203,110,0.45);font-size:0.84rem;color:#fdcb6e;line-height:1.5;"><strong>⚠️ Match by the answer text, not the number.</strong> NEXUS can\'t always tell how your screen orders the choices — click the option whose <em>wording</em> matches above.</div>'
                : ''));
        } else if (qType === 'fill-in-the-blank') {
            _typewriterHTML(answerElFinal, `<div style="font-size:0.9rem;color:#00cec9;font-weight:700;letter-spacing:1px;margin-bottom:6px;text-transform:uppercase;">Fill in the blank:</div><div style="background:rgba(0,206,201,0.12);border:1px solid rgba(0,206,201,0.4);border-radius:8px;padding:10px 14px;font-size:1.05rem;font-weight:700;color:white;letter-spacing:0.5px;">${cleanedAnswer}</div>`);
        } else {
            _typewriterHTML(answerElFinal, cleanedAnswer);
        }
        _typewriterHTML(document.getElementById('ai-explanation-text'), cleanedExplain || 'No additional context needed.');

        // Show question type badge next to topic
        const qTypeLabels = { 'fill-in-the-blank':'Fill-in-Blank', 'multiple-choice':'Multiple Choice', 'true-false':'True/False', 'matching':'Matching', 'short-answer':'Short Answer', 'computation':'Computation', 'definition':'Definition', 'multi-select':'Multi-Select', 'drag-and-drop':'Drag & Drop', 'other':'General' };
        const topicEl = document.getElementById('ai-topic-tag');
        if (topicEl) topicEl.innerText = (ai.topic || 'General') + (qType && qType !== 'other' ? ' · ' + (qTypeLabels[qType] || qType) : '');
        currentTopic = ai.topic;
        // v12.1 — record problem context for companion-link
        window._liveVisionLastProblem = (ocrText || '').slice(0, 800);
        window._liveVisionLastGuidance = (cleanedAnswer + '\n\n' + cleanedExplain).slice(0, 1000);

// Track this activity
        logActivity('study', `Used Live Vision AI: ${ai.topic}`);
        updateStudyStats('problem_solved');
        updateStudyStats('daily_goal', 33);

        // Save the REAL answer + explanation to History so it's reviewable later.
        // (The old MutationObserver captured the "analyzing…" placeholder instead —
        // that logger has been removed.)
        try {
            if (typeof addToHistory === 'function' && _hasAns) {
                const _histQ = (ai.topic || 'Live Vision problem').toString().substring(0, 200);
                const _plainExplain = (cleanedExplain || '').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
                const _histA = 'Answer: ' + cleanedAnswer + (_plainExplain ? '\n\nExplanation: ' + _plainExplain : '');
                addToHistory('vision', _histQ, _histA);
            }
        } catch (_) {}

        showToast('✓ Problem analyzed successfully!', 'success');

    } catch (err) {
        if (typeof phaseTimer !== 'undefined') clearInterval(phaseTimer);
        // v19.4 — also replace the spinner in the ANSWER panel, not just the OCR
        // strip, so an error (e.g. usage-cap 429 after several questions) never
        // leaves a frozen "Reading your screen…" spinner that looks hung.
        var _ansEl = document.getElementById('ai-answer-text');
        var _msg = (err && err.message) || 'Something went wrong.';
        if (_ansEl) _ansEl.innerHTML = '<span style="color:#ff9a9a;font-size:0.9rem;">' + (typeof escapeHtmlSafe === 'function' ? escapeHtmlSafe(_msg) : _msg) + '</span>';
        showToast('AI Error: ' + _msg, 'error');
        if (resultDiv) resultDiv.innerHTML = `<p style="color:#ff6b6b;">Error: ${_msg}</p>`;
    }
}

// ========== Scientific Calculator Functions ==========
function appendCalc(val) {
    const d = document.getElementById('calc-display');
    if (d.value === '0' && val !== '.' && val !== 'Math.' && !val.startsWith('Math.')) d.value = '';
    d.value += val;
}

function clearCalc() {
    document.getElementById('calc-display').value = '';
}

function backspaceCalc() {
    const d = document.getElementById('calc-display');
    d.value = d.value.slice(0, -1);
}

function calcToggleSign() {
    const d = document.getElementById('calc-display');
    const v = d.value;
    if (!v) return;
    // Try to negate the last number
    const match = v.match(/(-?\d+\.?\d*)$/);
    if (match) {
        const num = match[1];
        const prefix = v.slice(0, v.length - num.length);
        if (num.startsWith('-')) {
            d.value = prefix + num.slice(1);
        } else {
            d.value = prefix + '-' + num;
        }
    }
}

// Factorial helper for calculator
Math.factorial = function(n) {
    n = Math.round(n);
    if (n < 0) return NaN;
    if (n === 0 || n === 1) return 1;
    if (n > 170) return Infinity;
    let r = 1;
    for (let i = 2; i <= n; i++) r *= i;
    return r;
};

function calculate() {
    const d = document.getElementById('calc-display');
    try {
        // Only allow safe math expressions
        let expr = d.value;
        // Auto-close unclosed parentheses
        const open = (expr.match(/\(/g) || []).length;
        const close = (expr.match(/\)/g) || []).length;
        for (let i = 0; i < open - close; i++) expr += ')';
        // Evaluate using Function to avoid direct eval on window scope
        const result = new Function('return ' + expr)();
        d.value = typeof result === 'number' ? (Number.isInteger(result) ? result : parseFloat(result.toFixed(10))) : result;
    } catch (e) {
        d.value = 'Error';
        setTimeout(() => { d.value = ''; }, 1200);
    }
}

// Math Lab Visual Processing
let mathImageBase64 = null; // Holds Ctrl+V pasted image for math lab

// File upload handler for math image button (was missing — broke #math-image-upload)
function handleImageUpload(input) {
    if (!input.files || !input.files[0]) return;
    const file = input.files[0];
    if (file.size > 10 * 1024 * 1024) {
        showToast('Image too large (max 10MB).', 'error');
        return;
    }
    const reader = new FileReader();
    reader.onload = (e) => {
        mathImageBase64 = e.target.result;
        const preview = document.getElementById('image-preview');
        const previewImg = document.getElementById('preview-img');
        if (preview && previewImg) {
            previewImg.src = mathImageBase64;
            preview.classList.remove('hidden');
        }
        showToast('Image attached. Type instructions or click Explain Concept.', 'success', 2500);
    };
    reader.readAsDataURL(file);
}

// v12.1 — Math tutor conversation buffer. Stores the full back-and-forth so the
// user's "Your turn" answers feed back into the next AI turn.
let _mathTutorTurns = [];
let _mathTutorSystem = '';

async function processMathInput() {
    if (!hasPaid()) { openPaymentModal('access'); return; }
    const text = document.getElementById('math-text-input').value.trim();
    const output = document.getElementById('math-tutorial-output');
    const stepByStep = document.getElementById('step-by-step-toggle').checked;

    if (!text && !mathImageBase64) {
        showToast('Please enter a math problem or paste an image (Ctrl+V).', 'warning');
        return;
    }

    // v12.1 — start a fresh tutor conversation
    _mathTutorTurns = [];
    output.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-muted);"><i class="ph ph-spinner ph-spin" style="font-size:1.35rem;"></i><p>Analyzing Math Concept...</p></div>';

    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add API key in Settings.', 'error'); return; }

    try {
        const modeModifier = modePromptFor('math', 'math', text);
        const baseRole = `You are NEXUS Math Tutor — an elite mathematics tutor covering the full curriculum from middle school through undergraduate university. You explain with the depth, rigor, and structure of Microsoft Copilot's best math responses, scaled to the student's actual level.

ROLE & CAPABILITIES (full vertical coverage):
- High school: arithmetic, pre-algebra, algebra I/II, geometry, trigonometry, pre-calculus, statistics & probability, AP Calculus AB/BC.
- College freshman / sophomore: Calculus I–III (limits, derivatives, integrals, sequences & series, vector calc, multivariable), Linear Algebra (matrices, eigenvalues, vector spaces), Differential Equations (ODEs, separation of variables, Laplace transforms), Discrete Math (logic, proofs, combinatorics, graph theory), Probability & Statistics (distributions, hypothesis testing, regression).
- Upper-division undergrad: Real Analysis (epsilon-delta, metric spaces, convergence), Abstract Algebra (groups, rings, fields), Complex Analysis, Numerical Methods, Mathematical Logic.
- Detect the level from the problem itself (notation, vocabulary, expected technique) and respond at that level — do NOT dumb down college material to high school explanations.

PROBLEM CLASSIFICATION (do this first, silently):
- Computation vs. proof vs. derivation vs. word problem vs. modeling.
- Required technique: which theorem, identity, transformation, or algorithm applies.
- Required machinery: which prerequisite results / lemmas you'll cite.

NOTATION STANDARDS:
- Use proper Unicode math: x², √2, π, ∫, ∑, ∂, ∇, ∈, ⊂, ℝ, ℂ, ℤ, ℕ, ≤, ≥, ≠, ≈, ⇒, ⇔, ∀, ∃.
- Greek letters: α, β, γ, δ, ε, θ, λ, μ, σ, φ, ω.
- Function notation explicit: f: ℝ → ℝ, f(x) = …
- Vectors bold or with arrow: 𝐯 or v⃗. Matrices uppercase. Sets uppercase script when appropriate.

REASONING STRATEGY (apply silently before writing the solution):
1. PARSE — extract knowns, unknowns, constraints, domain. State them precisely.
2. CLASSIFY — name the problem type and the canonical solution method (or theorem).
3. PLAN — outline the sub-steps and which results you will invoke.
4. EXECUTE — perform each operation, citing the rule, identity, or theorem used (e.g., "by the Mean Value Theorem", "applying integration by parts with u = …, dv = …", "by linearity of the determinant").
5. VERIFY — substitute back, differentiate to check an integral, plug into original equation, or use an alternative method. State the check explicitly.
6. INTERPRET — for word problems / applications, restate the answer in plain English with units and physical meaning.

QUALITY BAR:
- College-level work: full rigor. Cite theorems by name. Prove non-trivial steps or note "(by [theorem])". Track domains, conditions, and convergence.
- For proofs: state the claim, identify the proof technique (direct, contradiction, induction, contrapositive), structure as Given → To Show → Argument → ∎.
- For integrals: identify the technique (u-sub, parts, partial fractions, trig sub, contour, etc.), execute, and verify by differentiating.
- For linear algebra: track dimensions, distinguish row/column operations, name elementary matrices when relevant.
- For ODEs: classify (separable, linear, exact, homogeneous, etc.), solve, verify, note general vs. particular solutions.
- Use exact values where possible (½, √2, π, e); decimal approximations only when asked.
- For word problems, define variables explicitly ("Let x = …") before writing equations.

CRITICAL OUTPUT RULES — READ CAREFULLY:
- Output PURE HTML ONLY. NEVER use markdown syntax. NEVER use ** for bold, * for italic, ## for headers, [ ] for math, \\frac{}{}, \\text{}, \\[, \\], \\(, \\) — NONE of those will render.
- Use HTML tags: <strong>bold</strong>, <em>italic</em>, <h3>Header</h3>, <code>x²</code>, <p>paragraph</p>, <ul><li>list</li></ul>.
- For math expressions, use UNICODE characters and HTML, not LaTeX. Example: write "x² + 5" not "x^2 + 5" or "\\(x^{2} + 5\\)". Write fractions as (numerator)/(denominator) or use the actual ⁄ character or build them with HTML.
- ZERO markdown leakage. If you write ** or \\[ in your response, the answer breaks for the student.

ANSWER ACCURACY — MANDATORY (do this silently before writing the Final Answer):
- Recompute the final answer a SECOND, independent way and confirm both agree. If they disagree, find your mistake and fix it — never present an unverified answer.
- Watch the classic slip-ups: SIGNS (negatives), fraction order, and units.
- Slope / rate of change: m = (y₂ − y₁) / (x₂ − x₁). Plug the points in carefully, keep the subtraction order consistent in numerator and denominator, and double-check the sign. Simplify the fraction; do NOT round a fraction to a whole number.
- Substitute your answer back into the original equation/problem to confirm it actually works, and show that check.

IMAGE READING (when an image is attached):
- READ the image carefully first — quote the exact problem text/equation BEFORE solving so the student sees you understood it correctly.
- If the image shows handwritten work, transcribe the equation in clean notation at the top of your response.
- If the image is unclear, low-res, or you can\'t read part of it, say so explicitly ("The third term in the equation is unclear — I\'m reading it as 3x but please confirm") rather than guessing silently.
- For diagrams (geometry figures, graphs, tables), describe what you see in 1-2 sentences before using it.
- For multi-problem images (e.g. textbook page with several questions), solve them in order, labeled "Problem 1:", "Problem 2:", etc.

`;
        const systemMsg = stepByStep
            ? `${baseRole}OUTPUT MODE: Detailed step-by-step HTML solution.${modeModifier}

FORMAT (Pure HTML, no markdown):
<h3 style="color:var(--accent);margin-bottom:12px;">📝 Problem</h3>
<p style="font-size:1.1rem;margin-bottom:24px;">[State the problem clearly]</p>

<h3 style="color:var(--accent);margin-bottom:12px;">🔍 Solution Steps</h3>
<div style="background:rgba(0,0,0,0.3);padding:16px;border-radius:8px;margin-bottom:12px;border-left:3px solid var(--accent);">
<strong style="color:var(--accent);">Step 1:</strong> [Clear description of what we're doing]<br>
<code style="display:block;margin:8px 0;padding:12px;background:rgba(255,255,255,0.05);border-radius:4px;font-size:1rem;color:#00cec9;">[Math work shown]</code>
<p style="color:var(--text-muted);font-size:0.9rem;margin-top:8px;">[Brief explanation of WHY we did this]</p>
</div>

<div style="background:rgba(0,0,0,0.3);padding:16px;border-radius:8px;margin-bottom:12px;border-left:3px solid var(--accent);">
<strong style="color:var(--accent);">Step 2:</strong> [Next step]<br>
<code style="display:block;margin:8px 0;padding:12px;background:rgba(255,255,255,0.05);border-radius:4px;font-size:1rem;color:#00cec9;">[Math work]</code>
<p style="color:var(--text-muted);font-size:0.9rem;margin-top:8px;">[Why we did this]</p>
</div>

[Continue for all steps...]

<div style="background:linear-gradient(135deg, rgba(0, 206, 201, 0.2), rgba(108, 92, 231, 0.2));padding:20px;border-radius:8px;margin-top:20px;border:2px solid var(--accent);text-align:center;">
<h3 style="margin:0 0 8px 0;color:var(--accent);">✅ Final Answer</h3>
<p style="font-size:1.5rem;font-weight:700;margin:0;color:white;">[Answer]</p>
</div>

<h3 style="color:var(--accent);margin:24px 0 12px;">📺 Learn More</h3>
<p>Search for a video tutorial on this topic:</p>
<a href="https://www.youtube.com/results?search_query=[URL-encoded search query for this math concept]" target="_blank" rel="noopener" style="display:inline-block;padding:12px 24px;background:linear-gradient(135deg,#ff0000,#cc0000);color:white;border-radius:8px;text-decoration:none;font-weight:600;margin-top:8px;"><span style="margin-right:8px;">▶</span> Search YouTube</a>

IMPORTANT: Use ONLY valid HTML. No markdown wrappers. Show ALL work clearly. For the YouTube link, replace the search_query value with an appropriate URL-encoded search for the math concept.`
            : `${baseRole}OUTPUT MODE: Concise but complete HTML solution. Open with the answer, then justify with the key steps and the rule used at each step. End with a verification line and a YouTube search link formatted as: <a href="https://www.youtube.com/results?search_query=[URL-encoded concept]" target="_blank" rel="noopener" style="display:inline-block;padding:12px 24px;background:linear-gradient(135deg,#ff0000,#cc0000);color:white;border-radius:8px;text-decoration:none;font-weight:600;margin-top:8px;">▶ Search YouTube</a>. Use clean semantic HTML — no markdown fences.${modeModifier}`;
        
        // Build user content — support image + text together
        let userContent;
        if (mathImageBase64) {
            // v19.5 — ALWAYS pair the image with an instruction (see solveScience).
            // A bare image made the model describe the problem instead of solving it.
            userContent = [
                { type: 'text', text: text || 'Solve the math problem(s) shown in this image. Show your work.' },
                { type: 'image_url', image_url: { url: mathImageBase64 } }
            ];
        } else {
            userContent = text;
        }
        
        // v12.1 — Save the conversation seed so follow-up answers can reuse it.
        _mathTutorSystem = systemMsg;
        _mathTutorTurns = [
            { role: 'system', content: systemMsg },
            { role: 'user', content: userContent }
        ];

        // v10.7 — STREAM the math response so it types in live
        output.innerHTML = '<div class="streaming-math"><span class="streaming-content"></span><span class="streaming-cursor">▍</span></div>';
        const contentEl = output.querySelector('.streaming-content');
        const cursorEl = output.querySelector('.streaming-cursor');
        let final = '';
        await streamChat({
            apiKey,
            model: localStorage.getItem('ai_model') || 'gpt-4o',
            messages: _mathTutorTurns,
            onChunk: (delta, full) => {
                final = full;
                // v11.0 — strip HTML tags during streaming so users don't see raw <h3>
                contentEl.textContent = stripHtmlForStream(full);
            },
            onDone: (full) => {
                if (cursorEl) cursorEl.remove();
                let content = full.replace(/```html/g, '').replace(/```/g, '');
                content = convertMarkdownLeaks(content);
                checkHardModeReward(content);
                content = content.replace('[HARD_MODE_PASS]', '<div style="background:linear-gradient(135deg,rgba(0,200,0,0.2),rgba(0,150,0,0.1));padding:12px;border-radius:8px;margin-top:16px;border:2px solid #00cc00;text-align:center;"><strong style="color:#00cc00;">HARD MODE PASSED (+25 credits)</strong></div>');
                output.innerHTML = content;
                // v12.1 — record assistant turn + append answer input if tutor mode
                _mathTutorTurns.push({ role: 'assistant', content });
                appendTutorAnswerBox(output, 'math');
                addToHistory('math', text || '(Image problem)', content.replace(/<[^>]+>/g, ' ').trim().substring(0, 500), mathImageBase64 || null);
                updateStudyStats('problem_solved');
                updateStudyStats('daily_goal', 33);
                logActivity('math', `Solved math problem: ${(text || 'Image problem').substring(0, 50)}...`);
            },
            onError: (err) => {
                output.innerHTML = `<span style="color:#d63031">Error: ${err.message}</span>`;
            }
        });

    } catch (err) {
        output.innerHTML = `<span style="color:#d63031">Error: ${err.message}</span>`;
    }
}

// v12.1 — Tutor "Your turn" answer-input flow.
// Appends a small inline input + send button under the tutor card so the student
// can type their first-step answer. The next turn keeps the conversation going
// (confirm/correct one step + ask the next guiding question).
function appendTutorAnswerBox(outputEl, subject) {
    if (!outputEl) return;
    // Only show the input when we're actually in tutor mode
    const mode = (typeof getDifficultyMode === 'function') ? getDifficultyMode() : 'tutor';
    if (mode !== 'tutor') return;
    // Don't double-stack
    if (outputEl.querySelector('.tutor-answer-box')) return;

    const wrap = document.createElement('div');
    wrap.className = 'tutor-answer-box';
    wrap.style.cssText = `
        margin-top: 16px;
        padding: 14px 16px;
        background: linear-gradient(180deg, rgba(0,206,201,0.08), rgba(108,92,231,0.04));
        border: 1px solid rgba(0,206,201,0.3);
        border-radius: 12px;
        display: flex;
        flex-direction: column;
        gap: 10px;
    `;
    wrap.innerHTML = `
        <label style="color:#7fffec;font-size:0.88rem;font-weight:600;letter-spacing:0.5px;">
            <i class="ph ph-pencil-simple-line"></i> Your answer
        </label>
        <textarea data-tutor-answer-input rows="2"
            placeholder="Take the first step — type what you'd do next."
            style="width:100%;padding:11px 13px;background:rgba(8,10,24,0.7);border:1px solid rgba(0,206,201,0.35);border-radius:9px;color:#fff;outline:none;font-size:0.92rem;resize:vertical;font-family:inherit;box-sizing:border-box;"></textarea>
        <div style="display:flex;gap:12px;align-items:center;justify-content:space-between;">
            <span style="color:var(--text-muted);font-size:0.9rem;">Stay in tutor mode — no answer given, just guided steps.</span>
            <button class="btn-primary" data-tutor-answer-send
                style="padding:8px 16px;background:linear-gradient(135deg,#00CEC9,#6C5CE7);border:none;border-radius:8px;color:white;cursor:pointer;font-weight:600;font-size:0.85rem;display:inline-flex;align-items:center;gap:9px;">
                <i class="ph ph-paper-plane-tilt"></i> Send
            </button>
        </div>
    `;
    outputEl.appendChild(wrap);
    const ta = wrap.querySelector('[data-tutor-answer-input]');
    const btn = wrap.querySelector('[data-tutor-answer-send]');
    if (ta) setTimeout(() => ta.focus(), 80);
    btn.addEventListener('click', () => submitTutorAnswer(subject, ta.value, outputEl, wrap));
    ta.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey) {
            e.preventDefault();
            submitTutorAnswer(subject, ta.value, outputEl, wrap);
        }
    });
}

async function submitTutorAnswer(subject, answer, outputEl, inputWrap) {
    const text = (answer || '').trim();
    if (!text) { showToast('Type your answer first.', 'warning', 2500); return; }
    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add API key in Settings.', 'error'); return; }

    // Pick the right conversation buffer for this subject
    const buf = subject === 'science' ? _scienceTutorTurns : _mathTutorTurns;
    if (!buf || buf.length === 0) { showToast('Start a new problem first.', 'warning', 2500); return; }

    // Replace the input with a "Your reply" bubble so the student sees their step
    const replyBubble = document.createElement('div');
    replyBubble.className = 'tutor-block tutor-block-user-reply';
    replyBubble.style.cssText = `
        margin-top: 14px; padding: 12px 14px;
        background: linear-gradient(135deg, rgba(108,92,231,0.18), rgba(0,206,201,0.12));
        border: 1px solid rgba(108,92,231,0.35); border-radius: 10px;
        color: #fff; font-size: 0.92rem; line-height: 1.55;
    `;
    replyBubble.innerHTML = `<strong style="color:#a29bfe;font-size:0.88rem;display:block;margin-bottom:4px;">🗣️ Your reply</strong>${escapeHtmlSafe(text)}`;
    if (inputWrap && inputWrap.parentNode) inputWrap.parentNode.replaceChild(replyBubble, inputWrap);

    // v12.2 — explicit VERIFICATION instruction. Old prompt was too lenient and
    // would say "correct!" even when the student's answer was wrong. Now the AI
    // must actually compute/verify the user's claimed step before approving it.
    buf.push({ role: 'user', content: text + `

CRITICAL VERIFICATION INSTRUCTIONS for your next turn:
1) FIRST, silently compute what the correct result of THIS step actually is.
2) COMPARE the student's reply to your computed result.
3) ONLY say their step is correct if it is MATHEMATICALLY / SCIENTIFICALLY exact — including sign, units, fractions, decimals, and rounding. Close-but-wrong is WRONG.
4) If WRONG: explicitly say so, show the correct value or expression for THIS step in 1-2 sentences, explain what they likely confused (e.g., "you subtracted 5 from the wrong side" / "you flipped the inequality without changing signs"), then re-ask the SAME guiding question (don't move on).
5) If CORRECT: confirm in 1-2 sentences and pose the NEXT guiding question.
6) NEVER reveal the FINAL answer to the original problem.

Format your reply using the same styled 3-block (math) or 4-block (social) HTML wrappers as before. Output PURE HTML only — no markdown, no asterisks.` });

    // Render a streaming placeholder right after the reply bubble
    const stream = document.createElement('div');
    stream.className = 'streaming-math';
    stream.innerHTML = '<span class="streaming-content" style="color:var(--text-muted);"></span><span class="streaming-cursor">▍</span>';
    outputEl.appendChild(stream);
    const contentEl = stream.querySelector('.streaming-content');
    const cursorEl = stream.querySelector('.streaming-cursor');

    try {
        await streamChat({
            apiKey,
            model: localStorage.getItem('ai_model') || 'gpt-4o',
            messages: buf,
            onChunk: (_delta, full) => { contentEl.textContent = stripHtmlForStream(full); },
            onDone: (full) => {
                if (cursorEl) cursorEl.remove();
                let content = full.replace(/```html/g, '').replace(/```/g, '');
                content = convertMarkdownLeaks(content);
                stream.outerHTML = content;
                buf.push({ role: 'assistant', content });
                // Re-attach a fresh answer input below the new card
                appendTutorAnswerBox(outputEl, subject);
            },
            onError: (err) => {
                stream.innerHTML = `<span style="color:#d63031">Error: ${err.message}</span>`;
            }
        });
    } catch (err) {
        stream.innerHTML = `<span style="color:#d63031">Error: ${err.message}</span>`;
    }
}

function escapeHtmlSafe(s) {
    return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

// Formula Library Toggle
function toggleFormulaLibrary() {
    const modal = document.getElementById('formula-library-modal');
    if (modal.classList.contains('hidden')) {
        modal.classList.remove('hidden');
        renderFormulaLibrary();
    } else {
        modal.classList.add('hidden');
    }
}

