// ── VISUALIZER MODE TOGGLE (Function vs Plot) ─────────────────────
let _visualizerMode = 'function';
let _plotPoints = []; // [{x, y}, ...] in math coordinates

function setVisualizerMode(mode) {
    _visualizerMode = mode;
    const fnBtn = document.getElementById('mvz-mode-fn');
    const plotBtn = document.getElementById('mvz-mode-plot');
    const fnControls = document.getElementById('mvz-fn-controls');
    const plotControls = document.getElementById('mvz-plot-controls');
    const activeStyle = 'flex:1;padding:10px;background:linear-gradient(135deg,#6c5ce7,#00cec9);border:none;border-radius:8px;color:white;font-size:0.9rem;font-weight:600;cursor:pointer;';
    const inactiveStyle = 'flex:1;padding:10px;background:transparent;border:none;border-radius:8px;color:var(--text-muted);font-size:0.9rem;font-weight:600;cursor:pointer;';
    if (mode === 'plot') {
        if (fnBtn) fnBtn.style.cssText = inactiveStyle;
        if (plotBtn) plotBtn.style.cssText = activeStyle;
        if (fnControls) fnControls.style.display = 'none';
        if (plotControls) plotControls.style.display = 'block';
        redrawPlotMode();
    } else {
        if (fnBtn) fnBtn.style.cssText = activeStyle;
        if (plotBtn) plotBtn.style.cssText = inactiveStyle;
        if (fnControls) fnControls.style.display = 'block';
        if (plotControls) plotControls.style.display = 'none';
        const canvas = document.getElementById('math-graph-canvas');
        if (canvas) drawGraphGrid(canvas.getContext('2d'), canvas.width, canvas.height);
    }
}

function addPlotPoint() {
    const xRaw = document.getElementById('mvz-plot-x').value;
    const yRaw = document.getElementById('mvz-plot-y').value;
    const x = parseFloat(xRaw);
    const y = parseFloat(yRaw);
    if (Number.isNaN(x) || Number.isNaN(y)) {
        showToast('Enter both X and Y as numbers.', 'warning');
        return;
    }
    _plotPoints.push({ x, y });
    document.getElementById('mvz-plot-x').value = '';
    document.getElementById('mvz-plot-y').value = '';
    document.getElementById('mvz-plot-x').focus();
    redrawPlotMode();
}

function clearPlotPoints() {
    _plotPoints = [];
    redrawPlotMode();
}

function redrawPlotMode() {
    const canvas = document.getElementById('math-graph-canvas');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    drawGraphGrid(ctx, canvas.width, canvas.height);
    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const scale = 40;
    // Plot each point as a dot
    _plotPoints.forEach((p, i) => {
        const px = centerX + p.x * scale;
        const py = centerY - p.y * scale;
        // Outer glow
        ctx.beginPath();
        ctx.arc(px, py, 8, 0, Math.PI * 2);
        ctx.fillStyle = 'rgba(0,206,201,0.25)';
        ctx.fill();
        // Solid dot
        ctx.beginPath();
        ctx.arc(px, py, 5, 0, Math.PI * 2);
        ctx.fillStyle = '#00cec9';
        ctx.fill();
        ctx.strokeStyle = '#fff';
        ctx.lineWidth = 1.2;
        ctx.stroke();
        // Label
        ctx.fillStyle = '#fff';
        ctx.font = '11px Inter';
        ctx.fillText(`(${p.x}, ${p.y})`, px + 9, py - 9);
    });
    // Update points list
    const list = document.getElementById('mvz-plot-points-list');
    if (list) {
        list.innerHTML = _plotPoints.length === 0
            ? '<em style="opacity:0.55;">No points yet.</em>'
            : _plotPoints.map((p, i) => `<div style="padding:3px 6px;border-bottom:1px solid rgba(255,255,255,0.05);">${i + 1}. (${p.x}, ${p.y})</div>`).join('');
    }
}

function drawGraphGrid(ctx, width, height) {
    const centerX = width / 2;
    const centerY = height / 2;
    const scale = 40; // pixels per unit

    ctx.clearRect(0, 0, width, height);

    // Background
    ctx.fillStyle = 'rgba(0,0,0,0.3)';
    ctx.fillRect(0, 0, width, height);

    // Grid lines
    ctx.strokeStyle = 'rgba(108,92,231,0.2)';
    ctx.lineWidth = 1;

    // Vertical lines
    for (let x = 0; x < width; x += scale) {
        ctx.beginPath();
        ctx.moveTo(x, 0);
        ctx.lineTo(x, height);
        ctx.stroke();
    }

    // Horizontal lines
    for (let y = 0; y < height; y += scale) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(width, y);
        ctx.stroke();
    }

    // Axes
    ctx.strokeStyle = '#6c5ce7';
    ctx.lineWidth = 2;

    // X-axis
    ctx.beginPath();
    ctx.moveTo(0, centerY);
    ctx.lineTo(width, centerY);
    ctx.stroke();

    // Y-axis
    ctx.beginPath();
    ctx.moveTo(centerX, 0);
    ctx.lineTo(centerX, height);
    ctx.stroke();

    // Axis labels
    ctx.fillStyle = '#00cec9';
    ctx.font = '12px Inter';
    ctx.fillText('0', centerX + 5, centerY - 5);
    ctx.fillText('x', width - 20, centerY - 5);
    ctx.fillText('y', centerX + 5, 15);
}

function plotEquation() {
    const input = document.getElementById('math-equation-input').value.trim();
    if (!input) {
        showToast('Please enter an equation', 'warning');
        return;
    }

    const canvas = document.getElementById('math-graph-canvas');
    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;
    const centerX = width / 2;
    const centerY = height / 2;
    const scale = 40;

    // Redraw grid
    drawGraphGrid(ctx, width, height);

    try {
        // Parse equation (simple y = f(x) format)
        let equation = input.toLowerCase().replace(/\s/g, '');
        equation = equation.replace('y=', '').replace('x^2', 'x*x').replace('x²', 'x*x');

        // Plot the function
        ctx.strokeStyle = '#00cec9';
        ctx.lineWidth = 3;
        ctx.beginPath();

        let firstPoint = true;
        for (let px = 0; px < width; px++) {
            const x = (px - centerX) / scale;
            let y;

            // Evaluate different function types
            if (equation.includes('sin')) {
                y = Math.sin(x);
            } else if (equation.includes('cos')) {
                y = Math.cos(x);
            } else if (equation.includes('tan')) {
                y = Math.tan(x);
            } else if (equation.includes('abs')) {
                const expr = equation.replace('abs(x)', 'Math.abs(x)');
                y = eval(expr.replace(/x/g, `(${x})`));
            } else {
                // General expression
                y = eval(equation.replace(/x/g, `(${x})`));
            }

            const py = centerY - (y * scale);

            if (firstPoint) {
                ctx.moveTo(px, py);
                firstPoint = false;
            } else {
                ctx.lineTo(px, py);
            }
        }

        ctx.stroke();
        showToast('Equation plotted successfully!', 'success');
    } catch (err) {
        showToast('Invalid equation format', 'error');
        console.error(err);
    }
}

