function switchNotebookTab(tab) {
    // v16.0 — notebook now hosts Notes, Drawing Canvas, Quiz Gen, and Flashcards
    var tabs = { notes:'notes-tab', canvas:'canvas-tab', quiz:'quiz-tab', cards:'cards-tab' };
    var secs = { notes:'notebook-notes-section', canvas:'notebook-canvas-section', quiz:'notebook-quiz-section', cards:'notebook-cards-section' };
    if (!tabs[tab]) tab = 'notes';
    Object.keys(tabs).forEach(function(k){ var b=document.getElementById(tabs[k]); if(b) b.classList.remove('active'); });
    Object.keys(secs).forEach(function(k){ var s=document.getElementById(secs[k]); if(s) s.style.display='none'; });
    var btn = document.getElementById(tabs[tab]); if (btn) btn.classList.add('active');
    var sec = document.getElementById(secs[tab]); if (sec) sec.style.display = 'block';
    if (tab === 'canvas') { initDrawingCanvas(); }
    else if (tab === 'quiz' && typeof renderQuizGen === 'function') { renderQuizGen(); }
    else if (tab === 'cards' && typeof renderSrsHomePanel === 'function') { renderSrsHomePanel(); }
}

function toggleDrawingMode() {
    switchNotebookTab('canvas');
}

function addTimestamp() {
    const now = new Date();
    const timestamp = now.toLocaleString('en-US', {
        month: 'short',
        day: 'numeric',
        year: 'numeric',
        hour: 'numeric',
        minute: '2-digit',
        hour12: true
    });

    const nb = document.getElementById('notebook-area');
    const timestampElement = document.createElement('div');
    timestampElement.style.cssText = 'color:#ffc312;font-weight:600;font-size:0.9rem;margin:8px 0;padding:4px 8px;background:rgba(255,195,18,0.1);border-left:3px solid #ffc312;border-radius:4px;display:inline-block;';
    timestampElement.innerHTML = `<i class="ph ph-clock"></i> ${timestamp}`;

    const sel = window.getSelection();
    if (sel && sel.rangeCount) {
        const range = sel.getRangeAt(0);
        range.insertNode(timestampElement);
        range.collapse(false);
    } else {
        nb.appendChild(timestampElement);
    }

    localStorage.setItem('user_notes', nb.innerHTML);
    showToast('Timestamp added!', 'success');
}

function clearNotebook() {
    if (confirm('Are you sure you want to clear all notes? This cannot be undone.')) {
        document.getElementById('notebook-area').innerHTML = '';
        localStorage.setItem('user_notes', '');
        showToast('Notebook cleared', 'info');
    }
}

// Drawing Canvas
let drawingCanvas = null;
let drawingCtx = null;
let isDrawing = false;
let lastX = 0;
let lastY = 0;

function initDrawingCanvas() {
    if (drawingCanvas) return; // Already initialized

    drawingCanvas = document.getElementById('notebook-canvas');
    if (!drawingCanvas) return;

    drawingCtx = drawingCanvas.getContext('2d');

    // Load saved canvas if exists
    const savedCanvas = localStorage.getItem('notebook_canvas');
    if (savedCanvas) {
        const img = new Image();
        img.onload = () => {
            drawingCtx.drawImage(img, 0, 0);
        };
        img.src = savedCanvas;
    }

    // Brush size display update
    const brushSlider = document.getElementById('canvas-brush-size');
    const brushDisplay = document.getElementById('brush-size-display');
    if (brushSlider && brushDisplay) {
        brushSlider.addEventListener('input', (e) => {
            brushDisplay.textContent = e.target.value + 'px';
        });
    }

    // Drawing events
    drawingCanvas.addEventListener('mousedown', startDrawing);
    drawingCanvas.addEventListener('mousemove', draw);
    drawingCanvas.addEventListener('mouseup', stopDrawing);
    drawingCanvas.addEventListener('mouseout', stopDrawing);

    // Touch events for mobile
    drawingCanvas.addEventListener('touchstart', handleTouchStart);
    drawingCanvas.addEventListener('touchmove', handleTouchMove);
    drawingCanvas.addEventListener('touchend', stopDrawing);
}

function startDrawing(e) {
    isDrawing = true;
    const rect = drawingCanvas.getBoundingClientRect();
    lastX = (e.clientX - rect.left) * (drawingCanvas.width / rect.width);
    lastY = (e.clientY - rect.top) * (drawingCanvas.height / rect.height);
}

function draw(e) {
    if (!isDrawing) return;

    const rect = drawingCanvas.getBoundingClientRect();
    const x = (e.clientX - rect.left) * (drawingCanvas.width / rect.width);
    const y = (e.clientY - rect.top) * (drawingCanvas.height / rect.height);

    const color = document.getElementById('canvas-color').value;
    const brushSize = document.getElementById('canvas-brush-size').value;

    drawingCtx.strokeStyle = color;
    drawingCtx.lineWidth = brushSize;
    drawingCtx.lineCap = 'round';
    drawingCtx.lineJoin = 'round';

    drawingCtx.beginPath();
    drawingCtx.moveTo(lastX, lastY);
    drawingCtx.lineTo(x, y);
    drawingCtx.stroke();

    lastX = x;
    lastY = y;
}

function stopDrawing() {
    if (isDrawing) {
        isDrawing = false;
        // Save canvas to localStorage
        localStorage.setItem('notebook_canvas', drawingCanvas.toDataURL());
    }
}

function handleTouchStart(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousedown', {
        clientX: touch.clientX,
        clientY: touch.clientY
    });
    drawingCanvas.dispatchEvent(mouseEvent);
}

function handleTouchMove(e) {
    e.preventDefault();
    const touch = e.touches[0];
    const mouseEvent = new MouseEvent('mousemove', {
        clientX: touch.clientX,
        clientY: touch.clientY
    });
    drawingCanvas.dispatchEvent(mouseEvent);
}

function clearCanvas() {
    if (confirm('Clear the entire canvas?')) {
        drawingCtx.clearRect(0, 0, drawingCanvas.width, drawingCanvas.height);
        localStorage.removeItem('notebook_canvas');
        showToast('Canvas cleared', 'info');
    }
}

function saveCanvasImage() {
    const link = document.createElement('a');
    link.download = `notebook-drawing-${Date.now()}.png`;
    link.href = drawingCanvas.toDataURL();
    link.click();
    showToast('Drawing saved!', 'success');
}

