// v16.0 — Help & FAQ FAB: first tap expands the "?" circle to a labeled pill,
// second tap opens the help center. Auto-collapses if left alone.
function toggleHelpFab() {
    const btn = document.getElementById('help-fab-btn');
    const label = document.getElementById('help-fab-label');
    if (!btn) { openHelpCenter(); return; }
    if (btn.dataset.expanded === '1') { collapseHelpFab(); openHelpCenter(); return; }
    btn.dataset.expanded = '1';
    if (label) label.style.display = 'inline';
    btn.style.width = 'auto';
    btn.style.borderRadius = '12px';
    btn.style.padding = '12px 20px';
    clearTimeout(window._helpFabTimer);
    window._helpFabTimer = setTimeout(collapseHelpFab, 3500);
}
function collapseHelpFab() {
    const btn = document.getElementById('help-fab-btn');
    const label = document.getElementById('help-fab-label');
    if (!btn) return;
    btn.dataset.expanded = '0';
    if (label) label.style.display = 'none';
    btn.style.width = '46px';
    btn.style.borderRadius = '50%';
    btn.style.padding = '0';
}

// v16.0 — make the Quick Notes bubble draggable; position persists in localStorage.
function _initQuickNotesDrag() {
    var fab = document.getElementById('quick-notes-fab');
    if (!fab || fab._dragInit) return;
    fab._dragInit = true;
    fab.style.touchAction = 'none';
    fab.title = (fab.title || 'Quick Note') + ' — drag to move';
    try {
        var pos = JSON.parse(localStorage.getItem('quicknotes_pos') || 'null');
        if (pos && typeof pos.left === 'number' && typeof pos.top === 'number') {
            fab.style.left = pos.left + 'px'; fab.style.top = pos.top + 'px'; fab.style.bottom = 'auto';
        }
    } catch (e) {}
    var down = false, moved = false, sx = 0, sy = 0, ox = 0, oy = 0;
    fab.addEventListener('pointerdown', function (e) {
        down = true; moved = false;
        var r = fab.getBoundingClientRect();
        sx = e.clientX; sy = e.clientY; ox = r.left; oy = r.top;
        if (fab.setPointerCapture) try { fab.setPointerCapture(e.pointerId); } catch (er) {}
    });
    fab.addEventListener('pointermove', function (e) {
        if (!down) return;
        var dx = e.clientX - sx, dy = e.clientY - sy;
        if (!moved && Math.abs(dx) + Math.abs(dy) < 5) return;   // tiny moves still count as a click
        moved = true; e.preventDefault();
        var nl = Math.max(6, Math.min(window.innerWidth - fab.offsetWidth - 6, ox + dx));
        var nt = Math.max(6, Math.min(window.innerHeight - fab.offsetHeight - 6, oy + dy));
        fab.style.left = nl + 'px'; fab.style.top = nt + 'px'; fab.style.bottom = 'auto';
    });
    fab.addEventListener('pointerup', function () {
        if (!down) return; down = false;
        if (moved) {
            var r = fab.getBoundingClientRect();
            localStorage.setItem('quicknotes_pos', JSON.stringify({ left: Math.round(r.left), top: Math.round(r.top) }));
            fab._suppressClick = true;
            setTimeout(function () { fab._suppressClick = false; }, 60);
        }
    });
    // If the pointer actually dragged, swallow the click so it doesn't open notes.
    fab.addEventListener('click', function (e) {
        if (fab._suppressClick) { e.preventDefault(); e.stopImmediatePropagation(); }
    }, true);
}
document.addEventListener('DOMContentLoaded', _initQuickNotesDrag);

// v19.5 — DECLUTTER HOME. Home had grown to ~4 screens of scrolling by stacking
// Daily Challenge, Debate, and Study History underneath the dashboard cards.
// Each panel now lives where it belongs (the markup still authors them under
// Command Center; we relocate the live nodes so ids + handlers keep working):
//   • Daily Challenge → the Quests modal (it IS a quest)
//   • Study History   → Profile (alongside the other stats)
//   • Debate Practice → stays in Command Center, paired with Prompt Generator
(function () {
    function _v195RelocatePanels() {
        // ── Daily Challenge → Quests modal ───────────────────────────────
        // Insert BEFORE #quests-body: renderQuestsModal() rewrites that body's
        // innerHTML on every open, which would destroy the panel if nested in it.
        var dc = document.getElementById('daily-challenge-panel');
        var qBody = document.getElementById('quests-body');
        if (dc && qBody && qBody.parentElement && dc.parentElement !== qBody.parentElement) {
            dc.style.margin = '0';
            var wrap = document.createElement('div');
            wrap.id = 'quests-daily-challenge-wrap';
            wrap.style.cssText = 'padding:16px 24px 0;flex-shrink:0;';
            wrap.appendChild(dc);
            qBody.parentElement.insertBefore(wrap, qBody);
        }

        // ── Study History → Profile ──────────────────────────────────────
        var sh = document.getElementById('home-study-history');
        var prof = document.getElementById('view-achievements');
        if (sh && prof && sh.parentElement !== prof) {
            prof.appendChild(sh);
        }

        // ── Clean up any stale home section headers from the old layout ──
        ['daily-challenge-panel', 'command-debate-section', 'home-study-history'].forEach(function (id) {
            var h = document.getElementById('home-label-' + id);
            if (h) h.remove();
        });
    }
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', _v195RelocatePanels);
    else _v195RelocatePanels();
})();

// v234 — the Debate ⇄ Prompt toggle is gone. Prompt Generator moved into
// English Generator, and Debate Practice is a standalone Command Center
// section again under its own heading. Before this, the always-visible toggle
// and Debate panel sat flush against the bottom edge of whichever tool panel
// was open (Live Vision, English Generator…), so Debate read as a mode of that
// tool. setCommandTool survives as a shim because the Debate card, and any
// older link, still calls it.
function setCommandTool(mode) {
    if (mode === 'prompt') { openPromptEngine(); return; }
    var debate = document.getElementById('command-debate-section');
    if (typeof switchTab === 'function' && document.getElementById('view-dashboard') &&
        !document.getElementById('view-dashboard').classList.contains('active')) {
        switchTab('dashboard');
    }
    if (debate) {
        debate.style.display = '';
        debate.open = true;
        setTimeout(function () { try { debate.scrollIntoView({ behavior: 'smooth', block: 'center' }); } catch (_) {} }, 120);
    }
}
window.setCommandTool = setCommandTool;

