function openHelpCenter() {
    const modal = document.getElementById('help-modal');
    if (modal) {
        modal.classList.remove('hidden');
        // Clear search on open
        const searchInput = document.getElementById('help-search');
        if (searchInput) searchInput.value = '';
        // Show all topics
        const topics = document.querySelectorAll('.help-topic');
        topics.forEach(topic => topic.style.display = 'block');
    }
}

function closeHelpCenter() {
    const modal = document.getElementById('help-modal');
    if (modal) modal.classList.add('hidden');
}

function scrollToHelpTopic(topicId) {
    const topic = document.getElementById(topicId);
    if (topic) {
        topic.scrollIntoView({ behavior: 'smooth', block: 'start' });
        // Add highlight effect
        topic.style.transition = 'all 0.3s';
        topic.style.transform = 'scale(1.02)';
        setTimeout(() => {
            topic.style.transform = 'scale(1)';
        }, 300);
    }
}

function filterHelpTopics(searchQuery) {
    const query = searchQuery.toLowerCase().trim();
    const topics = document.querySelectorAll('.help-topic');

    if (!query) {
        // Show all if search is empty
        topics.forEach(topic => topic.style.display = 'block');
        return;
    }

    topics.forEach(topic => {
        const keywords = topic.dataset.keywords || '';
        const topicText = topic.textContent.toLowerCase();

        // Check if query matches keywords or any text in the topic
        if (keywords.includes(query) || topicText.includes(query)) {
            topic.style.display = 'block';
        } else {
            topic.style.display = 'none';
        }
    });
}

// v10.5/v10.6: Filter help topics by category — works with both legacy pills AND new sidebar tabs
function filterHelpCategory(cat) {
    // Legacy pills (if still present)
    document.querySelectorAll('.help-cat-btn').forEach(btn => {
        const isActive = btn.dataset.cat === cat;
        btn.classList.toggle('active', isActive);
        btn.style.background = isActive
            ? 'linear-gradient(135deg,#6C5CE7,#00CEC9)'
            : 'rgba(255,255,255,0.06)';
        btn.style.color = isActive ? 'white' : 'var(--text-muted)';
        btn.style.border = isActive ? 'none' : '1px solid var(--glass-border)';
    });
    // v10.6 sidebar tabs
    document.querySelectorAll('[data-help-cat]').forEach(btn => {
        btn.classList.toggle('active', btn.dataset.helpCat === cat);
    });
    document.querySelectorAll('.help-topic').forEach(topic => {
        topic.style.display = (cat === 'all' || topic.id === cat) ? 'block' : 'none';
    });
    const searchEl = document.getElementById('help-search');
    if (searchEl) searchEl.value = '';
}

