// MOBILE SIDEBAR TOGGLE
// ============================================
function toggleMobileSidebar() {
    const sidebar = document.querySelector('.sidebar');
    const overlay = document.querySelector('.sidebar-overlay');
    if (sidebar) sidebar.classList.toggle('open');
    if (overlay) overlay.classList.toggle('active');
}

// Close sidebar when a nav item is clicked on mobile
document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('.nav-links li').forEach(item => {
        item.addEventListener('click', () => {
            if (window.innerWidth <= 768) {
                const sidebar = document.querySelector('.sidebar');
                const overlay = document.querySelector('.sidebar-overlay');
                if (sidebar) sidebar.classList.remove('open');
                if (overlay) overlay.classList.remove('active');
            }
        });
    });
});

// Handle dynamic resolution changes (e.g., switching monitors)
window.addEventListener('resize', () => {
    const sidebar = document.querySelector('.sidebar');
    const overlay = document.querySelector('.sidebar-overlay');
    if (window.innerWidth > 768) {
        // Desktop: reset mobile sidebar state
        if (sidebar) { sidebar.classList.remove('open'); sidebar.style.left = ''; }
        if (overlay) overlay.classList.remove('active');
    }
});

// ============================================
// LEADERBOARD SYSTEM
// ============================================
// v19.3 — REAL leaderboard backed by Supabase (migration 0006_leaderboard.sql).
// Opt-in (leaderboard_optin), username-only, RLS = write-your-own / read-all.
// Falls back to the local + demo view when the cloud/table isn't available so
// the page never breaks. `_realLeaderboard` caches the last cloud fetch.
let _realLeaderboard = null;

// Current signed-in user's live public stats, from local storage.
function _myLeaderboardStats() {
    const stats = getStudyStats();
    let userMins = 0, userAch = 0;
    try { userMins = getStudySessions().reduce((s, v) => s + (v.duration || 0), 0); } catch (e) {}
    try { userAch = JSON.parse(localStorage.getItem('achievements_completed') || '[]').length; } catch (e) {}
    return {
        username: localStorage.getItem('auth_user') || 'You',
        xp: parseInt(localStorage.getItem('total_xp') || '0', 10),
        problems: stats.problemsSolved || 0,
        streak: stats.currentStreak || 0,
        minutes: userMins,
        achievements: userAch,
        badge: (userLoadout && userLoadout.badge) || 'none'
    };
}

// Publish my stats to the cloud board — only if opted in AND signed into a real
// cloud account. Opting out removes my row. Best-effort, silent on failure.
async function publishLeaderboardStats() {
    try {
        if (!nexusSB) _initSupabase();
        if (!nexusSB) return;
        const u = await _cloudUser();
        if (!u || !u.id) return; // need a session to satisfy RLS auth.uid()
        const optedIn = localStorage.getItem('leaderboard_optin') !== '0'; // default on
        if (!optedIn) { try { await nexusSB.from('leaderboard').delete().eq('user_id', u.id); } catch (_) {} return; }
        const s = _myLeaderboardStats();
        await nexusSB.from('leaderboard').upsert({
            user_id: u.id, username: s.username, xp: s.xp, problems: s.problems,
            streak: s.streak, minutes: s.minutes, achievements: s.achievements,
            badge: s.badge, updated_at: new Date().toISOString()
        });
    } catch (_) { /* best-effort */ }
}

// Fetch the real board (top 100 by XP). Returns an array of rows, or null on
// failure/empty so callers can fall back.
async function fetchLeaderboard() {
    try {
        if (!nexusSB) _initSupabase();
        if (!nexusSB) return null;
        const q = await nexusSB.from('leaderboard')
            .select('user_id,username,xp,problems,streak,minutes,achievements,badge')
            .order('xp', { ascending: false })
            .limit(100);
        if (q && !q.error && Array.isArray(q.data) && q.data.length) return q.data;
        return null;
    } catch (_) { return null; }
}

function getLeaderboardData() {
    // v19.3 — prefer the real cloud board when we have it; mark the current
    // user's own row so the UI highlights it. Otherwise fall back to the
    // local + demo competitors below (keeps the page alive pre-migration).
    if (_realLeaderboard && _realLeaderboard.length) {
        const myName = localStorage.getItem('auth_user');
        // Normalize username → name (the render loop uses entry.name).
        const rows = _realLeaderboard.map(r => Object.assign({}, r, { name: r.username, isUser: r.username === myName }));
        const sortKey = window._lbSort || 'xp';
        rows.sort((a, b) => (b[sortKey] || 0) - (a[sortKey] || 0));
        return rows;
    }

    // Build leaderboard from local stats and simulated competitors
    const stats = getStudyStats();
    const username = localStorage.getItem('auth_user') || 'You';

    let userMins = 0, userAch = 0;
    try { userMins = getStudySessions().reduce((s, v) => s + (v.duration || 0), 0); } catch (e) {}
    try { userAch = JSON.parse(localStorage.getItem('achievements_completed') || '[]').length; } catch (e) {}

    const leaderboard = [
        { name: username, problems: stats.problemsSolved || 0, streak: stats.currentStreak || 0, xp: parseInt(localStorage.getItem('total_xp') || '0'), minutes: userMins, achievements: userAch, isUser: true },
        { name: 'StudyChamp',    problems: 312, streak: 31, xp: 10250, minutes: 2480, achievements: 24 },
        { name: 'NexusElite',    problems: 220, streak: 26, xp: 9100,  minutes: 2010, achievements: 21 },
        { name: 'CalcKing',      problems: 265, streak: 20, xp: 8800,  minutes: 1980, achievements: 20 },
        { name: 'MathWizard99',  problems: 247, streak: 14, xp: 8420,  minutes: 1760, achievements: 18 },
        { name: 'ScienceNerd',   problems: 198, streak: 22, xp: 7150,  minutes: 1890, achievements: 19 },
        { name: 'BrainiacX',     problems: 175, streak: 18, xp: 6400,  minutes: 1320, achievements: 15 },
        { name: 'HistoryBuff',   problems: 156, streak: 9,  xp: 5800,  minutes: 1140, achievements: 13 },
        { name: 'NightOwl',      problems: 142, streak: 16, xp: 5200,  minutes: 1450, achievements: 12 },
        { name: 'AcePilot',      problems: 134, streak: 7,  xp: 4900,  minutes: 980,  achievements: 11 },
        { name: 'LangPro',       problems: 118, streak: 11, xp: 4300,  minutes: 1020, achievements: 10 },
        { name: 'GalaxyLearner', problems: 103, streak: 12, xp: 3800,  minutes: 870,  achievements: 9 },
        { name: 'NovaScholar',   problems: 95,  streak: 8,  xp: 3500,  minutes: 760,  achievements: 7 },
        { name: 'QuizMaster',    problems: 89,  streak: 5,  xp: 3200,  minutes: 640,  achievements: 8 },
        { name: 'PaperAce',      problems: 77,  streak: 4,  xp: 2600,  minutes: 520,  achievements: 6 }
    ];

    const sortKey = window._lbSort || 'xp';
    leaderboard.sort((a, b) => (b[sortKey] || 0) - (a[sortKey] || 0));
    return leaderboard;
}

function _lbSetSort(k) { window._lbSort = k; renderLeaderboard(); } // v16.5 — switch leaderboard category

// v19.3 — refresh the real board from the cloud, then re-render. Called on tab
// open (not on every keystroke). Publishes the user's own stats first so they
// appear/update, then pulls the latest board.
async function refreshLeaderboardFromCloud() {
    if (window._lbRefreshing) return;
    window._lbRefreshing = true;
    try {
        await publishLeaderboardStats();
        const rows = await fetchLeaderboard();
        if (rows) { _realLeaderboard = rows; renderLeaderboard(); }
    } catch (_) { /* keep fallback */ }
    finally { window._lbRefreshing = false; }
}

function renderLeaderboard() {
    const container = document.getElementById('leaderboard-content');
    if (!container) return;

    const data = getLeaderboardData();
    const medals = ['🥇', '🥈', '🥉'];
    const searchVal = (document.getElementById('lb-search')?.value || '').toLowerCase();
    const filtered = searchVal ? data.filter(e => e.name.toLowerCase().includes(searchVal)) : data;

    // v16.5 — rank by any of these categories
    const LB_METRICS = [
        { key: 'xp', label: 'XP', icon: 'ph-star' },
        { key: 'problems', label: 'Problems', icon: 'ph-brain' },
        { key: 'streak', label: 'Streak', icon: 'ph-flame' },
        { key: 'minutes', label: 'Minutes', icon: 'ph-clock' },
        { key: 'achievements', label: 'Badges', icon: 'ph-medal' }
    ];
    const sortKey = window._lbSort || 'xp';
    const activeMetric = LB_METRICS.find(m => m.key === sortKey) || LB_METRICS[0];

    // v19.3 — status banner: real cloud board vs the pre-launch sample.
    const _isReal = !!(_realLeaderboard && _realLeaderboard.length);
    const _statusBanner = _isReal
        ? '<div style="font-size:0.78rem;color:#00b894;margin-bottom:12px;"><i class="ph ph-broadcast"></i> Live — ' + _realLeaderboard.length + ' student' + (_realLeaderboard.length === 1 ? '' : 's') + ' on the board. Rankings update as you study.</div>'
        : '<div style="font-size:0.78rem;color:var(--text-muted);margin-bottom:12px;"><i class="ph ph-info"></i> Sample leaderboard — real rankings appear here as students join. You\'re on it (opt out in Settings → Privacy).</div>';

    let html = _statusBanner + '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:14px;">'
        + LB_METRICS.map(m => '<button onclick="_lbSetSort(\'' + m.key + '\')" style="display:flex;align-items:center;gap:6px;padding:7px 13px;border-radius:9px;cursor:pointer;font-size:0.83rem;font-weight:600;transition:all .15s;border:1px solid ' + (m.key === sortKey ? 'transparent' : 'var(--glass-border)') + ';background:' + (m.key === sortKey ? 'linear-gradient(135deg,#6C5CE7,#00CEC9)' : 'rgba(255,255,255,0.05)') + ';color:' + (m.key === sortKey ? '#fff' : 'var(--text-muted)') + ';"><i class="ph ' + m.icon + '"></i> ' + m.label + '</button>').join('')
        + '</div>';
    html += `<div style="margin-bottom:16px;display:flex;gap:12px;">
        <input type="text" id="lb-search" placeholder="Search users..." value="${searchVal}"
            oninput="renderLeaderboard()"
            style="flex:1;padding:10px 14px;background:rgba(255,255,255,0.05);border:1px solid var(--glass-border);border-radius:8px;color:white;outline:none;font-size:0.9rem;">
        <button class="btn-secondary" onclick="document.getElementById('lb-search').value='';renderLeaderboard();" style="padding:10px 14px;"><i class="ph ph-x"></i></button>
    </div>`;

    if (filtered.length === 0) {
        html += '<div style="text-align:center;padding:30px;color:var(--text-muted);">No users found</div>';
        container.innerHTML = html;
        return;
    }

    filtered.forEach((entry, idx) => {
        const origIdx = data.indexOf(entry);
        const rank = origIdx + 1;
        const medal = medals[origIdx] || `#${rank}`;
        const isTop3 = origIdx < 3;
        const borderColor = origIdx === 0 ? '#FFD700' : origIdx === 1 ? '#C0C0C0' : origIdx === 2 ? '#CD7F32' : 'var(--glass-border)';

        // Simulated profile data for competitors
        const profilePic = entry.profilePic || (entry.isUser ? (localStorage.getItem('user_profile_pic') || '👤') : ['🧑‍🎓','👨‍💻','👩‍🔬','🧑‍🏫','👨‍🎨','👩‍💼','🧑‍🚀','👨‍🔧','👩‍⚕️'][origIdx % 9]);
        const badge = entry.badge || (entry.isUser ? (userLoadout.badge || 'none') : ['scholar','streak-king','quiz-master','speedster','night-owl','diamond','scholar','speedster','night-owl'][origIdx % 9]);
        const badgeEmojis = { none: '', scholar: '🎓', 'streak-king': '🔥', 'quiz-master': '🏆', speedster: '⚡', 'night-owl': '🌙', diamond: '💎', champion: '👑', 'nexus-emblem': '🔮' };

        html += `
        <div class="glass-panel" style="padding:14px 20px;margin-bottom:8px;display:flex;align-items:center;gap:16px;cursor:pointer;transition:all 0.2s;
            border:1px solid ${entry.isUser ? 'var(--accent)' : borderColor};
            ${entry.isUser ? 'background:linear-gradient(135deg, rgba(0,206,201,0.1), rgba(108,92,231,0.05));' : ''}
            ${isTop3 ? 'box-shadow:0 2px 12px ' + borderColor + '20;' : ''}"
            onclick="showUserProfile('${entry.name.replace(/'/g, "\\'")}', ${entry.problems}, ${entry.streak}, ${entry.xp}, '${profilePic}', '${badge}', ${entry.isUser || false})"
            onmouseenter="this.style.transform='translateX(4px)'" onmouseleave="this.style.transform='translateX(0)'">
            <div style="font-size:${isTop3 ? '1.8rem' : '1.1rem'};min-width:40px;text-align:center;${!isTop3 ? 'color:var(--text-muted);font-weight:600;' : ''}">${medal}</div>
            <div style="font-size:1.5rem;min-width:36px;text-align:center;">${profilePic}</div>
            <div style="flex:1;">
                <div style="font-weight:600;color:${entry.isUser ? 'var(--accent)' : 'white'};font-size:0.95rem;">
                    ${entry.name} ${badgeEmojis[badge] || ''} ${entry.isUser ? '<span style="font-size:0.9rem;background:var(--accent);color:#000;padding:2px 6px;border-radius:4px;margin-left:6px;">YOU</span>' : ''}
                </div>
                <div style="font-size:0.9rem;color:var(--text-muted);margin-top:2px;">
                    ${entry.problems} solved &bull; ${entry.streak} day streak
                </div>
            </div>
            <div style="text-align:right;">
                <div style="font-size:1.2rem;font-weight:700;background:linear-gradient(135deg, #FFD700, #FFA500);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;">${(entry[sortKey] || 0).toLocaleString()}</div>
                <div style="font-size:0.9rem;color:var(--text-muted);">${activeMetric.label}</div>
            </div>
        </div>`;
    });

    container.innerHTML = html;
}

function showUserProfile(name, problems, streak, xp, pic, badge, isUser) {
    const badgeNames = { none: 'None', scholar: 'Scholar Elite', 'streak-king': 'Streak King', 'quiz-master': 'Quiz Master', speedster: 'Speed Reader', 'night-owl': 'Night Owl', diamond: 'Diamond Mind', champion: 'Grand Champion', 'nexus-emblem': 'Nexus Emblem' };
    const badgeEmojis = { none: '—', scholar: '🎓', 'streak-king': '🔥', 'quiz-master': '🏆', speedster: '⚡', 'night-owl': '🌙', diamond: '💎', champion: '👑', 'nexus-emblem': '🔮' };

    // Generate simulated achievements for non-user profiles
    const achievements = isUser ? getUserAchievements() : generateSimulatedAchievements(problems, streak, xp);
    const completedCount = achievements.filter(a => a.completed).length;

    const modal = document.createElement('div');
    modal.id = 'profile-modal-overlay';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn 0.2s;';
    modal.onclick = (e) => { if (e.target === modal) modal.remove(); };

    modal.innerHTML = `
    <div class="glass-panel" style="max-width:500px;width:100%;padding:32px;max-height:80vh;overflow-y:auto;border:1px solid rgba(108,92,231,0.3);">
        <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:24px;">
            <div style="display:flex;align-items:center;gap:16px;">
                <div style="font-size:1.25rem;">${pic}</div>
                <div>
                    <h2 style="margin:0;color:white;">${name}</h2>
                    <div style="font-size:0.85rem;color:var(--text-muted);margin-top:4px;">Badge: ${badgeEmojis[badge] || '—'} ${badgeNames[badge] || 'None'}</div>
                </div>
            </div>
            <button class="btn-icon" onclick="this.closest('#profile-modal-overlay').remove()" style="font-size:1.2rem;"><i class="ph ph-x"></i></button>
        </div>

        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-bottom:24px;">
            <div class="glass-panel" style="padding:12px;text-align:center;">
                <div style="font-size:1.5rem;font-weight:700;color:var(--accent);">${problems}</div>
                <div style="font-size:0.85rem;color:var(--text-muted);">Problems</div>
            </div>
            <div class="glass-panel" style="padding:12px;text-align:center;">
                <div style="font-size:1.5rem;font-weight:700;color:#ff6b6b;">${streak}</div>
                <div style="font-size:0.85rem;color:var(--text-muted);">Day Streak</div>
            </div>
            <div class="glass-panel" style="padding:12px;text-align:center;">
                <div style="font-size:1.5rem;font-weight:700;background:linear-gradient(135deg, #FFD700, #FFA500);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;">${xp.toLocaleString()}</div>
                <div style="font-size:0.85rem;color:var(--text-muted);">XP</div>
            </div>
        </div>

        <h3 style="color:white;margin-bottom:12px;font-size:1rem;"><i class="ph ph-trophy"></i> Achievements (${completedCount}/${achievements.length})</h3>
        <div style="display:grid;gap:12px;">
            ${achievements.slice(0, 6).map(a => `
                <div style="display:flex;align-items:center;gap:10px;padding:8px 12px;background:rgba(255,255,255,${a.completed ? '0.05' : '0.02'});border-radius:8px;border-left:3px solid ${a.completed ? '#00b894' : 'rgba(255,255,255,0.1)'};">
                    <span style="font-size:1.2rem;${a.completed ? '' : 'opacity:0.3;filter:grayscale(1);'}">${a.icon}</span>
                    <div style="flex:1;">
                        <div style="font-size:0.85rem;color:${a.completed ? 'white' : 'var(--text-muted)'};">${a.name}</div>
                        <div style="font-size:0.9rem;color:var(--text-muted);">${a.desc}</div>
                    </div>
                    ${a.completed ? '<span style="font-size:0.9rem;color:#00b894;">✓</span>' : ''}
                </div>
            `).join('')}
        </div>
    </div>`;

    document.body.appendChild(modal);
}

function generateSimulatedAchievements(problems, streak, xp) {
    return [
        { name: 'First Steps', desc: 'Solve 1 problem', icon: '🎯', completed: problems >= 1 },
        { name: 'Problem Solver', desc: 'Solve 50 problems', icon: '🧠', completed: problems >= 50 },
        { name: 'Study Streak', desc: '7 day streak', icon: '🔥', completed: streak >= 7 },
        { name: 'XP Hunter', desc: 'Earn 1000 XP', icon: '⭐', completed: xp >= 1000 },
        { name: 'Centurion', desc: 'Solve 100 problems', icon: '💯', completed: problems >= 100 },
        { name: 'Dedicated', desc: '14 day streak', icon: '📅', completed: streak >= 14 }
    ];
}

