// v12.8 — Updates view tab switching (Changelog / Planning Board)
function switchUpdatesTab(tab) {
    const clBtn = document.getElementById('updates-tab-changelog');
    const rmBtn = document.getElementById('updates-tab-roadmap');
    const clCont = document.getElementById('update-log-container');
    const rmCont = document.getElementById('updates-roadmap-container');
    if (!clCont || !rmCont) return;
    if (tab === 'changelog') {
        clCont.style.display = '';
        rmCont.style.display = 'none';
        if (clBtn) { clBtn.classList.add('active'); }
        if (rmBtn) { rmBtn.classList.remove('active'); }
    } else {
        clCont.style.display = 'none';
        rmCont.style.display = '';
        if (clBtn) { clBtn.classList.remove('active'); }
        if (rmBtn) { rmBtn.classList.add('active'); }
        renderPlanningBoardInUpdates();
    }
}

function renderPlanningBoardInUpdates() {
    const container = document.getElementById('updates-roadmap-container');
    if (!container) return;
    const allPlans = getUpcomingPlans();
    if (allPlans.length === 0) {
        container.innerHTML = '<p style="color:var(--text-muted);text-align:center;padding:32px;">No plans yet.</p>';
        return;
    }
    const statusColors = { planned: '#6c5ce7', 'in-progress': '#fbbf24', shipped: '#00b894', cancelled: '#ff6b6b' };
    const statusLabels = { planned: '📋 Planned', 'in-progress': '🔨 In Progress', shipped: '✅ Shipped', cancelled: '❌ Cancelled' };
    let html = '<div style="display:flex;flex-direction:column;gap:12px;">';
    allPlans.forEach(plan => {
        const color = statusColors[plan.status] || '#888';
        const label = statusLabels[plan.status] || plan.status;
        html += `
        <div class="glass-panel" style="padding:18px 22px;border-left:4px solid ${color};">
            <div style="display:flex;align-items:center;gap:10px;margin-bottom:6px;">
                <span style="background:${color}22;color:${color};font-size:0.9rem;font-weight:700;padding:3px 9px;border-radius:5px;">${label}</span>
                ${plan.eta ? `<span style="font-size:0.85rem;color:var(--text-muted);margin-left:auto;">ETA: ${plan.eta}</span>` : ''}
            </div>
            <div style="font-weight:600;color:white;font-size:0.95rem;">${escapeHtmlSafe(plan.title)}</div>
            ${plan.body ? `<div style="font-size:0.9rem;color:var(--text-muted);margin-top:5px;">${escapeHtmlSafe(plan.body)}</div>` : ''}
            ${plan.from ? `<div style="font-size:0.9rem;color:var(--text-muted);margin-top:6px;">— ${escapeHtmlSafe(plan.from)}</div>` : ''}
        </div>`;
    });
    html += '</div>';
    container.innerHTML = html;
}

let _updateLogHtml = null; // cache — reset to null on each deploy to pick up new entries
function renderUpdateLog() {
    const container = document.getElementById('update-log-container');
    if (!container) return;
    // Only credit the "Lore Keeper" achievement when the user is actually viewing the
    // Updates tab — not when the changelog is rendered in the background at startup.
    const _uv = document.getElementById('view-updates');
    if (_uv && _uv.classList.contains('active')) {
        localStorage.setItem('update_log_opened', '1');
        setTimeout(checkAchievements, 500);
    }

    if (_updateLogHtml) { container.innerHTML = _updateLogHtml; return; }

    let html = '';
    UPDATE_LOG.forEach(update => {
        html += `
        <div class="glass-panel" style="padding:24px;margin-bottom:16px;border:1px solid ${update.tagColor}30;">
            <div style="display:flex;align-items:center;gap:12px;margin-bottom:14px;">
                <span style="background:${update.tagColor};color:#000;font-size:0.9rem;font-weight:700;padding:4px 10px;border-radius:6px;">${update.tag}</span>
                <h3 style="margin:0;color:${update.tagColor};">${update.version}</h3>
                <span style="font-size:0.85rem;color:var(--text-muted);margin-left:auto;">${update.date}</span>
            </div>
            <ul style="color:var(--text-muted);line-height:2;margin:0;padding-left:20px;">
                ${update.changes.map(c => `<li>${c}</li>`).join('')}
            </ul>
        </div>`;
    });

    _updateLogHtml = html;
    container.innerHTML = html;
}

// Render update log when switching to updates tab
const _origSwitchTabForUpdates = window.switchTab;
window.switchTab = function(tabId) {
    _origSwitchTabForUpdates(tabId);
    if (tabId === 'updates') { renderUpdateLog(); switchUpdatesTab('changelog'); }
    if (tabId === 'leaderboard') { renderLeaderboard(); if (typeof refreshLeaderboardFromCloud === 'function') refreshLeaderboardFromCloud(); }
};

// Also render on initial load if updates tab visible
document.addEventListener('DOMContentLoaded', () => {
    renderUpdateLog();
});

