function getUserAchievements() {
    const completed = JSON.parse(localStorage.getItem('achievements_completed') || '[]');
    return ACHIEVEMENTS.map(a => ({
        ...a,
        completed: completed.includes(a.id)
    }));
}

let _checkAchievementsRunning = false;
function checkAchievements() {
    // Guard against re-entrant calls (rapid successive calls before LS is persisted)
    if (_checkAchievementsRunning) return;
    // Signed-out guests have no account to attach achievements to — don't award
    // (a guest could otherwise bank credits, e.g. Night Owl, before ever signing up).
    if (!localStorage.getItem('auth_user')) return;
    _checkAchievementsRunning = true;
    try {
        const completed = JSON.parse(localStorage.getItem('achievements_completed') || '[]');
        let newlyCompleted = [];

        ACHIEVEMENTS.forEach(a => {
            if (!completed.includes(a.id) && a.check()) {
                completed.push(a.id);
                newlyCompleted.push(a);
            }
        });

        if (newlyCompleted.length > 0) {
            localStorage.setItem('achievements_completed', JSON.stringify(completed));
            newlyCompleted.forEach(a => {
                updateCredits(a.reward);
                showToast(`🏆 Achievement: ${a.name}! +${a.reward} credits`, 'success', 5000);
                logActivity('achievement', `Unlocked "${a.name}" - ${a.desc}`);
            });
        }
    } finally {
        _checkAchievementsRunning = false;
    }
}

// v12.8 — Achievement categories and progress helper
const ACHIEVEMENT_CATEGORIES = {
    progress:    { label: '📊 Progress', color: '#a29bfe' },
    streak:      { label: '🔥 Streaks',  color: '#FFD700' },
    collection:  { label: '📦 Collection', color: '#00CEC9' },
    exploration: { label: '🔭 Exploration', color: '#00b894' },
    secrets:     { label: '🔮 Secrets', color: '#ff4d8d' }
};

const ACHIEVEMENT_META = {
    // [id]: { cat, current, max }
    'first-steps':      { cat: 'progress',    getCurrent: () => getStudyStats().problemsSolved || 0, max: 1 },
    'puzzle-breaker':   { cat: 'progress',    getCurrent: () => getStudyStats().problemsSolved || 0, max: 25 },
    'problem-solver':   { cat: 'progress',    getCurrent: () => getStudyStats().problemsSolved || 0, max: 50 },
    'centurion':        { cat: 'progress',    getCurrent: () => getStudyStats().problemsSolved || 0, max: 100 },
    'xp-1000':          { cat: 'progress',    getCurrent: () => parseInt(localStorage.getItem('total_xp') || '0'), max: 1000 },
    'xp-5000':          { cat: 'progress',    getCurrent: () => parseInt(localStorage.getItem('total_xp') || '0'), max: 5000 },
    'streak-3':         { cat: 'streak',      getCurrent: () => getStudyStats().currentStreak || 0, max: 3 },
    'streak-7':         { cat: 'streak',      getCurrent: () => getStudyStats().currentStreak || 0, max: 7 },
    'streak-30':        { cat: 'streak',      getCurrent: () => getStudyStats().currentStreak || 0, max: 30 },
    'daily-5':          { cat: 'streak',      getCurrent: () => parseInt(localStorage.getItem('daily_claims_total') || '0'), max: 5 },
    'collector-10':     { cat: 'collection',  getCurrent: () => (typeof userInventory !== 'undefined' ? userInventory.length : 0), max: 10 },
    'collector-25':     { cat: 'collection',  getCurrent: () => (typeof userInventory !== 'undefined' ? userInventory.length : 0), max: 25 },
    'first-legendary':  { cat: 'collection',  getCurrent: null, max: null },
    'all-themes':       { cat: 'collection',  getCurrent: null, max: null },
    'fashion-show':     { cat: 'collection',  getCurrent: null, max: null },
    'nexus-discoverer': { cat: 'secrets',     getCurrent: null, max: null },
    'nexus-collector':  { cat: 'secrets',     getCurrent: () => {
        let n = 0;
        for (const cat of Object.values(SHOP_ITEMS)) cat.forEach(i => { if (i.nexus && userInventory.includes(i.id)) n++; });
        return n;
    }, max: 5 },
    'prompt-architect': { cat: 'exploration', getCurrent: () => parseInt(localStorage.getItem('prompt_engine_uses') || '0'), max: 10 },
    'prompt-virtuoso':  { cat: 'exploration', getCurrent: () => parseInt(localStorage.getItem('prompt_engine_uses') || '0'), max: 50 },
    'lore-keeper':      { cat: 'exploration', getCurrent: null, max: null },
    'night-owl-coder':  { cat: 'exploration', getCurrent: null, max: null },
    'early-bird':       { cat: 'exploration', getCurrent: null, max: null }
};

function renderAchievementsTab() {
    const container = document.getElementById('achievements-content');
    if (!container) return;

    const achievements = getUserAchievements();
    const completedCount = achievements.filter(a => a.completed).length;
    const total = achievements.length;
    const pct = Math.round((completedCount / total) * 100);

    // Tier based on completion %
    const tier = pct >= 80 ? { label: 'Diamond', color: '#00fff5', icon: '💎' }
               : pct >= 55 ? { label: 'Gold',    color: '#FFD700', icon: '🏆' }
               : pct >= 30 ? { label: 'Silver',  color: '#c0c0c0', icon: '🥈' }
                           : { label: 'Bronze',  color: '#cd7f32', icon: '🥉' };

    // Group by category
    const grouped = {};
    for (const catKey of Object.keys(ACHIEVEMENT_CATEGORIES)) grouped[catKey] = [];
    achievements.forEach(a => {
        const meta = ACHIEVEMENT_META[a.id];
        const catKey = (meta && meta.cat) ? meta.cat : 'exploration';
        if (!grouped[catKey]) grouped[catKey] = [];
        grouped[catKey].push({ ...a, meta });
    });

    let html = `
    <!-- Header -->
    <div class="glass-panel" style="padding:20px 24px;margin-bottom:20px;background:linear-gradient(135deg,rgba(108,92,231,0.18),rgba(0,206,201,0.08));border:1px solid rgba(108,92,231,0.3);">
        <div style="display:flex;align-items:center;gap:16px;flex-wrap:wrap;">
            <div style="font-size:2.6rem;line-height:1;">${tier.icon}</div>
            <div style="flex:1;min-width:160px;">
                <div style="display:flex;align-items:baseline;gap:12px;margin-bottom:4px;">
                    <span style="font-size:1.25rem;font-weight:800;color:white;">${completedCount} / ${total}</span>
                    <span style="font-size:0.88rem;color:${tier.color};font-weight:700;letter-spacing:1px;text-transform:uppercase;">${tier.label} Achiever</span>
                </div>
                <div style="height:10px;background:rgba(255,255,255,0.1);border-radius:6px;overflow:hidden;margin-bottom:6px;">
                    <div style="width:${pct}%;height:100%;background:linear-gradient(90deg,var(--primary),var(--accent));border-radius:6px;transition:width 0.8s ease;"></div>
                </div>
                <div style="font-size:0.88rem;color:var(--text-muted);">${pct}% complete — ${total - completedCount} remaining</div>
            </div>
            <div style="text-align:right;">
                <div style="font-size:0.9rem;color:var(--text-muted);margin-bottom:2px;">CREDITS AVAILABLE</div>
                <div style="font-size:1.3rem;font-weight:800;color:#FFD700;">
                    +${achievements.filter(a => !a.completed).reduce((s, a) => s + (a.reward || 0), 0).toLocaleString()}
                </div>
            </div>
        </div>
    </div>`;

    // Render each category
    for (const [catKey, catInfo] of Object.entries(ACHIEVEMENT_CATEGORIES)) {
        const items = grouped[catKey] || [];
        if (items.length === 0) continue;
        const catDone = items.filter(a => a.completed).length;

        html += `
        <div style="margin-bottom:24px;">
            <div style="display:flex;align-items:center;gap:12px;margin-bottom:12px;">
                <div style="font-size:1rem;font-weight:700;color:${catInfo.color};">${catInfo.label}</div>
                <div style="height:1px;flex:1;background:${catInfo.color}28;"></div>
                <div style="font-size:0.85rem;color:var(--text-muted);">${catDone}/${items.length}</div>
            </div>
            <div style="display:grid;gap:10px;">`;

        items.forEach(a => {
            const isHiddenLocked = a.hidden && !a.completed;
            const displayName = isHiddenLocked ? '???' : a.name;
            const displayDesc = isHiddenLocked ? 'A hidden discovery awaits — explore every corner of NEXUS.' : a.desc;
            const displayIcon = isHiddenLocked ? '🔒' : a.icon;
            const borderColor = a.completed ? '#00b894' : (a.hidden ? '#ff4d8d' : 'rgba(255,255,255,0.08)');
            const bgGlow = a.completed ? 'background:linear-gradient(135deg,rgba(0,184,148,0.08),rgba(0,184,148,0.03));' : '';

            // Progress bar for numeric achievements
            let progressBar = '';
            const meta = a.meta;
            if (!a.completed && meta && meta.max && meta.getCurrent) {
                const cur = Math.min(meta.getCurrent(), meta.max);
                const prog = Math.round((cur / meta.max) * 100);
                progressBar = `
                <div style="margin-top:8px;">
                    <div style="display:flex;justify-content:space-between;font-size:0.88rem;color:var(--text-muted);margin-bottom:3px;">
                        <span>${cur.toLocaleString()} / ${meta.max.toLocaleString()}</span>
                        <span>${prog}%</span>
                    </div>
                    <div style="height:5px;background:rgba(255,255,255,0.08);border-radius:3px;overflow:hidden;">
                        <div style="width:${prog}%;height:100%;background:linear-gradient(90deg,${catInfo.color},${catInfo.color}88);border-radius:3px;"></div>
                    </div>
                </div>`;
            }

            html += `
            <div class="glass-panel" style="padding:16px;display:flex;align-items:flex-start;gap:14px;border-left:3px solid ${borderColor};${bgGlow}${a.completed ? '' : 'opacity:0.78;'}transition:all 0.2s;">
                <div style="font-size:1.35rem;flex-shrink:0;${a.completed ? '' : 'filter:grayscale(1);opacity:0.45;'}">${displayIcon}</div>
                <div style="flex:1;min-width:0;">
                    <div style="display:flex;align-items:center;gap:9px;margin-bottom:2px;">
                        <span style="font-weight:700;color:${a.completed ? 'white' : 'var(--text-muted)'};font-size:0.93rem;">${displayName}</span>
                        ${a.hidden && !a.completed ? '<span style="font-size:0.78rem;color:#ff4d8d;font-weight:700;letter-spacing:1px;border:1px solid #ff4d8d55;border-radius:4px;padding:1px 5px;">HIDDEN</span>' : ''}
                        ${a.completed ? '<span style="font-size:0.62rem;color:#00b894;font-weight:700;letter-spacing:0.5px;">✓ DONE</span>' : ''}
                    </div>
                    <div style="font-size:0.88rem;color:var(--text-muted);line-height:1.4;">${displayDesc}</div>
                    ${progressBar}
                </div>
                <div style="text-align:right;flex-shrink:0;padding-left:6px;">
                    <div style="font-size:0.9rem;font-weight:700;color:${a.completed ? '#00b894' : '#FFD700'};">+${a.reward || 0}</div>
                    <div style="font-size:0.88rem;color:var(--text-muted);">${a.completed ? 'earned' : 'credits'}</div>
                </div>
            </div>`;
        });

        html += '</div></div>';
    }

    container.innerHTML = html;
}

// Check achievements periodically (45s — fast enough to catch events, light enough not to churn)
setInterval(checkAchievements, 45000);
// Also check on tab switch (handled in switchTab wrapper below)

// ============================================
// NEXUS EASTER EGG SYSTEM
// ============================================
const NEXUS_SECRET_CODE = ['n','e','x','u','s'];
let nexusCodeProgress = [];
let nexusUnlockCooldown = false;

document.addEventListener('keydown', (e) => {
    if (nexusUnlockCooldown) return;
    if (!e.key) return; // some events (autofill/IME) fire without a key — avoid toLowerCase on undefined
    const expected = NEXUS_SECRET_CODE[nexusCodeProgress.length];
    if (e.key.toLowerCase() === expected) {
        nexusCodeProgress.push(e.key.toLowerCase());
        if (nexusCodeProgress.length === NEXUS_SECRET_CODE.length) {
            nexusCodeProgress = [];
            unlockNexusItem();
        }
    } else {
        nexusCodeProgress = [];
        if (e.key.toLowerCase() === NEXUS_SECRET_CODE[0]) nexusCodeProgress.push(e.key.toLowerCase());
    }
});

function unlockNexusItem() {
    // Prevent rapid re-triggering
    if (nexusUnlockCooldown) return;
    nexusUnlockCooldown = true;
    setTimeout(() => { nexusUnlockCooldown = false; }, 10000); // 10 second cooldown

    // Find a Nexus item the user doesn't own yet
    const nexusItems = [];
    for (const [cat, items] of Object.entries(SHOP_ITEMS)) {
        items.forEach(item => {
            if (item.nexus && !userInventory.includes(item.id)) {
                nexusItems.push({ ...item, category: cat });
            }
        });
    }

    if (nexusItems.length === 0) {
        showToast('🔮 You already own all Nexus items!', 'info', 3000);
        return;
    }

    const won = nexusItems[Math.floor(Math.random() * nexusItems.length)];
    userInventory.push(won.id);
    localStorage.setItem('user_inventory', JSON.stringify(userInventory));

    // Reward coins based on rarity
    const reward = 750;
    updateCredits(reward);

    showToast(`🔮 NEXUS SECRET: ${won.name} discovered! +${reward} credits!`, 'success', 6000);
    logActivity('nexus', `Discovered Nexus item: ${won.name}`);
    createConfetti();

    // Check achievements
    setTimeout(checkAchievements, 500);
}

function checkNexusDiscovery(type, value) {
    // Check if the user just equipped a Nexus item for the first time
    for (const cat of Object.values(SHOP_ITEMS)) {
        const item = cat.find(i => i.id === value);
        if (item && item.nexus) {
            setTimeout(checkAchievements, 500);
        }
    }
}

// ============================================
// MYTHIC EASTER EGG SYSTEM (Sasuke / Enkidu / Thor)
// ============================================
// Three creative discovery paths — none unlock through plain text input.
//   • Sasuke "Awaken the Chidori" — multi-key Sharingan sequence + 3-tomoe click trial
//   • Enkidu "Chains of the Gods" — long-press the companion across 3 separate days
//   • Thor "Thunder's Judgment"   — hunt the rare storm cloud across 3 separate days
//
// Each unlock awards the companion skin + an achievement. Mythic items go straight
// into userInventory; achievements_completed is a separate ledger for credit rewards.

const EASTER_EGGS = {
    'sasuke-chidori':  { skinId: 'sasuke', achievement: 'awaken-chidori',   name: 'Sasuke Uchiha',  reward: 1500, color: '#7a48d4', flashColor: '#d8e8ff' },
    'enkidu-chains':   { skinId: 'enkidu', achievement: 'chains-of-gods',   name: 'Enkidu',         reward: 1500, color: '#88d4a0', flashColor: '#d8f8d0' },
    'thor-storm':      { skinId: 'thor',   achievement: 'thunders-judgment', name: 'Thor (GoW)',    reward: 1500, color: '#e84a18', flashColor: '#a8e0ff' }
};

function isEasterUnlocked(easterId) {
    const egg = EASTER_EGGS[easterId];
    return !!(egg && userInventory.includes(egg.skinId));
}

function unlockEasterSkin(easterId) {
    // v12.1 — kill switch: the persona companions (Sasuke, Enkidu, Thor) are
    // delisted from the public app. The trigger listeners below stay so old code
    // doesn't throw on startup, but no unlock can fire.
    if (true) return;
    const egg = EASTER_EGGS[easterId];
    if (!egg) return;
    if (userInventory.includes(egg.skinId)) {
        showToast(`${egg.name} is already in your collection.`, 'info', 3000);
        return;
    }
    userInventory.push(egg.skinId);
    // BUNDLE: Sasuke unlock also grants the Chidori cursor (mythic combo reward)
    if (easterId === 'sasuke-chidori' && !userInventory.includes('chidori')) {
        userInventory.push('chidori');
    }
    localStorage.setItem('user_inventory', JSON.stringify(userInventory));
    updateCredits(egg.reward);
    triggerEasterRevealCinematic(egg);
    logActivity('easter', `MYTHIC unlocked: ${egg.name}`);
    if (easterId === 'sasuke-chidori') {
        logActivity('easter', 'BONUS: Chidori cursor granted with Sasuke unlock');
        setTimeout(() => showToast('⚡ BONUS: Chidori cursor unlocked! Equip it from your Inventory.', 'success', 6000), 4000);
    }
    setTimeout(checkAchievements, 800);
}

function triggerEasterRevealCinematic(egg) {
    // Full-screen flash + center reveal banner
    const flash = document.createElement('div');
    flash.style.cssText = `
        position:fixed;inset:0;z-index:99998;pointer-events:none;
        background:radial-gradient(circle at 50% 50%, ${egg.flashColor} 0%, ${egg.color} 35%, transparent 80%);
        opacity:0;transition:opacity 0.25s ease-out;mix-blend-mode:screen;`;
    document.body.appendChild(flash);
    requestAnimationFrame(() => { flash.style.opacity = '0.95'; });
    setTimeout(() => { flash.style.opacity = '0'; setTimeout(() => flash.remove(), 700); }, 900);

    const banner = document.createElement('div');
    banner.style.cssText = `
        position:fixed;top:50%;left:50%;transform:translate(-50%,-50%) scale(0.6);z-index:99999;
        padding:32px 48px;border-radius:20px;text-align:center;pointer-events:none;
        background:linear-gradient(135deg, rgba(0,0,0,0.92), rgba(20,20,40,0.92));
        border:2px solid ${egg.color};
        box-shadow:0 0 64px ${egg.color}aa, 0 0 128px ${egg.color}55, inset 0 0 32px ${egg.color}33;
        opacity:0;transition:opacity 0.4s ease, transform 0.5s cubic-bezier(0.34,1.56,0.64,1);`;
    banner.innerHTML = `
        <div style="font-size:0.85rem;letter-spacing:6px;color:${egg.color};font-weight:800;margin-bottom:8px;">MYTHIC UNLOCK</div>
        <div style="font-size:1.4rem;font-weight:900;color:white;margin-bottom:6px;text-shadow:0 0 24px ${egg.color};">${egg.name}</div>
        <div style="font-size:0.9rem;color:rgba(255,255,255,0.7);">Companion added to your collection · +${egg.reward} credits</div>`;
    document.body.appendChild(banner);
    requestAnimationFrame(() => { banner.style.opacity = '1'; banner.style.transform = 'translate(-50%,-50%) scale(1)'; });
    setTimeout(() => {
        banner.style.opacity = '0';
        banner.style.transform = 'translate(-50%,-50%) scale(1.08)';
        setTimeout(() => banner.remove(), 600);
    }, 3400);

    if (typeof createConfetti === 'function') createConfetti();
}

// ── EASTER EGG #1 — SASUKE: AWAKEN THE CHIDORI ─────────────────────────
// Step 1: while focused on the Command Center (dashboard view), the user must
//         press Shift then type C → H → I (for "Chidori") within 1.5s of each key.
// Step 2: a Sharingan overlay appears with 3 spinning red tomoe. The user must
//         click each tomoe in clockwise order within 4 seconds. Wrong order or
//         timeout = the seal closes; they must retry the sequence.
const SASUKE_KEY_SEQUENCE = ['c','h','i'];
let sasukeKeyProgress = [];
let sasukeKeyResetTimer = null;

document.addEventListener('keydown', (e) => {
    // v12.1 — Sasuke easter egg disabled (persona delisted).
    return;
    // eslint-disable-next-line no-unreachable
    if (isEasterUnlocked('sasuke-chidori')) return;
    // Require Shift held + we're not typing in an editable field
    if (!e.shiftKey) return;
    const t = e.target;
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return;
    // Only trigger inside the Command Center / dashboard
    const dashView = document.getElementById('view-dashboard');
    if (!dashView || !dashView.classList.contains('active')) return;
    if (!e.key) return;

    const key = e.key.toLowerCase();
    const expected = SASUKE_KEY_SEQUENCE[sasukeKeyProgress.length];
    if (key === expected) {
        sasukeKeyProgress.push(key);
        if (sasukeKeyResetTimer) clearTimeout(sasukeKeyResetTimer);
        sasukeKeyResetTimer = setTimeout(() => { sasukeKeyProgress = []; }, 1500);
        if (sasukeKeyProgress.length === SASUKE_KEY_SEQUENCE.length) {
            sasukeKeyProgress = [];
            clearTimeout(sasukeKeyResetTimer);
            spawnSharingianTrial();
        }
    } else {
        sasukeKeyProgress = (key === SASUKE_KEY_SEQUENCE[0]) ? [key] : [];
    }
});

function spawnSharingianTrial() {
    if (document.getElementById('sharingan-trial')) return;
    const overlay = document.createElement('div');
    overlay.id = 'sharingan-trial';
    overlay.style.cssText = `
        position:fixed;inset:0;z-index:99997;background:radial-gradient(circle at 50% 50%, rgba(80,0,16,0.88) 0%, rgba(10,0,4,0.96) 70%);
        display:flex;align-items:center;justify-content:center;cursor:crosshair;
        animation:sharinganIn 0.4s ease-out;`;
    overlay.innerHTML = `
        <style>
            @keyframes sharinganIn { from { opacity:0; } to { opacity:1; } }
            @keyframes sharinganSpin { from { transform: rotate(0deg); } to { transform: rotate(360deg); } }
            @keyframes tomoePulse { 0%,100% { box-shadow:0 0 12px #ff2a2a, 0 0 24px #a01018; } 50% { box-shadow:0 0 24px #ff8888, 0 0 48px #ff2a2a; } }
        </style>
        <div id="sharingan-stage" style="position:relative;width:380px;height:380px;animation:sharinganSpin 8s linear infinite;">
            <div style="position:absolute;inset:0;border-radius:50%;background:radial-gradient(circle, #5a0010 0%, #1a0008 70%);border:3px solid #a01018;box-shadow:0 0 64px #a01018, inset 0 0 48px #1a0008;"></div>
            <div style="position:absolute;top:50%;left:50%;transform:translate(-50%,-50%);width:48px;height:48px;border-radius:50%;background:#0a0008;border:2px solid #a01018;"></div>
            <div class="tomoe" data-order="1" style="position:absolute;top:24px;left:50%;transform:translateX(-50%);width:38px;height:38px;border-radius:50%;background:#0a0008;cursor:pointer;animation:tomoePulse 1.5s ease-in-out infinite;"></div>
            <div class="tomoe" data-order="2" style="position:absolute;bottom:60px;right:60px;width:38px;height:38px;border-radius:50%;background:#0a0008;cursor:pointer;animation:tomoePulse 1.5s ease-in-out infinite;animation-delay:0.5s;"></div>
            <div class="tomoe" data-order="3" style="position:absolute;bottom:60px;left:60px;width:38px;height:38px;border-radius:50%;background:#0a0008;cursor:pointer;animation:tomoePulse 1.5s ease-in-out infinite;animation-delay:1s;"></div>
        </div>
        <div style="position:absolute;top:32px;left:0;right:0;text-align:center;color:#ff8888;font-size:1.1rem;letter-spacing:4px;font-weight:700;">CLICK THE TOMOE — CLOCKWISE — BEFORE THE SEAL CLOSES</div>
        <div id="sharingan-timer" style="position:absolute;bottom:32px;left:50%;transform:translateX(-50%);color:#ff8888;font-size:0.85rem;letter-spacing:2px;">4.0s</div>`;
    document.body.appendChild(overlay);

    let nextExpected = 1;
    let trialFailed = false;
    const tomoes = overlay.querySelectorAll('.tomoe');
    tomoes.forEach(t => {
        t.addEventListener('click', (ev) => {
            ev.stopPropagation();
            if (trialFailed) return;
            const order = parseInt(t.getAttribute('data-order'));
            if (order === nextExpected) {
                t.style.background = '#ff2a2a';
                t.style.boxShadow = '0 0 32px #ff2a2a';
                nextExpected++;
                if (nextExpected > 3) {
                    trialFailed = true; // lock further input
                    cleanup(true);
                }
            } else {
                trialFailed = true;
                cleanup(false);
            }
        });
    });
    overlay.addEventListener('click', (ev) => {
        // Click outside tomoe = miss, fail
        if (ev.target === overlay) { trialFailed = true; cleanup(false); }
    });

    let remaining = 4.0;
    const timerEl = overlay.querySelector('#sharingan-timer');
    const tickHandle = setInterval(() => {
        remaining -= 0.1;
        if (timerEl) timerEl.textContent = `${Math.max(0, remaining).toFixed(1)}s`;
        if (remaining <= 0) { clearInterval(tickHandle); if (!trialFailed) { trialFailed = true; cleanup(false); } }
    }, 100);

    function cleanup(success) {
        clearInterval(tickHandle);
        setTimeout(() => {
            overlay.style.transition = 'opacity 0.4s ease';
            overlay.style.opacity = '0';
            setTimeout(() => overlay.remove(), 450);
            if (success) {
                unlockEasterSkin('sasuke-chidori');
            } else {
                showToast('The Sharingan closes. Awaken it again to try once more.', 'warning', 3500);
            }
        }, success ? 600 : 200);
    }
}

// ── EASTER EGG #2 — ENKIDU: CHAINS OF THE GODS ─────────────────────────
// Long-press any active companion sprite for 7 seconds. Each successful press
// counts as one "bond". Need 3 bonds across 3 separate calendar days. On the
// third day the chains coil fully and Enkidu materializes.

const ENKIDU_PRESS_DURATION = 7000;
const ENKIDU_BONDS_REQUIRED = 3;

function getEnkiduProgress() {
    try { return JSON.parse(localStorage.getItem('easter_enkidu_bonds') || '[]'); }
    catch { return []; }
}
function saveEnkiduProgress(arr) {
    localStorage.setItem('easter_enkidu_bonds', JSON.stringify(arr));
}

let _enkiduPressTimer = null;
let _enkiduPressStarted = 0;
let _enkiduPressVisualizer = null;

function purgeEnkiduVisualizer() {
    // Remove ANY orphan visualizers from prior sessions/sprites/clicks
    document.querySelectorAll('.enkidu-press-vis').forEach(el => el.remove());
    _enkiduPressVisualizer = null;
    if (_enkiduPressTimer) { clearTimeout(_enkiduPressTimer); _enkiduPressTimer = null; }
}

function attachEnkiduLongPress(spriteEl) {
    // v12.1 — Enkidu easter egg disabled (persona delisted).
    return;
    // eslint-disable-next-line no-unreachable
    if (!spriteEl || spriteEl._enkiduWired) return;
    spriteEl._enkiduWired = true;
    const start = (e) => {
        if (isEasterUnlocked('enkidu-chains')) return;
        // Don't compete with chat-open click handler
        if (e.target.closest('.companion-chat-trigger')) return;
        purgeEnkiduVisualizer(); // safety: clear any orphan first
        _enkiduPressStarted = Date.now();
        _enkiduPressVisualizer = document.createElement('div');
        _enkiduPressVisualizer.className = 'enkidu-press-vis';
        _enkiduPressVisualizer.style.cssText = `
            position:fixed;width:120px;height:120px;border-radius:50%;pointer-events:none;
            border:3px solid #88d4a0;box-shadow:0 0 32px #88d4a0aa, inset 0 0 24px #d8f8d066;
            opacity:0;transition:opacity 0.3s ease;z-index:99996;
            animation:enkiduChainPulse 2s ease-in-out infinite;`;
        const rect = spriteEl.getBoundingClientRect();
        _enkiduPressVisualizer.style.left = (rect.left + rect.width/2 - 60) + 'px';
        _enkiduPressVisualizer.style.top = (rect.top + rect.height/2 - 60) + 'px';
        document.body.appendChild(_enkiduPressVisualizer);
        requestAnimationFrame(() => { if (_enkiduPressVisualizer) _enkiduPressVisualizer.style.opacity = '1'; });
        _enkiduPressTimer = setTimeout(() => completeEnkiduBond(spriteEl), ENKIDU_PRESS_DURATION);
        // Hard fallback — if mouseup never fires for any reason, kill the visualizer
        setTimeout(purgeEnkiduVisualizer, ENKIDU_PRESS_DURATION + 800);
    };
    const cancel = () => {
        if (_enkiduPressTimer) { clearTimeout(_enkiduPressTimer); _enkiduPressTimer = null; }
        if (_enkiduPressVisualizer) {
            const v = _enkiduPressVisualizer;
            v.style.opacity = '0';
            setTimeout(() => v.remove(), 300);
            _enkiduPressVisualizer = null;
        }
        // Also nuke any orphans that bypassed cleanup
        document.querySelectorAll('.enkidu-press-vis').forEach(el => {
            el.style.opacity = '0';
            setTimeout(() => el.remove(), 300);
        });
    };
    spriteEl.addEventListener('mousedown', start);
    spriteEl.addEventListener('touchstart', start, { passive: true });
    spriteEl.addEventListener('mouseup', cancel);
    spriteEl.addEventListener('mouseleave', cancel);
    spriteEl.addEventListener('touchend', cancel);
    spriteEl.addEventListener('touchcancel', cancel);
}

// Global safety: clean up ANY stuck enkidu visualizer on the next mouseup anywhere
document.addEventListener('mouseup', () => {
    document.querySelectorAll('.enkidu-press-vis').forEach(el => {
        if (Date.now() - (el._spawned || 0) > 200) {
            el.style.opacity = '0';
            setTimeout(() => el.remove(), 300);
        }
    });
});

function completeEnkiduBond(spriteEl) {
    if (_enkiduPressVisualizer) { _enkiduPressVisualizer.remove(); _enkiduPressVisualizer = null; }
    const today = new Date().toISOString().slice(0,10);
    const bonds = getEnkiduProgress();
    if (bonds.includes(today)) {
        showToast('⛓️ The chains know your bond — but a day must pass before they tighten again.', 'info', 4500);
        return;
    }
    bonds.push(today);
    saveEnkiduProgress(bonds);
    spawnChainParticles(spriteEl);
    if (bonds.length >= ENKIDU_BONDS_REQUIRED) {
        setTimeout(() => unlockEasterSkin('enkidu-chains'), 1200);
    } else {
        const remaining = ENKIDU_BONDS_REQUIRED - bonds.length;
        showToast(`⛓️ Bond formed (${bonds.length}/${ENKIDU_BONDS_REQUIRED}). Return on a different day to deepen the chain.`, 'success', 5000);
    }
}

function spawnChainParticles(anchorEl) {
    const rect = anchorEl.getBoundingClientRect();
    const cx = rect.left + rect.width/2;
    const cy = rect.top + rect.height/2;
    for (let i = 0; i < 12; i++) {
        const link = document.createElement('div');
        const angle = (i / 12) * Math.PI * 2;
        const dist = 100 + Math.random() * 60;
        link.textContent = '⛓';
        link.style.cssText = `
            position:fixed;left:${cx}px;top:${cy}px;font-size:1.4rem;color:#ffd428;
            text-shadow:0 0 12px #88d4a0;pointer-events:none;z-index:99996;
            transition:transform 1.4s cubic-bezier(0.22,1,0.36,1), opacity 1.4s ease-out;
            transform:translate(-50%, -50%) scale(0.4);opacity:0;`;
        document.body.appendChild(link);
        requestAnimationFrame(() => {
            link.style.transform = `translate(${Math.cos(angle)*dist - 12}px, ${Math.sin(angle)*dist - 12}px) scale(1) rotate(${angle}rad)`;
            link.style.opacity = '1';
        });
        setTimeout(() => { link.style.opacity = '0'; setTimeout(() => link.remove(), 800); }, 900);
    }
}

// ── EASTER EGG #3 — THOR: THUNDER'S JUDGMENT ───────────────────────────
// At random intervals (~every 2-6 minutes during active use), a small storm
// cloud emoji appears in a screen corner for 8 seconds. Click within the
// window to record a "strike". Need 3 strikes across 3 separate calendar
// days. On the third strike, lightning calls Thor down.

const THOR_STRIKES_REQUIRED = 3;
const THOR_CLOUD_DURATION = 8000;
let _thorCloudTimer = null;

function getThorProgress() {
    try { return JSON.parse(localStorage.getItem('easter_thor_strikes') || '[]'); }
    catch { return []; }
}
function saveThorProgress(arr) {
    localStorage.setItem('easter_thor_strikes', JSON.stringify(arr));
}

function scheduleThorCloud() {
    // v12.1 — disabled. Persona companions delisted; storm cloud no longer spawns.
    if (_thorCloudTimer) { clearTimeout(_thorCloudTimer); _thorCloudTimer = null; }
    return;
    /* legacy code below kept for reference but unreachable */
    // eslint-disable-next-line no-unreachable
    if (isEasterUnlocked('thor-storm')) return;
    const today = new Date().toISOString().slice(0,10);
    const strikes = getThorProgress();
    if (strikes.includes(today)) {
        // Already struck today; check again in 2 hours
        _thorCloudTimer = setTimeout(scheduleThorCloud, 1000 * 60 * 120);
        return;
    }
    const delay = 120000 + Math.random() * 240000; // 2–6 minutes
    _thorCloudTimer = setTimeout(spawnThorCloud, delay);
}

function spawnThorCloud() {
    if (isEasterUnlocked('thor-storm')) return;
    if (document.getElementById('thor-storm-cloud')) return;
    const corners = [
        { left: '24px', top: '120px' },
        { right: '24px', top: '120px' },
        { left: '24px', bottom: '120px' },
        { right: '24px', bottom: '120px' }
    ];
    const pos = corners[Math.floor(Math.random() * corners.length)];
    const cloud = document.createElement('div');
    cloud.id = 'thor-storm-cloud';
    Object.entries(pos).forEach(([k,v]) => cloud.style[k] = v);
    cloud.style.cssText += `
        position:fixed;width:64px;height:64px;font-size:2.4rem;cursor:pointer;z-index:99995;
        display:flex;align-items:center;justify-content:center;
        filter:drop-shadow(0 0 16px #2a48a8) drop-shadow(0 0 32px #a8e0ff);
        animation:thorCloudFloat 2s ease-in-out infinite alternate;
        opacity:0;transition:opacity 0.5s ease;`;
    cloud.textContent = '⛈️';
    cloud.title = 'Something is brewing…';
    cloud.addEventListener('click', () => completeThorStrike(cloud));
    document.body.appendChild(cloud);
    requestAnimationFrame(() => { cloud.style.opacity = '1'; });

    // Inject one-time keyframes
    if (!document.getElementById('thor-cloud-style')) {
        const s = document.createElement('style');
        s.id = 'thor-cloud-style';
        s.textContent = `@keyframes thorCloudFloat { from { transform: translateY(0); } to { transform: translateY(-8px); } }
        @keyframes enkiduChainPulse { 0%,100% { transform: scale(1); } 50% { transform: scale(1.1); } }
        @keyframes thorLightningFlash { 0%,100% { opacity: 0; } 20%,80% { opacity: 1; } }`;
        document.head.appendChild(s);
    }

    setTimeout(() => {
        if (cloud.parentElement) {
            cloud.style.opacity = '0';
            setTimeout(() => cloud.remove(), 500);
        }
        scheduleThorCloud();
    }, THOR_CLOUD_DURATION);
}

function completeThorStrike(cloudEl) {
    if (cloudEl) cloudEl.remove();
    const today = new Date().toISOString().slice(0,10);
    const strikes = getThorProgress();
    if (strikes.includes(today)) {
        scheduleThorCloud();
        return;
    }
    strikes.push(today);
    saveThorProgress(strikes);
    spawnLightningFlash();
    if (strikes.length >= THOR_STRIKES_REQUIRED) {
        setTimeout(() => unlockEasterSkin('thor-storm'), 900);
    } else {
        showToast(`⚡ The storm marks you (${strikes.length}/${THOR_STRIKES_REQUIRED}). Return on another day — Mjolnir watches.`, 'success', 5000);
        scheduleThorCloud();
    }
}

function spawnLightningFlash() {
    const f = document.createElement('div');
    f.style.cssText = `
        position:fixed;inset:0;z-index:99994;pointer-events:none;
        background:radial-gradient(circle at 50% 0%, #a8e0ff 0%, transparent 60%);
        opacity:0;mix-blend-mode:screen;`;
    document.body.appendChild(f);
    f.style.animation = 'thorLightningFlash 0.6s ease-out';
    setTimeout(() => f.remove(), 700);
}

// Boot the Thor cloud cycle once the page is alive
setTimeout(scheduleThorCloud, 60000); // first cloud no sooner than 1 min after load

// Wire Enkidu long-press onto the companion sprite whenever it spawns.
// Use MutationObserver instead of polling so there's zero CPU cost when idle.
(function() {
    function tryWireEnkidu() {
        const sprite = document.getElementById('companion-sprite');
        if (sprite && !sprite._enkiduWired) attachEnkiduLongPress(sprite);
    }
    tryWireEnkidu(); // try immediately
    const observer = new MutationObserver(tryWireEnkidu);
    observer.observe(document.body, { childList: true, subtree: true });
})();

