// ── 4. EQUIP / APPLY ──────────────────────────────────────────────────
function applyCompanion(id) {
    if (id === 'none' || !id) {
        despawnCompanion();
        refreshChidoriCursorState();
        return;
    }
    if (!hasPro()) {
        despawnCompanion();
        refreshChidoriCursorState();
        return;
    }
    // v12.3 — Sprite outfit variants: alias to nexus-orb for SVG/spawn, then
    // apply a CSS hue-shift filter to the sprite wrapper to recolor it.
    let actualId = id;
    let outfitHue = null;
    if (id === 'nexus-orb-ember')  { actualId = 'nexus-orb'; outfitHue = '180deg'; }
    if (id === 'nexus-orb-aurora') { actualId = 'nexus-orb'; outfitHue = '-90deg'; }
    if (id === 'nexus-orb-rose')   { actualId = 'nexus-orb'; outfitHue = '-30deg'; }
    spawnCompanion(actualId);
    // Apply outfit recolor after the spawn lands
    setTimeout(() => {
        const wrap = document.getElementById('companion-sprite-wrap');
        if (!wrap) return;
        if (outfitHue) {
            wrap.style.filter = `hue-rotate(${outfitHue}) saturate(1.15)`;
        } else {
            wrap.style.filter = '';
        }
    }, 100);
    refreshChidoriCursorState();
}

// ── CHIDORI CURSOR VFX ────────────────────────────────────────────────
// Fires when EITHER Sasuke is the equipped companion OR Chidori is the equipped cursor.
// Both unlock paths grant the bundled Chidori cursor; user can equip either independently.
function refreshChidoriCursorState() {
    try {
        const companion = (typeof userLoadout !== 'undefined' && userLoadout) ? userLoadout.companion : null;
        const cursor    = (typeof userLoadout !== 'undefined' && userLoadout) ? userLoadout.cursor    : null;
        applyChidoriCursorEffect(companion === 'sasuke' || cursor === 'chidori');
    } catch { applyChidoriCursorEffect(false); }
}

let _chidoriClickHandler = null;
function applyChidoriCursorEffect(enable) {
    if (_chidoriClickHandler) {
        document.removeEventListener('click', _chidoriClickHandler, true);
        _chidoriClickHandler = null;
    }
    if (!enable) return;
    _chidoriClickHandler = (e) => {
        // Skip for editable inputs (don't disrupt typing focus)
        if (e.target && (e.target.tagName === 'TEXTAREA' || (e.target.tagName === 'INPUT' && ['text','number','email','password','search','url','tel'].includes(e.target.type)))) return;
        spawnChidoriBurst(e.clientX, e.clientY);
    };
    document.addEventListener('click', _chidoriClickHandler, true);
}

function spawnChidoriBurst(cx, cy) {
    // Mythic-tier: layered burst with expanding outer ring, multi-layer lightning,
    // bright core flash, and 6 scattered electric particles flying outward.
    const uid = Date.now() + Math.random().toString(36).slice(2, 7);

    // Layer 1: expanding outer Chidori ring with cyan glow
    const ring = document.createElement('div');
    ring.style.cssText = `
        position:fixed;left:${cx}px;top:${cy}px;width:24px;height:24px;border-radius:50%;
        pointer-events:none;z-index:99992;
        transform:translate(-50%,-50%) scale(0.4);
        border:2px solid #a8e0ff;
        box-shadow:0 0 24px #a8e0ff, 0 0 48px #2a7adc, inset 0 0 12px #ffffff;
        opacity:0.95;
        transition:transform 0.55s cubic-bezier(0.22,1,0.36,1), opacity 0.55s ease-out;`;
    document.body.appendChild(ring);
    requestAnimationFrame(() => {
        ring.style.transform = 'translate(-50%,-50%) scale(3.2)';
        ring.style.opacity = '0';
    });
    setTimeout(() => ring.remove(), 600);

    // Layer 2: lightning burst SVG with multi-layer crackle (white + cyan)
    const burst = document.createElement('div');
    burst.style.cssText = `
        position:fixed;left:${cx}px;top:${cy}px;width:0;height:0;pointer-events:none;z-index:99993;
        transform:translate(-50%,-50%);
        transition:opacity 0.5s ease-out, transform 0.5s cubic-bezier(0.22,1,0.36,1);`;
    burst.innerHTML = `
        <svg width="120" height="120" viewBox="-60 -60 120 120" style="position:absolute;left:-60px;top:-60px;overflow:visible;">
            <defs>
                <radialGradient id="chid-core-${uid}" cx="50%" cy="50%" r="50%">
                    <stop offset="0%" stop-color="#ffffff"/>
                    <stop offset="35%" stop-color="#dcf4ff"/>
                    <stop offset="70%" stop-color="#5ac0f5"/>
                    <stop offset="100%" stop-color="#0a3a7a" stop-opacity="0"/>
                </radialGradient>
                <radialGradient id="chid-flash-${uid}" cx="50%" cy="50%" r="50%">
                    <stop offset="0%" stop-color="#ffffff"/>
                    <stop offset="100%" stop-color="#a8e0ff" stop-opacity="0"/>
                </radialGradient>
            </defs>
            <!-- Outer halo glow -->
            <circle cx="0" cy="0" r="32" fill="url(#chid-core-${uid})" opacity="0.6"/>
            <!-- Inner energy core -->
            <circle cx="0" cy="0" r="14" fill="url(#chid-flash-${uid})" opacity="0.9"/>
            <!-- Bright white center pulse -->
            <circle cx="0" cy="0" r="6" fill="#ffffff" opacity="0.95"/>
            <circle cx="0" cy="0" r="2.5" fill="#ffffff"/>
            <!-- 6 jagged primary lightning arcs (white) -->
            <path d="M0 0 L-16 -10 L-10 -5 L-26 -18 L-22 -14 L-34 -22" stroke="#ffffff" stroke-width="1.6" fill="none" stroke-linecap="round" opacity="0.95"/>
            <path d="M0 0 L16 -10 L10 -5 L26 -18 L22 -14 L34 -22"     stroke="#ffffff" stroke-width="1.6" fill="none" stroke-linecap="round" opacity="0.95"/>
            <path d="M0 0 L-14 10 L-8 7 L-24 22 L-20 18 L-32 28"       stroke="#ffffff" stroke-width="1.6" fill="none" stroke-linecap="round" opacity="0.95"/>
            <path d="M0 0 L14 10 L8 7 L24 22 L20 18 L32 28"            stroke="#ffffff" stroke-width="1.6" fill="none" stroke-linecap="round" opacity="0.95"/>
            <path d="M0 0 L-3 -16 L0 -10 L-2 -28 L1 -20 L-1 -38"       stroke="#ffffff" stroke-width="1.6" fill="none" stroke-linecap="round" opacity="0.95"/>
            <path d="M0 0 L3 16 L0 10 L2 28 L-1 20 L1 38"              stroke="#ffffff" stroke-width="1.6" fill="none" stroke-linecap="round" opacity="0.95"/>
            <!-- Cyan secondary lightning layer (offset, thinner) -->
            <path d="M0 0 L-22 -2 L-16 1 L-30 -1 L-26 2 L-40 0"        stroke="#a8e0ff" stroke-width="1.2" fill="none" stroke-linecap="round" opacity="0.85"/>
            <path d="M0 0 L22 -2 L16 1 L30 -1 L26 2 L40 0"             stroke="#a8e0ff" stroke-width="1.2" fill="none" stroke-linecap="round" opacity="0.85"/>
            <path d="M0 0 L-12 -16 L-7 -10 L-20 -24"                   stroke="#a8e0ff" stroke-width="1" fill="none" stroke-linecap="round" opacity="0.8"/>
            <path d="M0 0 L12 -16 L7 -10 L20 -24"                      stroke="#a8e0ff" stroke-width="1" fill="none" stroke-linecap="round" opacity="0.8"/>
            <path d="M0 0 L-12 16 L-7 10 L-20 24"                      stroke="#a8e0ff" stroke-width="1" fill="none" stroke-linecap="round" opacity="0.8"/>
            <path d="M0 0 L12 16 L7 10 L20 24"                         stroke="#a8e0ff" stroke-width="1" fill="none" stroke-linecap="round" opacity="0.8"/>
            <!-- Scattered electric particles around the burst -->
            <circle cx="-30" cy="-22" r="1.2" fill="#ffffff"/>
            <circle cx="30"  cy="-22" r="1.2" fill="#ffffff"/>
            <circle cx="-28" cy="24"  r="1.2" fill="#ffffff"/>
            <circle cx="28"  cy="24"  r="1.2" fill="#ffffff"/>
            <circle cx="0"   cy="-34" r="1"   fill="#a8e0ff"/>
            <circle cx="0"   cy="34"  r="1"   fill="#a8e0ff"/>
            <circle cx="-38" cy="2"   r="0.9" fill="#a8e0ff"/>
            <circle cx="38"  cy="2"   r="0.9" fill="#a8e0ff"/>
        </svg>`;
    burst.style.opacity = '1';
    document.body.appendChild(burst);
    requestAnimationFrame(() => {
        burst.style.opacity = '0';
        burst.style.transform = 'translate(-50%,-50%) scale(1.8) rotate(8deg)';
    });
    setTimeout(() => burst.remove(), 550);

    // Layer 3: 6 small crackle particles flying outward in a ring pattern
    for (let i = 0; i < 6; i++) {
        const angle = (i / 6) * Math.PI * 2 + Math.random() * 0.4;
        const dist = 28 + Math.random() * 18;
        const p = document.createElement('div');
        p.style.cssText = `
            position:fixed;left:${cx}px;top:${cy}px;width:5px;height:5px;border-radius:50%;
            background:#ffffff;box-shadow:0 0 6px #a8e0ff, 0 0 12px #2a7adc;
            pointer-events:none;z-index:99993;
            transform:translate(-50%,-50%) scale(1);
            transition:transform 0.5s cubic-bezier(0.22,1,0.36,1), opacity 0.5s ease-out;
            opacity:0.95;`;
        document.body.appendChild(p);
        requestAnimationFrame(() => {
            p.style.transform = `translate(${Math.cos(angle)*dist - 2.5}px, ${Math.sin(angle)*dist - 2.5}px) scale(0.2)`;
            p.style.opacity = '0';
        });
        setTimeout(() => p.remove(), 550);
    }
}

// On page load, restore Chidori effect if Sasuke is equipped OR Chidori cursor is equipped
document.addEventListener('DOMContentLoaded', () => {
    refreshChidoriCursorState();
});

function despawnCompanion() {
    const layer = document.getElementById('companion-layer');
    if (layer) layer.style.display = 'none';
    if (window._companionWalkTimer) { clearTimeout(window._companionWalkTimer); window._companionWalkTimer = null; }
    if (window._companionEmoteTimer) { clearTimeout(window._companionEmoteTimer); window._companionEmoteTimer = null; }
    closeCompanionChat();
}

// ── COMPANION SPRITE SIZE — scales with viewport ──
// Min 72px on tiny screens, max 132px on huge screens, ~10% of viewport width.
function getCompanionSpriteSize() {
    // v10.7 — honor Settings → Companion → Sprite size
    const setting = localStorage.getItem('companion_sprite_size') || 'auto';
    if (setting !== 'auto') {
        const n = parseInt(setting, 10);
        if (!isNaN(n)) return n;
    }
    const w = window.innerWidth;
    // v12.7: reduced ceiling from 132→88px so the sprite stays tastefully small
    return Math.max(60, Math.min(88, Math.round(w * 0.055)));
}

function spawnCompanion(id) {
    const data = COMPANIONS_DATA[id];
    if (!data) return;
    const layer = document.getElementById('companion-layer');
    const sprite = document.getElementById('companion-sprite');
    if (!layer || !sprite) return;
    layer.style.display = 'block';
    const spriteSize = getCompanionSpriteSize();
    sprite.innerHTML = getCompanionAvatarSVG(id, spriteSize);
    sprite.dataset.companionId = id;

    // Dynamically resize wrap + sprite div to prevent clipping (v12.4 sprite-fix)
    const wrap = document.getElementById('companion-sprite-wrap');
    const emote = document.getElementById('companion-emote');
    const shadow = document.getElementById('companion-shadow');
    const wrapH = spriteSize + 16; // +16 for shadow breathing room
    wrap.style.width = spriteSize + 'px';
    wrap.style.height = wrapH + 'px';
    sprite.style.width = spriteSize + 'px';
    sprite.style.height = spriteSize + 'px';
    if (emote) emote.style.bottom = wrapH + 'px';
    if (shadow) shadow.style.width = Math.round(spriteSize * 0.65) + 'px';

    // Glow tint based on companion accent
    sprite.style.filter = `drop-shadow(0 6px 12px ${data.glow}66) drop-shadow(0 0 18px ${data.accent}55)`;

    // Click → open chat; drag → move the sprite (v19)
    wrap.onclick = null;
    _initCompanionDrag(id);

    // Snap into starting boundary
    const bounds = getCompanionBounds();
    const startLeft = Math.max(bounds.minLeft, Math.min(bounds.maxLeft, parseFloat(wrap.style.left) || bounds.minLeft + 40));
    wrap.style.transition = 'none';
    wrap.style.left = startLeft + 'px';
    void wrap.offsetWidth;

    // Start walking + emoting
    if (window._companionWalkTimer) clearTimeout(window._companionWalkTimer);
    if (window._companionEmoteTimer) clearTimeout(window._companionEmoteTimer);
    walkCompanion();
    scheduleCompanionEmote();
}

// Compute the play area bounds — companion stays right of the sidebar and inside viewport.
function getCompanionBounds() {
    const sidebar = document.querySelector('.sidebar');
    const spriteWidth = getCompanionSpriteSize();
    const padding = 16;
    let minLeft = padding;
    if (sidebar) {
        const rect = sidebar.getBoundingClientRect();
        // Only enforce sidebar boundary if sidebar is visible (open) on screen
        if (rect.width > 0 && rect.right > 0 && rect.right < window.innerWidth) {
            minLeft = rect.right + padding;
        }
    }
    const maxLeft = Math.max(minLeft, window.innerWidth - spriteWidth - padding);
    return { minLeft, maxLeft, spriteWidth };
}

function walkCompanion() {
    const wrap = document.getElementById('companion-sprite-wrap');
    if (!wrap || !document.getElementById('companion-layer') || document.getElementById('companion-layer').style.display === 'none') return;
    if (localStorage.getItem('companion_walking_enabled') === 'false') {
        // v12.7: when walking is off, snap back to the home corner and stop the loop
        const bounds = getCompanionBounds();
        wrap.style.transition = 'left 0.8s ease';
        wrap.style.left = bounds.minLeft + 'px';
        wrap.classList.remove('facing-left');
        // Don't schedule another walk cycle — toggleCompanionWalk will restart when re-enabled
        return;
    }
    const bounds = getCompanionBounds();
    const range = Math.max(0, bounds.maxLeft - bounds.minLeft);
    const next = bounds.minLeft + Math.floor(Math.random() * range);
    const current = parseFloat(wrap.style.left) || bounds.minLeft;
    if (next < current) wrap.classList.add('facing-left');
    else wrap.classList.remove('facing-left');
    const distance = Math.abs(next - current);
    // v10.7 — Settings → Companion → Walk speed (0=Slow, 1=Normal, 2=Fast)
    const ws = parseInt(localStorage.getItem('companion_walk_speed') || '1', 10);
    const speedFactor = ws === 0 ? 0.5 : (ws === 2 ? 1.8 : 1);
    const duration = Math.max(3, Math.min(10, distance / (60 * speedFactor)));
    wrap.style.transition = `left ${duration}s linear, transform 0.4s ease`;
    wrap.style.left = next + 'px';
    window._companionWalkTimer = setTimeout(walkCompanion, (duration * 1000) + 1500 + Math.random() * 4000);
}

// v19 — Drag the sprite anywhere; it reacts with emotes. A real click (no drag)
// still opens the chat. After dropping, it returns to the floor and resumes walking.
const COMPANION_DRAG_LINES = ['Wheee! 🎢', 'Put me down! 😅', 'Where are we going?', 'Whoa!', 'Hehe!', 'Carry me! 💕', 'To the moon! 🚀', 'So high up!', 'I can fly! ✨'];
function _initCompanionDrag(id) {
    const wrap = document.getElementById('companion-sprite-wrap');
    if (!wrap) return;
    wrap.style.cursor = 'grab';
    if (wrap._dragInit) return; // attach handlers only once
    wrap._dragInit = true;
    let down = false, moved = false, sx = 0, sy = 0, ox = 0, oy = 0;
    function emoteEl() { return document.getElementById('companion-emote'); }
    function showDragEmote() { const em = emoteEl(); if (!em) return; em.textContent = COMPANION_DRAG_LINES[Math.floor(Math.random() * COMPANION_DRAG_LINES.length)]; em.style.opacity = '1'; em.style.transform = 'translateX(-50%) scale(1)'; }
    function hideDragEmote() { const em = emoteEl(); if (em) { em.style.opacity = '0'; em.style.transform = 'translateX(-50%) scale(0)'; } }
    function move(e) {
        if (!down) return;
        const pt = (e.touches && e.touches[0]) ? e.touches[0] : e;
        if (!moved && (Math.abs(pt.clientX - sx) > 5 || Math.abs(pt.clientY - sy) > 5)) { moved = true; wrap.style.cursor = 'grabbing'; showDragEmote(); }
        if (moved) {
            if (e.cancelable) e.preventDefault();
            let nx = Math.max(0, Math.min(window.innerWidth - wrap.offsetWidth, pt.clientX - ox));
            let ny = Math.max(0, Math.min(window.innerHeight - wrap.offsetHeight, pt.clientY - oy));
            wrap.style.left = nx + 'px'; wrap.style.top = ny + 'px'; wrap.style.bottom = 'auto';
        }
    }
    function end() {
        window.removeEventListener('mousemove', move); window.removeEventListener('mouseup', end);
        window.removeEventListener('touchmove', move); window.removeEventListener('touchend', end);
        wrap.style.cursor = 'grab';
        if (!down) return; down = false;
        const cid = (document.getElementById('companion-sprite') || {}).dataset ? document.getElementById('companion-sprite').dataset.companionId : id;
        if (!moved) { openCompanionChat(cid || id); return; } // tap = open chat
        setTimeout(hideDragEmote, 1400);
        if (localStorage.getItem('companion_walking_enabled') !== 'false') {
            window._companionWalkTimer = setTimeout(function () { wrap.style.top = 'auto'; wrap.style.bottom = '24px'; walkCompanion(); }, 5000);
        }
    }
    function start(e) {
        const pt = (e.touches && e.touches[0]) ? e.touches[0] : e;
        down = true; moved = false; sx = pt.clientX; sy = pt.clientY;
        const r = wrap.getBoundingClientRect(); ox = pt.clientX - r.left; oy = pt.clientY - r.top;
        wrap.style.transition = 'none';
        if (window._companionWalkTimer) { clearTimeout(window._companionWalkTimer); window._companionWalkTimer = null; }
        window.addEventListener('mousemove', move); window.addEventListener('mouseup', end);
        window.addEventListener('touchmove', move, { passive: false }); window.addEventListener('touchend', end);
    }
    wrap.addEventListener('mousedown', start);
    wrap.addEventListener('touchstart', start, { passive: true });
}

// Re-evaluate boundaries on resize so companion never gets stranded under the sidebar.
// Also re-render the sprite at the new viewport-appropriate size (item #5).
let _companionResizeDebounce = null;
window.addEventListener('resize', () => {
    const wrap = document.getElementById('companion-sprite-wrap');
    const sprite = document.getElementById('companion-sprite');
    if (!wrap) return;
    // Clamp position
    const bounds = getCompanionBounds();
    const current = parseFloat(wrap.style.left) || bounds.minLeft;
    if (current < bounds.minLeft || current > bounds.maxLeft) {
        const clamped = Math.max(bounds.minLeft, Math.min(bounds.maxLeft, current));
        wrap.style.transition = 'left 0.4s ease';
        wrap.style.left = clamped + 'px';
    }
    // Debounced sprite re-render at new size
    if (_companionResizeDebounce) clearTimeout(_companionResizeDebounce);
    _companionResizeDebounce = setTimeout(() => {
        if (!sprite || !sprite.dataset.companionId) return;
        const id = sprite.dataset.companionId;
        sprite.innerHTML = getCompanionAvatarSVG(id, getCompanionSpriteSize());
    }, 200);
});

function scheduleCompanionEmote() {
    if (!document.getElementById('companion-layer') || document.getElementById('companion-layer').style.display === 'none') return;
    // v10.7 — Settings → Companion → Emote frequency (0=Off, 1=Rare, 2=Normal, 3=Frequent)
    const ef = parseInt(localStorage.getItem('companion_emote_freq') || '2', 10);
    if (ef === 0) return; // never schedule
    const baseMin = ef === 3 ? 4000  : ef === 2 ? 8000  : 16000;
    const baseRng = ef === 3 ? 6000  : ef === 2 ? 14000 : 22000;
    const delay = baseMin + Math.random() * baseRng;
    window._companionEmoteTimer = setTimeout(() => {
        showCompanionEmote();
        scheduleCompanionEmote();
    }, delay);
}

function showCompanionEmote(forced) {
    const sprite = document.getElementById('companion-sprite');
    const emote = document.getElementById('companion-emote');
    if (!sprite || !emote) return;
    const id = sprite.dataset.companionId;
    const data = COMPANIONS_DATA[id];
    if (!data) return;
    // v12.4 — mood override: if setting is on, occasionally use mood-based emotes
    let text = forced;
    if (!text) {
        const moodPool = getCompanionMoodEmotes();
        const usesMood = moodPool && Math.random() < 0.35; // 35% chance of mood emote
        const pool = (usesMood && moodPool) ? moodPool : data.emotes;
        text = pool[Math.floor(Math.random() * pool.length)];
    }
    emote.textContent = text;
    emote.style.transform = 'translateX(-50%) scale(1)';
    emote.style.opacity = '1';
    setTimeout(() => {
        emote.style.transform = 'translateX(-50%) scale(0)';
        emote.style.opacity = '0';
    }, 3500);
}

// ── 5. CHAT BUBBLE ────────────────────────────────────────────────────
let _companionChatHistory = [];

function openCompanionChat(id) {
    if (!hasPro()) { showProUpgradePrompt('Companions'); return; }
    const data = COMPANIONS_DATA[id];
    if (!data) return;
    const chat = document.getElementById('companion-chat');
    const avatar = document.getElementById('companion-chat-avatar');
    const name = document.getElementById('companion-chat-name');
    const msgs = document.getElementById('companion-chat-messages');
    if (!chat) return;
    chat.style.display = 'flex';
    chat.dataset.companionId = id;
    avatar.innerHTML = getCompanionAvatarSVG(id, 48);
    name.textContent = data.name;

    // Hide Help & FAQ floating button while chat is open (they share the same corner)
    const helpFab = document.getElementById('help-fab');
    if (helpFab) helpFab.style.display = 'none';

    // Apply persisted size
    applyCompanionChatSize(localStorage.getItem('companion_chat_size') || 'medium');

    // Sync settings checkboxes
    const walkToggle = document.getElementById('setting-walking');
    if (walkToggle) walkToggle.checked = localStorage.getItem('companion_walking_enabled') !== 'false';

    // Sync persona override dropdown
    const personaSel = document.getElementById('setting-persona-override');
    if (personaSel) personaSel.value = localStorage.getItem('companion_persona_override') || 'default';

    // Reset only on switch (note: also re-greet if persona override changed since last open)
    const lastPersona = msgs.dataset.appliedPersona || '';
    const currentPersona = localStorage.getItem('companion_persona_override') || 'default';
    if (msgs.dataset.companionId !== id || lastPersona !== currentPersona) {
        msgs.innerHTML = '';
        _companionChatHistory = [];
        const personaData = (currentPersona !== 'default' && COMPANIONS_DATA[currentPersona]) ? COMPANIONS_DATA[currentPersona] : data;
        addCompanionMessage('ai', personaData.greeting);
        msgs.dataset.companionId = id;
        msgs.dataset.appliedPersona = currentPersona;
    }
    // v12.1 — refresh the Link button label on every chat open
    if (typeof updateCompanionLinkLabel === 'function') updateCompanionLinkLabel();
    setTimeout(() => {
        const inp = document.getElementById('companion-chat-input');
        if (inp) {
            inp.focus();
            // v10.7 — Shift+Enter newline, plain Enter sends; auto-resize textarea
            if (!inp._v107Wired) {
                inp._v107Wired = true;
                inp.addEventListener('keydown', (e) => {
                    if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
                        e.preventDefault();
                        sendCompanionMessage();
                    }
                });
                inp.addEventListener('input', () => {
                    inp.style.height = 'auto';
                    inp.style.height = Math.min(120, inp.scrollHeight) + 'px';
                });
            }
        }
    }, 80);
}

function closeCompanionChat() {
    const chat = document.getElementById('companion-chat');
    if (chat) chat.style.display = 'none';
    const popover = document.getElementById('companion-settings-popover');
    if (popover) popover.style.display = 'none';
    // Restore Help & FAQ button when chat closes
    const helpFab = document.getElementById('help-fab');
    if (helpFab) helpFab.style.display = '';
}

// ── PERSONA OVERRIDE ──────────────────────────────────────────────────
// Lets the user pick which companion VOICE the equipped companion uses,
// independent of which avatar is equipped. Stored in localStorage.
function setCompanionPersonaOverride(personaId) {
    if (personaId === 'default' || !personaId) {
        localStorage.removeItem('companion_persona_override');
    } else {
        localStorage.setItem('companion_persona_override', personaId);
    }
    // Re-open chat so the new greeting fires (if chat is open)
    const chat = document.getElementById('companion-chat');
    if (chat && chat.style.display !== 'none') {
        const id = chat.dataset.companionId;
        const msgs = document.getElementById('companion-chat-messages');
        if (msgs) { msgs.dataset.appliedPersona = ''; }
        if (id) openCompanionChat(id);
    }
    showToast(personaId === 'default'
        ? '🎭 Persona reset to default (matches equipped companion).'
        : `🎭 Persona override set to ${(COMPANIONS_DATA[personaId]?.name) || personaId}.`,
        'success', 3000);
}

function getActiveCompanionPersona(equippedId) {
    const override = localStorage.getItem('companion_persona_override');
    if (override && override !== 'default' && COMPANIONS_DATA[override]) {
        return COMPANIONS_DATA[override];
    }
    return COMPANIONS_DATA[equippedId];
}

// ── 5b. CHAT RESIZE + SETTINGS ────────────────────────────────────────
const COMPANION_CHAT_SIZES = {
    small:  { w: 320, h: 440, icon: 'ph-arrows-out' },
    medium: { w: 380, h: 520, icon: 'ph-arrows-out' },
    large:  { w: 460, h: 640, icon: 'ph-arrows-in' }
};

function applyCompanionChatSize(size) {
    const chat = document.getElementById('companion-chat');
    if (!chat) return;
    const cfg = COMPANION_CHAT_SIZES[size] || COMPANION_CHAT_SIZES.medium;
    chat.style.width = cfg.w + 'px';
    chat.style.height = cfg.h + 'px';
    chat.dataset.size = size;
    const btn = document.getElementById('companion-chat-resize-btn');
    if (btn) btn.innerHTML = `<i class="ph ${cfg.icon}"></i>`;
}

function cycleCompanionChatSize() {
    const chat = document.getElementById('companion-chat');
    if (!chat) return;
    const order = ['small', 'medium', 'large'];
    const current = chat.dataset.size || localStorage.getItem('companion_chat_size') || 'medium';
    const next = order[(order.indexOf(current) + 1) % order.length];
    applyCompanionChatSize(next);
    localStorage.setItem('companion_chat_size', next);
}

function toggleCompanionSettings(e) {
    if (e) e.stopPropagation();
    const popover = document.getElementById('companion-settings-popover');
    if (!popover) return;
    popover.style.display = popover.style.display === 'block' ? 'none' : 'block';
}
document.addEventListener('click', (e) => {
    const popover = document.getElementById('companion-settings-popover');
    const btn = document.getElementById('companion-chat-settings-btn');
    if (!popover || popover.style.display !== 'block') return;
    if (popover.contains(e.target) || (btn && btn.contains(e.target))) return;
    popover.style.display = 'none';
});

function toggleWalkingSetting(enabled) {
    localStorage.setItem('companion_walking_enabled', enabled ? 'true' : 'false');
    if (enabled) {
        // v12.7: restart walk loop when re-enabled
        if (window._companionWalkTimer) clearTimeout(window._companionWalkTimer);
        window._companionWalkTimer = setTimeout(walkCompanion, 500);
    }
}

// ════════════════════════════════════════════════════════════════════
// v12.3 — COMPANION VOICE MODE (community suggestion @voicelearn)
// Two browser-native pieces:
//   • Microphone (SpeechRecognition): hold-to-dictate or toggle to live-listen.
//     Transcribed text drops into the companion-chat input. User hits send.
//   • Speaker (SpeechSynthesis): when ON, every companion reply gets read aloud.
// Both work offline (no API tokens). Both gracefully no-op on browsers that
// don't support the Web Speech API (mostly fine on Chrome/Edge).
// ════════════════════════════════════════════════════════════════════
// v12.8 — Improved voice dictation: continuous mode with better interim/final tracking,
// no-speech recovery, and a clear visual indicator.
let _companionVoiceRecog = null;
let _companionVoiceListening = false;
let _voiceFinalTranscript = '';
let _voiceNoSpeechTimer = null;

function toggleCompanionVoiceDictate() {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { showToast('Voice input isn\'t supported in this browser. Try Chrome or Edge.', 'error', 4000); return; }
    const btn = document.getElementById('companion-mic-btn');

    if (_companionVoiceListening) {
        // Stop — commit what we have
        if (_companionVoiceRecog) { try { _companionVoiceRecog.stop(); } catch (_) {} }
        _companionVoiceListening = false;
        if (_voiceNoSpeechTimer) { clearTimeout(_voiceNoSpeechTimer); _voiceNoSpeechTimer = null; }
        if (btn) { btn.style.background = 'rgba(255,255,255,0.06)'; btn.innerHTML = '<i class="ph ph-microphone"></i>'; btn.title = 'Voice dictate'; }
        return;
    }

    _voiceFinalTranscript = '';
    _companionVoiceRecog = new SR();
    _companionVoiceRecog.lang = navigator.language || 'en-US';
    _companionVoiceRecog.interimResults = true;
    // v12.8 — continuous=true gives the user time to speak naturally;
    // it won't auto-stop after the first short pause the way continuous=false does.
    _companionVoiceRecog.continuous = true;
    _companionVoiceRecog.maxAlternatives = 1;

    _companionVoiceRecog.onresult = (e) => {
        if (_voiceNoSpeechTimer) { clearTimeout(_voiceNoSpeechTimer); _voiceNoSpeechTimer = null; }
        let interim = '';
        for (let i = e.resultIndex; i < e.results.length; i++) {
            const t = e.results[i][0].transcript;
            if (e.results[i].isFinal) {
                _voiceFinalTranscript += (t.endsWith(' ') ? t : t + ' ');
            } else {
                interim += t;
            }
        }
        const inp = document.getElementById('companion-chat-input');
        if (inp) {
            inp.value = (_voiceFinalTranscript + interim).trim();
            inp.style.height = 'auto';
            inp.style.height = Math.min(120, inp.scrollHeight) + 'px';
        }
        // Auto-stop 3 s after the last speech event (user stopped talking)
        _voiceNoSpeechTimer = setTimeout(() => {
            if (_companionVoiceRecog) { try { _companionVoiceRecog.stop(); } catch (_) {} }
        }, 3000);
    };

    _companionVoiceRecog.onspeechend = () => {
        // Speech segment ended — start countdown
        if (_voiceNoSpeechTimer) clearTimeout(_voiceNoSpeechTimer);
        _voiceNoSpeechTimer = setTimeout(() => {
            if (_companionVoiceRecog) { try { _companionVoiceRecog.stop(); } catch (_) {} }
        }, 1500);
    };

    _companionVoiceRecog.onend = () => {
        _companionVoiceListening = false;
        if (_voiceNoSpeechTimer) { clearTimeout(_voiceNoSpeechTimer); _voiceNoSpeechTimer = null; }
        if (btn) { btn.style.background = 'rgba(255,255,255,0.06)'; btn.innerHTML = '<i class="ph ph-microphone"></i>'; btn.title = 'Voice dictate'; }
        // If we captured something, auto-send a small confirmation
        if (_voiceFinalTranscript.trim()) {
            showToast('🎤 Got it — review your message and hit send.', 'info', 2200);
        }
    };

    _companionVoiceRecog.onerror = (e) => {
        _companionVoiceListening = false;
        if (btn) { btn.style.background = 'rgba(255,255,255,0.06)'; btn.innerHTML = '<i class="ph ph-microphone"></i>'; btn.title = 'Voice dictate'; }
        if (e.error === 'no-speech') {
            showToast('🎤 No speech detected — make sure your mic is on and speak clearly.', 'info', 3500);
        } else if (e.error === 'not-allowed' || e.error === 'permission-denied') {
            showToast('Mic blocked — allow microphone access in your browser\'s address bar.', 'error', 5000);
        } else if (e.error !== 'aborted') {
            showToast('Voice error: ' + e.error, 'error', 3000);
        }
    };

    try {
        _companionVoiceRecog.start();
        _companionVoiceListening = true;
        if (btn) { btn.style.background = 'linear-gradient(135deg,#ff6b6b,#e84393)'; btn.innerHTML = '<i class="ph ph-microphone-stage" style="animation:pulse 0.8s ease-in-out infinite;"></i>'; btn.title = 'Click to stop'; }
        showToast('🎤 Listening… speak naturally, then pause or click the mic to finish.', 'info', 3500);
    } catch (err) {
        showToast('Mic permission needed. Click the mic icon in your browser address bar to allow.', 'error', 5000);
    }
}

function isCompanionTTSOn() { return localStorage.getItem('companion_tts') === '1'; }
function toggleCompanionTTS() {
    const next = !isCompanionTTSOn();
    localStorage.setItem('companion_tts', next ? '1' : '0');
    const btn = document.getElementById('companion-tts-btn');
    if (btn) {
        btn.style.background = next ? 'linear-gradient(135deg,#00CEC9,#6C5CE7)' : 'rgba(255,255,255,0.06)';
        btn.title = next ? 'Companion replies will be spoken aloud — click to disable' : 'Read companion replies aloud';
    }
    showToast(next ? '🔊 Voice replies enabled.' : '🔇 Voice replies disabled.', 'info', 2200);
}
// v12.8 — TTS voice selection: prefer high-quality voices (Google/Microsoft neural)
// Falls back to the system default if none of the preferred voices are available.
function _getBestTTSVoice() {
    const voices = window.speechSynthesis.getVoices();
    if (!voices || voices.length === 0) return null;
    // Priority order: neural cloud voices first, then local quality voices
    const preferredNames = [
        'Google US English',         // Chrome on Windows/Mac (best quality)
        'Microsoft Aria Online',     // Edge neural voice
        'Microsoft Zira Online',     // Edge classic
        'Microsoft Aria',
        'Microsoft Zira',
        'Google UK English Female',
        'Samantha',                  // macOS Siri-quality
        'Alex',                      // macOS classic
        'en-US-Neural2-F',           // Chrome OS
    ];
    for (const name of preferredNames) {
        const v = voices.find(v => v.name === name);
        if (v) return v;
    }
    // Fall back to any English voice
    return voices.find(v => v.lang && v.lang.startsWith('en')) || voices[0];
}

function speakCompanionReply(text) {
    if (!isCompanionTTSOn()) return;
    if (!window.speechSynthesis) return;
    try {
        window.speechSynthesis.cancel();
        // Strip HTML, markdown asterisks, brackets, and excessive whitespace
        const cleanText = String(text)
            .replace(/<[^>]+>/g, ' ')    // HTML tags
            .replace(/\*+/g, '')          // markdown bold/italic
            .replace(/#{1,6}\s*/g, '')    // markdown headers
            .replace(/`+/g, '')           // code blocks
            .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1') // markdown links
            .replace(/\s+/g, ' ')
            .trim()
            .slice(0, 700); // slightly longer than before

        const utter = new SpeechSynthesisUtterance(cleanText);
        utter.lang = 'en-US';
        utter.rate = 0.95;   // slightly slower = more natural, easier to follow
        utter.pitch = 1.05;  // marginally higher = less robotic
        utter.volume = 1.0;

        // Assign best available voice asynchronously (voices may not be loaded yet)
        const setVoice = () => {
            const v = _getBestTTSVoice();
            if (v) utter.voice = v;
            window.speechSynthesis.speak(utter);
        };

        if (window.speechSynthesis.getVoices().length === 0) {
            // Voices not loaded yet — wait for the event
            window.speechSynthesis.addEventListener('voiceschanged', setVoice, { once: true });
        } else {
            setVoice();
        }
    } catch (_) {}
}
// Init TTS button visual state on load
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        const btn = document.getElementById('companion-tts-btn');
        if (btn && isCompanionTTSOn()) btn.style.background = 'linear-gradient(135deg,#00CEC9,#6C5CE7)';
    }, 700);
});

// ════════════════════════════════════════════════════════════════════
// v12.3 — COMPANION PERSISTENT MEMORY (community suggestion @longtermlearn)
// The companion remembers conversations across days. We store the chat
// transcript per companion in localStorage and inject the last N exchanges
// into every new system prompt as "Things we've talked about before".
// Users can clear it anytime in Settings → Companion → "Clear memory".
// ════════════════════════════════════════════════════════════════════
const COMPANION_MEMORY_MAX_ENTRIES = 40; // last 40 exchanges per companion
function getCompanionMemory(companionId) {
    try {
        const all = JSON.parse(localStorage.getItem('companion_memory') || '{}');
        let arr = all[companionId] || [];
        // v16.0 — retention: forget conversations older than the user's setting (0 = forever)
        const days = parseInt(localStorage.getItem('companion_memory_days') || '30', 10);
        if (!isNaN(days) && days > 0) {
            const cutoff = Date.now() - days * 86400000;
            arr = arr.filter(m => (m.ts || 0) >= cutoff);
        }
        return arr;
    } catch { return []; }
}
function appendCompanionMemory(companionId, userMsg, aiMsg) {
    try {
        const all = JSON.parse(localStorage.getItem('companion_memory') || '{}');
        const arr = all[companionId] || [];
        arr.push({ ts: Date.now(), user: String(userMsg).slice(0, 600), ai: String(aiMsg).slice(0, 600) });
        while (arr.length > COMPANION_MEMORY_MAX_ENTRIES) arr.shift();
        all[companionId] = arr;
        localStorage.setItem('companion_memory', JSON.stringify(all));
    } catch (_) {}
}
function buildCompanionMemoryContext(companionId) {
    const mem = getCompanionMemory(companionId);
    if (!mem || mem.length === 0) return '';
    // Skip very recent exchanges (they're already in _companionChatHistory)
    // and include the last 8-12 older ones as long-term memory.
    const olderThanToday = mem.filter(m => (Date.now() - m.ts) > 12 * 60 * 60 * 1000).slice(-10);
    if (olderThanToday.length === 0) return '';
    const lines = olderThanToday.map(m => `[${new Date(m.ts).toLocaleDateString()}] User: ${m.user.slice(0,180)}\nYou: ${m.ai.slice(0,180)}`).join('\n\n');
    return `\n\n=== LONG-TERM MEMORY (older conversations with this user, for natural callbacks) ===\n${lines}\n=== END MEMORY ===\n\nFeel free to reference these earlier conversations naturally when relevant ("last week we worked on..." / "remember when you asked about..."). Don't force callbacks; only use when genuinely relevant.`;
}
function clearCompanionMemory() {
    if (!confirm('Clear the companion\'s long-term memory of your past conversations?')) return;
    localStorage.removeItem('companion_memory');
    showToast('🧠 Companion memory cleared.', 'info', 2500);
    var m = document.getElementById('companion-memory-modal'); if (m) m.remove();
}
// v16.5 — Settings card: surface everything the companion remembers, across all companions.
function showCompanionMemorySummary() {
    var all = {};
    try { all = JSON.parse(localStorage.getItem('companion_memory') || '{}'); } catch (_) {}
    var days = parseInt(localStorage.getItem('companion_memory_days') || '30', 10);
    var cutoff = (!isNaN(days) && days > 0) ? (Date.now() - days * 86400000) : 0;
    var entries = [];
    Object.keys(all).forEach(function (cid) {
        var name = (typeof COMPANIONS_DATA !== 'undefined' && COMPANIONS_DATA[cid]) ? COMPANIONS_DATA[cid].name : cid;
        (all[cid] || []).forEach(function (m) {
            if ((m.ts || 0) >= cutoff) entries.push({ ts: m.ts, user: m.user, ai: m.ai, who: name });
        });
    });
    entries.sort(function (a, b) { return b.ts - a.ts; });

    var existing = document.getElementById('companion-memory-modal'); if (existing) existing.remove();
    var modal = document.createElement('div');
    modal.id = 'companion-memory-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.8);backdrop-filter:blur(8px);z-index:1000060;display:flex;align-items:center;justify-content:center;padding:20px;';
    modal.onclick = function (e) { if (e.target === modal) modal.remove(); };

    var body;
    if (!entries.length) {
        body = '<p style="color:var(--text-muted);text-align:center;padding:28px 8px;line-height:1.6;">Your companion hasn\'t saved any long-term memories yet.<br>Chat with your Sprite and meaningful exchanges will show up here.</p>';
    } else {
        body = '<p style="font-size:0.78rem;color:var(--text-muted);margin:0 0 12px;">Your companion remembers these ' + entries.length + ' past exchange' + (entries.length === 1 ? '' : 's') + ' (within your ' + (cutoff ? days + '-day' : 'unlimited') + ' retention window):</p>'
            + entries.map(function (m) {
                return '<div style="border:1px solid var(--glass-border);border-radius:10px;padding:10px 12px;margin-bottom:8px;background:rgba(255,255,255,0.02);">'
                    + '<div style="font-size:0.7rem;color:var(--text-muted);margin-bottom:5px;display:flex;justify-content:space-between;"><span>' + escapeHtmlSafe(m.who) + '</span><span>' + new Date(m.ts).toLocaleDateString() + '</span></div>'
                    + '<div style="font-size:0.84rem;color:#cdd2e0;"><strong style="color:#a29bfe;">You:</strong> ' + escapeHtmlSafe((m.user || '').slice(0, 180)) + '</div>'
                    + '<div style="font-size:0.84rem;color:#cdd2e0;margin-top:2px;"><strong style="color:#00CEC9;">Sprite:</strong> ' + escapeHtmlSafe((m.ai || '').slice(0, 180)) + '</div>'
                    + '</div>';
            }).join('');
    }

    modal.innerHTML = '<div class="glass-panel" style="max-width:540px;width:94%;max-height:84vh;display:flex;flex-direction:column;padding:0;overflow:hidden;border:1px solid rgba(108,92,231,0.5);">'
        + '<div style="display:flex;justify-content:space-between;align-items:center;padding:16px 20px;border-bottom:1px solid var(--glass-border);flex-shrink:0;"><h3 style="margin:0;color:white;font-size:1.05rem;"><i class="ph ph-brain" style="color:#a29bfe;"></i> What your companion knows</h3><button class="btn-icon" onclick="document.getElementById(\'companion-memory-modal\').remove()"><i class="ph ph-x"></i></button></div>'
        + '<div style="padding:16px 20px;overflow-y:auto;">' + body + '</div>'
        + (entries.length ? '<div style="padding:12px 20px;border-top:1px solid var(--glass-border);text-align:right;flex-shrink:0;"><button class="btn-secondary" style="color:#ff6b6b;border-color:rgba(255,107,107,0.35);font-size:0.85rem;" onclick="clearCompanionMemory()"><i class="ph ph-trash"></i> Clear all memory</button></div>' : '')
        + '</div>';
    document.body.appendChild(modal);
}

