function startAPExamPack(packId) {
    const pack = AP_EXAM_PACKS[packId];
    if (!pack) return;
    document.getElementById('ap-exam-modal').remove();
    // Force Tutor mode + pick a random topic + jump to the right subject
    localStorage.setItem('difficulty_mode', 'tutor');
    const topic = pack.topics[Math.floor(Math.random() * pack.topics.length)];
    const prompt = `Give me one challenging ${pack.name} practice problem on: ${topic}. Make it AP-exam-level difficulty.`;
    if (pack.subject === 'math') {
        switchTab('math');
        const inp = document.getElementById('math-text-input');
        if (inp) inp.value = prompt;
        setTimeout(() => processMathInput && processMathInput(), 350);
    } else if (pack.subject === 'science') {
        switchTab('science');
        const inp = document.getElementById('science-input');
        if (inp) inp.value = prompt;
        setTimeout(() => solveScience && solveScience(), 350);
    } else if (pack.subject === 'english') {
        switchTab('english');
        const inp = document.getElementById('english-input');
        if (inp) inp.value = prompt + '\n\nProvide a sample passage we can practice with, then ask me to apply the relevant skill to it.';
        setTimeout(() => englishAction && englishAction('analyze'), 350);
    } else if (pack.subject === 'social') {
        switchTab('social');
        const inp = document.getElementById('social-timing-search');
        if (inp) inp.value = topic;
        setTimeout(() => searchSocial && searchSocial('timing'), 350);
    }
    showToast(`📚 ${pack.name} — practice problem loading…`, 'success', 3500);
}

// v12.8 — Multi-theme system: dark / grey / onyx / light
const THEME_MODES = ['dark', 'grey', 'onyx', 'light'];
const THEME_CLASSES = { dark: '', grey: 'theme-grey', onyx: 'theme-onyx', light: 'theme-light' };

function applyThemeMode(mode) {
    if (!THEME_MODES.includes(mode)) mode = 'dark';
    // Remove all theme classes
    document.body.classList.remove('theme-light', 'theme-grey', 'theme-onyx');
    // Apply new class (dark = no class)
    if (THEME_CLASSES[mode]) document.body.classList.add(THEME_CLASSES[mode]);
    localStorage.setItem('nexus_theme', mode);
    // Sync legacy checkbox
    const cb = document.getElementById('setting-light-theme');
    if (cb) cb.checked = mode === 'light';
    // Sync quick toggle icon
    const icon = document.getElementById('theme-toggle-icon');
    const label = document.getElementById('theme-toggle-label');
    const icons = { dark: { cls: 'ph ph-moon', color: '#a29bfe', lbl: 'Dark Mode' },
                    grey: { cls: 'ph ph-circle-half', color: '#b8bcc8', lbl: 'Grey Mode' },
                    onyx: { cls: 'ph ph-circle', color: '#6c5ce7', lbl: 'Onyx Mode' },
                    light: { cls: 'ph ph-sun', color: '#fdcb6e', lbl: 'Light Mode' } };
    const ic = icons[mode] || icons.dark;
    if (icon) { icon.className = ic.cls; icon.style.color = ic.color; }
    if (label) label.textContent = ic.lbl;
    // Update theme picker buttons
    document.querySelectorAll('.theme-pick-btn').forEach(btn => {
        btn.classList.toggle('active-theme', btn.dataset.theme === mode);
    });
}

// Keep old toggleLightTheme for compatibility (checkbox in old settings)
function toggleLightTheme(enabled) {
    applyThemeMode(enabled ? 'light' : 'dark');
}

function applySavedThemeOnLoad() {
    const saved = localStorage.getItem('nexus_theme') || 'dark';
    applyThemeMode(saved);
}
document.addEventListener('DOMContentLoaded', () => { setTimeout(applySavedThemeOnLoad, 200); });

// v12.1 — Companion idle glow toggle. When OFF (default), the companion sprite
// fades to ~20% opacity when nothing is happening, and only fully brightens when
// you summon it, link it to a session, or actively chat with it.
function toggleCompanionIdleGlow(enabled) {
    localStorage.setItem('companion_idle_glow', enabled ? '1' : '0');
    applyCompanionGlowState();
}
function isCompanionIdleGlowOn() {
    return localStorage.getItem('companion_idle_glow') === '1';
}
function applyCompanionGlowState() {
    const layer = document.getElementById('companion-layer');
    if (!layer) return;
    const dimWhenIdle = !isCompanionIdleGlowOn();
    layer.classList.toggle('companion-dim-idle', dimWhenIdle);
    // Anything actively focused brightens it:
    //   • companion-chat panel open
    //   • a linked session is active (set via setCompanionLinkedSession)
    const chat = document.getElementById('companion-chat');
    const chatOpen = chat && chat.style.display && chat.style.display !== 'none';
    const linked = !!localStorage.getItem('companion_linked_session');
    layer.classList.toggle('companion-active', chatOpen || linked);
}
// Re-apply whenever chat opens/closes
const _origOpenChat = (typeof openCompanionChat === 'function') ? openCompanionChat : null;
if (_origOpenChat) {
    window.openCompanionChat = function(id) {
        const r = _origOpenChat(id);
        setTimeout(applyCompanionGlowState, 50);
        return r;
    };
}
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        const cb = document.getElementById('setting-companion-idle-glow');
        if (cb) cb.checked = isCompanionIdleGlowOn();
        applyCompanionGlowState();
    }, 700);
});

function addCompanionMessage(role, text) {
    const msgs = document.getElementById('companion-chat-messages');
    if (!msgs) return;
    const div = document.createElement('div');
    div.className = role === 'user' ? 'companion-msg-user' : 'companion-msg-ai';
    // Render mild markdown: **bold**, line breaks
    const safe = text.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
    const formatted = safe.replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>').replace(/\n/g,'<br>');
    div.innerHTML = formatted;
    msgs.appendChild(div);
    msgs.scrollTop = msgs.scrollHeight;
}

function clearCompanionChatImage() {
    window._companionChatImage = null;
    const preview = document.getElementById('companion-chat-image-preview');
    const thumb = document.getElementById('companion-chat-image-thumb');
    if (preview) preview.style.display = 'none';
    if (thumb) thumb.src = '';
}

// ════════════════════════════════════════════════════════════════════
// v12.1 — COMPANION: LINK TO SESSION
// Lets the user "link" the companion to a current Math / Science / English /
// Live Vision session. While linked, every companion reply has the full
// transcript of that session injected as a system message, so the companion
// can answer follow-up questions with full context (problem, steps, answers).
// ════════════════════════════════════════════════════════════════════
function getActiveLinkableSessions() {
    const out = [];
    // Math tutor — uses _mathTutorTurns
    if (typeof _mathTutorTurns !== 'undefined' && _mathTutorTurns.length > 1) {
        const firstUser = _mathTutorTurns.find(m => m.role === 'user');
        const summary = typeof firstUser?.content === 'string'
            ? firstUser.content.slice(0, 80)
            : '(math problem with image)';
        out.push({ id: 'math', label: 'Math: ' + summary, icon: 'ph-function' });
    }
    // Science tutor
    if (typeof _scienceTutorTurns !== 'undefined' && _scienceTutorTurns.length > 1) {
        const firstUser = _scienceTutorTurns.find(m => m.role === 'user');
        const summary = typeof firstUser?.content === 'string'
            ? firstUser.content.slice(0, 80)
            : '(science topic with image)';
        out.push({ id: 'science', label: 'Science: ' + summary, icon: 'ph-flask' });
    }
    // Live Vision — available once a guidance/answer card has been generated.
    // (OCR is no longer used, so we key off the guidance, not the empty problem text.)
    if (typeof window._liveVisionLastGuidance === 'string' && window._liveVisionLastGuidance.length > 0) {
        const snip = window._liveVisionLastGuidance.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 60);
        out.push({ id: 'live-vision', label: 'Live Vision: ' + snip + '…', icon: 'ph-eye' });
    }
    return out;
}

function getLinkedSession() {
    try { return JSON.parse(localStorage.getItem('companion_linked_session') || 'null'); }
    catch { return null; }
}
function setLinkedSession(linked) {
    if (linked) localStorage.setItem('companion_linked_session', JSON.stringify(linked));
    else localStorage.removeItem('companion_linked_session');
    updateCompanionLinkLabel();
    if (typeof applyCompanionGlowState === 'function') applyCompanionGlowState();
}
function updateCompanionLinkLabel() {
    const lbl = document.getElementById('companion-link-label');
    if (!lbl) return;
    const linked = getLinkedSession();
    lbl.textContent = linked ? ('Linked: ' + (linked.id.charAt(0).toUpperCase() + linked.id.slice(1))) : 'Link';
    const btn = document.getElementById('companion-chat-link-btn');
    if (btn) {
        btn.style.background = linked ? 'linear-gradient(135deg,rgba(0,206,201,0.45),rgba(108,92,231,0.45))' : 'rgba(0,206,201,0.18)';
        btn.style.color = linked ? '#fff' : '#7fffec';
    }
    // v12.2 — show the dedicated Unlink button when there's an active link
    const unlinkBtn = document.getElementById('companion-chat-unlink-btn');
    if (unlinkBtn) unlinkBtn.style.display = linked ? 'flex' : 'none';
}

// ════════════════════════════════════════════════════════════════════
// v12.2 — COMPANION CHAT: DRAG + RESIZE
// User can drag the chat panel by its header and resize from any edge or
// corner. Sizes/positions persist to localStorage so the user's preferred
// layout sticks across reloads. Skipped while docked into the Vision pocket.
// ════════════════════════════════════════════════════════════════════
function _saveCompanionChatGeometry(chat) {
    if (!chat || _companionVisionDocked) return;
    try {
        localStorage.setItem('companion_chat_geometry', JSON.stringify({
            left: chat.style.left || '',
            top: chat.style.top || '',
            right: chat.style.right || '',
            bottom: chat.style.bottom || '',
            width: chat.style.width || '',
            height: chat.style.height || ''
        }));
    } catch (_) {}
}
function _restoreCompanionChatGeometry() {
    const chat = document.getElementById('companion-chat');
    if (!chat) return;
    try {
        const g = JSON.parse(localStorage.getItem('companion_chat_geometry') || 'null');
        if (!g) return;
        Object.entries(g).forEach(([k, v]) => { if (v) chat.style[k] = v; });
    } catch (_) {}
}
function wireCompanionDragResize() {
    const chat = document.getElementById('companion-chat');
    if (!chat || chat._dragResizeWired) return;
    chat._dragResizeWired = true;

    // Drag-by-header — anything in the top 56px that ISN'T a button or a
    // resize handle counts as drag surface.
    chat.addEventListener('mousedown', (e) => {
        if (_companionVisionDocked) return;
        if (e.target.closest('.companion-resize-handle')) return;
        if (e.target.closest('button')) return;
        if (e.target.closest('input, textarea, select')) return;
        const rect = chat.getBoundingClientRect();
        if (e.clientY - rect.top > 56) return; // only header drags
        const offsetX = e.clientX - rect.left;
        const offsetY = e.clientY - rect.top;
        const onMove = (ev) => {
            const nx = ev.clientX - offsetX;
            const ny = ev.clientY - offsetY;
            chat.style.left = Math.max(0, Math.min(window.innerWidth - 100, nx)) + 'px';
            chat.style.top  = Math.max(0, Math.min(window.innerHeight - 60, ny)) + 'px';
            chat.style.right = ''; chat.style.bottom = '';
        };
        const onUp = () => {
            document.removeEventListener('mousemove', onMove);
            document.removeEventListener('mouseup', onUp);
            _saveCompanionChatGeometry(chat);
        };
        document.addEventListener('mousemove', onMove);
        document.addEventListener('mouseup', onUp);
        e.preventDefault();
    });

    // Resize handles — each handle knows which edges it controls
    const handles = {
        'companion-chat-resize-tl': { l: true,  t: true  },
        'companion-chat-resize-tr': { r: true,  t: true  },
        'companion-chat-resize-bl': { l: true,  b: true  },
        'companion-chat-resize-br': { r: true,  b: true  },
        'companion-chat-resize-l':  { l: true             },
        'companion-chat-resize-r':  { r: true             },
        'companion-chat-resize-t':  {            t: true  },
        'companion-chat-resize-b':  {            b: true  }
    };
    Object.entries(handles).forEach(([id, edges]) => {
        const h = document.getElementById(id);
        if (!h) return;
        h.addEventListener('mousedown', (e) => {
            if (_companionVisionDocked) return;
            const start = {
                x: e.clientX, y: e.clientY,
                rect: chat.getBoundingClientRect()
            };
            // Switch to top/left positioning so we have absolute control during resize
            chat.style.left = start.rect.left + 'px';
            chat.style.top = start.rect.top + 'px';
            chat.style.right = ''; chat.style.bottom = '';
            const onMove = (ev) => {
                const dx = ev.clientX - start.x;
                const dy = ev.clientY - start.y;
                let { left, top, width, height } = { left: start.rect.left, top: start.rect.top, width: start.rect.width, height: start.rect.height };
                if (edges.r) width = Math.max(280, width + dx);
                if (edges.b) height = Math.max(300, height + dy);
                if (edges.l) { width = Math.max(280, width - dx); left = Math.min(left + dx, start.rect.right - 280); }
                if (edges.t) { height = Math.max(300, height - dy); top = Math.min(top + dy, start.rect.bottom - 300); }
                chat.style.width  = width + 'px';
                chat.style.height = height + 'px';
                chat.style.left   = left + 'px';
                chat.style.top    = top + 'px';
            };
            const onUp = () => {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
                _saveCompanionChatGeometry(chat);
            };
            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
            e.preventDefault();
            e.stopPropagation();
        });
    });
}
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        _restoreCompanionChatGeometry();
        wireCompanionDragResize();
    }, 600);
});
function toggleCompanionLinkMenu(evt) {
    if (evt) evt.stopPropagation();
    const menu = document.getElementById('companion-link-menu');
    if (!menu) return;
    const wasOpen = menu.style.display === 'block';
    menu.style.display = wasOpen ? 'none' : 'block';
    if (wasOpen) return;
    // Build options
    const opts = document.getElementById('companion-link-options');
    if (!opts) return;
    const sessions = getActiveLinkableSessions();
    const linked = getLinkedSession();
    const renderOpt = (s) => `
        <button onclick="linkCompanionTo('${s.id}')" style="display:flex;align-items:center;gap:12px;width:100%;text-align:left;background:${linked && linked.id === s.id ? 'rgba(0,206,201,0.25)' : 'transparent'};border:1px solid ${linked && linked.id === s.id ? 'rgba(0,206,201,0.5)' : 'transparent'};color:white;padding:8px 10px;border-radius:8px;cursor:pointer;font-size:0.9rem;margin-bottom:4px;" onmouseover="this.style.background='rgba(0,206,201,0.15)'" onmouseout="this.style.background='${linked && linked.id === s.id ? 'rgba(0,206,201,0.25)' : 'transparent'}'">
            <i class="ph ${s.icon}" style="color:#00CEC9;"></i>
            <span style="flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${escapeHtmlSafe(s.label)}</span>
        </button>`;
    let html = '';
    if (sessions.length === 0) {
        html = '<div style="padding:10px;color:var(--text-muted);font-size:0.88rem;text-align:center;">No active sessions yet.<br><span style="opacity:0.7;">Start a math/science/Live Vision problem to link.</span></div>';
    } else {
        html = sessions.map(renderOpt).join('');
    }
    if (linked) {
        html += `<div style="border-top:1px solid rgba(255,255,255,0.1);margin-top:6px;padding-top:6px;"><button onclick="linkCompanionTo(null)" style="width:100%;text-align:left;background:transparent;border:none;color:#ff6b6b;padding:8px 10px;border-radius:6px;cursor:pointer;font-size:0.88rem;"><i class="ph ph-link-break"></i> Unlink</button></div>`;
    }
    opts.innerHTML = html;
}
function linkCompanionTo(sessionId) {
    if (!sessionId) {
        setLinkedSession(null);
        undockCompanionFromVision();
        showToast('Companion unlinked.', 'info', 2000);
    } else {
        const sessions = getActiveLinkableSessions();
        const found = sessions.find(s => s.id === sessionId);
        if (!found) { showToast('That session is no longer active.', 'warning'); return; }
        setLinkedSession({ id: sessionId, label: found.label, linkedAt: Date.now() });
        // v12.2 — when linked to Live Vision, dock the companion chat into the
        // empty pocket below the vision feed (or open chat if it's closed)
        if (sessionId === 'live-vision') {
            if (typeof openCompanionChat === 'function') {
                const equipped = (userLoadout && userLoadout.companion) || 'nexus-orb';
                openCompanionChat(equipped === 'none' ? 'nexus-orb' : equipped);
            }
            setTimeout(dockCompanionInVisionPocket, 100);
        } else {
            undockCompanionFromVision();
        }
        showToast(`Linked to ${sessionId}. Companion now sees the full transcript.`, 'success', 3500);
    }
    const menu = document.getElementById('companion-link-menu');
    if (menu) menu.style.display = 'none';
}

// v12.2 — Dock the companion chat into the empty space inside the Live Vision
// panel. We use the existing #live-vision-panel as the anchor and absolutely-
// position the chat to fill the analysis-feed column's bottom half (where the
// "pocket" the user pointed to lives).
let _companionVisionDocked = false;
let _companionOriginalStyles = null;
function dockCompanionInVisionPocket() {
    const chat = document.getElementById('companion-chat');
    const vision = document.getElementById('live-vision-panel');
    if (!chat || !vision || vision.classList.contains('hidden')) return;
    if (_companionVisionDocked) return;
    // Snapshot current floating styles so we can restore on undock
    _companionOriginalStyles = {
        position: chat.style.position, top: chat.style.top, right: chat.style.right,
        bottom: chat.style.bottom, left: chat.style.left,
        width: chat.style.width, height: chat.style.height,
        borderRadius: chat.style.borderRadius
    };
    // Move into the vision panel and anchor to the bottom-left pocket
    vision.style.position = 'relative';
    vision.appendChild(chat);
    chat.style.position = 'absolute';
    chat.style.top = '';
    chat.style.right = '14px';
    chat.style.bottom = '14px';
    chat.style.left = '';
    chat.style.width = '380px';
    chat.style.height = 'calc(60% - 28px)';
    chat.style.borderRadius = '14px';
    chat.classList.add('companion-docked-vision');
    _companionVisionDocked = true;
}
function undockCompanionFromVision() {
    const chat = document.getElementById('companion-chat');
    if (!chat || !_companionVisionDocked) return;
    // Put it back on the body and restore floating
    document.body.appendChild(chat);
    if (_companionOriginalStyles) {
        Object.entries(_companionOriginalStyles).forEach(([k, v]) => { chat.style[k] = v || ''; });
    } else {
        chat.style.position = 'fixed';
        chat.style.bottom = '24px';
        chat.style.right = '24px';
        chat.style.top = '';
        chat.style.left = '';
        chat.style.width = '380px';
        chat.style.height = '520px';
        chat.style.borderRadius = '18px';
    }
    chat.classList.remove('companion-docked-vision');
    _companionVisionDocked = false;
}
// Close link menu on outside click
document.addEventListener('click', (e) => {
    const menu = document.getElementById('companion-link-menu');
    const btn = document.getElementById('companion-chat-link-btn');
    if (!menu || menu.style.display === 'none') return;
    if (menu.contains(e.target) || (btn && btn.contains(e.target))) return;
    menu.style.display = 'none';
});

// Build the system-prompt extension that injects the linked session transcript
function buildLinkedSessionContext() {
    const linked = getLinkedSession();
    if (!linked) return '';
    let transcript = '';
    if (linked.id === 'math' && typeof _mathTutorTurns !== 'undefined') {
        transcript = _mathTutorTurns
            .filter(m => m.role !== 'system')
            .map(m => `${m.role.toUpperCase()}: ${typeof m.content === 'string' ? m.content : '(image)'}`)
            .join('\n\n');
    } else if (linked.id === 'science' && typeof _scienceTutorTurns !== 'undefined') {
        transcript = _scienceTutorTurns
            .filter(m => m.role !== 'system')
            .map(m => `${m.role.toUpperCase()}: ${typeof m.content === 'string' ? m.content : '(image)'}`)
            .join('\n\n');
    } else if (linked.id === 'live-vision') {
        const problem = (window._liveVisionLastProblem || '').trim();
        const guidance = (window._liveVisionLastGuidance || '').trim();
        transcript = (problem ? `PROBLEM ON SCREEN:\n${problem}\n\n` : '') +
            `WHAT NEXUS SHOWED THE STUDENT (read from their screen):\n${guidance}`;
    }
    if (!transcript) return '';
    return `\n\n=== LINKED SESSION CONTEXT (${linked.id.toUpperCase()}) ===\nYou are linked into the user's current ${linked.id} session. Use this transcript to answer follow-up questions with full context. Reference specific steps. Stay consistent with the guidance already given — don't reveal answers if the session was in Tutor mode.\n\n${transcript}\n=== END LINKED SESSION ===\n`;
}

async function sendCompanionMessage() {
    const input = document.getElementById('companion-chat-input');
    const chat = document.getElementById('companion-chat');
    if (!input || !chat) return;
    const text = input.value.trim();
    const attachedImage = window._companionChatImage || null;
    if (!text && !attachedImage) return;
    const id = chat.dataset.companionId;
    const data = COMPANIONS_DATA[id];
    if (!data) return;

    // Build user message: text + optional image (vision-aware)
    const displayText = text || '(image attached)';
    addCompanionMessage('user', attachedImage ? `📎 [image] ${displayText}` : displayText);
    const userContentForApi = attachedImage
        ? [{ type: 'text', text: text || 'Please look at this image and help me with it.' }, { type: 'image_url', image_url: { url: attachedImage } }]
        : text;
    _companionChatHistory.push({ role: 'user', content: userContentForApi });
    input.value = '';
    input.style.height = ''; // reset textarea height
    clearCompanionChatImage();

    const apiKey = getApiKey();
    if (!apiKey) {
        addCompanionMessage('ai', "I need an OpenAI API key first — pop into Settings and add one, then come back.");
        return;
    }

    // Typing indicator
    const msgs = document.getElementById('companion-chat-messages');
    const typing = document.createElement('div');
    typing.className = 'companion-msg-ai';
    typing.id = 'companion-typing';
    typing.innerHTML = '<i class="ph ph-spinner ph-spin"></i> thinking…';
    msgs.appendChild(typing);
    msgs.scrollTop = msgs.scrollHeight;

    try {
        const personaData = getActiveCompanionPersona(id) || data;
        // v12.1 — append linked-session transcript if the companion is linked
        const sessionContext = buildLinkedSessionContext();
        // v12.3 — also append long-term memory of past conversations
        const memoryContext = (typeof buildCompanionMemoryContext === 'function') ? buildCompanionMemoryContext(id) : '';
        // v15.0 — companion personality prefix
        const _cpersonality = localStorage.getItem('companion_personality') || 'default';
        const _cpersonalityPrefixes = {
            default:    '',
            drill:      '\n\nPERSONALITY OVERRIDE — DRILL SERGEANT: You are tough-love, blunt, and demanding. Short sharp responses only. No coddling. Push the student hard. Use commands. No filler.',
            bestfriend: '\n\nPERSONALITY OVERRIDE — BEST FRIEND: Super casual and encouraging. Use "dude", "you got this", "no cap", "fr fr". High energy, hype them up, keep it chill.',
            sherlock:   '\n\nPERSONALITY OVERRIDE — SHERLOCK: Analytical and deductive. Never give the direct answer. Ask probing questions to lead the student to discover it themselves. Speak with precise, clinical observation.',
            sensei:     '\n\nPERSONALITY OVERRIDE — CHILL SENSEI: Calm, Zen, and wise. Use metaphors and analogies. Speak slowly (in text). Never rush. Always find the deeper lesson.',
            rival:      '\n\nPERSONALITY OVERRIDE — ACADEMIC RIVAL: You are the student\'s friendly-but-competitive academic rival. Treat studying like a contest you\'re both in — gently taunt and challenge them ("I already nailed this one, bet you can\'t beat my time"), hype it up when they win, and push them to outdo you. Confident and a little cocky, but never mean and never withhold real help.'
        };
        const personalityPrefix = _cpersonalityPrefixes[_cpersonality] || '';
        const systemPrompt = NEXUS_COMPANION_PROMPT + personalityPrefix + '\n\n' + personaData.persona + sessionContext + memoryContext;
        const messages = [
            { role: 'system', content: systemPrompt },
            ..._companionChatHistory.slice(-12)
        ];

        // v10.7 — STREAM the response into a live message bubble
        document.getElementById('companion-typing')?.remove();
        const liveBubble = document.createElement('div');
        liveBubble.className = 'companion-msg-ai';
        liveBubble.innerHTML = '<span class="streaming-content"></span><span class="streaming-cursor">▍</span>';
        msgs.appendChild(liveBubble);
        msgs.scrollTop = msgs.scrollHeight;
        const contentEl = liveBubble.querySelector('.streaming-content');
        const cursorEl = liveBubble.querySelector('.streaming-cursor');

        let accumulated = '';
        await streamChat({
            apiKey,
            model: localStorage.getItem('ai_model') || 'gpt-4o',
            messages,
            temperature: 0.85,
            max_tokens: 1500,
            onChunk: (delta, full) => {
                accumulated = full;
                contentEl.textContent = stripHtmlForStream(accumulated);
                msgs.scrollTop = msgs.scrollHeight;
            },
            onDone: (full) => {
                if (cursorEl) cursorEl.remove();
                // Final pass: format markdown leaks + minimal HTML
                const formatted = (typeof convertMarkdownLeaks === 'function')
                    ? convertMarkdownLeaks(full).replace(/\n/g, '<br>')
                    : full.replace(/\n/g, '<br>');
                contentEl.innerHTML = formatted;
                _companionChatHistory.push({ role: 'assistant', content: full });
                // v12.3 — persist this exchange to long-term memory + maybe speak aloud
                const userMsg = typeof text === 'string' ? text : (Array.isArray(userContentForApi) ? userContentForApi.find(p => p.type === 'text')?.text : 'image');
                if (typeof appendCompanionMemory === 'function') appendCompanionMemory(id, userMsg || '', full);
                if (typeof speakCompanionReply === 'function') speakCompanionReply(full);
                if (typeof recordQuestProgress === 'function') recordQuestProgress('companion_chat');
            },
            onError: (err) => {
                if (cursorEl) cursorEl.remove();
                contentEl.textContent = 'I hit an error: ' + err.message;
            }
        });
    } catch (err) {
        document.getElementById('companion-typing')?.remove();
        addCompanionMessage('ai', `I hit an error: ${err.message}`);
    }
}

// ── 6. INIT — spawn equipped companion on load if user is Pro ─────────
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        // v10.7 — Settings → Companion → Auto-spawn on launch
        // v12.7: default changed to OFF — companion only appears when manually summoned
        const autospawn = (localStorage.getItem('companion_autospawn') || '0') === '1';
        if (!autospawn) return;
        const equipped = (userLoadout && userLoadout.companion) || 'none';
        if (equipped !== 'none' && hasPro()) {
            applyCompanion(equipped);
        }
    }, 800);

    // Re-check on tier change — listen for storage events from other tabs / same-tab updates
    window.addEventListener('storage', (e) => {
        if (e.key === 'user_tier') {
            const equipped = (userLoadout && userLoadout.companion) || 'none';
            if (equipped !== 'none' && hasPro()) applyCompanion(equipped);
            else despawnCompanion();
        }
    });

    // ── COMPANION BACKTICK TOGGLE (`) ──
    // Press ` to hide/summon the companion. Ignored while typing in inputs/textareas/contenteditable.
    window._companionManuallyHidden = false;

    // ── v12.7 SHORTCUT EDITOR SYSTEM ──────────────────────────────────────────
    // Default bindings. Users can override via Settings → Shortcuts (click-to-record).
    const SHORTCUT_DEFAULTS = {
        companion_toggle: { label: 'Toggle companion',   desc: 'Hide / re-summon your companion',      key: '`',           ctrl: false, alt: false, shift: false },
        open_settings:    { label: 'Open Settings',      desc: 'Quick-open the Settings modal',         key: ',',           ctrl: true,  alt: false, shift: false },
        open_help:        { label: 'Open Help / FAQ',    desc: 'Jump to the Help & FAQ panel',          key: '?',           ctrl: false, alt: false, shift: false },
        quick_notes:      { label: 'Quick Notes',        desc: 'Pop open the floating notepad',         key: 'n',           ctrl: true,  alt: false, shift: true  },
    };

    function _getShortcuts() {
        try {
            const saved = JSON.parse(localStorage.getItem('shortcut_bindings') || 'null');
            if (saved && typeof saved === 'object') {
                // Merge: saved overrides defaults, new defaults are added
                return Object.fromEntries(
                    Object.entries(SHORTCUT_DEFAULTS).map(([id, def]) => [id, saved[id] || def])
                );
            }
        } catch (_) {}
        return { ...SHORTCUT_DEFAULTS };
    }
    function _saveShortcuts(bindings) {
        localStorage.setItem('shortcut_bindings', JSON.stringify(bindings));
    }
    function _keyLabel(binding) {
        const parts = [];
        if (binding.ctrl)  parts.push('Ctrl');
        if (binding.alt)   parts.push('Alt');
        if (binding.shift) parts.push('Shift');
        parts.push(binding.key === ' ' ? 'Space' : (binding.key || '?'));
        return parts.join(' + ');
    }
    function _matchesBinding(e, binding) {
        return e.key === binding.key &&
               !!e.ctrlKey  === !!binding.ctrl &&
               !!e.altKey   === !!binding.alt  &&
               !!e.shiftKey === !!binding.shift;
    }

    window.renderShortcutEditor = function() {
        const el = document.getElementById('shortcut-editor-list');
        if (!el) return;
        const bindings = _getShortcuts();
        el.innerHTML = Object.entries(bindings).map(([id, b]) => `
            <div class="glass-panel" style="padding:14px;margin-bottom:8px;display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;">
                <div style="flex:1;min-width:160px;">
                    <div style="color:white;font-weight:500;">${b.label}</div>
                    <p style="margin:2px 0 0;font-size:0.88rem;color:var(--text-muted);">${b.desc}</p>
                </div>
                <div style="display:flex;align-items:center;gap:12px;">
                    <button id="sc-btn-${id}" onclick="startRebind('${id}')"
                        style="background:rgba(0,206,201,0.13);border:1px solid rgba(0,206,201,0.4);border-radius:6px;padding:5px 12px;font-family:monospace;font-size:0.84rem;color:#00cec9;cursor:pointer;white-space:nowrap;min-width:90px;text-align:center;">
                        ${escapeHtml(_keyLabel(b))}
                    </button>
                    <button onclick="resetShortcut('${id}')" title="Reset to default"
                        style="background:rgba(255,255,255,0.06);border:1px solid var(--glass-border);border-radius:6px;padding:5px 8px;cursor:pointer;color:var(--text-muted);font-size:0.9rem;">
                        <i class="ph ph-arrow-counter-clockwise"></i>
                    </button>
                </div>
            </div>`).join('');
    };

    let _rebindActive = null;
    window.startRebind = function(id) {
        if (_rebindActive) stopRebind();
        _rebindActive = id;
        const btn = document.getElementById('sc-btn-' + id);
        if (btn) {
            btn.textContent = '⌨ Press key...';
            btn.style.borderColor = '#fdcb6e';
            btn.style.color = '#fdcb6e';
            btn.style.background = 'rgba(253,203,110,0.12)';
        }
    };
    function stopRebind() {
        if (!_rebindActive) return;
        const btn = document.getElementById('sc-btn-' + _rebindActive);
        _rebindActive = null;
        if (btn) {
            btn.style.borderColor = '';
            btn.style.color = '';
            btn.style.background = '';
        }
        if (window.renderShortcutEditor) renderShortcutEditor();
    }
    window.resetShortcut = function(id) {
        const bindings = _getShortcuts();
        bindings[id] = { ...SHORTCUT_DEFAULTS[id] };
        _saveShortcuts(bindings);
        renderShortcutEditor();
    };
    window.resetAllShortcuts = function() {
        _saveShortcuts({ ...SHORTCUT_DEFAULTS });
        renderShortcutEditor();
        showToast('All shortcuts reset to defaults.', 'success');
    };

    // Listen for rebind keydown events BEFORE global shortcut dispatch
    document.addEventListener('keydown', (e) => {
        if (!_rebindActive) return;
        if (e.key === 'Escape') { stopRebind(); e.preventDefault(); return; }
        // Ignore modifier-only presses
        if (['Control','Alt','Shift','Meta'].includes(e.key)) return;
        e.preventDefault();
        const activeId = _rebindActive; // capture before stopRebind clears it
        const bindings = _getShortcuts();
        bindings[activeId] = { ...bindings[activeId], key: e.key, ctrl: e.ctrlKey, alt: e.altKey, shift: e.shiftKey };
        _saveShortcuts(bindings);
        stopRebind();
        showToast(`✓ Shortcut updated: ${_keyLabel(bindings[activeId])}`, 'success');
    }, true); // capture phase so it fires before global listeners

    // Render editor when the shortcuts tab is opened
    (function() {
        document.addEventListener('click', (e) => {
            const btn = e.target.closest('.settings-tab-btn');
            if (btn && btn.dataset.tab === 'shortcuts') {
                setTimeout(renderShortcutEditor, 50);
            }
        });
    })();

    document.addEventListener('keydown', (e) => {
        return; // v19 — keyboard shortcuts removed app-wide
        if (localStorage.getItem('shortcuts_enabled') === '0') return;
        if (_rebindActive) return; // handled above
        const t = e.target;
        const tag = ((t && t.tagName) || '').toLowerCase();
        const isTyping = tag === 'input' || tag === 'textarea' || (t && t.isContentEditable);
        const sc = _getShortcuts();
        // Companion toggle
        if (_matchesBinding(e, sc.companion_toggle) && !isTyping) {
            const equipped = (userLoadout && userLoadout.companion) || 'none';
            if (equipped === 'none' || !hasPro()) return;
            e.preventDefault();
            if (window._companionManuallyHidden) {
                window._companionManuallyHidden = false;
                applyCompanion(equipped);
            } else {
                window._companionManuallyHidden = true;
                despawnCompanion();
            }
            return;
        }
        // Open Settings
        if (_matchesBinding(e, sc.open_settings)) {
            e.preventDefault();
            if (typeof toggleSettings === 'function') toggleSettings();
            return;
        }
        // Open Help/FAQ
        if (_matchesBinding(e, sc.open_help) && !isTyping) {
            e.preventDefault();
            if (typeof openHelpCenter === 'function') openHelpCenter();
            return;
        }
        // Quick Notes
        if (_matchesBinding(e, sc.quick_notes) && !isTyping) {
            e.preventDefault();
            if (typeof openQuickNotes === 'function') openQuickNotes();
            return;
        }
        // Esc — removed v12.7 (caused unintentional modal dismissals)
    });

    // ── DON'T-SPAWN-WHILE-TYPING ──
    // While the user is actively typing in a text field, hide the companion sprite to
    // prevent it from walking over what they're writing. Restore on blur (after a brief delay).
    let _typingHideTimer = null;
    function isTypingTarget(el) {
        if (!el) return false;
        const tag = (el.tagName || '').toLowerCase();
        return tag === 'input' || tag === 'textarea' || el.isContentEditable;
    }
    document.addEventListener('focusin', (e) => {
        if (!isTypingTarget(e.target)) return;
        // v10.7 — honor Settings → Companion → Hide while typing
        if ((localStorage.getItem('companion_hide_typing') || '1') !== '1') return;
        if (window._companionManuallyHidden) return;
        const layer = document.getElementById('companion-layer');
        if (layer) layer.style.opacity = '0.15';
    });
    document.addEventListener('focusout', (e) => {
        if (!isTypingTarget(e.target)) return;
        clearTimeout(_typingHideTimer);
        _typingHideTimer = setTimeout(() => {
            const layer = document.getElementById('companion-layer');
            if (layer && !window._companionManuallyHidden) layer.style.opacity = '1';
        }, 400);
    });
});

// ════════════════════════════════════════════════════════════════════
// READING COMPREHENSION SPRINT (v10.6 — replaces WPM Game)
// ════════════════════════════════════════════════════════════════════
let _sprintTimerInt = null;
let _sprintStartTime = 0;
let _sprintReadSeconds = 0;
let _sprintQuestions = [];
let _sprintAnswers = [];

const SPRINT_SAMPLES = {
    article: `The decline of pollinator populations has emerged as one of the most pressing ecological concerns of the 21st century. Bees, butterflies, beetles, and birds are responsible for the reproduction of nearly 90 percent of wild flowering plant species and roughly one-third of the food crops humans consume. When their numbers fall, the consequences ripple through ecosystems and economies alike.\n\nResearchers point to a convergence of pressures: industrial-scale monoculture farming reduces the variety of flowers available across the season, neonicotinoid pesticides impair bee navigation, and climate shifts disrupt the synchronized timing between blooms and the pollinators that depend on them. No single cause is sufficient on its own; it is the combination that drives the collapse.\n\nSolutions exist, but they require coordination at every level. Farmers can leave wildflower margins along their fields. Cities can plant native flora in unused medians. Regulators can restrict the most damaging pesticides. Most of all, individuals can choose to grow even a small patch of native flowers, contributing to a continent-wide network of refuges. The work is unglamorous, but it is precisely the kind of distributed effort the problem demands.`,
    science: `In a stable star, two opposing forces hold the entire structure in balance. Gravity continually pulls every particle of stellar matter toward the center, while the immense pressure produced by nuclear fusion in the core pushes outward. As long as fusion continues, the two forces remain in equilibrium, and the star maintains its size and luminosity.\n\nThe trouble begins when the core's hydrogen runs out. Without fusion to sustain outward pressure, gravity wins, and the core contracts. Compression heats the surrounding shell of hydrogen until it ignites, and the star expands enormously into a red giant. For stars about the mass of our Sun, this phase lasts roughly a billion years before the outer layers are shed as a planetary nebula and the core cools into a white dwarf.\n\nMassive stars take a different path. Their cores grow hot enough to fuse heavier and heavier elements — carbon, neon, oxygen, silicon — until iron accumulates. Iron fusion absorbs energy rather than releasing it, so the core collapses catastrophically in seconds, triggering a supernova that scatters newly forged elements across the galaxy. These elements eventually become the raw material of new stars, planets, and, in rare cases, life.`,
    history: `The Treaty of Westphalia, signed in 1648, ended the Thirty Years' War and is often credited with establishing the modern international system of sovereign states. Before Westphalia, European political authority was tangled — emperors, popes, princes, and free cities all claimed overlapping jurisdictions over the same territories and peoples. The treaty's central innovation was the principle of cuius regio, eius religio: the ruler of a territory determined its religion, and outside powers had no business interfering.\n\nThis principle had two consequences that still shape global politics today. First, it elevated the territorial state above competing institutions, giving rise to the idea of sovereignty as a recognized legal status rather than a contested claim. Second, it implied that states, regardless of their size or strength, were formal equals in their dealings with one another — at least in theory. The smallest German principality and the kingdom of France were now both sovereign signatories.\n\nHistorians continue to debate how clean this break really was. Many of Westphalia's supposed innovations developed only gradually, and great-power interference in weaker states' affairs hardly stopped in 1648. But as a symbolic anchor for the modern world order, the treaty endures: every UN charter and every nonintervention argument carries traces of the Westphalian settlement.`
};

function loadSprintSample(kind) {
    const ta = document.getElementById('sprint-passage');
    if (ta) ta.value = SPRINT_SAMPLES[kind] || SPRINT_SAMPLES.article;
}

// v10.7 — paste an image, OCR it, and dump the text into the Reading Sprint passage box
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        const ta = document.getElementById('sprint-passage');
        if (!ta || ta._sprintPasteWired) return;
        ta._sprintPasteWired = true;
        ta.addEventListener('paste', async (e) => {
            const items = (e.clipboardData || {}).items;
            if (!items) return;
            for (const item of items) {
                if (item.type && item.type.startsWith('image/')) {
                    e.preventDefault();
                    const file = item.getAsFile();
                    const reader = new FileReader();
                    reader.onload = async (ev) => {
                        showToast('Image pasted — running OCR…', 'info', 2500);
                        try {
                            await ensureTesseract();
                            const { data: { text } } = await Tesseract.recognize(ev.target.result, 'eng');
                            if (text && text.trim()) {
                                const trimmed = text.trim();
                                ta.value = ta.value ? (ta.value + '\n\n' + trimmed) : trimmed;
                                showToast('OCR done — passage filled in.', 'success');
                            } else {
                                showToast('OCR could not read any text from that image.', 'error');
                            }
                        } catch (err) {
                            showToast('OCR failed: ' + err.message, 'error');
                        }
                    };
                    reader.readAsDataURL(file);
                    return;
                }
            }
        });
    }, 800);
});

function startReadingSprint() {
    if (!hasPaid()) { openPaymentModal('access'); return; }
    const passage = (document.getElementById('sprint-passage').value || '').trim();
    if (passage.split(/\s+/).length < 30) {
        showToast('Paste a longer passage (at least 30 words).', 'warning');
        return;
    }
    document.getElementById('sprint-setup').classList.add('hidden');
    document.getElementById('sprint-result').classList.add('hidden');
    document.getElementById('sprint-quiz').classList.add('hidden');
    const reading = document.getElementById('sprint-reading');
    reading.classList.remove('hidden');
    document.getElementById('sprint-passage-display').textContent = passage;
    _sprintStartTime = Date.now();
    _sprintReadSeconds = 0;
    if (_sprintTimerInt) clearInterval(_sprintTimerInt);
    _sprintTimerInt = setInterval(() => {
        _sprintReadSeconds = (Date.now() - _sprintStartTime) / 1000;
        document.getElementById('sprint-timer').textContent = _sprintReadSeconds.toFixed(1) + 's';
    }, 100);
}

async function finishReadingSprint() {
    if (_sprintTimerInt) { clearInterval(_sprintTimerInt); _sprintTimerInt = null; }
    const passage = (document.getElementById('sprint-passage').value || '').trim();
    const difficulty = document.getElementById('sprint-difficulty').value;
    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add an API key in Settings first.', 'error'); return; }

    document.getElementById('sprint-reading').classList.add('hidden');
    const quiz = document.getElementById('sprint-quiz');
    quiz.classList.remove('hidden');
    document.getElementById('sprint-quiz-content').innerHTML = '<div style="text-align:center;padding:40px;color:var(--text-muted);"><i class="ph ph-spinner ph-spin" style="font-size:1.6rem;"></i><p>Generating 5 comprehension questions...</p></div>';

    const sys = `You are a reading comprehension test generator. Given a passage, output STRICT JSON with exactly 5 multiple-choice questions. Difficulty: ${difficulty}.
- easy: simple recall ("According to the passage...")
- normal: 3 recall + 2 inference
- hard: all inference / analysis (author intent, implied conclusions, vocabulary in context)
JSON shape: {"questions":[{"q":"...","choices":["A","B","C","D"],"correctIndex":0,"why":"brief"}, ...5 total]}
Each question must be answerable from the passage alone. Distractors must be plausible. Never include the answer letter in the question.`;

    try {
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o-mini',
                response_format: { type: 'json_object' },
                messages: [
                    { role: 'system', content: sys },
                    { role: 'user', content: 'PASSAGE:\n\n' + passage }
                ],
                temperature: 0.4
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message);
        const parsed = JSON.parse(data.choices[0].message.content);
        _sprintQuestions = parsed.questions || [];
        _sprintAnswers = new Array(_sprintQuestions.length).fill(null);
        renderSprintQuiz();
    } catch (err) {
        document.getElementById('sprint-quiz-content').innerHTML = `<p style="color:#ff6b6b;">Failed to generate quiz: ${err.message}</p>`;
    }
}

function renderSprintQuiz() {
    const c = document.getElementById('sprint-quiz-content');
    c.innerHTML = _sprintQuestions.map((q, qi) => `
        <div class="glass-panel" style="padding:18px;margin-bottom:12px;">
            <div style="font-size:0.88rem;color:#a29bfe;font-weight:700;letter-spacing:1px;margin-bottom:6px;">QUESTION ${qi + 1} OF ${_sprintQuestions.length}</div>
            <p style="color:white;font-size:1rem;margin:0 0 12px;line-height:1.5;font-weight:600;">${q.q}</p>
            <div style="display:grid;gap:12px;">
                ${q.choices.map((ch, ci) => `
                    <label style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:rgba(255,255,255,0.04);border:1px solid var(--glass-border);border-radius:8px;cursor:pointer;color:white;">
                        <input type="radio" name="sprint-q-${qi}" value="${ci}" onchange="_sprintAnswers[${qi}]=${ci}" style="accent-color:var(--accent);">
                        <span>${String.fromCharCode(65 + ci)}. ${ch}</span>
                    </label>
                `).join('')}
            </div>
        </div>
    `).join('') + `
        <button class="btn-primary" style="width:100%;padding:14px;font-size:1rem;" onclick="submitSprintAnswers()">
            <i class="ph ph-check-circle"></i> Submit Answers
        </button>`;
}

function submitSprintAnswers() {
    if (_sprintAnswers.includes(null)) {
        showToast('Answer all questions first.', 'warning');
        return;
    }
    let correct = 0;
    _sprintAnswers.forEach((a, i) => { if (a === _sprintQuestions[i].correctIndex) correct++; });
    const accuracy = correct / _sprintQuestions.length;
    const wordCount = document.getElementById('sprint-passage').value.trim().split(/\s+/).length;
    // Speed bonus: 250 wpm = baseline 1.0x; faster = bonus, slower = penalty
    const wpm = (wordCount / Math.max(1, _sprintReadSeconds)) * 60;
    const speedFactor = Math.min(1.6, Math.max(0.4, wpm / 250));
    const score = Math.round(100 * accuracy * speedFactor);
    const credits = Math.max(5, Math.round(score * 0.4));

    document.getElementById('sprint-quiz').classList.add('hidden');
    const result = document.getElementById('sprint-result');
    result.classList.remove('hidden');
    document.getElementById('sprint-final-score').textContent = score;
    document.getElementById('sprint-final-breakdown').innerHTML =
        `${correct}/${_sprintQuestions.length} correct &middot; ${Math.round(wpm)} wpm reading speed &middot; ${(accuracy * 100).toFixed(0)}% accuracy`;
    document.getElementById('sprint-credits-earned').innerHTML = `<i class="ph ph-coin"></i> +${credits} credits earned`;

    if (typeof updateCredits === 'function') updateCredits(credits);
    if (typeof recordQuestProgress === 'function') recordQuestProgress('essay_scored'); // counts as written-comprehension activity
    if (typeof addToHistory === 'function') addToHistory('english', 'Reading Sprint', `Scored ${score} (${correct}/${_sprintQuestions.length} correct, ${Math.round(wpm)} wpm).`);
}

function resetReadingSprint() {
    document.getElementById('sprint-result').classList.add('hidden');
    document.getElementById('sprint-quiz').classList.add('hidden');
    document.getElementById('sprint-reading').classList.add('hidden');
    document.getElementById('sprint-setup').classList.remove('hidden');
}

