let _selectedDictLetter = 'A';

function openDictionaryBrowse() {
    const m = document.getElementById('dict-browse-modal');
    if (!m) return;
    m.classList.remove('hidden');
    m.style.display = 'flex';
    renderDictionaryBrowse();
}
function closeDictionaryBrowse() {
    const m = document.getElementById('dict-browse-modal');
    if (!m) return;
    m.classList.add('hidden');
    m.style.display = 'none';
}
function renderDictionaryBrowse() {
    const lettersEl = document.getElementById('dict-browse-letters');
    const wordsEl = document.getElementById('dict-browse-words');
    if (!lettersEl || !wordsEl) return;
    const letters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'.split('');
    lettersEl.innerHTML = letters.map(L => `
        <button onclick="selectDictLetter('${L}')"
            style="padding:8px 0;background:${L === _selectedDictLetter ? 'linear-gradient(135deg,#6C5CE7,#00CEC9)' : 'rgba(255,255,255,0.05)'};
                   color:white;border:1px solid ${L === _selectedDictLetter ? 'transparent' : 'var(--glass-border)'};
                   border-radius:6px;cursor:pointer;font-weight:700;font-size:0.85rem;">${L}</button>
    `).join('');
    const words = DICT_BROWSE_WORDS[_selectedDictLetter] || [];
    if (!words.length) {
        wordsEl.innerHTML = `<p style="color:var(--text-muted);">No words listed for "${_selectedDictLetter}".</p>`;
        return;
    }
    wordsEl.innerHTML = `
        <h3 style="color:var(--accent);margin:0 0 10px;font-size:1rem;letter-spacing:1.2px;text-transform:uppercase;">${_selectedDictLetter} — ${words.length} words</h3>
        <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:12px;">
            ${words.map(w => `
                <button onclick="lookupBrowseWord('${w}')"
                    style="padding:8px 10px;background:rgba(108,92,231,0.08);border:1px solid rgba(108,92,231,0.25);
                           border-radius:6px;color:white;cursor:pointer;text-align:left;font-size:0.88rem;transition:all 0.15s;"
                    onmouseover="this.style.background='rgba(108,92,231,0.18)'"
                    onmouseout="this.style.background='rgba(108,92,231,0.08)'">${w}</button>
            `).join('')}
        </div>`;
}
function selectDictLetter(L) {
    _selectedDictLetter = L;
    renderDictionaryBrowse();
}
function lookupBrowseWord(word) {
    const input = document.getElementById('dict-word-input');
    if (input) input.value = word;
    closeDictionaryBrowse();
    if (typeof lookupWord === 'function') lookupWord();
}

