// v10.7 — Enter-to-submit / Shift+Enter-newline binding for chat-style textareas
function bindEnterSubmit(elementId, submitFn) {
    const el = document.getElementById(elementId);
    if (!el || el._enterSubmitWired) return;
    el._enterSubmitWired = true;
    el.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) {
            e.preventDefault();
            try { submitFn(); } catch (_) {}
        }
    });
}

// ── Hook common events into quest progress ──
document.addEventListener('DOMContentLoaded', () => {
    // v10.6 — apply accessibility settings on every app load
    if (typeof applyAccessibilitySettings === 'function') applyAccessibilitySettings();
    // v10.6 — grant classic common-tier items immediately on load
    if (typeof grantCommonClassics === 'function') grantCommonClassics();
    // v10.7 — wire Enter-submit on long-form textareas
    setTimeout(() => {
        bindEnterSubmit('math-text-input',     () => typeof processMathInput === 'function' && processMathInput());
        bindEnterSubmit('science-input',       () => typeof processScienceInput === 'function' && processScienceInput());
        bindEnterSubmit('english-prompt-input',() => typeof processEnglishPrompt === 'function' && processEnglishPrompt());
        bindEnterSubmit('eng-gen-prompt-input', () => typeof generateEnglishGenPrompt === 'function' && generateEnglishGenPrompt());
    }, 600);
    // v10.6 — default subject on launch
    const defaultSub = localStorage.getItem('default_subject');
    if (defaultSub && defaultSub !== 'dashboard' && typeof switchTab === 'function') {
        setTimeout(() => { try { switchTab(defaultSub); } catch (_) {} }, 600);
    }
    // App-open ping (lazy: also fired by openQuestsModal)
    setTimeout(() => recordQuestProgress('app_open'), 1500);

    // Wrap updateStudyStats to capture problem_solved
    if (typeof window.updateStudyStats === 'function') {
        const orig = window.updateStudyStats;
        window.updateStudyStats = function(type, ...rest) {
            const r = orig.apply(this, [type, ...rest]);
            if (type === 'problem_solved') recordQuestProgress('problem_solved');
            return r;
        };
    }

    // v10.6: history_added — fire whenever addToHistory runs
    if (typeof window.addToHistory === 'function') {
        const orig = window.addToHistory;
        window.addToHistory = function(type, q, a, img) {
            const r = orig.call(this, type, q, a, img);
            recordQuestProgress('history_added');
            if (type === 'vision') recordQuestProgress('vision_used');
            // subject_used — track unique subjects per day
            if (['math','science','english','social-studies','social','code'].includes(type)) {
                try {
                    const today = new Date().toISOString().slice(0,10);
                    const key = 'subjects_used_' + today;
                    const used = JSON.parse(localStorage.getItem(key) || '[]');
                    if (!used.includes(type)) {
                        used.push(type);
                        localStorage.setItem(key, JSON.stringify(used));
                        recordQuestProgress('subject_used');
                    }
                } catch (_) {}
            }
            return r;
        };
    }

    // v10.6: dict_lookup
    if (typeof window.lookupWord === 'function') {
        const orig = window.lookupWord;
        window.lookupWord = function(...args) {
            const r = orig.apply(this, args);
            recordQuestProgress('dict_lookup');
            return r;
        };
    }

    // ── v12.4: study streak + auto day/night + companion mood + sfx ──
    updateStudyStreak();
    applyAutoDayNightTheme();
    // Reload sfx settings from storage
    const sfxVol = parseFloat(localStorage.getItem('sfx_volume') ?? '0.5');
    if (sfxVol === 0) localStorage.setItem('sfx_enabled', '0');
    // Show Pomodoro bar if timer was running (companion-chat is closed on load, so it'll show in float widget instead)
    // (handled by the separate DOMContentLoaded at line ~9410)

    // v15.5 — REMOVED the v14.0 "scroll wheel cycles nav tabs" handler. It
    // preventDefault()ed every wheel notch and switched tabs (resetting scroll
    // to the top), which hijacked normal scrolling — the wheel appeared dead and
    // only click-and-drag worked. Scrolling is now native (main content + nav).
});

