// ════════════════════════════════════════════════════════════════════
// v12.4 — SOUND EFFECTS SYSTEM
// ════════════════════════════════════════════════════════════════════
function applySfxSettings() {
    // Reads setting-sfx-enabled and setting-sfx-volume, stores to localStorage
    const enabled = document.getElementById('setting-sfx-enabled')?.checked ?? true;
    const vol = document.getElementById('setting-sfx-volume')?.value ?? '50';
    localStorage.setItem('sfx_enabled', enabled ? '1' : '0');
    localStorage.setItem('sfx_volume', (parseFloat(vol) / 100).toFixed(2));
}

// Shared AudioContext — reused across calls to avoid the overhead of new AudioContext() per tab switch
let _sfxAudioCtx = null;
function _getSfxCtx() {
    if (!_sfxAudioCtx || _sfxAudioCtx.state === 'closed') {
        _sfxAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (_sfxAudioCtx.state === 'suspended') _sfxAudioCtx.resume();
    return _sfxAudioCtx;
}

function playSfx(type) {
    // v12.7: default sfx_enabled to '1' so new installs have sound on
    if (localStorage.getItem('sfx_enabled') === '0') return;
    const vol = parseFloat(localStorage.getItem('sfx_volume') ?? '0.35');
    if (vol === 0) return;
    try {
        const ctx = _getSfxCtx();
        const gain = ctx.createGain();
        gain.connect(ctx.destination);

        const playNote = (freq, startT, dur, waveType = 'sine', gainMult = 1) => {
            const osc = ctx.createOscillator();
            osc.type = waveType;
            osc.connect(gain);
            osc.frequency.setValueAtTime(freq, startT);
            gain.gain.setValueAtTime(vol * gainMult * 0.45, startT);
            gain.gain.exponentialRampToValueAtTime(0.0001, startT + dur);
            osc.start(startT); osc.stop(startT + dur + 0.01);
        };

        const t = ctx.currentTime;
        if (type === 'click') {
            playNote(1200, t, 0.04, 'sine', 0.4);
        } else if (type === 'success') {
            // Two-note chime: E5 → G5
            playNote(659, t,       0.14, 'sine', 0.6);
            playNote(784, t+0.10,  0.18, 'sine', 0.5);
        } else if (type === 'error') {
            playNote(300, t,      0.12, 'sawtooth', 0.5);
            playNote(220, t+0.09, 0.14, 'sawtooth', 0.4);
        } else if (type === 'levelup') {
            // Four-note rising fanfare
            [523, 659, 784, 1047].forEach((f, i) => playNote(f, t + i * 0.09, 0.16, 'triangle', 0.6));
        } else if (type === 'tab') {
            playNote(880, t, 0.05, 'sine', 0.25);
        }
    } catch (_) {}
}

function playTestBeep() { _pomodoroBeep(); }

// ════════════════════════════════════════════════════════════════════
// v12.4 — AUTO DAY/NIGHT THEME
// Switches to light theme at sunrise (6 AM) and dark theme at sunset (8 PM)
// based purely on local clock time. Checks every 5 minutes.
// ════════════════════════════════════════════════════════════════════
let _autoDayNightInterval = null;

function applyAutoDayNightTheme() {
    const enabled = document.getElementById('setting-auto-daynight')?.checked
                 ?? (localStorage.getItem('auto_daynight') === '1');
    if (!enabled) {
        if (_autoDayNightInterval) { clearInterval(_autoDayNightInterval); _autoDayNightInterval = null; }
        return;
    }
    _doAutoDayNight();
    if (!_autoDayNightInterval) {
        _autoDayNightInterval = setInterval(_doAutoDayNight, 5 * 60 * 1000);
    }
}

function _doAutoDayNight() {
    const h = new Date().getHours();
    const isDay = (h >= 6 && h < 20); // 6 AM – 8 PM = day
    const currentlyLight = localStorage.getItem('nexus_theme') === 'light';
    if (isDay && !currentlyLight) {
        if (typeof toggleLightTheme === 'function') toggleLightTheme(true);
    } else if (!isDay && currentlyLight) {
        if (typeof toggleLightTheme === 'function') toggleLightTheme(false);
    }
}

// ════════════════════════════════════════════════════════════════════
// v12.4 — COMPANION MOOD SYSTEM
// The companion's emote pool shifts based on sessions completed today.
// 0 sessions = sleepy/chill; 1-2 = normal; 3-4 = focused; 5+ = hyped.
// Applied in getCompanionMoodEmotes() — called by scheduleCompanionEmote.
// ════════════════════════════════════════════════════════════════════
function getSessionsToday() {
    try {
        const today = new Date().toISOString().slice(0, 10);
        const hist = JSON.parse(localStorage.getItem('user_history') || '[]');
        return hist.filter(h => (h.timestamp || '').startsWith(today)).length;
    } catch { return 0; }
}

function getCompanionMoodEmotes() {
    const moodEnabled = localStorage.getItem('companion_mood') !== '0';
    if (!moodEnabled) return null; // null = use default emote pool
    const n = getSessionsToday();
    if (n === 0) return ['😴 Waiting for you…', '☁️ All quiet…', '💤 Ready when you are', 'yawns softly'];
    if (n <= 2)  return ['📚 Keep it up!', '✨ Nice work today', '🌟 You\'re doing great!', '😊 Let\'s learn something'];
    if (n <= 4)  return ['🔥 On a roll!', '⚡ Locked in!', '🚀 Keep the streak going', '💡 You\'re focused!'];
    return ['🏆 UNSTOPPABLE!', '🎯 5+ sessions? Legend!', '🔥🔥 You\'re on fire!', '💪 Max study mode!'];
}

// ════════════════════════════════════════════════════════════════════
// v12.4 — STUDY STREAK TRACKER
// Piggybacks on the existing getStudyStats() streak system.
// Called on app load — shows milestone toasts for key streak days.
// ════════════════════════════════════════════════════════════════════
function updateStudyStreak() {
    const stats = getStudyStats(); // already handles streak increment logic
    const streak = stats.currentStreak || 0;

    // Stat card on Command Center
    const el = document.getElementById('stat-current-streak');
    if (el) el.textContent = streak;

    // Milestone toasts — only show once per day per milestone
    const today = new Date().toISOString().slice(0, 10);
    const lastMilestoneDate = localStorage.getItem('streak_milestone_toast_date');
    if (lastMilestoneDate !== today && [3, 7, 14, 30, 60, 100].includes(streak)) {
        localStorage.setItem('streak_milestone_toast_date', today);
        setTimeout(() => showToast(`🔥 ${streak}-day study streak! Keep it up!`, 'success', 5000), 1500);
    }
    return streak;
}

function getStudyStreak() {
    return getStudyStats().currentStreak || 0;
}

