// v12.4 — QUICK NOTES FLOATING WIDGET
// A sticky-note overlay that floats above all tabs. Auto-saves content
// to the Notebook tab so notes persist in the right place.
// ════════════════════════════════════════════════════════════════════
let _quickNotesOpen = false;

function openQuickNotes() {
    if (_quickNotesOpen) { closeQuickNotes(); return; }
    _quickNotesOpen = true;
    let panel = document.getElementById('quick-notes-widget');
    if (!panel) {
        panel = document.createElement('div');
        panel.id = 'quick-notes-widget';
        panel.style.cssText = `
            position:fixed;bottom:88px;right:24px;width:300px;z-index:9450;
            background:rgba(10,10,20,0.97);border:1px solid rgba(255,195,18,0.45);
            border-radius:14px;box-shadow:0 12px 40px rgba(0,0,0,0.6),0 0 20px rgba(255,195,18,0.12);
            backdrop-filter:blur(14px);font-family:inherit;display:flex;flex-direction:column;
        `;
        panel.innerHTML = `
            <div style="display:flex;justify-content:space-between;align-items:center;padding:10px 14px;border-bottom:1px solid rgba(255,255,255,0.08);">
                <span style="color:#ffc312;font-weight:700;font-size:0.85rem;"><i class="ph ph-note-pencil"></i> Quick Note</span>
                <div style="display:flex;gap:9px;">
                    <button onclick="saveQuickNoteToNotebook()" title="Save to Notebook" style="background:rgba(0,184,148,0.15);border:1px solid rgba(0,184,148,0.3);border-radius:6px;color:#00b894;cursor:pointer;padding:4px 8px;font-size:0.85rem;"><i class="ph ph-floppy-disk"></i> Save</button>
                    <button onclick="closeQuickNotes()" style="background:transparent;border:none;color:var(--text-muted);cursor:pointer;font-size:1rem;padding:4px;"><i class="ph ph-x"></i></button>
                </div>
            </div>
            <textarea id="quick-notes-textarea" placeholder="Jot anything down… auto-saves to Notebook."
                style="flex:1;min-height:160px;padding:12px;background:transparent;border:none;color:white;font-size:0.88rem;resize:none;outline:none;font-family:inherit;line-height:1.6;"></textarea>
            <div style="padding:6px 14px 8px;font-size:0.9rem;color:var(--text-muted);border-top:1px solid rgba(255,255,255,0.05);">Auto-saves to Notebook on close</div>
        `;
        document.body.appendChild(panel);
        // Load any draft
        const draft = localStorage.getItem('quick_note_draft') || '';
        document.getElementById('quick-notes-textarea').value = draft;
    }
    panel.style.display = 'flex';
}

function closeQuickNotes() {
    _quickNotesOpen = false;
    const panel = document.getElementById('quick-notes-widget');
    if (!panel) return;
    // Auto-save to notebook
    saveQuickNoteToNotebook(true);
    panel.style.display = 'none';
}

function saveQuickNoteToNotebook(silent) {
    const ta = document.getElementById('quick-notes-textarea');
    if (!ta) return;
    const text = (ta.value || '').trim();
    if (!text) return;
    // Save draft
    localStorage.setItem('quick_note_draft', ta.value);
    // Append to Notebook
    try {
        const notes = JSON.parse(localStorage.getItem('notebook_notes') || '[]');
        const ts = new Date().toLocaleString();
        notes.unshift({ id: Date.now(), title: 'Quick Note — ' + ts, content: text, createdAt: Date.now() });
        localStorage.setItem('notebook_notes', JSON.stringify(notes));
        if (!silent) {
            ta.value = '';
            localStorage.removeItem('quick_note_draft');
            showToast('Note saved to Notebook!', 'success');
        }
    } catch (e) {
        if (!silent) showToast('Could not save note: ' + e.message, 'error');
    }
}

