// v12.4 — Wire new settings into loadExpandedSettings + saveSettings patch
// ════════════════════════════════════════════════════════════════════
(function _patchSettingsSave() {
    const origSave = window.saveSettings;
    if (origSave) {
        window.saveSettings = function() {
            // Save new v12.4 settings before calling original save
            const sset = (id, key) => {
                const el = document.getElementById(id);
                if (!el) return;
                const v = el.type === 'checkbox' ? (el.checked ? '1' : '0') : el.value;
                localStorage.setItem(key, v);
            };
            sset('setting-sfx-enabled', 'sfx_enabled');
            sset('setting-sfx-volume', 'sfx_volume_pct');
            const sfxVol = parseFloat(document.getElementById('setting-sfx-volume')?.value || '50') / 100;
            localStorage.setItem('sfx_volume', sfxVol.toFixed(2));
            sset('setting-auto-daynight', 'auto_daynight');
            sset('setting-companion-mood', 'companion_mood');
            applyAutoDayNightTheme();
            origSave.call(window);
        };
    }
})();

(function _patchSettingsLoad() {
    const origLoad = window.loadExpandedSettings;
    if (origLoad) {
        window.loadExpandedSettings = function() {
            origLoad.call(window);
            // Load new v12.4 settings
            const lget = (id, key, defVal) => {
                const el = document.getElementById(id);
                if (!el) return;
                const v = localStorage.getItem(key);
                const val = v !== null ? v : (defVal !== undefined ? String(defVal) : null);
                if (val === null) return;
                if (el.type === 'checkbox') el.checked = (val === '1' || val === 'true');
                else el.value = val;
            };
            lget('setting-sfx-enabled', 'sfx_enabled', true);
            const sfxPct = Math.round(parseFloat(localStorage.getItem('sfx_volume') ?? '0.5') * 100);
            const sfxRange = document.getElementById('setting-sfx-volume');
            if (sfxRange) { sfxRange.value = sfxPct; document.getElementById('setting-sfx-volume-display').textContent = sfxPct + '%'; }
            lget('setting-auto-daynight', 'auto_daynight', false);
            lget('setting-companion-mood', 'companion_mood', true);
        };
    }
})();

// ════════════════════════════════════════════════════════════════════
// v12.5 — LOADING SCREEN
// ════════════════════════════════════════════════════════════════════
(function _initLoadingScreen() {
    const screen = document.getElementById('nexus-loading-screen');
    const bar = document.getElementById('nexus-load-bar');
    if (!screen) return;
    let pct = 0;
    const tick = setInterval(() => {
        pct = Math.min(pct + (Math.random() * 18 + 8), 88);
        if (bar) bar.style.width = pct + '%';
    }, 120);
    function hide() {
        clearInterval(tick);
        if (bar) bar.style.width = '100%';
        setTimeout(() => {
            screen.style.opacity = '0';
            screen.style.visibility = 'hidden';
            setTimeout(() => screen.remove(), 700);
        }, 280);
    }
    if (document.readyState === 'complete') { setTimeout(hide, 400); }
    else { window.addEventListener('load', () => setTimeout(hide, 400), { once: true }); }
    setTimeout(hide, 3500); // hard fallback
})();

