// v15.0 — AMBIENT SOUNDS (YouTube IFrame API)
// ════════════════════════════════════════════════════════════════════
let _ambientCtx = null;          // kept for legacy Web Audio refs
const _ambientNodes = {};        // legacy Web Audio node cleanup
const _ambientGains = {};        // playing-state tracker (holds YT player or null)

// YouTube video IDs — 10-hour loops, no music, pure ambient
const _YT_VIDEOS = {
    thunder:    'nDq6TstdEi8',   // EPIC THUNDER & RAIN | 10 Hours
    cafe:       'h2zkV-l_TbY',   // RESTAURANT AMBIENCE • 10H Busy Coffee Shop
    whitenoise: 'nMfPqeZjc2c',   // White Noise Black Screen | 10 Hours
    fire:       'EiwLa7pGy5Q',   // 10 Hours 4K Fireplace Cozy Crackling
    stream:     'jSG4HX2j7Ao',   // River Sounds for Studying/Relaxation | 10 Hours
};
const _ytPlayers  = {};          // id → YT.Player instance
let   _ytApiReady = false;
const _ytQueue    = [];          // { id, vol } pairs waiting for API / player ready

function _ensureYouTubeAPI() {
    if (document.querySelector('script[src*="youtube.com/iframe_api"]')) return;
    const tag = document.createElement('script');
    tag.src = 'https://www.youtube.com/iframe_api';
    document.head.appendChild(tag);
}

window.onYouTubeIframeAPIReady = function() {
    _ytApiReady = true;
    // Build a hidden container for the 6 iframes (1×1px, off-screen)
    if (!document.getElementById('yt-ambient-wrap')) {
        const wrap = document.createElement('div');
        wrap.id = 'yt-ambient-wrap';
        wrap.style.cssText = 'position:fixed;top:-2px;left:-2px;width:1px;height:1px;opacity:0;pointer-events:none;overflow:hidden;z-index:-9999;';
        Object.keys(_YT_VIDEOS).forEach(function(id) {
            const d = document.createElement('div'); d.id = 'yt-p-' + id;
            wrap.appendChild(d);
        });
        document.body.appendChild(wrap);
    }
    // Create each player
    Object.entries(_YT_VIDEOS).forEach(function([id, videoId]) {
        _ytPlayers[id] = new YT.Player('yt-p-' + id, {
            videoId: videoId,
            playerVars: {
                autoplay: 0, controls: 0, loop: 1, playlist: videoId,
                modestbranding: 1, rel: 0, iv_load_policy: 3, disablekb: 1,
            },
            events: {
                onReady: function(e) {
                    e.target.setVolume(0);
                    // Drain any queued plays for this sound
                    for (let i = _ytQueue.length - 1; i >= 0; i--) {
                        if (_ytQueue[i].id === id) {
                            const q = _ytQueue.splice(i, 1)[0];
                            _startAmbientSound(q.id, q.vol);
                        }
                    }
                }
            }
        });
    });
};

const AMBIENT_SOUNDS = [
    { id: 'thunder',    label: 'Storm',        icon: 'ph-cloud-lightning', color: '#a29bfe',
      desc: 'Distant thunder & rain' },
    { id: 'cafe',       label: 'Café',         icon: 'ph-coffee',       color: '#fab1a0',
      desc: 'Ambient coffee-shop chatter' },
    { id: 'whitenoise', label: 'White Noise',  icon: 'ph-waves',        color: '#dfe6e9',
      desc: 'Pure, steady background hiss' },
    { id: 'fire',       label: 'Fireplace',    icon: 'ph-fire',         color: '#e17055',
      desc: 'Crackling fire ambience' },
    { id: 'stream',     label: 'Stream',       icon: 'ph-drop',         color: '#74b9ff',
      desc: 'Flowing river & brook' }
];

function _getAmbientCtx() {
    if (!_ambientCtx || _ambientCtx.state === 'closed') {
        _ambientCtx = new (window.AudioContext || window.webkitAudioContext)();
    }
    if (_ambientCtx.state === 'suspended') _ambientCtx.resume();
    return _ambientCtx;
}

function _makeNoise(ctx, type = 'white') {
    const bufSize = ctx.sampleRate * 2;
    const buf = ctx.createBuffer(1, bufSize, ctx.sampleRate);
    const data = buf.getChannelData(0);
    let b0=0,b1=0,b2=0,b3=0,b4=0,b5=0,b6=0;
    for (let i = 0; i < bufSize; i++) {
        const wh = Math.random() * 2 - 1;
        if (type === 'pink') {
            b0=0.99886*b0+wh*0.0555179; b1=0.99332*b1+wh*0.0750759;
            b2=0.96900*b2+wh*0.1538520; b3=0.86650*b3+wh*0.3104856;
            b4=0.55000*b4+wh*0.5329522; b5=-0.7616*b5-wh*0.0168980;
            data[i] = (b0+b1+b2+b3+b4+b5+b6+wh*0.5362) * 0.11;
            b6 = wh * 0.115926;
        } else if (type === 'brown') {
            b0 = (b0 + 0.02 * wh) / 1.02;
            data[i] = b0 * 3.5;
        } else { data[i] = wh; }
    }
    const src = ctx.createBufferSource();
    src.buffer = buf; src.loop = true;
    return src;
}

// ── Pre-rendered ambient buffers ─────────────────────────────────────────────
// Simulate discrete physical events (drops, crackles, pops) into a looping
// buffer at startup.  Far more realistic than continuous filtered noise.

function _makeRainBuffer(ctx, dropsPerSec) {
    // Each drop = sharp white-noise impact (2 ms) + decaying glass ring (sine)
    const dur = 9, sr = ctx.sampleRate;
    const len = Math.ceil(sr * dur);
    const buf = ctx.createBuffer(1, len, sr);
    const data = buf.getChannelData(0);
    let t = 0.05;
    while (t < dur) {
        t += -Math.log(1 - Math.random()) / dropsPerSec; // Poisson inter-arrival
        if (t >= dur) break;
        const si0    = Math.floor(t * sr);
        const vol    = 0.22 + Math.random() * 0.55;
        const freq   = 1400 + Math.random() * 1900;  // 1.4–3.3 kHz glass ring
        const decay  = 16   + Math.random() * 22;    // ring decay rate (higher = shorter)
        const impLen = Math.ceil(sr * 0.0022);        // ~2 ms noise tap
        const rngLen = Math.ceil(sr * 0.10);          // up to 100 ms ring
        // Impact transient
        for (let i = 0; i < impLen; i++) {
            const si = si0 + i; if (si >= len) break;
            data[si] += (Math.random() * 2 - 1) * vol * Math.pow(1 - i / impLen, 2.5);
        }
        // Glass resonance ring
        for (let i = 0; i < rngLen; i++) {
            const si = si0 + impLen + i; if (si >= len) break;
            const env = Math.exp(-decay * i / sr); if (env < 0.001) break;
            data[si] += Math.sin(2 * Math.PI * freq * i / sr) * vol * 0.42 * env;
        }
    }
    // Normalize so we don't clip
    let peak = 0;
    for (let i = 0; i < len; i++) if (Math.abs(data[i]) > peak) peak = Math.abs(data[i]);
    if (peak > 0.88) { const s = 0.88 / peak; for (let i = 0; i < len; i++) data[i] *= s; }
    const src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
    return src;
}

function _makeFireBuffer(ctx) {
    // Each crackle = short high-freq noise burst; density varies to simulate wood
    const dur = 9, sr = ctx.sampleRate;
    const len = Math.ceil(sr * dur);
    const buf = ctx.createBuffer(1, len, sr);
    const data = buf.getChannelData(0);
    // Layer 1: frequent small snaps (~10/sec)
    let t = 0.1;
    while (t < dur) {
        t += -Math.log(1 - Math.random()) / 10;
        if (t >= dur) break;
        const si0 = Math.floor(t * sr);
        const vol = 0.3 + Math.random() * 0.55;
        const cLen = Math.ceil(sr * (0.003 + Math.random() * 0.010));
        for (let i = 0; i < cLen; i++) {
            const si = si0 + i; if (si >= len) break;
            data[si] += (Math.random() * 2 - 1) * vol * Math.exp(-i / (cLen * 0.35));
        }
    }
    // Layer 2: bigger pops (~2/sec)
    t = 0.5;
    while (t < dur) {
        t += -Math.log(1 - Math.random()) / 2.2;
        if (t >= dur) break;
        const si0 = Math.floor(t * sr);
        const vol = 0.55 + Math.random() * 0.45;
        const cLen = Math.ceil(sr * (0.008 + Math.random() * 0.018));
        for (let i = 0; i < cLen; i++) {
            const si = si0 + i; if (si >= len) break;
            data[si] += (Math.random() * 2 - 1) * vol * Math.exp(-i / (cLen * 0.28));
        }
        // Occasional second pop 40–90 ms later
        if (Math.random() < 0.25) {
            const si2 = si0 + Math.ceil(sr * (0.04 + Math.random() * 0.05));
            const cl2 = Math.ceil(sr * 0.006);
            for (let i = 0; i < cl2; i++) {
                const si = si2 + i; if (si >= len) break;
                data[si] += (Math.random() * 2 - 1) * vol * 0.5 * Math.exp(-i / (cl2 * 0.35));
            }
        }
    }
    // Normalize
    let peak = 0;
    for (let i = 0; i < len; i++) if (Math.abs(data[i]) > peak) peak = Math.abs(data[i]);
    if (peak > 0.90) { const s = 0.90 / peak; for (let i = 0; i < len; i++) data[i] *= s; }
    const src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
    return src;
}

function _makeCafeChatterBuffer(ctx) {
    // Voice-frequency noise bursts at random timings — crowd murmur texture
    const dur = 10, sr = ctx.sampleRate;
    const len = Math.ceil(sr * dur);
    const buf = ctx.createBuffer(1, len, sr);
    const data = buf.getChannelData(0);
    // Simulate overlapping "word" bursts: 200–500 ms each, voice frequencies
    const voiceFreqs = [260, 330, 420, 550, 720, 950, 1200, 1600];
    for (let v = 0; v < 12; v++) {  // ~12 simultaneous talkers
        let t = Math.random() * 2;  // stagger start
        while (t < dur) {
            t += 0.08 + Math.random() * 0.55;  // syllable / word gaps
            if (t >= dur) break;
            const burstDur  = 0.12 + Math.random() * 0.38;  // 120–500 ms syllable
            const si0       = Math.floor(t * sr);
            const burstLen  = Math.ceil(sr * burstDur);
            const f         = voiceFreqs[Math.floor(Math.random() * voiceFreqs.length)];
            const bw        = 80 + Math.random() * 200;  // bandpass width
            const vol       = 0.04 + Math.random() * 0.08;
            // Pink-ish noise band-limited to voice freq (simple sin modulation trick)
            for (let i = 0; i < burstLen; i++) {
                const si = si0 + i; if (si >= len) break;
                const trel = i / burstLen;
                // Smooth onset / offset envelope
                const env = Math.sin(Math.PI * trel);
                // Noise sample (white noise × sine carrier gives rough bandpass)
                const noise = (Math.random() * 2 - 1);
                const carrier = Math.sin(2 * Math.PI * f * i / sr);
                const upper   = Math.sin(2 * Math.PI * (f + bw) * i / sr);
                data[si] += (noise * 0.4 + carrier * 0.35 + upper * 0.25) * vol * env;
            }
        }
    }
    // Normalize
    let peak = 0;
    for (let i = 0; i < len; i++) if (Math.abs(data[i]) > peak) peak = Math.abs(data[i]);
    if (peak > 0.85) { const s = 0.85 / peak; for (let i = 0; i < len; i++) data[i] *= s; }
    const src = ctx.createBufferSource(); src.buffer = buf; src.loop = true;
    return src;
}

function _startAmbientSound(id, vol = 0.5) {
    // ── v15.0: YouTube-backed ambient sounds ──
    _ensureYouTubeAPI();

    const player = _ytPlayers[id];
    if (!player || typeof player.playVideo !== 'function') {
        // API or player not ready yet — queue for when onReady fires
        if (!_ytQueue.find(function(q) { return q.id === id; })) {
            _ytQueue.push({ id: id, vol: vol });
        }
        return;
    }

    // Stop any existing playback cleanly first
    if (_ambientGains[id]) {
        const old = _ambientGains[id];
        if (old && typeof old.pauseVideo === 'function') {
            try { old.setVolume(0); old.pauseVideo(); } catch(e) {}
        }
        delete _ambientGains[id];
    }
    const legacyNodes = _ambientNodes[id];
    if (legacyNodes) {
        legacyNodes.forEach(function(n) { try { n.stop(); } catch(e) {} });
        delete _ambientNodes[id];
    }

    // Begin playback with fade-in
    _ambientGains[id] = player;
    try {
        player.setVolume(0);
        player.unMute();
        player.playVideo();
    } catch(e) {}

    const target = Math.round(vol * 100);
    let cur = 0;
    const fade = setInterval(function() {
        cur = Math.min(cur + 4, target);
        try { player.setVolume(cur); } catch(e) {}
        if (cur >= target) clearInterval(fade);
    }, 60); // 60 ms × 25 steps ≈ 1.5 s fade-in
}

// ── LEGACY SYNTHESIS (kept for reference, no longer called) ──────────────
function _startAmbientSoundSynth(id, vol = 0.5) {
    stopAmbientSound(id);
    const ctx = _getAmbientCtx();
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(0, ctx.currentTime);
    gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 1.5);
    gain.connect(ctx.destination);
    _ambientGains[id] = gain;

    if (id === 'rain') {
        // ── RAIN ON GLASS: pre-rendered drop simulation ──
        // Individual drop events (impact tap + glass ring) beat any filter approach
        const drops = _makeRainBuffer(ctx, 75);  // 75 drops/sec = steady rain
        const dropsG = ctx.createGain(); dropsG.gain.value = 0.82;
        drops.connect(dropsG); dropsG.connect(gain); drops.start();

        // Very light continuous hiss underneath (rain between drops)
        const hiss   = _makeNoise(ctx, 'white');
        const hissHp = ctx.createBiquadFilter(); hissHp.type = 'highpass'; hissHp.frequency.value = 1800;
        const hissLp = ctx.createBiquadFilter(); hissLp.type = 'lowpass';  hissLp.frequency.value = 5000;
        const hissG  = ctx.createGain(); hissG.gain.value = 0.12;
        hiss.connect(hissHp); hissHp.connect(hissLp); hissLp.connect(hissG); hissG.connect(gain); hiss.start();

        _ambientNodes[id] = [drops, hiss];

    } else if (id === 'thunder') {
        // ── STORM: dense rain (pre-rendered) + wind + thunder scheduler ──
        const stormDrops = _makeRainBuffer(ctx, 130);  // 130/sec = heavy downpour
        const stormDropsG = ctx.createGain(); stormDropsG.gain.value = 0.75;
        stormDrops.connect(stormDropsG); stormDropsG.connect(gain); stormDrops.start();

        // Storm wind
        const wind   = _makeNoise(ctx, 'pink');
        const windBp = ctx.createBiquadFilter(); windBp.type = 'bandpass'; windBp.frequency.value = 350; windBp.Q.value = 0.55;
        const windG  = ctx.createGain(); windG.gain.value = 0.14;
        wind.connect(windBp); windBp.connect(windG); windG.connect(gain); wind.start();

        // Thunder: sub-bass + mid-body, scheduler-driven (unpredictable timing)
        const thdSub   = _makeNoise(ctx, 'brown');
        const thdSubLp = ctx.createBiquadFilter(); thdSubLp.type = 'lowpass'; thdSubLp.frequency.value = 130;
        const thdSubG  = ctx.createGain(); thdSubG.gain.value = 0;
        thdSub.connect(thdSubLp); thdSubLp.connect(thdSubG); thdSubG.connect(gain); thdSub.start();

        const thdMid   = _makeNoise(ctx, 'brown');
        const thdMidLp = ctx.createBiquadFilter(); thdMidLp.type = 'lowpass';  thdMidLp.frequency.value = 420;
        const thdMidHp = ctx.createBiquadFilter(); thdMidHp.type = 'highpass'; thdMidHp.frequency.value = 65;
        const thdMidG  = ctx.createGain(); thdMidG.gain.value = 0;
        thdMid.connect(thdMidHp); thdMidHp.connect(thdMidLp); thdMidLp.connect(thdMidG); thdMidG.connect(gain); thdMid.start();

        function scheduleThunder() {
            if (!_ambientNodes[id]) return;
            setTimeout(() => {
                if (!_ambientNodes[id]) return;
                const now     = ctx.currentTime;
                const boomAmp = 1.1 + Math.random() * 0.8;
                const decay   = 3.5 + Math.random() * 2.5;
                thdSubG.gain.cancelScheduledValues(now);
                thdSubG.gain.setValueAtTime(0, now);
                thdSubG.gain.linearRampToValueAtTime(boomAmp, now + 0.07);
                thdSubG.gain.exponentialRampToValueAtTime(0.001, now + decay);
                thdMidG.gain.cancelScheduledValues(now + 0.02);
                thdMidG.gain.setValueAtTime(0, now + 0.02);
                thdMidG.gain.linearRampToValueAtTime(boomAmp * 0.60, now + 0.12);
                thdMidG.gain.exponentialRampToValueAtTime(0.001, now + decay * 0.65);
                scheduleThunder();
            }, (8 + Math.random() * 19) * 1000);
        }
        scheduleThunder();
        _ambientNodes[id] = [stormDrops, wind, thdSub, thdMid];

    } else if (id === 'whitenoise') {
        // ── WHITE NOISE: attenuated internally so it's not blasting ──
        const noise = _makeNoise(ctx, 'white');
        const lp    = ctx.createBiquadFilter(); lp.type = 'lowpass';  lp.frequency.value = 9000;
        const hp    = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 30;
        const atten = ctx.createGain(); atten.gain.value = 0.32;
        noise.connect(hp); hp.connect(lp); lp.connect(atten); atten.connect(gain);
        noise.start();
        _ambientNodes[id] = [noise];

    } else if (id === 'cafe') {
        // ── CAFÉ: pre-rendered crowd chatter + HVAC hum + cup clinks ──
        const cafeBus = ctx.createGain(); cafeBus.gain.value = 0.90; cafeBus.connect(gain);

        // Crowd murmur: pre-rendered voice-frequency bursts — sounds like a crowd
        const chatter  = _makeCafeChatterBuffer(ctx);
        const chatterG = ctx.createGain(); chatterG.gain.value = 0.72;
        chatter.connect(chatterG); chatterG.connect(cafeBus); chatter.start();

        // HVAC / low room tone
        const room   = _makeNoise(ctx, 'brown');
        const roomLp = ctx.createBiquadFilter(); roomLp.type = 'lowpass'; roomLp.frequency.value = 150;
        const roomG  = ctx.createGain(); roomG.gain.value = 0.08;
        room.connect(roomLp); roomLp.connect(roomG); roomG.connect(cafeBus); room.start();

        // Cup clinks / cutlery: pitched sine, random 750–1300 Hz, every 4–12 s
        const clinkOsc = ctx.createOscillator(); clinkOsc.type = 'sine'; clinkOsc.frequency.value = 950;
        const clinkG   = ctx.createGain(); clinkG.gain.value = 0;
        clinkOsc.connect(clinkG); clinkG.connect(cafeBus); clinkOsc.start();
        function scheduleClink() {
            if (!_ambientNodes[id]) return;
            setTimeout(() => {
                if (!_ambientNodes[id]) return;
                const now  = ctx.currentTime;
                const freq = 750 + Math.random() * 550;
                clinkOsc.frequency.setValueAtTime(freq, now);
                clinkG.gain.cancelScheduledValues(now);
                clinkG.gain.setValueAtTime(0, now);
                clinkG.gain.linearRampToValueAtTime(0.22 + Math.random() * 0.14, now + 0.006);
                clinkG.gain.exponentialRampToValueAtTime(0.001, now + 0.22 + Math.random() * 0.16);
                // Occasional second clink (glass touching glass)
                if (Math.random() < 0.3) {
                    const t2 = now + 0.08 + Math.random() * 0.12;
                    clinkOsc.frequency.setValueAtTime(freq * (0.85 + Math.random() * 0.3), t2);
                    clinkG.gain.setValueAtTime(0, t2);
                    clinkG.gain.linearRampToValueAtTime(0.12 + Math.random() * 0.10, t2 + 0.005);
                    clinkG.gain.exponentialRampToValueAtTime(0.001, t2 + 0.18);
                }
                scheduleClink();
            }, (4 + Math.random() * 8) * 1000);
        }
        scheduleClink();
        _ambientNodes[id] = [chatter, room, clinkOsc];

    } else if (id === 'fire') {
        // ── FIREPLACE: pre-rendered crackle events + continuous warm roar ──
        const fireBus = ctx.createGain(); fireBus.gain.value = 0.92; fireBus.connect(gain);

        // Pre-rendered crackle buffer: discrete impulsive events at realistic density
        const crackle  = _makeFireBuffer(ctx);
        const crackleG = ctx.createGain(); crackleG.gain.value = 0.70;
        crackle.connect(crackleG); crackleG.connect(fireBus); crackle.start();

        // Continuous warm roar: brown noise through LP (the bed of the fire)
        const base   = _makeNoise(ctx, 'brown');
        const baseLp = ctx.createBiquadFilter(); baseLp.type = 'lowpass'; baseLp.frequency.value = 360;
        const baseG  = ctx.createGain(); baseG.gain.value = 0.42;
        base.connect(baseLp); baseLp.connect(baseG); baseG.connect(fireBus); base.start();

        // Sizzle: mid-freq pink noise (hiss of burning wood)
        const sizzle   = _makeNoise(ctx, 'pink');
        const sizzleBp = ctx.createBiquadFilter(); sizzleBp.type = 'bandpass'; sizzleBp.frequency.value = 1000; sizzleBp.Q.value = 0.75;
        const sizzleG  = ctx.createGain(); sizzleG.gain.value = 0.18;
        sizzle.connect(sizzleBp); sizzleBp.connect(sizzleG); sizzleG.connect(fireBus); sizzle.start();

        // Slow breathing flutter on the roar (flames growing & dimming)
        const flutter  = ctx.createOscillator(); flutter.frequency.value = 0.07;
        const flutterG = ctx.createGain(); flutterG.gain.value = 0.14;
        flutter.connect(flutterG); flutterG.connect(baseG.gain); flutter.start();

        _ambientNodes[id] = [crackle, base, sizzle, flutter];

    } else if (id === 'forest') {
        // ── FOREST: gentle wind + insects + 4 bird species ──
        const forestBus = ctx.createGain(); forestBus.gain.value = 0.92; forestBus.connect(gain);

        // Gentle wind — very low so birds dominate
        const wind   = _makeNoise(ctx, 'pink');
        const windLp = ctx.createBiquadFilter(); windLp.type = 'lowpass'; windLp.frequency.value = 520;
        const windG  = ctx.createGain(); windG.gain.value = 0.16;
        wind.connect(windLp); windLp.connect(windG); windG.connect(forestBus); wind.start();
        const gustLfo  = ctx.createOscillator(); gustLfo.frequency.value = 0.055;
        const gustLfoG = ctx.createGain(); gustLfoG.gain.value = 0.055;
        gustLfo.connect(gustLfoG); gustLfoG.connect(windG.gain); gustLfo.start();

        // Insects/cicadas: narrow band ~4.3 kHz
        const insects  = _makeNoise(ctx, 'white');
        const insectBp = ctx.createBiquadFilter(); insectBp.type = 'bandpass'; insectBp.frequency.value = 4300; insectBp.Q.value = 3.5;
        const insectG  = ctx.createGain(); insectG.gain.value = 0.044;
        insects.connect(insectBp); insectBp.connect(insectG); insectG.connect(forestBus); insects.start();
        const insectLfo  = ctx.createOscillator(); insectLfo.frequency.value = 0.38;
        const insectLfoG = ctx.createGain(); insectLfoG.gain.value = 0.024;
        insectLfo.connect(insectLfoG); insectLfoG.connect(insectG.gain); insectLfo.start();

        // 4 bird species — each with own timing, frequency glide, amplitude envelope
        const birdDefs = [
            { fA: 2500, fB: 3300, fC: 2800, dur: 0.17, amp: 0.044, minInt: 1.5, maxInt: 5.5 },
            { fA: 1700, fB: 1700, fC: 2300, dur: 0.13, amp: 0.035, minInt: 2.5, maxInt: 8.0 },
            { fA: 3900, fB: 4700, fC: 3900, dur: 0.09, amp: 0.040, minInt: 1.0, maxInt: 4.5 },
            { fA: 2100, fB: 2100, fC: 2700, dur: 0.20, amp: 0.030, minInt: 3.5, maxInt: 10.0 },
        ];
        const birdOscs = [];
        birdDefs.forEach(function(def, bi) {
            const osc  = ctx.createOscillator(); osc.type = 'sine'; osc.frequency.value = def.fA;
            const envG = ctx.createGain(); envG.gain.value = 0;
            osc.connect(envG); envG.connect(forestBus); osc.start();
            birdOscs.push(osc);
            const atk = def.dur * 0.22, rel = def.dur * 0.38;
            function scheduleChirp() {
                if (!_ambientNodes[id]) return;
                setTimeout(function() {
                    if (!_ambientNodes[id]) return;
                    const now = ctx.currentTime;
                    osc.frequency.cancelScheduledValues(now);
                    osc.frequency.setValueAtTime(def.fA, now);
                    osc.frequency.linearRampToValueAtTime(def.fB, now + atk);
                    osc.frequency.linearRampToValueAtTime(def.fC, now + def.dur);
                    envG.gain.cancelScheduledValues(now);
                    envG.gain.setValueAtTime(0, now);
                    envG.gain.linearRampToValueAtTime(def.amp, now + atk);
                    envG.gain.setValueAtTime(def.amp, now + def.dur - rel);
                    envG.gain.linearRampToValueAtTime(0, now + def.dur);
                    if (Math.random() < 0.25) {
                        const t2 = now + def.dur + 0.04 + Math.random() * 0.07;
                        osc.frequency.setValueAtTime(def.fA, t2);
                        osc.frequency.linearRampToValueAtTime(def.fB, t2 + atk);
                        osc.frequency.linearRampToValueAtTime(def.fC, t2 + def.dur);
                        envG.gain.setValueAtTime(0, t2);
                        envG.gain.linearRampToValueAtTime(def.amp * 0.75, t2 + atk);
                        envG.gain.setValueAtTime(def.amp * 0.75, t2 + def.dur - rel);
                        envG.gain.linearRampToValueAtTime(0, t2 + def.dur);
                    }
                    scheduleChirp();
                }, (def.minInt + Math.random() * (def.maxInt - def.minInt)) * 1000);
            }
            setTimeout(scheduleChirp, bi * 900 + Math.random() * 1200);
        });
        _ambientNodes[id] = [wind, gustLfo, insects, insectLfo, ...birdOscs];
    }
}

function stopAmbientSound(id) {
    // ── YouTube player fade-out ──
    const player = _ambientGains[id];
    if (player && typeof player.getVolume === 'function') {
        let vol = 50;
        try { vol = player.getVolume(); } catch(e) {}
        const fade = setInterval(function() {
            vol = Math.max(0, vol - 7);
            try { player.setVolume(vol); } catch(e) {}
            if (vol <= 0) {
                clearInterval(fade);
                try { player.pauseVideo(); } catch(e) {}
            }
        }, 50); // ~7 steps × 50 ms ≈ 500 ms fade-out
    }
    delete _ambientGains[id];
    // Legacy Web Audio cleanup
    const nodes = _ambientNodes[id];
    if (nodes) {
        nodes.forEach(function(n) { try { n.stop(); } catch(e) {} });
        delete _ambientNodes[id];
    }
}

function setAmbientVolume(id, vol) {
    const player = _ambientGains[id];
    if (player && typeof player.setVolume === 'function') {
        try { player.setVolume(Math.round(vol * 100)); } catch(e) {}
    }
}

// Pre-load YouTube API as soon as the script runs so players are ready on first click
_ensureYouTubeAPI();

// ── v15.0 — Command Center ambient: mixer state ──────────────────────────────
const _ccAmbientVols = { rain: 50, thunder: 50, cafe: 50, whitenoise: 50, fire: 50, forest: 50 };
let   _ccMixerOpen   = false;

// Sync a mixer row's active styling to whether the sound is playing
function _ccSyncMixerRow(id, active) {
    var row = document.getElementById('cc-mix-' + id);
    if (row) row.classList.toggle('active', active);
}

// Sync the toggle button's lit-up state
function _ccSyncBtn(id, active, sound) {
    var btn = document.getElementById('cc-amb-btn-' + id);
    if (!btn) return;
    if (active) {
        btn.style.borderColor = sound.color + 'bb';
        btn.style.background  = sound.color + '28';
        btn.style.boxShadow   = '0 0 18px ' + sound.color + '55';
        btn.querySelector('i').style.opacity = '1';
    } else {
        btn.style.borderColor = 'rgba(255,255,255,0.15)';
        btn.style.background  = 'rgba(255,255,255,0.04)';
        btn.style.boxShadow   = '';
        btn.querySelector('i').style.opacity = '0.45';
    }
}

// Toggle a single sound on/off
function toggleCCAmbient(id) {
    var sound = AMBIENT_SOUNDS.find(function(s) { return s.id === id; });
    if (!sound) return;
    if (_ambientGains[id]) {
        stopAmbientSound(id);
        _ccSyncBtn(id, false, sound);
        _ccSyncMixerRow(id, false);
    } else {
        _startAmbientSound(id, (_ccAmbientVols[id] || 50) / 100);
        _ccSyncBtn(id, true, sound);
        _ccSyncMixerRow(id, true);
    }
    // Any manual toggle = custom preset
    var sel = document.getElementById('cc-preset-select');
    if (sel && sel.value !== 'custom') sel.value = 'custom';
}

// Open/close the mixer panel
function toggleCCMixer() {
    _ccMixerOpen = !_ccMixerOpen;
    var panel   = document.getElementById('cc-mixer-panel');
    var chevron = document.getElementById('cc-mixer-chevron');
    var btn     = document.getElementById('cc-mixer-toggle-btn');
    if (panel)   panel.style.display          = _ccMixerOpen ? 'block' : 'none';
    if (chevron) chevron.style.transform       = _ccMixerOpen ? 'rotate(180deg)' : '';
    if (btn)     btn.classList.toggle('open', _ccMixerOpen);
}

// Adjust volume of a running sound via slider
function setCCAmbientVol(id, val) {
    var v = parseInt(val, 10);
    _ccAmbientVols[id] = v;
    var lbl = document.getElementById('cc-vol-lbl-' + id);
    if (lbl) lbl.textContent = v + '%';
    // Apply live if playing
    setAmbientVolume(id, v / 100);
    // Revert preset to Custom
    var sel = document.getElementById('cc-preset-select');
    if (sel && sel.value !== 'custom') sel.value = 'custom';
}

// Apply a named preset: stop all, then start the right sounds at specified vols
function applyAmbientPreset(preset) {
    var PRESETS = {
        study:  { rain: 55 },
        sleep:  { whitenoise: 68, rain: 32 },
        storm:  { thunder: 72 },
        cozy:   { fire: 62, cafe: 38 },
        nature: { forest: 65 },
    };
    // Stop all playing sounds
    Object.keys(_YT_VIDEOS).forEach(function(id) {
        var sound = AMBIENT_SOUNDS.find(function(s) { return s.id === id; });
        if (_ambientGains[id]) {
            stopAmbientSound(id);
            if (sound) _ccSyncBtn(id, false, sound);
            _ccSyncMixerRow(id, false);
        }
    });
    if (preset === 'custom' || !PRESETS[preset]) return;
    // Small gap to let fade-outs start before new sounds layer in
    setTimeout(function() {
        var mix = PRESETS[preset];
        Object.entries(mix).forEach(function([id, vol]) {
            var sound = AMBIENT_SOUNDS.find(function(s) { return s.id === id; });
            _ccAmbientVols[id] = vol;
            // Update slider + label
            var slider = document.getElementById('cc-vol-' + id);
            var lbl    = document.getElementById('cc-vol-lbl-' + id);
            if (slider) slider.value   = vol;
            if (lbl)    lbl.textContent = vol + '%';
            // Start the sound
            _startAmbientSound(id, vol / 100);
            if (sound) _ccSyncBtn(id, true, sound);
            _ccSyncMixerRow(id, true);
        });
    }, 650);
}

// Stop every active sound and reset UI
function stopAllAmbient() {
    Object.keys(_YT_VIDEOS).forEach(function(id) {
        var sound = AMBIENT_SOUNDS.find(function(s) { return s.id === id; });
        if (_ambientGains[id]) {
            stopAmbientSound(id);
            if (sound) _ccSyncBtn(id, false, sound);
            _ccSyncMixerRow(id, false);
        }
    });
    var sel = document.getElementById('cc-preset-select');
    if (sel) sel.value = 'custom';
}

function openAmbientPlayer() {
    const existing = document.getElementById('ambient-modal');
    if (existing) { existing.classList.remove('hidden'); return; }
    const modal = document.createElement('div');
    modal.id = 'ambient-modal';
    modal.className = 'modal';
    modal.style.cssText = 'display:flex;';
    modal.innerHTML = `
    <div class="modal-content glass-panel" style="max-width:600px;width:95%;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;">
            <div>
                <h2 style="margin:0;display:flex;align-items:center;gap:10px;"><i class="ph ph-cloud-rain" style="color:#74b9ff;"></i> Ambient Sounds</h2>
                <p style="margin:4px 0 0;font-size:0.9rem;color:var(--text-muted);">Real ambient sounds from YouTube. Tap to toggle, mix multiple together.</p>
            </div>
            <button onclick="document.getElementById('ambient-modal').classList.add('hidden')" style="background:rgba(255,255,255,0.07);border:1px solid var(--glass-border);border-radius:8px;padding:8px 12px;cursor:pointer;color:white;">✕</button>
        </div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:18px;">
        ${AMBIENT_SOUNDS.map(s => `
            <div id="amb-card-${s.id}" class="glass-panel" style="padding:16px;cursor:pointer;border:1px solid rgba(255,255,255,0.06);transition:all 0.2s;"
                onmouseenter="this.style.borderColor='${s.color}55'" onmouseleave="if(!document.getElementById('amb-toggle-${s.id}').checked)this.style.borderColor='rgba(255,255,255,0.06)'"
                onclick="if(!event.target.closest('label')&&event.target.type!=='range')document.getElementById('amb-toggle-${s.id}').click()">
                <div style="display:flex;justify-content:space-between;align-items:start;margin-bottom:10px;">
                    <div>
                        <div style="display:flex;align-items:center;gap:12px;margin-bottom:3px;">
                            <i class="ph ${s.icon}" style="font-size:1.3rem;color:${s.color};"></i>
                            <span style="font-weight:600;font-size:0.95rem;">${s.label}</span>
                        </div>
                        <p style="margin:0;font-size:0.85rem;color:var(--text-muted);">${s.desc}</p>
                    </div>
                    <label style="position:relative;display:inline-block;width:36px;height:20px;flex-shrink:0;">
                        <input type="checkbox" id="amb-toggle-${s.id}" onchange="toggleAmbient('${s.id}',this.checked,document.getElementById('amb-vol-${s.id}').value)" style="opacity:0;width:0;height:0;">
                        <span onclick="return false;" style="position:absolute;cursor:pointer;top:0;left:0;right:0;bottom:0;background:rgba(255,255,255,0.1);border-radius:20px;transition:.3s;" id="amb-slider-${s.id}"></span>
                    </label>
                </div>
                <div style="display:flex;align-items:center;gap:12px;">
                    <i class="ph ph-speaker-low" style="font-size:0.9rem;color:var(--text-muted);"></i>
                    <input type="range" id="amb-vol-${s.id}" min="0" max="100" value="50"
                        oninput="setAmbientVolume('${s.id}',this.value/100)"
                        style="flex:1;height:4px;accent-color:${s.color};cursor:pointer;">
                    <i class="ph ph-speaker-high" style="font-size:0.9rem;color:var(--text-muted);"></i>
                </div>
            </div>`).join('')}
        </div>
        <button onclick="stopAllAmbient()" class="btn-secondary" style="width:100%;margin-top:16px;"><i class="ph ph-stop-circle"></i> Stop All</button>
    </div>`;
    document.body.appendChild(modal);
}

function toggleAmbient(id, on, vol) {
    const card = document.getElementById('amb-card-' + id);
    const sliderEl = document.getElementById('amb-slider-' + id);
    const sound = AMBIENT_SOUNDS.find(s => s.id === id);
    if (on) {
        _startAmbientSound(id, (parseFloat(vol) || 50) / 100);
        if (card) card.style.borderColor = sound ? sound.color + '88' : 'var(--accent)';
        if (sliderEl) sliderEl.style.background = sound ? sound.color : 'var(--accent)';
    } else {
        stopAmbientSound(id);
        if (card) card.style.borderColor = 'rgba(255,255,255,0.06)';
        if (sliderEl) sliderEl.style.background = 'rgba(255,255,255,0.1)';
    }
}

function stopAllAmbient() {
    AMBIENT_SOUNDS.forEach(s => {
        stopAmbientSound(s.id);
        const toggle = document.getElementById('amb-toggle-' + s.id);
        if (toggle) toggle.checked = false;
        const card = document.getElementById('amb-card-' + s.id);
        if (card) card.style.borderColor = 'rgba(255,255,255,0.06)';
        const slider = document.getElementById('amb-slider-' + s.id);
        if (slider) slider.style.background = 'rgba(255,255,255,0.1)';
    });
}

// ════════════════════════════════════════════════════════════════════
// v12.5 — GPA TRACKER
// ════════════════════════════════════════════════════════════════════
const GPA_SCALE = { 'A+':4.0,'A':4.0,'A-':3.7,'B+':3.3,'B':3.0,'B-':2.7,'C+':2.3,'C':2.0,'C-':1.7,'D+':1.3,'D':1.0,'D-':0.7,'F':0.0 };

function _loadGPAData() { try { return JSON.parse(localStorage.getItem('gpa_data') || '[]'); } catch(_) { return []; } }
function _saveGPAData(data) { localStorage.setItem('gpa_data', JSON.stringify(data)); }

function openAddGPAClass(editIdx) {
    const data = _loadGPAData();
    const editing = editIdx !== undefined ? data[editIdx] : null;
    const modal = document.createElement('div');
    modal.className = 'modal';
    modal.style.cssText = 'display:flex;';
    const semesters = [...new Set(['Current Semester', ...data.map(d => d.semester)])];
    modal.innerHTML = `
    <div class="modal-content glass-panel" style="max-width:460px;width:95%;">
        <h2 style="margin:0 0 20px;display:flex;align-items:center;gap:10px;"><i class="ph ph-books" style="color:#a29bfe;"></i>${editing ? 'Edit' : 'Add'} Class</h2>
        <div style="display:flex;flex-direction:column;gap:14px;margin-bottom:20px;">
            <div>
                <label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:5px;">Class Name *</label>
                <input id="gpa-input-name" type="text" value="${editing?.name||''}" placeholder="e.g. AP Biology, Algebra II…" style="width:100%;padding:10px 13px;background:rgba(255,255,255,0.05);border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.95rem;outline:none;box-sizing:border-box;">
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;">
                <div>
                    <label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:5px;">Grade *</label>
                    <select id="gpa-input-grade" style="width:100%;padding:10px 13px;background:#14142a;border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.95rem;outline:none;cursor:pointer;">
                        ${Object.keys(GPA_SCALE).map(g => `<option value="${g}" ${(editing?.grade||'A')===g?'selected':''} style="background:#14142a;">${g} (${GPA_SCALE[g].toFixed(1)})</option>`).join('')}
                    </select>
                </div>
                <div>
                    <label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:5px;">Credit Hours *</label>
                    <input id="gpa-input-credits" type="number" min="0.5" max="6" step="0.5" value="${editing?.credits||3}" style="width:100%;padding:10px 13px;background:rgba(255,255,255,0.05);border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.95rem;outline:none;box-sizing:border-box;">
                </div>
            </div>
            <div>
                <label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:5px;">Semester</label>
                <input id="gpa-input-semester" type="text" value="${editing?.semester||'Current Semester'}" placeholder="e.g. Fall 2026, Current Semester" style="width:100%;padding:10px 13px;background:rgba(255,255,255,0.05);border:1px solid var(--glass-border);border-radius:8px;color:white;font-size:0.95rem;outline:none;box-sizing:border-box;" list="gpa-semester-list">
                <datalist id="gpa-semester-list">${semesters.map(s => `<option value="${s}">`).join('')}</datalist>
            </div>
        </div>
        <div style="display:flex;gap:10px;">
            <button onclick="this.closest('.modal').remove()" class="btn-secondary" style="flex:1;">Cancel</button>
            <button onclick="saveGPAClass(${editIdx !== undefined ? editIdx : 'undefined'}, this.closest('.modal'))" class="btn-primary" style="flex:2;background:linear-gradient(135deg,#a29bfe,#6c5ce7);">
                <i class="ph ph-floppy-disk"></i> Save Class
            </button>
        </div>
    </div>`;
    document.body.appendChild(modal);
    setTimeout(() => document.getElementById('gpa-input-name')?.focus(), 80);
}

function saveGPAClass(editIdx, modalEl) {
    const name = document.getElementById('gpa-input-name')?.value.trim();
    const grade = document.getElementById('gpa-input-grade')?.value;
    const credits = parseFloat(document.getElementById('gpa-input-credits')?.value) || 3;
    const semester = document.getElementById('gpa-input-semester')?.value.trim() || 'Current Semester';
    if (!name) { showToast('Please enter a class name.', 'error'); return; }
    const data = _loadGPAData();
    const entry = { name, grade, credits, semester, points: GPA_SCALE[grade] * credits, addedAt: Date.now() };
    if (editIdx !== undefined) { data[editIdx] = entry; } else { data.push(entry); }
    _saveGPAData(data);
    modalEl.remove();
    renderGPATable();
    updateGPASummary();
    showToast(editIdx !== undefined ? 'Class updated!' : `${name} added!`, 'success');
}

function deleteGPAClass(idx) {
    const data = _loadGPAData();
    const name = data[idx]?.name || 'Class';
    data.splice(idx, 1);
    _saveGPAData(data);
    renderGPATable();
    updateGPASummary();
    showToast(`${name} removed.`, 'info');
}

function renderGPATable() {
    const tbody = document.getElementById('gpa-table-body');
    if (!tbody) return;
    const data = _loadGPAData();
    const filter = document.getElementById('gpa-semester-filter')?.value || 'all';
    const filtered = filter === 'all' ? data : data.filter(d => d.semester === (filter === 'current' ? 'Current Semester' : filter));
    if (filtered.length === 0) {
        tbody.innerHTML = `<tr><td colspan="6" style="padding:40px;text-align:center;color:var(--text-muted);">No classes ${filter !== 'all' ? 'for this semester' : 'yet'}. Click <strong style="color:white;">Add Class</strong> to get started.</td></tr>`;
        return;
    }
    const gradeColors = { 'A+':'#00b894','A':'#00b894','A-':'#00cec9','B+':'#6c5ce7','B':'#6c5ce7','B-':'#a29bfe','C+':'#fdcb6e','C':'#fdcb6e','C-':'#fab1a0','D+':'#e17055','D':'#e17055','D-':'#d63031','F':'#ff4757' };
    tbody.innerHTML = filtered.map((cls, i) => {
        const realIdx = data.indexOf(cls);
        const col = gradeColors[cls.grade] || '#a29bfe';
        return `<tr style="border-bottom:1px solid rgba(255,255,255,0.04);">
            <td style="padding:14px 16px;">
                <div style="font-weight:600;color:white;">${cls.name}</div>
            </td>
            <td style="padding:14px 16px;text-align:center;color:var(--text-muted);">${cls.credits}</td>
            <td style="padding:14px 16px;text-align:center;">
                <span style="background:${col}22;color:${col};border:1px solid ${col}44;border-radius:6px;padding:3px 10px;font-weight:700;font-size:0.9rem;">${cls.grade}</span>
            </td>
            <td style="padding:14px 16px;text-align:center;color:var(--text-muted);">${(GPA_SCALE[cls.grade]||0).toFixed(1)}</td>
            <td style="padding:14px 16px;text-align:center;font-size:0.9rem;color:var(--text-muted);">${cls.semester}</td>
            <td style="padding:14px 16px;text-align:center;">
                <button onclick="openAddGPAClass(${realIdx})" style="background:rgba(255,255,255,0.07);border:1px solid var(--glass-border);border-radius:6px;padding:5px 10px;cursor:pointer;color:white;margin-right:4px;font-size:0.9rem;"><i class="ph ph-pencil"></i></button>
                <button onclick="deleteGPAClass(${realIdx})" style="background:rgba(255,107,107,0.1);border:1px solid rgba(255,107,107,0.3);border-radius:6px;padding:5px 10px;cursor:pointer;color:#ff6b6b;font-size:0.9rem;"><i class="ph ph-trash"></i></button>
            </td>
        </tr>`;
    }).join('');
    // Rebuild semester filter options
    const sel = document.getElementById('gpa-semester-filter');
    if (sel) {
        const sems = [...new Set(data.map(d => d.semester))];
        const cur = sel.value;
        sel.innerHTML = `<option value="all" style="background:#14142a;">All Semesters</option><option value="current" style="background:#14142a;">Current Semester</option>` +
            sems.filter(s => s !== 'Current Semester').map(s => `<option value="${s}" style="background:#14142a;">${s}</option>`).join('');
        sel.value = cur;
    }
}

function updateGPASummary() {
    const data = _loadGPAData();
    // Cumulative
    const totalCredits = data.reduce((s, c) => s + c.credits, 0);
    const totalPoints = data.reduce((s, c) => s + (GPA_SCALE[c.grade] || 0) * c.credits, 0);
    const cumGPA = totalCredits > 0 ? (totalPoints / totalCredits).toFixed(2) : '—';
    // Semester (Current only)
    const cur = data.filter(c => c.semester === 'Current Semester');
    const curCredits = cur.reduce((s, c) => s + c.credits, 0);
    const curPoints = cur.reduce((s, c) => s + (GPA_SCALE[c.grade] || 0) * c.credits, 0);
    const semGPA = curCredits > 0 ? (curPoints / curCredits).toFixed(2) : '—';
    const el = (id, v) => { const e = document.getElementById(id); if (e) e.textContent = v; };
    el('gpa-cumulative', cumGPA);
    el('gpa-semester', semGPA);
    el('gpa-credits', totalCredits);
    el('gpa-class-count', data.length);
}

function clearGPAData() {
    if (!confirm('Delete all GPA data? This cannot be undone.')) return;
    localStorage.removeItem('gpa_data');
    renderGPATable();
    updateGPASummary();
    showToast('GPA data cleared.', 'info');
}

function exportGPAReport() {
    const data = _loadGPAData();
    if (!data.length) { showToast('No data to export yet.', 'error'); return; }
    const totalCredits = data.reduce((s, c) => s + c.credits, 0);
    const totalPoints = data.reduce((s, c) => s + (GPA_SCALE[c.grade] || 0) * c.credits, 0);
    const cumGPA = totalCredits > 0 ? (totalPoints / totalCredits).toFixed(2) : 'N/A';
    const rows = data.map(c => `<tr><td style="padding:8px 12px;border:1px solid #ddd;">${c.name}</td><td style="padding:8px 12px;border:1px solid #ddd;text-align:center;">${c.grade}</td><td style="padding:8px 12px;border:1px solid #ddd;text-align:center;">${c.credits}</td><td style="padding:8px 12px;border:1px solid #ddd;text-align:center;">${(GPA_SCALE[c.grade]||0).toFixed(1)}</td><td style="padding:8px 12px;border:1px solid #ddd;">${c.semester}</td></tr>`).join('');
    const html = `<!DOCTYPE html><html><head><title>NEXUS GPA Report</title></head><body style="font-family:sans-serif;max-width:720px;margin:40px auto;padding:24px;"><h1 style="color:#6C5CE7;">📊 NEXUS GPA Report</h1><p style="color:#888;">Generated ${new Date().toLocaleDateString()}</p><div style="background:#f8f9fa;border-radius:8px;padding:16px;margin-bottom:24px;display:flex;gap:32px;"><div><strong style="font-size:1.35rem;color:#6C5CE7;">${cumGPA}</strong><br><span style="color:#888;font-size:0.85rem;">Cumulative GPA</span></div><div><strong style="font-size:1.35rem;">${totalCredits}</strong><br><span style="color:#888;font-size:0.85rem;">Total Credits</span></div><div><strong style="font-size:1.35rem;">${data.length}</strong><br><span style="color:#888;font-size:0.85rem;">Classes</span></div></div><table style="width:100%;border-collapse:collapse;"><thead><tr style="background:#6C5CE7;color:white;"><th style="padding:10px 12px;text-align:left;">Class</th><th style="padding:10px 12px;">Grade</th><th style="padding:10px 12px;">Credits</th><th style="padding:10px 12px;">Points</th><th style="padding:10px 12px;text-align:left;">Semester</th></tr></thead><tbody>${rows}</tbody></table></body></html>`;
    const blob = new Blob([html], { type: 'text/html' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
    a.download = 'nexus-gpa-report.html'; a.click();
    showToast('GPA report downloaded!', 'success');
}

// Hook GPA tab into switchTab
const _origSwitchTab_gpa = window.switchTab;
if (typeof switchTab === 'function') {
    const _wrapped = switchTab;
    window.switchTab = function(tabId) {
        _wrapped(tabId);
        if (tabId === 'gpa') {
            renderGPATable();
            updateGPASummary();
        }
    };
}

// ════════════════════════════════════════════════════════════════════
// v12.5 — EXPORT NOTES AS PDF
// ════════════════════════════════════════════════════════════════════
function exportNotesAsPDF() {
    const content = document.getElementById('notebook-area');
    if (!content) { showToast('No notes to export.', 'error'); return; }
    const text = content.innerHTML;
    const html = `<!DOCTYPE html><html><head><title>NEXUS Notebook Export</title>
    <style>body{font-family:'Segoe Print','Comic Sans MS',cursive;font-size:14px;line-height:32px;max-width:800px;margin:40px auto;padding:40px 60px;background:white;color:#111;position:relative;}
    body::before{content:'';position:fixed;top:0;left:0;right:0;bottom:0;background-image:repeating-linear-gradient(transparent,transparent 31px,#dde 31px,#dde 32px);pointer-events:none;}
    body::after{content:'';position:fixed;top:0;left:72px;bottom:0;width:2px;background:rgba(255,100,100,0.4);pointer-events:none;}
    h1,h2,h3{color:#6C5CE7;} @media print{body{margin:0;padding:20px 60px;}}</style>
    </head><body>
    <div style="margin-bottom:24px;padding-bottom:12px;border-bottom:2px solid #6C5CE7;display:flex;justify-content:space-between;align-items:center;">
        <strong style="color:#6C5CE7;font-size:1.2rem;font-family:Orbitron,sans-serif;">NEXUS Notebook</strong>
        <span style="color:#888;font-size:0.85rem;">${new Date().toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}</span>
    </div>
    ${text}
    </body></html>`;
    const win = window.open('', '_blank');
    if (win) {
        win.document.write(html);
        win.document.close();
        setTimeout(() => win.print(), 500);
    } else {
        // Fallback: download HTML file
        const blob = new Blob([html], { type: 'text/html' });
        const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
        a.download = 'nexus-notes.html'; a.click();
        showToast('Notes exported as HTML (open and print to PDF).', 'info');
    }
}

// ════════════════════════════════════════════════════════════════════
// v12.5 — STUDY ACTIVITY HEATMAP
// ════════════════════════════════════════════════════════════════════
function renderStudyHeatmap() {
    const canvas = document.getElementById('study-heatmap');
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const W = canvas.offsetWidth || 600;
    const dpr = window.devicePixelRatio || 1;
    const COLS = 16, ROWS = 7, gap = 3, oy = 8;
    const cellSize = Math.max(8, Math.floor((W - 32) / COLS));
    const CW = W;
    const CH = oy + ROWS * (cellSize + gap) + 8; // grow to fit all 7 rows (was hard-capped at 88 → clipped)
    canvas.width = W * dpr;
    canvas.height = CH * dpr;
    canvas.style.height = CH + 'px';
    ctx.scale(dpr, dpr);
    ctx.clearRect(0, 0, CW, CH);

    // Build activity map: date string → minutes studied (real study time).
    const actMap = {};
    try {
        // Primary source: tracked study sessions (minutes per day).
        const sessions = JSON.parse(localStorage.getItem('study_sessions_v2') || '[]');
        sessions.forEach(s => { if (s && s.date) actMap[s.date] = (actMap[s.date] || 0) + (s.duration || 1); });
        // Fallback: legacy activity log (count as ~1 min each) if no sessions yet.
        if (Object.keys(actMap).length === 0) {
            const hist = JSON.parse(localStorage.getItem('studyHistory') || localStorage.getItem('study_history') || '[]');
            hist.forEach(entry => {
                const d = new Date(entry.timestamp || entry.date || entry.t || 0);
                if (isNaN(d)) return;
                actMap[d.toISOString().slice(0, 10)] = (actMap[d.toISOString().slice(0, 10)] || 0) + 1;
            });
        }
    } catch(_) {}

    const ox = (CW - (COLS * (cellSize + gap) - gap)) / 2;
    const today = new Date(); today.setHours(0,0,0,0);
    const maxCount = Math.max(1, ...Object.values(actMap));

    // Day labels
    const days = ['S','M','T','W','T','F','S'];
    ctx.font = '9px Inter,sans-serif'; ctx.fillStyle = 'rgba(255,255,255,0.3)'; ctx.textAlign = 'center';
    for (let r = 0; r < ROWS; r++) {
        ctx.fillText(days[r], ox - 10, oy + r * (cellSize + gap) + cellSize * 0.7);
    }

    // Draw cells
    for (let col = 0; col < COLS; col++) {
        for (let row = 0; row < ROWS; row++) {
            const daysAgo = (COLS - 1 - col) * 7 + (6 - row);
            const d = new Date(today); d.setDate(d.getDate() - daysAgo);
            const key = d.toISOString().slice(0, 10);
            const count = actMap[key] || 0;
            const x = ox + col * (cellSize + gap);
            const y = oy + row * (cellSize + gap);
            // Color
            let fill;
            if (count === 0) {
                fill = 'rgba(108,92,231,0.10)';
            } else {
                const intensity = Math.min(count / Math.max(maxCount, 3), 1);
                if (intensity < 0.33) fill = 'rgba(108,92,231,0.35)';
                else if (intensity < 0.66) fill = 'rgba(108,92,231,0.62)';
                else if (intensity < 0.9) fill = '#6c5ce7';
                else fill = '#00cec9';
            }
            ctx.fillStyle = fill;
            ctx.beginPath();
            ctx.roundRect(x, y, cellSize, cellSize, 2);
            ctx.fill();
            // Today indicator
            if (daysAgo === 0) {
                ctx.strokeStyle = 'rgba(255,255,255,0.5)';
                ctx.lineWidth = 1.5;
                ctx.beginPath(); ctx.roundRect(x, y, cellSize, cellSize, 2); ctx.stroke();
            }
        }
    }
    // Total label — show real minutes studied across the window
    const total = Object.values(actMap).reduce((s, v) => s + v, 0);
    const label = document.getElementById('heatmap-total-label');
    if (label) {
        const h = Math.floor(total / 60), m = total % 60;
        label.textContent = (h > 0 ? h + 'h ' + m + 'm' : total + ' min') + ' studied';
    }
}

// Hook heatmap into history tab
(function _patchSwitchTabHeatmap() {
    const _prev = window.switchTab;
    if (typeof _prev === 'function') {
        window.switchTab = function(tabId) {
            _prev(tabId);
            if (tabId === 'history') setTimeout(renderStudyHeatmap, 80);
        };
    }
})();

// ════════════════════════════════════════════════════════════════════
// v12.5 — SPACED REPETITION (SM-2 algorithm for Flashcards)
// ════════════════════════════════════════════════════════════════════
function _sm2Update(card, rating) {
    // rating: 0=Again, 1=Hard, 2=Good, 3=Easy
    const q = rating; // quality (0-3 → map to SM-2 0-5 scale)
    const qNorm = [0, 2, 4, 5][q] || 0; // Again=0, Hard=2, Good=4, Easy=5
    let { ef = 2.5, interval = 1, reps = 0 } = card.sm2 || {};
    if (qNorm < 3) {
        reps = 0; interval = 1;
    } else {
        if (reps === 0) interval = 1;
        else if (reps === 1) interval = 6;
        else interval = Math.round(interval * ef);
        reps++;
    }
    ef = Math.max(1.3, ef + 0.1 - (5 - qNorm) * (0.08 + (5 - qNorm) * 0.02));
    const nextReview = Date.now() + interval * 86400000;
    return { ...card, sm2: { ef, interval, reps, nextReview, lastReview: Date.now(), rating: q } };
}

function _injectSM2Buttons(deckId) {
    // Find the flip/next button area in the flashcard study UI and add SR buttons
    const actions = document.getElementById('fc-card-actions');
    if (!actions || actions.dataset.sm2) return;
    actions.dataset.sm2 = '1';
    const srRow = document.createElement('div');
    srRow.id = 'sm2-row';
    srRow.style.cssText = 'display:none;flex-direction:column;align-items:center;gap:10px;margin-top:12px;width:100%;';
    srRow.innerHTML = `
        <p style="margin:0;font-size:0.9rem;color:var(--text-muted);">How well did you know this?</p>
        <div style="display:flex;gap:12px;flex-wrap:wrap;justify-content:center;">
            <button onclick="_handleSM2(0,'${deckId}')" style="padding:8px 16px;border-radius:8px;background:rgba(255,71,87,0.2);border:1px solid rgba(255,71,87,0.5);color:#ff4757;cursor:pointer;font-weight:600;font-size:0.88rem;">Again 🔴</button>
            <button onclick="_handleSM2(1,'${deckId}')" style="padding:8px 16px;border-radius:8px;background:rgba(253,203,110,0.2);border:1px solid rgba(253,203,110,0.5);color:#fdcb6e;cursor:pointer;font-weight:600;font-size:0.88rem;">Hard 🟡</button>
            <button onclick="_handleSM2(2,'${deckId}')" style="padding:8px 16px;border-radius:8px;background:rgba(0,206,201,0.2);border:1px solid rgba(0,206,201,0.5);color:#00cec9;cursor:pointer;font-weight:600;font-size:0.88rem;">Good 🟢</button>
            <button onclick="_handleSM2(3,'${deckId}')" style="padding:8px 16px;border-radius:8px;background:rgba(0,184,148,0.2);border:1px solid rgba(0,184,148,0.5);color:#00b894;cursor:pointer;font-weight:600;font-size:0.88rem;">Easy ⚡</button>
        </div>`;
    actions.appendChild(srRow);
}

function _handleSM2(rating, deckId) {
    // Update the current card's SM-2 data
    try {
        const decks = JSON.parse(localStorage.getItem('flashcard_decks') || '[]');
        const deckIdx = decks.findIndex(d => String(d.id) === String(deckId));
        if (deckIdx === -1) return;
        const deck = decks[deckIdx];
        const cardIdx = window._fc_currentIdx !== undefined ? window._fc_currentIdx : 0;
        if (deck.cards && deck.cards[cardIdx]) {
            deck.cards[cardIdx] = _sm2Update(deck.cards[cardIdx], rating);
            localStorage.setItem('flashcard_decks', JSON.stringify(decks));
        }
        // Hide SR row, advance to next
        const srRow = document.getElementById('sm2-row');
        if (srRow) srRow.style.display = 'none';
        const nextBtn = document.getElementById('fc-next-btn');
        if (nextBtn) nextBtn.click();
        else { const flip = document.getElementById('fc-flip-btn'); if (flip) flip.click(); }
        const labels = ['Again','Hard','Good','Easy'];
        showToast(`Marked as ${labels[rating]}. Next review in ${[1,1,4,7][rating]} day${rating > 1 ? 's' : ''}.`, 'info');
    } catch(e) { console.warn('SM-2 update failed', e); }
}

// Define flipFlashcard: reveals the SM-2 rating row after a card is flipped to the answer side
window.flipFlashcard = function() {
    const srRow = document.getElementById('sm2-row');
    if (srRow) srRow.style.display = 'flex';
};

