// v12.7 — WALLPAPER AUTO-ROTATE
// Setting: wallpaper_auto_rotate ('1'/'0'). Rotates through all owned
// wallpapers every 10 minutes using a setInterval.
// ════════════════════════════════════════════════════════════════════
let _wallpaperRotateInterval = null;

function startWallpaperAutoRotate() {
    if (_wallpaperRotateInterval) clearInterval(_wallpaperRotateInterval);
    _wallpaperRotateInterval = setInterval(() => {
        const inv = userInventory || [];
        const owned = inv.filter(id => {
            // Check that the item exists in SHOP_ITEMS and is a wallpaper
            if (typeof SHOP_ITEMS !== 'undefined') {
                const item = SHOP_ITEMS.find(i => i.id === id);
                return item && item.category === 'wallpaper';
            }
            return false;
        });
        if (owned.length < 2) return;
        const current = (userLoadout && userLoadout.wallpaper) || 'none';
        const others = owned.filter(id => id !== current);
        if (others.length === 0) return;
        const next = others[Math.floor(Math.random() * others.length)];
        if (typeof applyWallpaper === 'function') applyWallpaper(next);
        if (userLoadout) userLoadout.wallpaper = next;
        localStorage.setItem('user_loadout', JSON.stringify(userLoadout));
    }, 10 * 60 * 1000); // every 10 minutes
}

function stopWallpaperAutoRotate() {
    if (_wallpaperRotateInterval) { clearInterval(_wallpaperRotateInterval); _wallpaperRotateInterval = null; }
}

// Apply setting on load + whenever settings change
(function _initWallpaperAutoRotate() {
    document.addEventListener('DOMContentLoaded', () => {
        setTimeout(() => {
            if (localStorage.getItem('wallpaper_auto_rotate') === '1') startWallpaperAutoRotate();
        }, 1200);
    });
})();

// Hook into saveSettings to start/stop when the toggle changes
(function _patchSaveSettingsForWallpaperRotate() {
    const _origSave = window.saveSettings;
    if (typeof _origSave !== 'function') return;
    window.saveSettings = function() {
        _origSave.apply(this, arguments);
        const el = document.getElementById('setting-wallpaper-rotate');
        if (el) {
            if (el.checked) startWallpaperAutoRotate();
            else stopWallpaperAutoRotate();
        }
    };
})();

