// ── Copy button on AI responses ──────────────────────────────────────
// Attaches a small "Copy" button to the top-right corner of any AI
// output container. Called automatically via MutationObserver whenever
// one of the three main output panels gets new content.
function _attachCopyBtn(containerEl) {
    if (!containerEl || containerEl.dataset.copyWired) return;
    containerEl.dataset.copyWired = '1';
    containerEl.style.position = 'relative'; // ensure positioning context

    const btn = document.createElement('button');
    btn.title = 'Copy response';
    btn.style.cssText = [
        'position:absolute', 'top:8px', 'right:8px',
        'padding:4px 10px', 'font-size:0.9rem', 'border-radius:6px',
        'background:rgba(108,92,231,0.18)', 'border:1px solid rgba(108,92,231,0.4)',
        'color:var(--text-muted)', 'cursor:pointer', 'z-index:10',
        'display:none', 'align-items:center', 'gap:4px',
        'transition:opacity 0.15s'
    ].join(';');
    btn.innerHTML = '<i class="ph ph-copy"></i> Copy';

    btn.addEventListener('click', () => {
        const text = containerEl.innerText || containerEl.textContent || '';
        navigator.clipboard.writeText(text.trim()).then(() => {
            const prev = btn.innerHTML;
            btn.innerHTML = '<i class="ph ph-check"></i> Copied!';
            btn.style.color = '#00b894';
            btn.style.borderColor = 'rgba(0,184,148,0.5)';
            setTimeout(() => { btn.innerHTML = prev; btn.style.color = ''; btn.style.borderColor = ''; }, 1800);
        }).catch(() => { showToast('Copy failed — try selecting text manually.', 'error'); });
    });

    containerEl.appendChild(btn);

    // Show button only when container has meaningful content
    const mo = new MutationObserver(() => {
        const hasContent = (containerEl.innerText || '').trim().length > 20;
        btn.style.display = hasContent ? 'flex' : 'none';
    });
    mo.observe(containerEl, { childList: true, subtree: true, characterData: true });
}

// Wire copy buttons to all three main AI output panels once DOM is ready
document.addEventListener('DOMContentLoaded', () => {
    setTimeout(() => {
        ['math-tutorial-output', 'science-output', 'english-output'].forEach(id => {
            _attachCopyBtn(document.getElementById(id));
        });
    }, 800);
});

// ── Flashcard keyboard shortcuts ─────────────────────────────────────
// Active only when flashcard content is visible (deck has been opened).
// Space = flip card   ←/→ = Prev/Next   1/2/3/4 = SM-2 Again/Hard/Good/Easy
document.addEventListener('keydown', function _fcKeyNav(e) {
    return; // v19 — keyboard shortcuts removed app-wide
    // Only active when the flashcards tab is showing review content
    const content = document.getElementById('flashcards-content');
    if (!content || !content.closest('.view.active')) return;

    // Don't steal keys from inputs / textareas
    if (['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)) return;

    const card = content.querySelector('[data-flipped]');
    if (!card) return; // not in review mode

    if (e.code === 'Space') {
        e.preventDefault();
        card.click(); // toggle flip
    } else if (e.code === 'ArrowRight') {
        e.preventDefault();
        const nextBtn = document.getElementById('fc-next-btn');
        if (nextBtn && !nextBtn.disabled) nextBtn.click();
    } else if (e.code === 'ArrowLeft') {
        e.preventDefault();
        const prevBtn = document.getElementById('fc-prev-btn');
        if (prevBtn && !prevBtn.disabled) prevBtn.click();
    } else if (['Digit1','Digit2','Digit3','Digit4'].includes(e.code)) {
        // SM-2 ratings: 1=Again, 2=Hard, 3=Good, 4=Easy
        const srRow = document.getElementById('sm2-row');
        if (!srRow || srRow.style.display === 'none') return; // must be flipped first
        const ratingMap = { Digit1: 0, Digit2: 1, Digit3: 2, Digit4: 3 };
        const btns = srRow.querySelectorAll('button');
        const idx = ratingMap[e.code];
        if (btns[idx]) btns[idx].click();
    }
});

