// ─────────────────────────────────────────
// HOMEWORK TRACKER — REMOVED in v234
// ─────────────────────────────────────────
// The Homework Tracker was retired in v13.0, but ~315 lines of it kept
// shipping: getHomework/saveHomework/renderHomework, the add/edit/delete/
// toggle handlers, exportHomeworkPDF, and hwAiHelp/hwAiAsk. None of it was
// reachable — #view-homework had no nav entry and rendered as a blank tab.
// Deleted along with that div. Nothing outside the block referenced it.

// ─────────────────────────────────────────
// GRADE CALCULATOR
// ─────────────────────────────────────────
function getGradeCourses() {
    try { return JSON.parse(localStorage.getItem('grade_courses') || '[]'); } catch { return []; }
}
function saveGradeCourses(c) { localStorage.setItem('grade_courses', JSON.stringify(c)); }
function calcCourseAvg(course) {
    if (!course.grades || course.grades.length === 0) return null;
    const hasWeights = course.grades.some(function(g){ return g.weight > 0; });
    if (hasWeights) {
        var totalW = course.grades.reduce(function(s,g){ return s + (parseFloat(g.weight)||0); }, 0);
        if (totalW === 0) return null;
        var ws = course.grades.reduce(function(s,g){ return s + (parseFloat(g.score)||0)*(parseFloat(g.weight)||0); }, 0);
        return ws / totalW;
    }
    return course.grades.reduce(function(s,g){ return s+(parseFloat(g.score)||0); },0) / course.grades.length;
}
function letterGrade(avg) {
    if (avg === null) return '—';
    if (avg >= 90) return 'A'; if (avg >= 80) return 'B';
    if (avg >= 70) return 'C'; if (avg >= 60) return 'D'; return 'F';
}
function gradeColor(avg) {
    if (avg === null) return 'var(--text-muted)';
    if (avg >= 90) return '#00b894'; if (avg >= 80) return '#00CEC9';
    if (avg >= 70) return '#fdcb6e'; if (avg >= 60) return '#e17055'; return '#ff6b6b';
}

// v13.1 — Category colors for assignment types
var GRADE_CATEGORY_COLORS = { test:'#ff6b6b', quiz:'#fdcb6e', homework:'#00CEC9', project:'#a855f7', lab:'#00b894', participation:'#74b9ff', other:'var(--text-muted)' };

function letterGradeDetailed(avg) {
    if (avg === null) return '—';
    if (avg >= 97) return 'A+'; if (avg >= 93) return 'A'; if (avg >= 90) return 'A−';
    if (avg >= 87) return 'B+'; if (avg >= 83) return 'B'; if (avg >= 80) return 'B−';
    if (avg >= 77) return 'C+'; if (avg >= 73) return 'C'; if (avg >= 70) return 'C−';
    if (avg >= 67) return 'D+'; if (avg >= 60) return 'D';
    return 'F';
}

// v16.5 — standard percent → 4.0 GPA conversion (replaces the rough (pct-60)/10)
function pctToGpa4(p) {
    if (p === null || isNaN(p)) return 0;
    if (p >= 93) return 4.0; if (p >= 90) return 3.7; if (p >= 87) return 3.3; if (p >= 83) return 3.0;
    if (p >= 80) return 2.7; if (p >= 77) return 2.3; if (p >= 73) return 2.0; if (p >= 70) return 1.7;
    if (p >= 67) return 1.3; if (p >= 63) return 1.0; if (p >= 60) return 0.7; return 0.0;
}

function calcNeededScore(course) {
    if (!course.targetGrade || course.grades.length === 0) return null;
    var target = course.targetGrade;
    var n = course.grades.length;
    var currentSum = course.grades.reduce(function(s,g){ return s+(parseFloat(g.score)||0); }, 0);
    // What do I need on the next exam to reach my target given existing grades?
    // (currentSum + needed) / (n+1) >= target => needed = target*(n+1) - currentSum
    var needed = target * (n + 1) - currentSum;
    return Math.min(needed, 100).toFixed(1);
}

function renderGradeCalc() {
    var panel = document.getElementById('grade-calc-panel');
    if (!panel) return;
    var courses = getGradeCourses();
    if (courses.length === 0) {
        panel.innerHTML = '<div style="text-align:center;padding:48px 20px;color:var(--text-muted);"><i class="ph ph-chart-bar" style="font-size:1.25rem;display:block;margin-bottom:12px;opacity:0.4;"></i><div style="font-size:1rem;">No courses yet.</div><div style="font-size:0.85rem;margin-top:6px;">Click <strong style="color:white;">Add Course</strong> above to get started.</div></div>';
        return;
    }
    var avgs = courses.map(calcCourseAvg).filter(function(a){ return a!==null; });
    var overallPct = avgs.length ? (avgs.reduce(function(s,a){return s+a;},0)/avgs.length) : null;
    var overallGPA = overallPct !== null ? overallPct.toFixed(1) : '—';
    var overallLetter = letterGradeDetailed(overallPct);
    // 4.0 scale: standard letter-grade conversion
    var gpa4 = overallPct !== null ? pctToGpa4(overallPct).toFixed(1) : '—';
    var bestCourse = courses.reduce(function(b,c){ var a=calcCourseAvg(c); return (a!==null&&(b===null||a>b.avg))?{name:c.name,avg:a}:b; }, null);

    var html = '<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:12px;margin-bottom:20px;">'
        +'<div class="glass-panel" style="padding:14px;text-align:center;">'
            +'<div style="font-size:1.25rem;font-weight:700;color:'+gradeColor(overallPct)+';">'+overallGPA+'%</div>'
            +'<div style="font-size:0.88rem;color:var(--text-muted);">Overall Avg</div>'
        +'</div>'
        +'<div class="glass-panel" style="padding:14px;text-align:center;">'
            +'<div style="font-size:1.25rem;font-weight:700;color:#a855f7;">'+overallLetter+'</div>'
            +'<div style="font-size:0.88rem;color:var(--text-muted);">Letter Grade</div>'
        +'</div>'
        +'<div class="glass-panel" style="padding:14px;text-align:center;">'
            +'<div style="font-size:1.25rem;font-weight:700;color:#00CEC9;">'+gpa4+'</div>'
            +'<div style="font-size:0.88rem;color:var(--text-muted);">GPA (4.0)</div>'
        +'</div>'
        +'<div class="glass-panel" style="padding:14px;text-align:center;">'
            +'<div style="font-size:1.25rem;font-weight:700;color:#fdcb6e;">'+courses.length+'</div>'
            +'<div style="font-size:0.88rem;color:var(--text-muted);">Courses</div>'
        +'</div>'
    +'</div>';

    // Overall grade progress bar
    if (overallPct !== null) {
        var barColor = gradeColor(overallPct);
        html += '<div class="glass-panel" style="padding:14px;margin-bottom:16px;">'
            +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;">'
                +'<span style="font-size:0.9rem;font-weight:600;color:white;">Overall Progress</span>'
                +(bestCourse?'<span style="font-size:0.85rem;color:var(--text-muted);">Best: '+bestCourse.name+' ('+bestCourse.avg.toFixed(1)+'%)</span>':'')
            +'</div>'
            +'<div style="height:10px;background:rgba(255,255,255,0.08);border-radius:5px;overflow:hidden;">'
                +'<div style="height:100%;width:'+Math.min(100,overallPct)+'%;background:linear-gradient(90deg,'+barColor+','+barColor+'cc);border-radius:5px;transition:width 0.5s;"></div>'
            +'</div>'
            +'<div style="display:flex;justify-content:space-between;font-size:0.9rem;color:var(--text-muted);margin-top:4px;">'
                +'<span>0%</span><span>60% (D)</span><span>70% (C)</span><span>80% (B)</span><span>90% (A)</span><span>100%</span>'
            +'</div>'
        +'</div>';
    }

    courses.forEach(function(course) {
        var avg = calcCourseAvg(course);
        var letter = letterGradeDetailed(avg);
        var color  = gradeColor(avg);
        var pct    = avg !== null ? avg.toFixed(1) : '—';

        // Target tracking
        var targetNote = '';
        if (avg !== null && course.targetGrade) {
            var needed = calcNeededScore(course);
            if (avg >= course.targetGrade) {
                targetNote = '<div style="font-size:0.9rem;color:#00b894;padding:7px 10px;background:rgba(0,184,148,0.1);border-radius:7px;margin-bottom:10px;display:flex;align-items:center;gap:9px;"><i class="ph ph-check-circle"></i> On track for your '+course.targetGrade+'% target</div>';
            } else if (needed !== null) {
                targetNote = '<div style="font-size:0.9rem;color:#fdcb6e;padding:7px 10px;background:rgba(253,203,110,0.1);border-radius:7px;margin-bottom:10px;display:flex;align-items:center;gap:9px;"><i class="ph ph-warning"></i> Need '+needed+'% on next assessment to reach '+course.targetGrade+'%</div>';
            }
        }

        // Grade progress bar
        var barWidth = avg !== null ? Math.min(100, avg).toFixed(0) : 0;
        var gradeBar = '<div style="height:6px;background:rgba(255,255,255,0.07);border-radius:3px;overflow:hidden;margin-bottom:10px;">'
            +'<div style="height:100%;width:'+barWidth+'%;background:linear-gradient(90deg,'+color+','+color+'aa);border-radius:3px;transition:width 0.5s;"></div>'
            +'</div>';

        // Category type breakdown
        var catCounts = {};
        (course.grades||[]).forEach(function(g){ var c=g.category||'other'; catCounts[c]=(catCounts[c]||0)+1; });
        var catBreakdown = Object.keys(catCounts).length > 1
            ? '<div style="display:flex;gap:9px;flex-wrap:wrap;margin-bottom:10px;">'
                + Object.keys(catCounts).map(function(c){ return '<span style="font-size:0.88rem;padding:2px 8px;border-radius:10px;background:'+(GRADE_CATEGORY_COLORS[c]||'var(--text-muted)')+'22;color:'+(GRADE_CATEGORY_COLORS[c]||'var(--text-muted)')+';border:1px solid '+(GRADE_CATEGORY_COLORS[c]||'var(--text-muted)')+'44;">'+c+': '+catCounts[c]+'</span>'; }).join('')
              + '</div>'
            : '';

        var gradesHtml = (course.grades||[]).map(function(g,gi){
            var catColor = GRADE_CATEGORY_COLORS[g.category||'other'] || 'var(--text-muted)';
            var catTag = g.category ? '<span style="font-size:0.88rem;padding:1px 6px;border-radius:8px;background:'+catColor+'22;color:'+catColor+';border:1px solid '+catColor+'44;margin-right:4px;">'+g.category+'</span>' : '';
            return '<div style="display:flex;align-items:center;gap:12px;padding:7px 0;border-bottom:1px solid rgba(255,255,255,0.06);">'
                +'<div style="flex:1;font-size:0.85rem;color:white;min-width:0;">'
                    +'<div style="white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">'+catTag+(g.name||'Grade '+(gi+1))+'</div>'
                +'</div>'
                +'<div style="display:flex;align-items:center;gap:9px;flex-shrink:0;">'
                    +'<div style="font-size:0.85rem;font-weight:600;color:'+gradeColor(parseFloat(g.score))+';">'+g.score+'%</div>'
                    +(g.weight&&g.weight!==1?'<div style="font-size:0.9rem;color:var(--text-muted);">×'+g.weight+'</div>':'')
                    +'<button onclick="deleteGrade('+course.id+','+gi+')" style="background:transparent;border:none;color:#ff6b6b;cursor:pointer;font-size:0.9rem;padding:2px 4px;" title="Delete"><i class="ph ph-x"></i></button>'
                +'</div>'
            +'</div>';
        }).join('');

        html += '<div class="glass-panel" style="padding:16px;margin-bottom:12px;">'
            // Course header
            +'<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;flex-wrap:wrap;gap:12px;">'
                +'<div style="min-width:0;flex:1;">'
                    +'<div style="font-weight:700;color:white;font-size:1.05rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+course.name+'</div>'
                    +'<div style="font-size:0.88rem;color:var(--text-muted);">'+course.grades.length+' grade'+(course.grades.length!==1?'s':'')+' entered'+(course.targetGrade?' &bull; Target: '+course.targetGrade+'%':'')+'</div>'
                +'</div>'
                +'<div style="text-align:right;flex-shrink:0;">'
                    +'<div style="font-size:1.35rem;font-weight:700;line-height:1;color:'+color+';">'+letter+'</div>'
                    +'<div style="font-size:0.9rem;color:'+color+';">'+pct+'%</div>'
                +'</div>'
            +'</div>'
            + gradeBar
            + targetNote
            + catBreakdown
            + (course.grades.length > 0 ? '<div style="margin-bottom:12px;max-height:200px;overflow-y:auto;">'+gradesHtml+'</div>' : '')
            +'<div style="display:flex;gap:12px;flex-wrap:wrap;">'
                +'<button class="btn-primary" style="font-size:0.9rem;padding:7px 12px;" onclick="openAddGradeModal('+course.id+')"><i class="ph ph-plus"></i> Add Grade</button>'
                +'<button class="btn-secondary" style="font-size:0.9rem;padding:7px 10px;" onclick="openTargetModal('+course.id+')"><i class="ph ph-target"></i> Target</button>'
                +'<button class="btn-secondary" style="font-size:0.9rem;padding:7px 10px;" onclick="openGradeAiAnalysis('+course.id+')"><i class="ph ph-sparkle"></i> AI Advice</button>'
                +'<button style="background:transparent;border:none;color:#ff6b6b;cursor:pointer;font-size:0.9rem;padding:7px 10px;" onclick="deleteCourse('+course.id+')"><i class="ph ph-trash"></i> Remove</button>'
            +'</div>'
        +'</div>';
    });
    panel.innerHTML = html;
}

function openAddCourseModal() {
    var modal = document.createElement('div');
    modal.id = 'grade-modal-overlay';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn 0.2s;';
    modal.onclick = function(e) { if (e.target === modal) modal.remove(); };
    modal.innerHTML = '<div class="glass-panel" style="max-width:380px;width:100%;padding:28px;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;"><h3 style="margin:0;color:white;">Add Course</h3><button class="btn-icon" onclick="document.getElementById(\'grade-modal-overlay\').remove()"><i class="ph ph-x"></i></button></div><label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:4px;">Course Name *</label><input id="grade-course-name" class="input-field" style="width:100%;padding:10px;margin-bottom:14px;" placeholder="e.g. Algebra 1"><label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:4px;">Target Grade (%)</label><input id="grade-course-target" class="input-field" type="number" min="0" max="100" style="width:100%;padding:10px;margin-bottom:18px;" placeholder="e.g. 85"><div style="display:flex;gap:12px;justify-content:flex-end;"><button class="btn-secondary" onclick="document.getElementById(\'grade-modal-overlay\').remove()">Cancel</button><button class="btn-primary" onclick="addCourse()">Add Course</button></div></div>';
    document.body.appendChild(modal);
    setTimeout(function(){ var el=document.getElementById('grade-course-name'); if(el) el.focus(); }, 100);
}
function addCourse() {
    var name = document.getElementById('grade-course-name').value.trim();
    if (!name) { showToast('Course name required.', 'error'); return; }
    var target = parseFloat(document.getElementById('grade-course-target').value) || 0;
    var courses = getGradeCourses();
    courses.push({ id: Date.now(), name: name, targetGrade: target||null, grades: [] });
    saveGradeCourses(courses);
    document.getElementById('grade-modal-overlay').remove();
    renderGradeCalc();
    showToast('Course "'+name+'" added!', 'success', 2000);
}
function openAddGradeModal(courseId) {
    var modal = document.createElement('div');
    modal.id = 'grade-modal-overlay';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.7);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn 0.2s;';
    modal.onclick = function(e) { if (e.target === modal) modal.remove(); };
    modal.innerHTML = `
    <div class="glass-panel" style="max-width:400px;width:100%;padding:28px;">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;">
            <h3 style="margin:0;color:white;"><i class="ph ph-plus-circle" style="color:var(--accent);"></i> Add Grade</h3>
            <button class="btn-icon" onclick="document.getElementById('grade-modal-overlay').remove()"><i class="ph ph-x"></i></button>
        </div>
        <div style="display:flex;flex-direction:column;gap:12px;">
            <div>
                <label style="font-size:0.88rem;color:var(--text-muted);display:block;margin-bottom:4px;">Assignment Name</label>
                <input id="grade-name" class="input-field" placeholder="e.g. Unit 3 Test">
            </div>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;">
                <div>
                    <label style="font-size:0.88rem;color:var(--text-muted);display:block;margin-bottom:4px;">Category</label>
                    <select id="grade-category" class="input-field">
                        <option value="test">Test / Exam</option>
                        <option value="quiz">Quiz</option>
                        <option value="homework" selected>Homework</option>
                        <option value="project">Project</option>
                        <option value="lab">Lab</option>
                        <option value="participation">Participation</option>
                        <option value="other">Other</option>
                    </select>
                </div>
                <div>
                    <label style="font-size:0.88rem;color:var(--text-muted);display:block;margin-bottom:4px;">Score (%)*</label>
                    <input id="grade-score" class="input-field" type="number" min="0" max="100" placeholder="e.g. 87">
                </div>
            </div>
            <div>
                <label style="font-size:0.88rem;color:var(--text-muted);display:block;margin-bottom:4px;">Weight (optional — 1 = normal)</label>
                <input id="grade-weight" class="input-field" type="number" min="0" max="10" step="0.5" placeholder="1">
            </div>
        </div>
        <div style="display:flex;gap:12px;justify-content:flex-end;margin-top:18px;">
            <button class="btn-secondary" onclick="document.getElementById('grade-modal-overlay').remove()">Cancel</button>
            <button class="btn-primary" onclick="addGrade(${courseId})">Add Grade</button>
        </div>
    </div>`;
    document.body.appendChild(modal);
    setTimeout(function(){ var el=document.getElementById('grade-name'); if(el) el.focus(); }, 100);
}
function addGrade(courseId) {
    var score = parseFloat(document.getElementById('grade-score').value);
    if (isNaN(score)||score<0||score>100) { showToast('Enter a valid score (0-100).', 'error'); return; }
    var name     = (document.getElementById('grade-name').value||'').trim() || 'Grade';
    var category = (document.getElementById('grade-category')||{}).value || 'other';
    var weight   = parseFloat(document.getElementById('grade-weight').value)||1;
    var courses = getGradeCourses();
    var idx = courses.findIndex(function(c){ return c.id===courseId; });
    if (idx<0) return;
    courses[idx].grades.push({ name: name, score: score, weight: weight, category: category });
    saveGradeCourses(courses);
    document.getElementById('grade-modal-overlay').remove();
    renderGradeCalc();
    showToast('Grade added!', 'success', 2000);
    logStudyEvent('grade', `${courses[idx].name}: ${name} — ${score}% (${category})`);
}
function openTargetModal(courseId) {
    var courses = getGradeCourses();
    var course = courses.find(function(c){ return c.id===courseId; });
    if (!course) return;
    var t = prompt('Set target grade (%) for "'+course.name+'":', course.targetGrade||'');
    if (t === null) return;
    var val = parseFloat(t);
    course.targetGrade = isNaN(val) ? null : Math.max(0,Math.min(100,val));
    saveGradeCourses(courses);
    renderGradeCalc();
    showToast('Target updated!', 'success', 1800);
}
function deleteGrade(courseId, gradeIdx) {
    var courses = getGradeCourses();
    var idx = courses.findIndex(function(c){ return c.id===courseId; });
    if (idx<0) return;
    courses[idx].grades.splice(gradeIdx, 1);
    saveGradeCourses(courses);
    renderGradeCalc();
}
function deleteCourse(courseId) {
    if (!confirm('Remove this course and all its grades?')) return;
    saveGradeCourses(getGradeCourses().filter(function(c){ return c.id!==courseId; }));
    renderGradeCalc();
    showToast('Course removed.', 'info', 1500);
}

// v13.1 — AI academic advice for a specific course
async function openGradeAiAnalysis(courseId) {
    var courses = getGradeCourses();
    var course = courses.find(function(c){ return c.id===courseId; });
    if (!course) return;
    var apiKey = getApiKey();
    if (!apiKey) { showToast('Add your API key in Settings to use AI analysis.','error',3000); return; }

    var avg = calcCourseAvg(course);
    var letter = letterGradeDetailed(avg);
    var gradeList = (course.grades||[]).map(function(g){ return g.category+': '+g.name+' = '+g.score+'%'+(g.weight&&g.weight!==1?' (weight: '+g.weight+')':''); }).join(', ');

    var modal = document.createElement('div');
    modal.id = 'grade-ai-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.82);backdrop-filter:blur(6px);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn 0.2s;';
    modal.onclick = function(e){ if(e.target===modal) modal.remove(); };
    modal.innerHTML = '<div class="glass-panel" style="max-width:500px;width:100%;padding:0;border:1px solid rgba(0,206,201,0.35);overflow:hidden;">'
        +'<div style="padding:14px 20px;border-bottom:1px solid rgba(255,255,255,0.1);background:linear-gradient(135deg,rgba(0,206,201,0.1),rgba(108,92,231,0.08));display:flex;align-items:center;gap:10px;">'
            +'<div style="flex:1;"><div style="font-size:0.9rem;color:var(--accent);font-weight:700;letter-spacing:1.2px;margin-bottom:2px;">AI ACADEMIC ADVISOR</div><div style="color:white;font-size:0.92rem;font-weight:600;">'+course.name+'</div></div>'
            +'<button class="btn-icon" onclick="document.getElementById(\'grade-ai-modal\').remove()"><i class="ph ph-x"></i></button>'
        +'</div>'
        +'<div style="padding:20px;" id="grade-ai-body"><div style="color:var(--accent);display:flex;align-items:center;gap:12px;"><i class="ph ph-spinner ph-spin"></i> Analyzing your grades…</div></div>'
    +'</div>';
    document.body.appendChild(modal);

    try {
        var res = await fetch('https://api.openai.com/v1/chat/completions', {
            method:'POST',
            headers:{'Content-Type':'application/json','Authorization':'Bearer '+apiKey},
            body: JSON.stringify({
                model:'gpt-4o-mini',
                messages:[
                    {role:'system', content:`You are NEXUS academic advisor. Analyze a student's grade data and give actionable, encouraging advice.
Format your response as clean HTML (no markdown). Use <strong>, <ul><li>, <br>.
Be specific and practical. Keep it under 250 words.`},
                    {role:'user', content:`Course: ${course.name}\nCurrent average: ${avg!==null?avg.toFixed(1)+'%':'Not enough grades'} (${letter})\nTarget: ${course.targetGrade?course.targetGrade+'%':'Not set'}\nGrades: ${gradeList||'No grades yet.'}\n\nGive me: 1) What my grade trend shows 2) Specific things to focus on 3) How to reach my target if set.`}
                ],
                temperature:0.6,max_tokens:400
            })
        });
        var data = await res.json();
        if(data.error) throw new Error(data.error.message);
        var answer = data.choices[0].message.content||'';
        var cleaned = typeof convertMarkdownLeaks==='function'?convertMarkdownLeaks(answer):answer;
        var body = document.getElementById('grade-ai-body');
        if(body){ body.style.opacity='0'; body.innerHTML='<div style="line-height:1.65;font-size:0.88rem;color:#dde0ee;">'+cleaned+'</div>'; requestAnimationFrame(function(){body.style.transition='opacity 0.35s';body.style.opacity='1';}); }
    } catch(err) {
        var b=document.getElementById('grade-ai-body'); if(b) b.innerHTML='<p style="color:#ff6b6b;">Error: '+err.message+'</p>';
    }
}
function exportGradesPDF() {
    var courses = getGradeCourses();
    var w = window.open('', '_blank');
    if (!w) { showToast('Allow pop-ups to export.', 'error'); return; }
    var avgs = courses.map(calcCourseAvg).filter(function(a){ return a!==null; });
    var overall = avgs.length ? (avgs.reduce(function(s,a){return s+a;},0)/avgs.length).toFixed(1) : '—';
    var rows = courses.map(function(c){ var avg=calcCourseAvg(c); return '<tr><td>'+c.name+'</td><td>'+c.grades.length+'</td><td>'+(avg!==null?avg.toFixed(1)+'%':'—')+'</td><td>'+letterGrade(avg)+'</td><td>'+(c.targetGrade?c.targetGrade+'%':'—')+'</td></tr>'; }).join('');
    w.document.write('<!DOCTYPE html><html><head><title>Grades — NEXUS</title><style>body{font-family:sans-serif;padding:24px;}h2{color:#6C5CE7;}table{width:100%;border-collapse:collapse;}th,td{border:1px solid #ccc;padding:8px;text-align:left;}th{background:#f0f0f0;}</style></head><body><h2>NEXUS Grade Report</h2><p>'+new Date().toLocaleDateString()+' | Overall: '+overall+'%</p><table><tr><th>Course</th><th>Grades</th><th>Average</th><th>Letter</th><th>Target</th></tr>'+rows+'</table></body></html>');
    w.document.close(); w.print();
}

// ─────────────────────────────────────────
// CITATION GENERATOR
// ─────────────────────────────────────────
function getSavedCitations() {
    try { return JSON.parse(localStorage.getItem('saved_citations') || '[]'); } catch { return []; }
}
function saveCitations(c) { localStorage.setItem('saved_citations', JSON.stringify(c)); }
var _citStyle = 'mla', _citType = 'book', _citationResult = '';

function renderCitationTab() {
    var panel = document.getElementById('citation-panel');
    if (!panel) return;
    var saved = getSavedCitations();
    var styleOpts = ['mla','apa','chicago'].map(function(v){
        return '<option value="'+v+'"'+(_citStyle===v?' selected':'')+'>'+{'mla':'MLA 9th','apa':'APA 7th','chicago':'Chicago'}[v]+'</option>';
    }).join('');
    var typeOpts = ['book','website','journal','newspaper','video'].map(function(v){
        return '<option value="'+v+'"'+(_citType===v?' selected':'')+'>'+{'book':'Book','website':'Website','journal':'Journal Article','newspaper':'Newspaper','video':'Online Video'}[v]+'</option>';
    }).join('');
    var savedHtml = saved.length > 0 ? '<div style="margin-top:24px;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;"><h4 style="margin:0;color:white;">Saved Citations ('+saved.length+')</h4><div style="display:flex;gap:12px;"><button class="btn-secondary" style="font-size:0.9rem;padding:6px 10px;" onclick="exportCitationsPDF()"><i class="ph ph-printer"></i> Export</button><button class="btn-secondary" style="font-size:0.9rem;padding:6px 10px;color:#ff6b6b;" onclick="clearAllCitations()"><i class="ph ph-trash"></i> Clear</button></div></div>'
        +saved.map(function(c,i){ return '<div class="glass-panel" style="padding:12px 14px;margin-bottom:8px;display:flex;align-items:center;gap:10px;"><div style="flex:1;font-size:0.85rem;color:white;font-family:serif;">'+c.text+'</div><div style="display:flex;gap:9px;flex-shrink:0;"><button onclick="copyCitation('+i+')" style="background:transparent;border:none;color:var(--text-muted);cursor:pointer;font-size:1rem;" title="Copy"><i class="ph ph-copy"></i></button><button onclick="deleteSavedCitation('+i+')" style="background:transparent;border:none;color:#ff6b6b;cursor:pointer;font-size:1rem;" title="Delete"><i class="ph ph-trash"></i></button></div></div>'; }).join('')
        +'</div>' : '';
    panel.innerHTML = '<div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px;"><div><label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:4px;">Format</label><select id="cit-style" class="input-field" style="width:100%;padding:10px;" onchange="_citStyle=this.value;renderCitationForm()">'+styleOpts+'</select></div><div><label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:4px;">Source Type</label><select id="cit-type" class="input-field" style="width:100%;padding:10px;" onchange="_citType=this.value;renderCitationForm()">'+typeOpts+'</select></div></div><div id="cit-form-area"></div><div id="cit-result-area" style="margin-top:16px;"></div>'+savedHtml;
    renderCitationForm();
}
function copyCitation(idx) {
    var saved = getSavedCitations();
    if (saved[idx]) {
        navigator.clipboard.writeText(saved[idx].text).then(function(){ showToast('Copied!', 'success', 1800); }).catch(function(){
            var ta = document.createElement('textarea'); ta.value = saved[idx].text; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); showToast('Copied!', 'success', 1800);
        });
    }
}
function copyText(text) {
    navigator.clipboard.writeText(text).then(function(){ showToast('Copied!', 'success', 1800); }).catch(function(){
        var ta = document.createElement('textarea'); ta.value = text; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); showToast('Copied!', 'success', 1800);
    });
}
var _CIT_FIELDS_V13 = {
    book:      [{id:'author',label:'Author(s)',ph:'Last, First',req:1},{id:'title',label:'Title',ph:'Full title',req:1},{id:'publisher',label:'Publisher',ph:'Publisher'},{id:'year',label:'Year',ph:'2024'},{id:'city',label:'City',ph:'New York'},{id:'pages',label:'Pages',ph:'12-34'}],
    website:   [{id:'author',label:'Author / Site Name',ph:'Last, First or Site'},{id:'title',label:'Page Title',ph:'Full title',req:1},{id:'site',label:'Website Name',ph:'Example.com',req:1},{id:'url',label:'URL',ph:'https://...',req:1},{id:'published',label:'Published Date',ph:'12 Jan 2024'},{id:'accessed',label:'Accessed Date',ph:'15 May 2024'}],
    journal:   [{id:'author',label:'Author(s)',ph:'Last, First',req:1},{id:'title',label:'Article Title',ph:'Full title',req:1},{id:'journal',label:'Journal Name',ph:'Journal of...',req:1},{id:'volume',label:'Volume',ph:'12'},{id:'issue',label:'Issue',ph:'3'},{id:'year',label:'Year',ph:'2024'},{id:'pages',label:'Pages',ph:'45-67'},{id:'doi',label:'DOI / URL',ph:'10.1000/...'}],
    newspaper: [{id:'author',label:'Author(s)',ph:'Last, First',req:1},{id:'title',label:'Article Title',ph:'Full title',req:1},{id:'paper',label:'Newspaper Name',ph:'The New York Times',req:1},{id:'date',label:'Date',ph:'15 Jan 2024',req:1},{id:'pages',label:'Page(s)',ph:'A1'},{id:'url',label:'URL (online)',ph:'https://...'}],
    video:     [{id:'author',label:'Channel / Creator',ph:'Channel Name',req:1},{id:'title',label:'Video Title',ph:'Full title',req:1},{id:'site',label:'Platform',ph:'YouTube',req:1},{id:'date',label:'Upload Date',ph:'15 Jan 2024'},{id:'url',label:'URL',ph:'https://...',req:1}]
};
function renderCitationForm() {
    var area = document.getElementById('cit-form-area');
    if (!area) return;
    var fields = _CIT_FIELDS_V13[_citType] || _CIT_FIELDS_V13.book;
    area.innerHTML = '<div style="display:flex;flex-direction:column;gap:10px;">'
        + fields.map(function(f){ return '<div><label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:3px;">'+f.label+(f.req?'<span style="color:#ff6b6b;"> *</span>':'')+'</label><input id="cit-field-'+f.id+'" class="input-field" style="width:100%;padding:10px;" placeholder="'+(f.ph||'')+'"></div>'; }).join('')
        + '</div><button class="btn-primary" style="margin-top:14px;width:100%;" onclick="generateCitation()"><i class="ph ph-quotes"></i> Generate Citation</button>';
}
function getField(id) { var el=document.getElementById('cit-field-'+id); return el?el.value.trim():''; }
function generateCitation() {
    var s=_citStyle, t=_citType;
    var a=getField('author'), ti=getField('title'), year=getField('year'), pub=getField('publisher'), city=getField('city');
    var site=getField('site'), url=getField('url'), acc=getField('accessed'), pub2=getField('published');
    var journal=getField('journal'), vol=getField('volume'), iss=getField('issue'), pages=getField('pages'), doi=getField('doi');
    var paper=getField('paper'), date=getField('date'), edition=getField('edition');
    var cit = '';
    if (s==='mla') {
        if (t==='book')      cit=(a?a+'. ':'')+'’'+ti+'’.'+(edition?' '+edition+',':'')+' '+(pub?pub+',':'')+' '+(year||'')+'.';
        else if (t==='website') cit=(a?a+'. ':'')+'"'+ti+'." ’'+site+'’,'+(pub2?' '+pub2+',':'')+' '+url+'.'+(acc?' Accessed '+acc+'.':'');
        else if (t==='journal') cit=a+'. "'+ti+'." ’'+journal+'’, vol. '+(vol||'?')+', no. '+(iss||'?')+', '+(year||'n.d.')+', pp. '+(pages||'n.p.')+'.'+(doi?' doi:'+doi:'');
        else if (t==='newspaper') cit=a+'. "'+ti+'." ’'+paper+'’, '+date+(pages?', p. '+pages:'')+'.'+(url?' '+url+'.':'');
        else if (t==='video') cit=a+'. "'+ti+'." ’'+site+'’,'+(date?' '+date+',':'')+' '+url+'.';
    } else if (s==='apa') {
        if (t==='book')      cit=(a||'Author')+' ('+(year||'n.d.')+').'+(ti?' *'+ti+'*'+(edition?' ('+edition+')':'')+'.':(':'+''))+' '+(pub||'Publisher')+'.';
        else if (t==='website') cit=(a||site)+' ('+(pub2||'n.d.')+').'+' '+ti+'. *'+site+'*. '+url;
        else if (t==='journal') cit=a+' ('+(year||'n.d.')+').'+' '+ti+'. *'+journal+'*, *'+(vol||'?')+'*('+(iss||'?')+'), '+(pages||'n.p.')+'.'+(doi?' https://doi.org/'+doi:'');
        else if (t==='newspaper') cit=a+' ('+date+').'+' '+ti+'. *'+paper+'*'+(pages?', '+pages:'')+'.'+(url?' '+url:'');
        else if (t==='video') cit=a+' ['+site+']. ('+(date||'n.d.')+').'+' *'+ti+'* [Video]. '+site+'. '+url;
    } else if (s==='chicago') {
        if (t==='book')      cit=a+'. *'+ti+'*. '+(city?city+': ':'')+''+(pub||'Publisher')+', '+(year||'n.d.')+'.';
        else if (t==='website') cit=(a||site)+'. "'+ti+'." '+site+'.'+(pub2?' '+pub2+'.':'')+' '+url+'.';
        else if (t==='journal') cit=a+'. "'+ti+'." *'+journal+'* '+(vol||'?')+', no. '+(iss||'?')+' ('+(year||'n.d.')+'): '+(pages||'n.p.')+'.'+(doi?' https://doi.org/'+doi+'.':'');
        else if (t==='newspaper') cit=a+'. "'+ti+'." *'+paper+'*, '+date+(pages?', '+pages:'')+'.';
        else if (t==='video') cit=a+'. "'+ti+'." '+site+' video, '+(date||'n.d.')+'. '+url+'.';
    }
    cit = (cit||'').replace(/\s+/g,' ').trim();
    if (!cit||cit.replace(/[.*\s]/g,'').length<5) { showToast('Fill in the required fields.', 'error'); return; }
    _citationResult = cit;
    var area = document.getElementById('cit-result-area');
    if (area) area.innerHTML = '<div class="glass-panel" style="padding:14px;border:1px solid rgba(0,206,201,0.3);"><div style="font-size:0.85rem;color:var(--accent);font-weight:700;letter-spacing:1px;margin-bottom:8px;">'+s.toUpperCase()+' — '+t.charAt(0).toUpperCase()+t.slice(1)+'</div><div id="cit-output-text" style="font-size:0.92rem;color:white;font-family:serif;line-height:1.6;">'+cit+'</div><div style="display:flex;gap:12px;margin-top:12px;"><button class="btn-primary" style="font-size:0.9rem;padding:6px 12px;" onclick="copyText(\''+cit.replace(/'/g,"\\'")+'\')" ><i class="ph ph-copy"></i> Copy</button><button class="btn-secondary" style="font-size:0.9rem;padding:6px 12px;" onclick="saveCitation()"><i class="ph ph-bookmark-simple"></i> Save</button></div></div>';
}
function saveCitation() {
    if (!_citationResult) return;
    var saved = getSavedCitations();
    saved.unshift({ text: _citationResult, style: _citStyle, type: _citType, date: Date.now() });
    if (saved.length > 50) saved.splice(50);
    saveCitations(saved);
    renderCitationTab();
    showToast('Citation saved!', 'success', 2000);
}
function deleteSavedCitation(idx) {
    var saved = getSavedCitations(); saved.splice(idx,1); saveCitations(saved); renderCitationTab();
}
function clearAllCitations() {
    if (!confirm('Clear all saved citations?')) return; saveCitations([]); renderCitationTab(); showToast('Cleared.','info',1500);
}
function exportCitationsPDF() {
    var saved = getSavedCitations();
    var w = window.open('','_blank');
    if (!w) { showToast('Allow pop-ups.','error'); return; }
    w.document.write('<!DOCTYPE html><html><head><title>Citations</title><style>body{font-family:Georgia,serif;padding:24px;color:#111;}h2{font-family:sans-serif;color:#6C5CE7;}p{margin:0 0 12px;padding:8px 0;border-bottom:1px solid #eee;}</style></head><body><h2>NEXUS Citations</h2><p style="font-family:sans-serif;color:#666;border:none;">'+new Date().toLocaleDateString()+'</p>'+saved.map(function(c,i){ return '<p>'+(i+1)+'. '+c.text+'</p>'; }).join('')+'</body></html>');
    w.document.close(); w.print();
}

// ─────────────────────────────────────────
// QUICK STUDY QUIZ — Subject-specific entry point
// ─────────────────────────────────────────
function openQuickStudyQuiz(subject) {
    const subjectColors = {
        'Math':'#6c5ce7','Science':'#00b894','English':'#a29bfe','Social Studies':'#fd79a8'
    };
    const color = subjectColors[subject] || 'var(--accent)';
    const existing = document.getElementById('quick-quiz-modal');
    if (existing) existing.remove();

    const modal = document.createElement('div');
    modal.id = 'quick-quiz-modal';
    modal.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,0.85);backdrop-filter:blur(8px);z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;animation:fadeIn 0.2s;';
    modal.onclick = e => { if (e.target === modal) modal.remove(); };

    modal.innerHTML = `
    <div class="glass-panel" style="max-width:540px;width:100%;padding:0;border:1px solid ${color}55;overflow:hidden;max-height:88vh;display:flex;flex-direction:column;">
        <div style="padding:14px 20px;border-bottom:1px solid rgba(255,255,255,0.1);background:linear-gradient(135deg,${color}22,rgba(0,0,0,0.2));display:flex;align-items:center;gap:10px;">
            <div style="flex:1;min-width:0;">
                <div style="font-size:0.9rem;color:${color};font-weight:700;letter-spacing:1.2px;text-transform:uppercase;">Quiz Yourself</div>
                <div style="color:white;font-size:0.92rem;font-weight:600;">${subject} — AI Quiz Generator</div>
            </div>
            <button class="btn-icon" onclick="document.getElementById('quick-quiz-modal').remove()"><i class="ph ph-x"></i></button>
        </div>
        <div style="padding:20px;overflow-y:auto;flex:1;" id="quick-quiz-body">
            <p style="font-size:0.85rem;color:var(--text-muted);margin:0 0 14px;">Paste notes, a textbook excerpt, or describe a topic and the AI will generate a quiz for you.</p>
            <textarea id="quick-quiz-input" class="input-field" style="width:100%;min-height:130px;resize:vertical;font-size:0.88rem;" placeholder="Paste your ${subject} notes here, or just type a topic like 'photosynthesis' or 'quadratic equations'…"></textarea>
            <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0;">
                <div>
                    <label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:4px;">Questions</label>
                    <select id="quick-quiz-count" class="input-field" style="width:100%;padding:10px;">
                        <option value="5">5</option><option value="10" selected>10</option><option value="15">15</option>
                    </select>
                </div>
                <div>
                    <label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:4px;">Difficulty</label>
                    <select id="quick-quiz-diff" class="input-field" style="width:100%;padding:10px;">
                        <option value="easy">Easy</option><option value="medium" selected>Medium</option><option value="hard">Hard</option>
                    </select>
                </div>
            </div>
            <button id="quick-quiz-btn" class="btn-primary" style="width:100%;padding:12px;" onclick="runQuickStudyQuiz('${subject}')">
                <i class="ph ph-magic-wand"></i> Generate Quiz
            </button>
            <div id="quick-quiz-status" style="margin-top:10px;color:var(--text-muted);font-size:0.85rem;text-align:center;"></div>
            <div id="quick-quiz-result" style="margin-top:14px;"></div>
        </div>
    </div>`;
    document.body.appendChild(modal);
    setTimeout(() => { const el = document.getElementById('quick-quiz-input'); if (el) el.focus(); }, 100);
}

async function runQuickStudyQuiz(subject) {
    const text    = (document.getElementById('quick-quiz-input')||{}).value || '';
    const count   = parseInt((document.getElementById('quick-quiz-count')||{}).value || '10');
    const diff    = (document.getElementById('quick-quiz-diff')||{}).value || 'medium';
    const btn     = document.getElementById('quick-quiz-btn');
    const status  = document.getElementById('quick-quiz-status');
    const result  = document.getElementById('quick-quiz-result');

    if (text.trim().length < 10) { showToast('Add some notes or a topic first.','error'); return; }

    const apiKey = getApiKey();
    if (!apiKey) { showToast('Add API key in Settings to use quiz generation.','error',3500); return; }

    if (btn) { btn.disabled = true; btn.innerHTML = '<i class="ph ph-spinner ph-spin"></i> Generating…'; }
    if (status) status.textContent = 'Asking AI to create your quiz…';
    if (result) result.innerHTML = '';

    const systemPrompt = `You are a quiz generator. Create exactly ${count} multiple-choice ${diff} ${subject} questions from the given text/topic. Return ONLY valid JSON in this format:
[{"q":"Question text","options":["A","B","C","D"],"correct":0}]
where "correct" is the 0-based index of the right answer. No commentary, just JSON.`;

    try {
        const res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${apiKey}` },
            body: JSON.stringify({
                model: 'gpt-4o',
                messages: [
                    { role: 'system', content: systemPrompt },
                    { role: 'user', content: text.length > 3000 ? text.substring(0, 3000) : text }
                ],
                temperature: 0.6, max_tokens: 2000
            })
        });
        const data = await res.json();
        if (data.error) throw new Error(data.error.message);
        let raw = data.choices[0].message.content || '';
        const jsonStart = raw.indexOf('[');
        const jsonEnd   = raw.lastIndexOf(']') + 1;
        if (jsonStart < 0) throw new Error('No quiz data returned');
        raw = raw.substring(jsonStart, jsonEnd);
        const questions = JSON.parse(raw);

        // Load into main quiz gen and launch
        _quizGenQuestions = questions;
        _quizGenActive    = true;
        _quizGenCurrent   = 0;
        _quizGenScore     = 0;
        _quizGenAnswers   = [];

        // Close the quick modal and open the Notebook's Quiz Gen tab with the quiz
        const modal = document.getElementById('quick-quiz-modal');
        if (modal) modal.remove();
        switchTab('notebook');
        setTimeout(() => {
            switchNotebookTab('quiz');
            const panel = document.getElementById('quizgen-panel');
            if (panel) renderQuizGenQuestion(panel);
            logStudyEvent('study', `${subject} quiz — ${count} questions`);
        }, 250);
    } catch (err) {
        if (btn) { btn.disabled = false; btn.innerHTML = '<i class="ph ph-magic-wand"></i> Generate Quiz'; }
        if (status) status.textContent = 'Error: ' + err.message;
    }
}

// ─────────────────────────────────────────
// QUIZ GENERATOR (AI)
// ─────────────────────────────────────────
var _quizGenQuestions=[], _quizGenActive=false, _quizGenCurrent=0, _quizGenScore=0, _quizGenAnswers=[];
function renderQuizGen() {
    var panel = document.getElementById('quizgen-panel');
    if (!panel) return;
    if (_quizGenActive) { renderQuizGenQuestion(panel); return; }
    panel.innerHTML = '<div style="margin-bottom:16px;"><label style="font-size:0.85rem;color:var(--text-muted);display:block;margin-bottom:6px;">Paste your notes, textbook excerpt, or any text. The AI generates a multiple-choice quiz from it.</label><textarea id="quizgen-input" class="input-field" style="width:100%;min-height:160px;padding:12px;resize:vertical;font-size:0.9rem;line-height:1.5;" placeholder="Paste notes here..."></textarea></div><div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:16px;"><div><label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:4px;">Questions</label><select id="quizgen-count" class="input-field" style="width:100%;padding:10px;"><option value="5">5</option><option value="10" selected>10</option><option value="15">15</option><option value="20">20</option></select></div><div><label style="font-size:0.9rem;color:var(--text-muted);display:block;margin-bottom:4px;">Difficulty</label><select id="quizgen-diff" class="input-field" style="width:100%;padding:10px;"><option value="easy">Easy</option><option value="medium" selected>Medium</option><option value="hard">Hard</option></select></div></div><button id="quizgen-btn" class="btn-primary" style="width:100%;padding:12px;" onclick="generateNotesQuiz()"><i class="ph ph-magic-wand"></i> Generate Quiz from Notes</button><div id="quizgen-status" style="margin-top:12px;color:var(--text-muted);font-size:0.85rem;text-align:center;"></div>';
}
async function generateNotesQuiz() {
    var text = (document.getElementById('quizgen-input') ? document.getElementById('quizgen-input').value : '').trim();
    if (text.length < 50) { showToast('Paste at least 50 characters of notes.', 'error'); return; }
    var apiKey = getApiKey();
    if (!apiKey) { showToast('Add your OpenAI API key in Settings > AI.', 'error'); return; }
    var count = parseInt((document.getElementById('quizgen-count')||{}).value||'10');
    var diff  = (document.getElementById('quizgen-diff')||{}).value||'medium';
    var btn = document.getElementById('quizgen-btn');
    var status = document.getElementById('quizgen-status');
    if (btn) { btn.disabled=true; btn.innerHTML='<i class="ph ph-circle-notch" style="animation:spin 1s linear infinite"></i> Generating...'; }
    if (status) status.textContent='Analyzing your notes and building questions...';
    try {
        var res = await fetch('https://api.openai.com/v1/chat/completions', {
            method:'POST',
            headers:{'Content-Type':'application/json','Authorization':'Bearer '+apiKey},
            body: JSON.stringify({
                model:'gpt-4o',
                response_format:{type:'json_object'},
                messages:[
                    {role:'system',content:'You are a quiz maker. Create exactly '+count+' multiple-choice questions at '+diff+' difficulty from the provided text. Each question has exactly 4 options labeled A, B, C, D. Return STRICT JSON: {"questions":[{"q":"question","options":["A. ...","B. ...","C. ...","D. ..."],"answer":"A"}]}'},
                    {role:'user',content:'Text:\n'+text.slice(0,8000)}
                ]
            })
        });
        var data = await res.json();
        if (data.error) throw new Error(data.error.message);
        var parsed = JSON.parse(data.choices[0].message.content);
        if (!parsed.questions||parsed.questions.length===0) throw new Error('No questions returned.');
        _quizGenQuestions=parsed.questions; _quizGenActive=true; _quizGenCurrent=0; _quizGenScore=0; _quizGenAnswers=[];
        var panel=document.getElementById('quizgen-panel'); if(panel) renderQuizGenQuestion(panel);
    } catch(err) {
        showToast('Quiz error: '+err.message,'error',4000);
        if (btn) { btn.disabled=false; btn.innerHTML='<i class="ph ph-magic-wand"></i> Generate Quiz from Notes'; }
        if (status) status.textContent='';
    }
}
function renderQuizGenQuestion(panel) {
    if (_quizGenCurrent>=_quizGenQuestions.length) { renderQuizGenResults(panel); return; }
    var q=_quizGenQuestions[_quizGenCurrent], total=_quizGenQuestions.length;
    panel.innerHTML='<div style="margin-bottom:16px;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><div style="font-size:0.9rem;color:var(--text-muted);">Question '+(_quizGenCurrent+1)+' of '+total+'</div><div style="font-size:0.9rem;color:var(--accent);">Score: '+_quizGenScore+'/'+_quizGenCurrent+'</div></div><div style="height:4px;background:rgba(255,255,255,0.1);border-radius:2px;margin-bottom:18px;"><div style="width:'+((_quizGenCurrent/total)*100)+'%;height:100%;background:var(--accent);border-radius:2px;"></div></div><div style="font-size:1.05rem;font-weight:600;color:white;line-height:1.5;margin-bottom:20px;">'+q.q+'</div><div style="display:flex;flex-direction:column;gap:10px;">'
        +q.options.map(function(opt,i){ var L=String.fromCharCode(65+i); return '<button class="quiz-gen-opt" data-letter="'+L+'" onclick="selectQuizGenAnswer(\''+L+'\')" style="width:100%;text-align:left;padding:14px 16px;border-radius:10px;border:1px solid rgba(255,255,255,0.15);background:rgba(255,255,255,0.04);color:white;cursor:pointer;font-size:0.92rem;transition:all 0.15s;line-height:1.4;" onmouseenter="this.style.background=\'rgba(0,206,201,0.12)\';this.style.borderColor=\'rgba(0,206,201,0.4)\'" onmouseleave="this.style.background=\'rgba(255,255,255,0.04)\';this.style.borderColor=\'rgba(255,255,255,0.15)\'">'+opt+'</button>'; }).join('')
        +'</div></div>';
}
// Normalize the AI's "answer" to a clean A-D letter. The model returns it
// inconsistently ("A", "a", "A. Photosynthesis", or even the full option text),
// so a strict === against the clicked letter was marking correct picks wrong.
function _quizGenCorrectLetter(q) {
    var a = String(q.answer || '').trim();
    var m = a.match(/^\s*([A-Da-d])(?![A-Za-z])/);   // leading letter not part of a word
    if (m) return m[1].toUpperCase();
    for (var i = 0; i < (q.options || []).length; i++) {   // else match the option text
        var txt = String(q.options[i]).replace(/^[A-Da-d][\.\):\-]\s*/, '').trim().toLowerCase();
        var al = a.toLowerCase();
        if (txt && (al === txt || al.indexOf(txt) !== -1 || txt.indexOf(al) !== -1))
            return String.fromCharCode(65 + i);
    }
    return (a.toUpperCase().match(/[A-D]/) || ['A'])[0];
}
function selectQuizGenAnswer(letter) {
    var q=_quizGenQuestions[_quizGenCurrent], correctL=_quizGenCorrectLetter(q), ok=(letter===correctL);
    _quizGenAnswers.push({q:q.q,selected:letter,correct:correctL,ok:ok});
    if(ok) _quizGenScore++;
    document.querySelectorAll('.quiz-gen-opt').forEach(function(btn){
        btn.style.pointerEvents='none';
        var l=btn.dataset.letter;
        if(l===correctL){btn.style.background='rgba(0,184,148,0.25)';btn.style.borderColor='#00b894';btn.style.color='#00b894';}
        else if(l===letter&&!ok){btn.style.background='rgba(255,107,107,0.2)';btn.style.borderColor='#ff6b6b';btn.style.color='#ff6b6b';}
    });
    setTimeout(function(){
        _quizGenCurrent++;
        var panel=document.getElementById('quizgen-panel'); if(panel) renderQuizGenQuestion(panel);
    },900);
}
function renderQuizGenResults(panel) {
    _quizGenActive=false;
    var total=_quizGenQuestions.length, pct=Math.round((_quizGenScore/total)*100), xpE=Math.round(pct*0.5);
    if(typeof awardXP==='function') awardXP(xpE);
    if(typeof addCredits==='function') addCredits(Math.round(xpE*0.3));
    panel.innerHTML='<div style="text-align:center;margin-bottom:24px;"><div style="font-size:1.35rem;margin-bottom:8px;">'+(pct>=80?'🎉':pct>=60?'👍':'📚')+'</div><div style="font-size:1.4rem;font-weight:700;color:'+(pct>=80?'#00b894':pct>=60?'#fdcb6e':'#ff6b6b')+';">'+pct+'%</div><div style="color:var(--text-muted);margin-top:4px;">'+_quizGenScore+' / '+total+' correct</div><div style="font-size:0.85rem;color:var(--accent);margin-top:8px;">+'+xpE+' XP earned</div></div>'
        +'<div style="display:flex;flex-direction:column;gap:12px;margin-bottom:20px;">'
        +_quizGenAnswers.map(function(a,i){ return '<div class="glass-panel" style="padding:12px;border-left:3px solid '+(a.ok?'#00b894':'#ff6b6b')+';"><div style="font-size:0.85rem;color:white;margin-bottom:4px;">'+(i+1)+'. '+a.q+'</div><div style="font-size:0.9rem;">'+(a.ok?'<span style="color:#00b894;"><i class="ph ph-check-circle"></i> Correct ('+a.correct+')</span>':'<span style="color:#ff6b6b;"><i class="ph ph-x-circle"></i> You chose '+a.selected+' — Correct: '+a.correct+'</span>')+'</div></div>'; }).join('')
        +'</div><div style="display:flex;gap:10px;"><button class="btn-secondary" style="flex:1;" onclick="renderQuizGen()">New Quiz</button><button class="btn-primary" style="flex:1;" onclick="_quizGenCurrent=0;_quizGenScore=0;_quizGenAnswers=[];_quizGenActive=true;var p=document.getElementById(\'quizgen-panel\');if(p)renderQuizGenQuestion(p);">Retry</button></div>';
}

// ─────────────────────────────────────────
// SRS (SPACED REPETITION) — SM-2 Algorithm
// ─────────────────────────────────────────
function srsNextReview(card, rating) {
    var interval=card.interval||0, easeFactor=card.easeFactor||2.5, repetitions=card.repetitions||0;
    if (rating < 3) { repetitions=0; interval=1; }
    else {
        if (repetitions===0) interval=1;
        else if (repetitions===1) interval=6;
        else interval=Math.round(interval*easeFactor);
        repetitions++;
    }
    easeFactor = Math.max(1.3, easeFactor+0.1-(5-rating)*(0.08+(5-rating)*0.02));
    var next=new Date(); next.setDate(next.getDate()+interval);
    return { interval:interval, easeFactor:easeFactor, repetitions:repetitions, nextReview:next.toISOString().slice(0,10) };
}
function getDueFlashcards() {
    var decks=getFlashcardDecks(), today=new Date().toISOString().slice(0,10), due=[];
    decks.forEach(function(deck){
        (deck.cards||[]).forEach(function(card,ci){
            var nr=card.nextReview||'0000-00-00';
            if(nr<=today) due.push({deckId:deck.id,deckTitle:deck.title,cardIdx:ci,card:card});
        });
    });
    return due;
}
function getSrsDueCount() { return getDueFlashcards().length; }

var _srsCards=[], _srsCurrent=0, _srsFlipped=false, _srsSession={reviewed:0,correct:0}, _srsActive=false;
function startSrsReview() {
    _srsCards=getDueFlashcards();
    if (_srsCards.length===0) { showToast('No cards due today!','success',3000); return; }
    for(var i=_srsCards.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var tmp=_srsCards[i];_srsCards[i]=_srsCards[j];_srsCards[j]=tmp;}
    _srsCurrent=0; _srsFlipped=false; _srsSession={reviewed:0,correct:0}; _srsActive=true;
    renderSrsCard();
}
function startSrsDeckReview(deckId) {
    _srsCards=getDueFlashcards().filter(function(c){return c.deckId===deckId;});
    if(_srsCards.length===0){showToast('No cards due in this deck!','info');return;}
    for(var i=_srsCards.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var tmp=_srsCards[i];_srsCards[i]=_srsCards[j];_srsCards[j]=tmp;}
    _srsCurrent=0; _srsFlipped=false; _srsSession={reviewed:0,correct:0}; _srsActive=true;
    var panel=document.getElementById('srs-panel');
    if(panel){panel.scrollIntoView({behavior:'smooth'});renderSrsCard();}
}
function renderSrsCard() {
    var panel=document.getElementById('srs-panel');
    if(!panel) return;
    if(_srsCurrent>=_srsCards.length){renderSrsResults(panel);return;}
    var item=_srsCards[_srsCurrent], card=item.card, total=_srsCards.length;
    panel.innerHTML='<div style="margin-bottom:16px;"><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;"><div style="font-size:0.9rem;color:var(--text-muted);">Card '+(_srsCurrent+1)+' / '+total+'</div><div style="font-size:0.9rem;color:var(--accent);">'+item.deckTitle+'</div></div><div style="height:4px;background:rgba(255,255,255,0.1);border-radius:2px;margin-bottom:20px;"><div style="width:'+((_srsCurrent/total)*100)+'%;height:100%;background:var(--accent);border-radius:2px;"></div></div></div>'
        +'<div id="srs-card-flip" onclick="flipSrsCard()" style="cursor:pointer;min-height:160px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.12);border-radius:14px;padding:28px;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;transition:all 0.2s;user-select:none;" onmouseenter="this.style.borderColor=\'rgba(0,206,201,0.4)\'" onmouseleave="this.style.borderColor=\'rgba(255,255,255,0.12)\'"><div style="font-size:0.85rem;color:var(--text-muted);text-transform:uppercase;letter-spacing:1px;margin-bottom:10px;">'+(_srsFlipped?'ANSWER':'QUESTION — tap to reveal')+'</div><div style="font-size:1.05rem;color:white;line-height:1.6;">'+(_srsFlipped?card.back:card.front)+'</div></div>'
        +(_srsFlipped?'<div style="margin-top:18px;"><div style="font-size:0.9rem;color:var(--text-muted);text-align:center;margin-bottom:10px;">How well did you remember?</div><div style="display:grid;grid-template-columns:repeat(4,1fr);gap:12px;"><button onclick="rateSrsCard(0)" style="padding:10px 6px;border-radius:8px;border:none;background:rgba(255,107,107,0.2);color:#ff6b6b;cursor:pointer;font-size:0.9rem;font-weight:600;">Again</button><button onclick="rateSrsCard(1)" style="padding:10px 6px;border-radius:8px;border:none;background:rgba(253,203,110,0.2);color:#fdcb6e;cursor:pointer;font-size:0.9rem;font-weight:600;">Hard</button><button onclick="rateSrsCard(3)" style="padding:10px 6px;border-radius:8px;border:none;background:rgba(0,206,201,0.2);color:#00CEC9;cursor:pointer;font-size:0.9rem;font-weight:600;">Good</button><button onclick="rateSrsCard(5)" style="padding:10px 6px;border-radius:8px;border:none;background:rgba(0,184,148,0.2);color:#00b894;cursor:pointer;font-size:0.9rem;font-weight:600;">Easy</button></div></div>'
            :'<div style="text-align:center;margin-top:18px;"><button class="btn-secondary" onclick="flipSrsCard()" style="padding:10px 24px;"><i class="ph ph-eye"></i> Reveal Answer</button></div>');
}
function flipSrsCard() { _srsFlipped=!_srsFlipped; renderSrsCard(); }
function rateSrsCard(rating) {
    var item=_srsCards[_srsCurrent], decks=getFlashcardDecks();
    var dIdx=decks.findIndex(function(d){return d.id===item.deckId;});
    if(dIdx>=0){ var srs=srsNextReview(item.card,rating); Object.assign(decks[dIdx].cards[item.cardIdx],srs); saveFlashcardDecks(decks); }
    if(rating>=3) _srsSession.correct++;
    _srsSession.reviewed++; _srsCurrent++; _srsFlipped=false; renderSrsCard();
}
function renderSrsResults(panel) {
    _srsActive=false;
    var pct=_srsSession.reviewed>0?Math.round((_srsSession.correct/_srsSession.reviewed)*100):0;
    var xp=_srsSession.reviewed*5+_srsSession.correct*3;
    if(typeof awardXP==='function') awardXP(xp);
    panel.innerHTML='<div style="text-align:center;padding:32px 16px;"><div style="font-size:1.25rem;margin-bottom:10px;">🎓</div><h3 style="color:white;margin:0 0 6px;">Review Complete!</h3><div style="color:var(--text-muted);margin-bottom:20px;">Reviewed '+_srsSession.reviewed+' cards — '+pct+'% recalled</div><div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:20px;"><div class="glass-panel" style="padding:14px;"><div style="font-size:1.5rem;font-weight:700;color:#00b894;">'+_srsSession.correct+'</div><div style="font-size:0.85rem;color:var(--text-muted);">Remembered</div></div><div class="glass-panel" style="padding:14px;"><div style="font-size:1.5rem;font-weight:700;color:#ff6b6b;">'+(_srsSession.reviewed-_srsSession.correct)+'</div><div style="font-size:0.85rem;color:var(--text-muted);">Need Practice</div></div><div class="glass-panel" style="padding:14px;"><div style="font-size:1.5rem;font-weight:700;color:var(--accent);">+'+xp+'</div><div style="font-size:0.85rem;color:var(--text-muted);">XP Earned</div></div></div><button class="btn-primary" onclick="renderSrsHomePanel()"><i class="ph ph-cards"></i> Back to Decks</button></div>';
}

function renderSrsHomePanel() {
    var p=document.getElementById('srs-home-panel'); if(!p) return;
    var due=getDueFlashcards().length, decks=getFlashcardDecks();
    p.innerHTML='<div class="glass-panel" style="padding:20px;margin-bottom:16px;text-align:center;"><div style="font-size:1.25rem;margin-bottom:8px;">'+(due>0?'🃏':'✅')+'</div><div style="font-size:1.25rem;font-weight:700;color:'+(due>0?'var(--accent)':'#00b894')+';">'+due+'</div><div style="color:var(--text-muted);margin-bottom:16px;">card'+(due!==1?'s':'')+' due for review today</div>'
        +(due>0?'<button class="btn-primary" style="padding:12px 28px;" onclick="startSrsReview()"><i class="ph ph-play"></i> Start Review ('+due+' cards)</button>':'<div style="color:#00b894;">All caught up! Come back tomorrow.</div>')
        +'</div><div><div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;"><h4 style="margin:0;color:white;">Decks ('+decks.length+')</h4><button class="btn-secondary" style="font-size:0.9rem;padding:6px 12px;" onclick="openCsvImportModal()"><i class="ph ph-upload-simple"></i> Import CSV</button></div>'
        +(decks.length===0?'<div style="text-align:center;padding:24px;color:var(--text-muted);">No decks yet.</div>'
            :decks.map(function(d){ var di=getDueFlashcards().filter(function(c){return c.deckId===d.id;}).length; return '<div class="glass-panel" style="padding:14px;margin-bottom:8px;display:flex;align-items:center;gap:12px;"><div style="flex:1;"><div style="font-weight:600;color:white;">'+d.title+'</div><div style="font-size:0.88rem;color:var(--text-muted);">'+(d.cards||[]).length+' cards &bull; '+(di>0?'<span style="color:var(--accent);">'+di+' due</span>':'<span style="color:#00b894;">All caught up</span>')+'</div></div>'+(di>0?'<button class="btn-primary" style="font-size:0.9rem;padding:6px 12px;" onclick="startSrsDeckReview('+d.id+')"><i class="ph ph-play"></i> Review</button>':'')+'<button class="btn-secondary" title="Export deck as CSV" aria-label="Export deck as CSV" style="font-size:0.9rem;padding:6px 10px;" onclick="exportFlashcardDeck('+d.id+')"><i class="ph ph-download-simple"></i></button></div>'; }).join(''))
        +'</div><div id="srs-panel" style="margin-top:16px;"></div>';
}

