// ════════════════════════════════════════════════════════════════════
// v15.0 — DEBATE PRACTICE (Feature 5)
// ════════════════════════════════════════════════════════════════════
var _debateTopic = '';
var _debateSide = 'FOR';
var _debateHistory = [];
var _debateExchanges = 0;

function startDebate() {
    var topicEl = document.getElementById('debate-topic-input');
    var sideEl = document.getElementById('debate-side-select');
    if (!topicEl || !sideEl) return;
    var topic = topicEl.value.trim();
    if (!topic) { showToast('Enter a debate topic first.', 'warning'); return; }
    _debateTopic = topic;
    _debateSide = sideEl.value;
    _debateHistory = [];
    _debateExchanges = 0;
    var chatArea = document.getElementById('debate-chat-area');
    if (chatArea) {
        chatArea.innerHTML = '';
        chatArea.style.display = 'flex';
    }
    document.getElementById('debate-input-row').style.display = 'flex';
    document.getElementById('debate-start-btn').style.display = 'none';
    document.getElementById('debate-new-btn').style.display = 'inline-flex';
    var oppSideLabel = _debateSide === 'FOR' ? 'AGAINST' : 'FOR';
    _addDebateMsg('system', 'Topic: <strong>' + topic + '</strong> — You argue <strong>' + _debateSide + '</strong>. Opponent argues <strong>' + oppSideLabel + '</strong>. Make your opening argument!');
}

function _addDebateMsg(role, html) {
    var area = document.getElementById('debate-chat-area');
    if (!area) return;
    var div = document.createElement('div');
    div.style.cssText = 'margin-bottom:10px;padding:10px 14px;border-radius:10px;font-size:0.9rem;line-height:1.5;max-width:85%;';
    if (role === 'user') {
        div.style.cssText += 'background:rgba(108,92,231,0.2);border:1px solid rgba(108,92,231,0.4);align-self:flex-end;margin-left:auto;color:white;';
    } else if (role === 'ai') {
        div.style.cssText += 'background:rgba(0,206,201,0.1);border:1px solid rgba(0,206,201,0.3);color:#e0f7f7;';
    } else {
        div.style.cssText += 'background:rgba(255,255,255,0.05);border:1px solid rgba(255,255,255,0.1);color:var(--text-muted);font-size:0.82rem;font-style:italic;width:100%;max-width:100%;text-align:center;';
    }
    div.innerHTML = html;
    area.appendChild(div);
    area.scrollTop = area.scrollHeight;
}

async function sendDebateMsg() {
    var input = document.getElementById('debate-user-input');
    if (!input) return;
    var text = input.value.trim();
    if (!text) return;
    input.value = '';
    _addDebateMsg('user', text);
    _debateHistory.push({ role: 'user', content: text });
    _debateExchanges++;

    var apiKey = getApiKey();
    if (!apiKey) { _addDebateMsg('ai', 'Need API key in Settings.'); return; }

    var oppSide = _debateSide === 'FOR' ? 'AGAINST' : 'FOR';
    var sysPrompt = "You are a sharp debate opponent. Topic: '" + _debateTopic + "'. The student argues " + _debateSide + ". You argue " + oppSide + " convincingly. 2-3 sentences per response, no filler. After exactly 5 student messages, output '\u{1F3C6} VERDICT:' followed by who made the stronger case and why.";

    var messages = [{ role: 'system', content: sysPrompt }].concat(_debateHistory.slice(-10));

    try {
        var res = await fetch('https://api.openai.com/v1/chat/completions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
            body: JSON.stringify({ model: 'gpt-4o-mini', messages: messages, max_tokens: 300, temperature: 0.8 })
        });
        var data = await res.json();
        if (data.error) throw new Error(data.error.message);
        var reply = data.choices[0].message.content || '';
        _debateHistory.push({ role: 'assistant', content: reply });
        _addDebateMsg('ai', reply.replace(/\n/g, '<br>'));
        if (reply.indexOf('VERDICT:') !== -1) {
            document.getElementById('debate-input-row').style.display = 'none';
        }
    } catch (err) {
        _addDebateMsg('ai', 'Error: ' + err.message);
    }
}

function resetDebate() {
    _debateTopic = '';
    _debateHistory = [];
    _debateExchanges = 0;
    var chatArea = document.getElementById('debate-chat-area');
    if (chatArea) { chatArea.innerHTML = ''; chatArea.style.display = 'none'; }
    var inputRow = document.getElementById('debate-input-row');
    if (inputRow) inputRow.style.display = 'none';
    var startBtn = document.getElementById('debate-start-btn');
    if (startBtn) startBtn.style.display = 'inline-flex';
    var newBtn = document.getElementById('debate-new-btn');
    if (newBtn) newBtn.style.display = 'none';
    var topicEl = document.getElementById('debate-topic-input');
    if (topicEl) topicEl.value = '';
}

// ════════════════════════════════════════════════════════════════════
// v15.0 — PRACTICE TEST MODE (Feature 6)
// ════════════════════════════════════════════════════════════════════
var _ptQuestions = [];
var _ptAnswers = {};
var _ptTimerInterval = null;
var _ptSecondsLeft = 0;
var _ptStartTime = 0;

function generatePracticeTest() {
    var subject = document.getElementById('pt-subject').value;
    var difficulty = document.getElementById('pt-difficulty').value;
    var numQ = parseInt(document.getElementById('pt-num-questions').value);
    var timeLimitMin = parseInt(document.getElementById('pt-time-limit').value);

    var apiKey = getApiKey();
    if (!apiKey) { showToast('Add API key in Settings.', 'error'); return; }

    var setupDiv = document.getElementById('pt-setup');
    var loadingDiv = document.getElementById('pt-loading');
    if (setupDiv) setupDiv.style.display = 'none';
    if (loadingDiv) loadingDiv.style.display = 'block';

    var prompt = 'Generate ' + numQ + ' ' + difficulty + ' ' + subject + ' multiple-choice questions for a high school / college student. Return ONLY valid JSON:\n{"questions":[{"q":"question text","options":["A. ...","B. ...","C. ...","D. ..."],"answer":"A","explanation":"why A is correct"}]}\nNo extra text outside the JSON.\n\nACCURACY RULES (v19.1 — answer keys were coming back wrong ~30% of the time):\n1. SOLVE each question yourself and write the full working in "explanation" BEFORE choosing the answer letter.\n2. "answer" MUST be the letter of the option that contains the result you derived in the explanation. If the explanation and the answer letter disagree, FIX THE LETTER before responding.\n3. Exactly one option is correct; re-check the arithmetic of the correct option digit by digit.\n4. Do not place the correct answer in the same position for every question.';

    fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + apiKey },
        body: JSON.stringify({
            model: 'gpt-4o',
            messages: [{ role: 'user', content: prompt }],
            response_format: { type: 'json_object' },
            max_tokens: 2000,
            temperature: 0.7
        })
    })
    .then(function(r) { return r.json(); })
    .then(function(data) {
        if (data.error) throw new Error(data.error.message);
        var parsed = JSON.parse(data.choices[0].message.content);
        // v19.1 — shuffle options client-side: the model put the correct answer
        // at "A" on ~9 of 10 questions, so pattern-spotting beat studying.
        _ptQuestions = (parsed.questions || []).map(_ptShuffleQuestion);
        _ptAnswers = {};
        _ptStartTime = Date.now();
        _ptSecondsLeft = timeLimitMin * 60;
        if (loadingDiv) loadingDiv.style.display = 'none';
        _renderPracticeTest();
        _startPracticeTimer();
    })
    .catch(function(err) {
        if (loadingDiv) loadingDiv.style.display = 'none';
        if (setupDiv) setupDiv.style.display = 'block';
        showToast('Error: ' + err.message, 'error');
    });
}

// v19.4 — ANSWER-KEY RECONCILER. Even gpt-4o sometimes derives the right
// result in its explanation but labels the wrong option (observed live:
// "…divide by 3: x = 4" keyed to the option containing 5). The worked text is
// the reliable signal, so pull the final value from it and, when exactly ONE
// option matches, trust that over the model's letter. Conservative by design:
// any ambiguity (no match, or multiple matches) leaves the key untouched.
// Returns a corrected 0-based index, or -1 to keep the model's answer.
function _reconcileAnswerIndex(optionTexts, workText) {
    try {
        if (!workText || !Array.isArray(optionTexts) || optionTexts.length < 2) return -1;
        var work = String(workText);
        // Prefer the last "= <value>" (the conclusion); else the last number.
        var eqMatches = work.match(/=\s*(-?\d+(?:\.\d+)?(?:\/\d+)?)/g);
        var finalVal = null;
        if (eqMatches && eqMatches.length) {
            finalVal = eqMatches[eqMatches.length - 1].replace(/^=\s*/, '');
        } else {
            var nums = work.match(/-?\d+(?:\.\d+)?/g);
            if (nums && nums.length) finalVal = nums[nums.length - 1];
        }
        if (finalVal === null) return -1;
        var norm = function (s) {
            var m = String(s).replace(/^\s*[A-F][.)]\s*/, '').trim().match(/^-?\d+(?:\.\d+)?(?:\/\d+)?/);
            return m ? m[0] : null;
        };
        var target = norm(finalVal);
        if (target === null) return -1;
        var hits = [];
        optionTexts.forEach(function (o, i) { if (norm(o) === target) hits.push(i); });
        return hits.length === 1 ? hits[0] : -1; // unique match only
    } catch (_) { return -1; }
}

// v19.1 — shuffle a practice-test question's options and remap the answer
// letter. Tolerates "A. ", "A) " or bare option text; keeps the original
// question untouched if the shape is unexpected.
function _ptShuffleQuestion(q) {
    try {
        var letters = ['A', 'B', 'C', 'D', 'E', 'F'];
        var stripped = (q.options || []).map(function (o) { return String(o).replace(/^\s*[A-F][.)]\s*/, ''); });
        if (stripped.length < 2) return q;
        var ansIdx = letters.indexOf(String(q.answer || 'A').trim().toUpperCase().charAt(0));
        if (ansIdx < 0 || ansIdx >= stripped.length) ansIdx = 0;
        // v19.4 — trust the worked explanation over the model's letter when it
        // unambiguously points at a different option.
        var fixed = _reconcileAnswerIndex(stripped, q.explanation);
        if (fixed >= 0 && fixed !== ansIdx) ansIdx = fixed;
        var correctText = stripped[ansIdx];
        for (var i = stripped.length - 1; i > 0; i--) {
            var j = Math.floor(Math.random() * (i + 1));
            var tmp = stripped[i]; stripped[i] = stripped[j]; stripped[j] = tmp;
        }
        var newIdx = stripped.indexOf(correctText);
        if (newIdx < 0) return q;
        q.options = stripped.map(function (t, k) { return letters[k] + '. ' + t; });
        q.answer = letters[newIdx];
    } catch (_) { /* keep original question on any surprise shape */ }
    return q;
}

function _startPracticeTimer() {
    if (_ptTimerInterval) clearInterval(_ptTimerInterval);
    _updatePracticeTimer();
    _ptTimerInterval = setInterval(function() {
        _ptSecondsLeft--;
        _updatePracticeTimer();
        if (_ptSecondsLeft <= 0) {
            clearInterval(_ptTimerInterval);
            showToast('Time is up! Submitting...', 'warning');
            submitPracticeTest();
        }
    }, 1000);
}

function _updatePracticeTimer() {
    var el = document.getElementById('pt-timer-display');
    if (!el) return;
    var m = Math.floor(_ptSecondsLeft / 60);
    var s = _ptSecondsLeft % 60;
    el.textContent = String(m).padStart(2,'0') + ':' + String(s).padStart(2,'0');
    el.style.color = _ptSecondsLeft < 120 ? '#ff6b6b' : 'white';
}

function _renderPracticeTest() {
    var testDiv = document.getElementById('pt-test-area');
    if (!testDiv) return;
    testDiv.style.display = 'block';
    var questionsDiv = document.getElementById('pt-questions');
    if (!questionsDiv) return;
    questionsDiv.innerHTML = _ptQuestions.map(function(q, i) {
        return '<div style="margin-bottom:20px;padding:16px;background:rgba(255,255,255,0.04);border:1px solid rgba(255,255,255,0.1);border-radius:10px;">'
            + '<div style="font-weight:600;color:white;margin-bottom:10px;">' + (i+1) + '. ' + q.q + '</div>'
            + '<div style="display:flex;flex-direction:column;gap:6px;">'
            + q.options.map(function(opt, oi) {
                var letter = ['A','B','C','D'][oi];
                return '<label style="display:flex;align-items:center;gap:8px;color:var(--text-muted);cursor:pointer;padding:6px 10px;border-radius:6px;">'
                    + '<input type="radio" name="pt-q-' + i + '" value="' + letter + '" onchange="window._ptAnswers[' + i + ']=this.value;" style="accent-color:var(--accent);">'
                    + opt
                    + '</label>';
            }).join('')
            + '</div></div>';
    }).join('');
}

function submitPracticeTest() {
    if (_ptTimerInterval) clearInterval(_ptTimerInterval);
    var timeUsed = Math.round((Date.now() - _ptStartTime) / 1000);
    var testDiv = document.getElementById('pt-test-area');
    if (testDiv) testDiv.style.display = 'none';

    var correct = 0;
    var resultsDiv = document.getElementById('pt-results');
    if (!resultsDiv) return;
    resultsDiv.style.display = 'block';

    var details = _ptQuestions.map(function(q, i) {
        var userAns = _ptAnswers[i] || '—';
        var isCorrect = userAns === q.answer;
        if (isCorrect) correct++;
        var bg = isCorrect ? 'rgba(0,184,148,0.1)' : 'rgba(255,107,107,0.1)';
        var border = isCorrect ? 'rgba(0,184,148,0.4)' : 'rgba(255,107,107,0.4)';
        var color = isCorrect ? '#00b894' : '#ff6b6b';
        var verdict = isCorrect ? '&#10003;' : '&#10007; Correct: ' + q.answer;
        return '<div style="margin-bottom:12px;padding:12px;background:' + bg + ';border:1px solid ' + border + ';border-radius:8px;">'
            + '<div style="font-weight:600;color:white;margin-bottom:4px;">' + (i+1) + '. ' + q.q + '</div>'
            + '<div style="font-size:0.85rem;color:' + color + ';">Your answer: ' + userAns + ' ' + verdict + '</div>'
            + '<div style="font-size:0.82rem;color:var(--text-muted);margin-top:4px;">' + q.explanation + '</div>'
            + '</div>';
    }).join('');

    var mins = Math.floor(timeUsed/60), secs = timeUsed%60;
    var scoreEl = document.getElementById('pt-score-display');
    if (scoreEl) {
        scoreEl.innerHTML = '<div style="text-align:center;margin-bottom:20px;">'
            + '<div style="font-size:3rem;font-weight:900;background:linear-gradient(135deg,var(--accent),var(--grad));-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;">' + correct + '/' + _ptQuestions.length + '</div>'
            + '<div style="color:var(--text-muted);margin-top:4px;">Time used: ' + String(mins).padStart(2,'0') + ':' + String(secs).padStart(2,'0') + '</div>'
            + '</div>' + details;
    }
}

function resetPracticeTest() {
    if (_ptTimerInterval) clearInterval(_ptTimerInterval);
    _ptQuestions = [];
    _ptAnswers = {};
    var setupDiv = document.getElementById('pt-setup');
    var loadingDiv = document.getElementById('pt-loading');
    var testDiv = document.getElementById('pt-test-area');
    var resultsDiv = document.getElementById('pt-results');
    if (setupDiv) setupDiv.style.display = 'block';
    if (loadingDiv) loadingDiv.style.display = 'none';
    if (testDiv) testDiv.style.display = 'none';
    if (resultsDiv) resultsDiv.style.display = 'none';
}

// ════════════════════════════════════════════════════════════════════
// v15.6 — LO-FI MUSIC PLAYER (ad-free local tracks)
//   • Plays royalty-free .mp3 files bundled in assets/audio/ via HTML5 audio
//   • NO ADS, no YouTube, no streams — fully self-contained & reliable
//   • Real per-song prev/next/skip, now-playing, persisted track + volume,
//     auto-advance, sleep timer — keeps the sidebar popover UI
//   • To add/replace songs: drop an .mp3 in assets/audio/ and add it to TRACKS
// ════════════════════════════════════════════════════════════════════
(function() {
    var TRACKS = [
        { file: 'assets/audio/mondamusic-lofi-lofi-music-529554.mp3',          title: 'Lofi Music',  artist: 'mondamusic' },
        { file: 'assets/audio/pulsebox-lofi-smooth-522876.mp3',                title: 'Smooth',      artist: 'pulsebox' },
        { file: 'assets/audio/pulsebox-lofi-production-522875.mp3',            title: 'Production',   artist: 'pulsebox' },
        { file: 'assets/audio/leberch-lofi-hip-hop-519408.mp3',               title: 'Hip Hop',     artist: 'leberch' },
        { file: 'assets/audio/solarflex-lofi-beats-541528.mp3',               title: 'Beats',       artist: 'solarflex' },
        { file: 'assets/audio/mirostar-lofi-beats-531504.mp3',                title: 'Beats',       artist: 'mirostar' },
        { file: 'assets/audio/fassounds-good-night-lofi-cozy-chill-music-160166.mp3', title: 'Good Night', artist: 'fassounds' },
        { file: 'assets/audio/watermello-lofi-lofi-girl-lofi-chill-484610.mp3',     title: 'Lofi Chill', artist: 'watermello' },
        { file: 'assets/audio/the_mountain-lofi-513863.mp3',                        title: 'Lofi',       artist: 'the_mountain' },
        { file: 'assets/audio/prettyjohn1-lofi-beats-524251.mp3',                   title: 'Beats',      artist: 'prettyjohn1' },
        { file: 'assets/audio/pulsebox-lofi-mellow-522897.mp3',                     title: 'Mellow',     artist: 'pulsebox' },
        { file: 'assets/audio/pulsebox-lofi-melody-522894.mp3',                     title: 'Melody',     artist: 'pulsebox' },
        { file: 'assets/audio/pulsebox-lofi-night-522890.mp3',                      title: 'Night',      artist: 'pulsebox' }
    ];

    var _track = parseInt(localStorage.getItem('lofi_track') || '0', 10);
    if (isNaN(_track) || _track < 0 || _track >= TRACKS.length) _track = 0;
    var _volume = parseInt(localStorage.getItem('lofi_volume') || '70', 10);
    if (isNaN(_volume) || _volume < 0 || _volume > 100) _volume = 70;
    var _playing = false;
    var _audio = null;
    var _errCount = 0;
    var _sleepMin = 0, _sleepTimer = null, _sleepTick = null, _sleepDeadline = 0;

    // ─── audio engine (HTML5 <audio>, lives in the closure so it keeps
    //     playing when the popover is closed) ──────────────────────────
    function _ensureAudio() {
        if (_audio) return _audio;
        _audio = new Audio();
        _audio.preload = 'none';
        _audio.volume = _volume / 100;
        _audio.addEventListener('ended', function () { _next(); });           // auto-advance
        _audio.addEventListener('error', function () { _onError(); });
        _audio.addEventListener('playing', function () { _playing = true; _errCount = 0; _setStatus(''); _syncUI(); });
        _audio.addEventListener('pause',  function () { _playing = false; _syncUI(); });
        return _audio;
    }

    function _load(autoplay) {
        var a = _ensureAudio();
        a.src = TRACKS[_track].file;
        a.volume = _volume / 100;
        if (autoplay) { var p = a.play(); if (p && p.catch) p.catch(function () {}); }
    }

    function _onError() {
        _errCount++;
        if (_errCount >= TRACKS.length) { _errCount = 0; _pause(); _setStatus('Could not play audio.'); return; }
        _setStatus('Skipping a track that won’t play…');
        _setIndex(_track + 1); _load(true);
    }

    // ─── controls ────────────────────────────────────────────────────
    function _play()  { var a = _ensureAudio(); if (!a.src) { _load(true); } else { var p = a.play(); if (p && p.catch) p.catch(function () {}); } _playing = true; _syncUI(); }
    function _pause() { if (_audio) _audio.pause(); _playing = false; _syncUI(); }
    function _toggle(){ _playing ? _pause() : _play(); }

    function _setIndex(i) {
        _track = ((i % TRACKS.length) + TRACKS.length) % TRACKS.length;
        localStorage.setItem('lofi_track', _track);
        _syncUI();
    }
    function _pick(i) { _setIndex(i); _load(true); _playing = true; _syncUI(); } // click a track → play it
    function _prev()  { _setIndex(_track - 1); _load(true); _playing = true; _syncUI(); } // prev song
    function _next()  { _setIndex(_track + 1); _load(true); _playing = true; _syncUI(); } // next/skip song

    function _setVolume(v) {
        _volume = Math.max(0, Math.min(100, parseInt(v, 10) || 0));
        localStorage.setItem('lofi_volume', _volume);
        if (_audio) _audio.volume = _volume / 100;
    }

    // ─── sleep timer ─────────────────────────────────────────────────
    function _setSleep(min) {
        if (_sleepTimer) { clearTimeout(_sleepTimer); _sleepTimer = null; }
        if (_sleepTick)  { clearInterval(_sleepTick); _sleepTick = null; }
        _sleepMin = min;
        if (min > 0) {
            _sleepDeadline = Date.now() + min * 60000;
            _sleepTimer = setTimeout(function () {
                _pause(); _setSleep(0); _setStatus('Sleep timer ended — music stopped.');
            }, min * 60000);
            _sleepTick = setInterval(_updateSleepLabel, 1000);
        }
        _syncUI();
        _updateSleepLabel();
    }

    // ─── UI (popover anchored to the sidebar "Lo-fi Music" item) ──────
    function _buildPopover() {
        if (document.getElementById('lofi-popover')) return;
        var pop = document.createElement('div');
        pop.id = 'lofi-popover';
        pop.style.cssText = 'position:fixed;z-index:1000020;width:300px;max-width:calc(100vw - 24px);background:rgba(12,14,24,0.98);border:1px solid rgba(108,92,231,0.5);border-radius:16px;box-shadow:0 16px 50px rgba(0,0,0,0.7);backdrop-filter:blur(16px);display:none;overflow:hidden;';
        pop.innerHTML =
            '<div style="display:flex;justify-content:space-between;align-items:center;padding:13px 16px;border-bottom:1px solid var(--glass-border);">'
          +   '<span style="color:#a29bfe;font-size:0.78rem;font-weight:700;letter-spacing:1px;text-transform:uppercase;"><i class="ph-fill ph-music-notes"></i> Lo-fi Player</span>'
          +   '<button onclick="closeLofiPlayer()" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:1rem;padding:2px;line-height:1;"><i class="ph ph-x"></i></button>'
          + '</div>'
          + '<div style="padding:14px 16px;">'
          +   '<div style="display:flex;align-items:center;gap:12px;margin-bottom:14px;">'
          +     '<div style="width:52px;height:52px;flex-shrink:0;border-radius:12px;background:linear-gradient(135deg,#6C5CE7,#00CEC9);display:flex;align-items:center;justify-content:center;box-shadow:0 6px 20px rgba(108,92,231,0.45);"><i class="ph ph-vinyl-record" id="lofi-disc" style="font-size:1.7rem;color:white;"></i></div>'
          +     '<div style="min-width:0;flex:1;">'
          +       '<div id="lofi-np-name" style="color:white;font-size:0.95rem;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"></div>'
          +       '<div id="lofi-np-genre" style="color:var(--text-muted);font-size:0.76rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"></div>'
          +       '<div id="lofi-status" style="color:#fdcb6e;font-size:0.72rem;margin-top:3px;min-height:1em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"></div>'
          +     '</div>'
          +   '</div>'
          +   '<div style="display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:16px;">'
          +     '<button onclick="window._lofiPrev()" title="Previous song" style="background:rgba(255,255,255,0.06);border:none;color:white;width:38px;height:38px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:1rem;"><i class="ph ph-skip-back"></i></button>'
          +     '<button id="lofi-play-btn" onclick="window._lofiTogglePlay()" style="background:linear-gradient(135deg,#6C5CE7,#00CEC9);border:none;color:white;width:50px;height:50px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:1.4rem;box-shadow:0 6px 18px rgba(108,92,231,0.5);"><i class="ph ph-play"></i></button>'
          +     '<button onclick="window._lofiNext()" title="Next song (skip)" style="background:rgba(255,255,255,0.06);border:none;color:white;width:38px;height:38px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:1rem;"><i class="ph ph-skip-forward"></i></button>'
          +   '</div>'
          +   '<div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">'
          +     '<i class="ph ph-speaker-low" style="color:var(--text-muted);font-size:0.9rem;"></i>'
          +     '<input id="lofi-volume" type="range" min="0" max="100" value="' + _volume + '" oninput="window._lofiVol(this.value)" style="flex:1;accent-color:#6C5CE7;cursor:pointer;">'
          +     '<i class="ph ph-speaker-high" style="color:var(--text-muted);font-size:0.9rem;"></i>'
          +   '</div>'
          +   '<div style="margin-bottom:14px;">'
          +     '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:7px;"><span style="color:var(--text-muted);font-size:0.72rem;font-weight:600;letter-spacing:0.5px;"><i class="ph ph-moon-stars"></i> SLEEP</span><span id="lofi-sleep-label" style="color:#a29bfe;font-size:0.72rem;"></span></div>'
          +     '<div id="lofi-sleep-row" style="display:flex;gap:5px;">'
          +       '<button data-min="0"  onclick="window._lofiSleep(0)"  class="lofi-sleep-btn" style="flex:1;">Off</button>'
          +       '<button data-min="25" onclick="window._lofiSleep(25)" class="lofi-sleep-btn" style="flex:1;">25m</button>'
          +       '<button data-min="45" onclick="window._lofiSleep(45)" class="lofi-sleep-btn" style="flex:1;">45m</button>'
          +       '<button data-min="60" onclick="window._lofiSleep(60)" class="lofi-sleep-btn" style="flex:1;">60m</button>'
          +     '</div>'
          +   '</div>'
          +   '<div style="color:var(--text-muted);font-size:0.72rem;font-weight:600;letter-spacing:0.5px;margin-bottom:7px;"><i class="ph ph-playlist"></i> TRACKS</div>'
          +   '<div id="lofi-track-list" style="display:flex;flex-direction:column;gap:5px;max-height:150px;overflow-y:auto;"></div>'
          + '</div>';
        document.body.appendChild(pop);

        if (!document.getElementById('lofi-style')) {
            var st = document.createElement('style');
            st.id = 'lofi-style';
            st.textContent =
                '.lofi-sleep-btn{background:rgba(255,255,255,0.06);border:1px solid var(--glass-border);color:var(--text-muted);border-radius:7px;padding:6px 0;cursor:pointer;font-size:0.76rem;transition:all .15s;}'
              + '.lofi-sleep-btn:hover{border-color:rgba(108,92,231,0.6);color:white;}'
              + '.lofi-sleep-btn.active{background:linear-gradient(135deg,#6C5CE7,#00CEC9);border-color:transparent;color:white;}'
              + '.lofi-track-row{display:flex;align-items:center;gap:9px;padding:8px 10px;border-radius:9px;border:1px solid var(--glass-border);background:rgba(255,255,255,0.03);cursor:pointer;transition:all .15s;}'
              + '.lofi-track-row:hover{border-color:rgba(108,92,231,0.6);background:rgba(108,92,231,0.08);}'
              + '.lofi-track-row.active{border-color:#6C5CE7;background:rgba(108,92,231,0.15);}'
              + '#lofi-disc.spin{animation:spin 4s linear infinite;}';
            document.head.appendChild(st);
        }
        _renderTracks();
        _syncUI();
    }

    function _positionPopover() {
        var pop = document.getElementById('lofi-popover');
        if (!pop || pop.style.display === 'none') return;
        var pw = pop.offsetWidth, ph = pop.offsetHeight;
        var item = document.getElementById('lofi-menu-item');
        var left, top;
        if (item) {
            var r = item.getBoundingClientRect();
            left = r.right + 10;
            top  = r.bottom - ph;
            if (left + pw > window.innerWidth - 8) left = r.left - pw - 10;
        } else {
            left = 16; top = window.innerHeight - ph - 80;
        }
        if (left < 8) left = 8;
        if (top < 8) top = 8;
        if (top + ph > window.innerHeight - 8) top = window.innerHeight - ph - 8;
        pop.style.left = left + 'px';
        pop.style.top = top + 'px';
        pop.style.bottom = 'auto';
    }

    function _renderTracks() {
        var list = document.getElementById('lofi-track-list');
        if (!list) return;
        list.innerHTML = TRACKS.map(function (t, i) {
            return '<div class="lofi-track-row' + (i === _track ? ' active' : '') + '" onclick="window._lofiPick(' + i + ')">'
                 +   '<i class="ph ' + (i === _track && _playing ? 'ph-speaker-high' : 'ph-music-note') + '" style="color:#a29bfe;font-size:1.1rem;"></i>'
                 +   '<div style="flex:1;min-width:0;"><div style="color:white;font-size:0.9rem;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;">' + t.title + '</div>'
                 +     '<div style="color:var(--text-muted);font-size:0.74rem;">' + t.artist + '</div></div>'
                 +   (i === _track ? '<i class="ph ph-check-circle" style="color:#00CEC9;"></i>' : '')
                 + '</div>';
        }).join('');
    }

    function _setStatus(msg) {
        var el = document.getElementById('lofi-status');
        if (el) el.textContent = msg || '';
    }

    function _updateSleepLabel() {
        var el = document.getElementById('lofi-sleep-label');
        if (!el) return;
        if (_sleepMin <= 0) { el.textContent = ''; return; }
        var left = Math.max(0, _sleepDeadline - Date.now());
        var m = Math.floor(left / 60000), s = Math.floor((left % 60000) / 1000);
        el.textContent = m + ':' + (s < 10 ? '0' : '') + s + ' left';
    }

    function _syncUI() {
        var name = document.getElementById('lofi-np-name');
        var genre = document.getElementById('lofi-np-genre');
        var btn = document.getElementById('lofi-play-btn');
        var disc = document.getElementById('lofi-disc');
        if (name)  name.textContent = TRACKS[_track].title;
        if (genre) genre.textContent = TRACKS[_track].artist;
        if (btn)   btn.innerHTML = _playing ? '<i class="ph ph-pause"></i>' : '<i class="ph ph-play"></i>';
        if (disc)  disc.className = 'ph ph-vinyl-record' + (_playing ? ' spin' : '');
        var vol = document.getElementById('lofi-volume');
        if (vol && document.activeElement !== vol) vol.value = _volume;
        var rows = document.querySelectorAll('.lofi-sleep-btn');
        rows.forEach(function (b) { b.classList.toggle('active', parseInt(b.getAttribute('data-min'), 10) === _sleepMin); });
        _renderTracks();
    }

    // ─── public API ──────────────────────────────────────────────────
    var _popOpen = false;
    function _onDocClick(e) {
        var pop = document.getElementById('lofi-popover');
        var item = document.getElementById('lofi-menu-item');
        if (!pop) return;
        if (pop.contains(e.target)) return;
        if (item && item.contains(e.target)) return;
        window.closeLofiPlayer();
    }
    window.openLofiPlayer = function () {
        _buildPopover();
        var pop = document.getElementById('lofi-popover');
        if (pop) pop.style.display = 'block';
        _popOpen = true;
        _positionPopover();
        _syncUI();
        _updateSleepLabel();
        setTimeout(function () { document.addEventListener('click', _onDocClick, true); }, 0);
        window.addEventListener('resize', _positionPopover);
    };
    window.closeLofiPlayer = function () {
        var pop = document.getElementById('lofi-popover');
        if (pop) pop.style.display = 'none'; // music keeps playing
        _popOpen = false;
        document.removeEventListener('click', _onDocClick, true);
        window.removeEventListener('resize', _positionPopover);
    };
    window.toggleLofiPlayer = function () {
        if (_popOpen) window.closeLofiPlayer();
        else window.openLofiPlayer();
    };

    window._lofiTogglePlay = _toggle;
    window._lofiPrev = _prev;
    window._lofiNext = _next;
    window._lofiPick = _pick;
    window._lofiVol = _setVolume;
    window._lofiSleep = _setSleep;
})();

// ── DEAD CODE (v15.6): the old YouTube-based lo-fi engine below is disabled by
// the early `return` — it assigns nothing and never runs, so the v15.6 audio
// engine above is authoritative. Kept (not deleted) to avoid a risky 320-line
// removal; safe to delete this whole IIFE later.
(function() {
    return;
    // Regular YouTube MIX videos (NOT live streams) — these are stable: normal
    // uploads keep the same id and don't restart like live streams do. Each loops
    // when it ends. Genre variety like the old v15 stations. If a video ever blocks
    // embedding the player auto-skips it; to swap one, paste a new ?v= id below.
    var LOFI_STATIONS = [
        { name: 'Lofi Hip Hop', genre: 'Lofi Girl mix',       id: 'CFGLoQIhmow' },
        { name: 'Chillhop',     genre: 'Jazzy chillhop beats', id: 'Liv0MXUPiqo' },
        { name: 'Jazz Hop',     genre: 'Nujabes-era jazzhop',  id: 'Z0veIEk4OEE' },
        { name: 'Synthwave',    genre: 'Dreamy retro synth',   id: '8sPfeUXPZxU' },
        { name: 'Rain + Study', genre: '90s lofi + rain',      id: 'sF80I-TQiW0' },
        { name: '1 A.M Session', genre: 'Late-night lofi',     id: 'lTRiuFIWV54' }
    ];

    var _station = parseInt(localStorage.getItem('lofi_station') || '0', 10);
    if (isNaN(_station) || _station < 0 || _station >= LOFI_STATIONS.length) _station = 0;
    var _volume = parseInt(localStorage.getItem('lofi_volume') || '70', 10);
    if (isNaN(_volume) || _volume < 0 || _volume > 100) _volume = 70;
    var _playing = false;
    var _player = null;        // YT.Player instance
    var _apiLoading = false;
    var _wantPlay = false;     // start playback as soon as the player is ready
    var _errSkips = 0;         // consecutive dead-stream skips (avoid infinite loop)
    var _sleepMin = 0;         // 0 = off
    var _sleepTimer = null, _sleepTick = null, _sleepDeadline = 0;

    // ─── YouTube IFrame API ──────────────────────────────────────────
    // Hidden, audio-only host that lives on <body> so music keeps playing
    // even when the modal is closed. Must exist before new YT.Player('lofi-yt').
    function _ensureHost() {
        if (document.getElementById('lofi-yt-host')) return;
        var host = document.createElement('div');
        host.id = 'lofi-yt-host';
        host.style.cssText = 'position:fixed;width:1px;height:1px;left:-9999px;top:-9999px;opacity:0;pointer-events:none;';
        var inner = document.createElement('div');
        inner.id = 'lofi-yt';
        host.appendChild(inner);
        document.body.appendChild(host);
    }

    function _ensureApi(cb) {
        _ensureHost(); // always — the API may already be loaded (ambient sounds load it)
        if (window.YT && window.YT.Player) { cb(); return; }
        var prev = window.onYouTubeIframeAPIReady;
        window.onYouTubeIframeAPIReady = function() {
            if (typeof prev === 'function') { try { prev(); } catch (e) {} }
            cb();
        };
        if (_apiLoading) return;
        _apiLoading = true;
        if (!document.querySelector('script[src*="youtube.com/iframe_api"]')) {
            var tag = document.createElement('script');
            tag.src = 'https://www.youtube.com/iframe_api';
            document.head.appendChild(tag);
        }
    }

    function _createPlayer() {
        _ensureApi(function() {
            if (_player) { _startCurrent(); return; }
            _player = new YT.Player('lofi-yt', {
                height: '1', width: '1',
                videoId: LOFI_STATIONS[_station].id,
                playerVars: { autoplay: 1, controls: 0, disablekb: 1, fs: 0, playsinline: 1 },
                events: {
                    onReady: function(e) {
                        e.target.setVolume(_volume);
                        if (_wantPlay) e.target.playVideo();
                    },
                    onStateChange: function(e) {
                        if (e.data === YT.PlayerState.PLAYING) { _playing = true; _errSkips = 0; }
                        else if (e.data === YT.PlayerState.PAUSED) { _playing = false; }
                        else if (e.data === YT.PlayerState.ENDED) { try { e.target.seekTo(0); e.target.playVideo(); } catch (er) {} } // loop the mix
                        _syncUI();
                    },
                    onError: function() { _onStreamError(); }
                }
            });
        });
    }

    function _startCurrent() {
        if (!_player) { _createPlayer(); return; }
        try {
            _player.loadVideoById(LOFI_STATIONS[_station].id); // autoplays
            _player.setVolume(_volume);
        } catch (e) {}
    }

    function _onStreamError() {
        _errSkips++;
        _setStatus('“' + LOFI_STATIONS[_station].name + '” is unavailable — skipping…');
        if (_errSkips >= LOFI_STATIONS.length) {
            _errSkips = 0;
            _pause();
            _setStatus('All stations are unreachable right now. Try again later.');
            return;
        }
        _setIndex((_station + 1) % LOFI_STATIONS.length);
        if (_playing || _wantPlay) _startCurrent();
    }

    // ─── playback controls ───────────────────────────────────────────
    function _play()  { _wantPlay = true;  _playing = true;  if (!_player) _createPlayer(); else _startCurrent(); _syncUI(); }
    function _pause() { _wantPlay = false; _playing = false; if (_player) { try { _player.pauseVideo(); } catch (e) {} } _syncUI(); }
    function _toggle(){ _playing ? _pause() : _play(); }

    function _setIndex(i) {
        _station = ((i % LOFI_STATIONS.length) + LOFI_STATIONS.length) % LOFI_STATIONS.length;
        localStorage.setItem('lofi_station', _station);
        _syncUI();
    }
    function _pick(i) { _setIndex(i); _play(); }                 // clicking a station plays it
    function _prev()  { _setIndex(_station - 1); if (_playing || _wantPlay) _startCurrent(); }
    function _next()  { _setIndex(_station + 1); if (_playing || _wantPlay) _startCurrent(); }

    // "Skip song" — these stations are long mixes with no per-track data, so skip
    // jumps ~2 min ahead (about one lofi track) to land on roughly the next song.
    var SKIP_SECONDS = 140;
    function _skipSong() {
        if (!_player || typeof _player.getCurrentTime !== 'function') { _play(); return; }
        try {
            var t = _player.getCurrentTime() + SKIP_SECONDS;
            var d = (typeof _player.getDuration === 'function') ? _player.getDuration() : 0;
            if (d && t >= d - 2) { _player.seekTo(0, true); }   // past the end → loop the mix
            else { _player.seekTo(t, true); }
            if (!_playing) _play();
            _setStatus('Skipped ~' + Math.round(SKIP_SECONDS / 60) + ' min ahead');
        } catch (e) {}
    }

    function _setVolume(v) {
        _volume = Math.max(0, Math.min(100, parseInt(v, 10) || 0));
        localStorage.setItem('lofi_volume', _volume);
        if (_player) { try { _player.setVolume(_volume); } catch (e) {} }
    }

    // ─── sleep timer ─────────────────────────────────────────────────
    function _setSleep(min) {
        if (_sleepTimer) { clearTimeout(_sleepTimer); _sleepTimer = null; }
        if (_sleepTick)  { clearInterval(_sleepTick); _sleepTick = null; }
        _sleepMin = min;
        if (min > 0) {
            _sleepDeadline = Date.now() + min * 60000;
            _sleepTimer = setTimeout(function () {
                _pause(); _setSleep(0); _setStatus('Sleep timer ended — music stopped.');
            }, min * 60000);
            _sleepTick = setInterval(_updateSleepLabel, 1000);
        }
        _syncUI();
        _updateSleepLabel();
    }

    // ─── UI (popover anchored to the sidebar "Lo-fi Music" item) ──────
    function _buildPopover() {
        if (document.getElementById('lofi-popover')) return;
        var pop = document.createElement('div');
        pop.id = 'lofi-popover';
        pop.style.cssText = 'position:fixed;z-index:1000020;width:300px;max-width:calc(100vw - 24px);background:rgba(12,14,24,0.98);border:1px solid rgba(108,92,231,0.5);border-radius:16px;box-shadow:0 16px 50px rgba(0,0,0,0.7);backdrop-filter:blur(16px);display:none;overflow:hidden;';
        pop.innerHTML =
            '<div style="display:flex;justify-content:space-between;align-items:center;padding:13px 16px;border-bottom:1px solid var(--glass-border);">'
          +   '<span style="color:#a29bfe;font-size:0.78rem;font-weight:700;letter-spacing:1px;text-transform:uppercase;"><i class="ph-fill ph-music-notes"></i> Lo-fi Player</span>'
          +   '<button onclick="closeLofiPlayer()" style="background:none;border:none;color:var(--text-muted);cursor:pointer;font-size:1rem;padding:2px;line-height:1;"><i class="ph ph-x"></i></button>'
          + '</div>'
          + '<div style="padding:14px 16px;">'
          +   '<div style="display:flex;align-items:center;gap:12px;margin-bottom:14px;">'
          +     '<div style="width:52px;height:52px;flex-shrink:0;border-radius:12px;background:linear-gradient(135deg,#6C5CE7,#00CEC9);display:flex;align-items:center;justify-content:center;box-shadow:0 6px 20px rgba(108,92,231,0.45);"><i class="ph ph-vinyl-record" id="lofi-disc" style="font-size:1.7rem;color:white;"></i></div>'
          +     '<div style="min-width:0;flex:1;">'
          +       '<div id="lofi-np-name" style="color:white;font-size:0.95rem;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"></div>'
          +       '<div id="lofi-np-genre" style="color:var(--text-muted);font-size:0.76rem;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"></div>'
          +       '<div id="lofi-status" style="color:#fdcb6e;font-size:0.72rem;margin-top:3px;min-height:1em;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;"></div>'
          +     '</div>'
          +   '</div>'
          +   '<div style="display:flex;align-items:center;justify-content:center;gap:14px;margin-bottom:10px;">'
          +     '<button onclick="window._lofiPrev()" title="Previous station" style="background:rgba(255,255,255,0.06);border:none;color:white;width:38px;height:38px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:1rem;"><i class="ph ph-skip-back"></i></button>'
          +     '<button id="lofi-play-btn" onclick="window._lofiTogglePlay()" style="background:linear-gradient(135deg,#6C5CE7,#00CEC9);border:none;color:white;width:50px;height:50px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:1.4rem;box-shadow:0 6px 18px rgba(108,92,231,0.5);"><i class="ph ph-play"></i></button>'
          +     '<button onclick="window._lofiNext()" title="Next station" style="background:rgba(255,255,255,0.06);border:none;color:white;width:38px;height:38px;border-radius:50%;cursor:pointer;display:flex;align-items:center;justify-content:center;font-size:1rem;"><i class="ph ph-skip-forward"></i></button>'
          +   '</div>'
          +   '<button onclick="window._lofiSkip()" title="Jump ~2 min ahead to the next song in this mix" style="width:100%;background:rgba(255,255,255,0.05);border:1px solid var(--glass-border);color:#a29bfe;border-radius:9px;padding:8px;cursor:pointer;font-size:0.8rem;font-weight:600;display:flex;align-items:center;justify-content:center;gap:6px;margin-bottom:16px;"><i class="ph ph-fast-forward"></i> Skip song</button>'
          +   '<div style="display:flex;align-items:center;gap:8px;margin-bottom:16px;">'
          +     '<i class="ph ph-speaker-low" style="color:var(--text-muted);font-size:0.9rem;"></i>'
          +     '<input id="lofi-volume" type="range" min="0" max="100" value="' + _volume + '" oninput="window._lofiVol(this.value)" style="flex:1;accent-color:#6C5CE7;cursor:pointer;">'
          +     '<i class="ph ph-speaker-high" style="color:var(--text-muted);font-size:0.9rem;"></i>'
          +   '</div>'
          +   '<div style="margin-bottom:14px;">'
          +     '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:7px;"><span style="color:var(--text-muted);font-size:0.72rem;font-weight:600;letter-spacing:0.5px;"><i class="ph ph-moon-stars"></i> SLEEP</span><span id="lofi-sleep-label" style="color:#a29bfe;font-size:0.72rem;"></span></div>'
          +     '<div id="lofi-sleep-row" style="display:flex;gap:5px;">'
          +       '<button data-min="0"  onclick="window._lofiSleep(0)"  class="lofi-sleep-btn" style="flex:1;">Off</button>'
          +       '<button data-min="25" onclick="window._lofiSleep(25)" class="lofi-sleep-btn" style="flex:1;">25m</button>'
          +       '<button data-min="45" onclick="window._lofiSleep(45)" class="lofi-sleep-btn" style="flex:1;">45m</button>'
          +       '<button data-min="60" onclick="window._lofiSleep(60)" class="lofi-sleep-btn" style="flex:1;">60m</button>'
          +     '</div>'
          +   '</div>'
          +   '<div style="color:var(--text-muted);font-size:0.72rem;font-weight:600;letter-spacing:0.5px;margin-bottom:7px;"><i class="ph ph-playlist"></i> STATIONS</div>'
          +   '<div id="lofi-station-list" style="display:flex;flex-direction:column;gap:5px;max-height:150px;overflow-y:auto;"></div>'
          + '</div>';
        document.body.appendChild(pop);

        // sleep-button + station-row styling injected once
        if (!document.getElementById('lofi-style')) {
            var st = document.createElement('style');
            st.id = 'lofi-style';
            st.textContent =
                '.lofi-sleep-btn{background:rgba(255,255,255,0.06);border:1px solid var(--glass-border);color:var(--text-muted);border-radius:7px;padding:6px 0;cursor:pointer;font-size:0.76rem;transition:all .15s;}'
              + '.lofi-sleep-btn:hover{border-color:rgba(108,92,231,0.6);color:white;}'
              + '.lofi-sleep-btn.active{background:linear-gradient(135deg,#6C5CE7,#00CEC9);border-color:transparent;color:white;}'
              + '.lofi-station-row{display:flex;align-items:center;gap:9px;padding:8px 10px;border-radius:9px;border:1px solid var(--glass-border);background:rgba(255,255,255,0.03);cursor:pointer;transition:all .15s;}'
              + '.lofi-station-row:hover{border-color:rgba(108,92,231,0.6);background:rgba(108,92,231,0.08);}'
              + '.lofi-station-row.active{border-color:#6C5CE7;background:rgba(108,92,231,0.15);}'
              + '#lofi-disc.spin{animation:spin 4s linear infinite;}';
            document.head.appendChild(st);
        }
        _renderStations();
        _syncUI();
    }

    // Anchor the popover next to the sidebar "Lo-fi Music" item, popping upward.
    function _positionPopover() {
        var pop = document.getElementById('lofi-popover');
        if (!pop || pop.style.display === 'none') return;
        var pw = pop.offsetWidth, ph = pop.offsetHeight;
        var item = document.getElementById('lofi-menu-item');
        var left, top;
        if (item) {
            var r = item.getBoundingClientRect();
            left = r.right + 10;                 // to the right of the sidebar
            top  = r.bottom - ph;                // align bottoms (grows upward)
            if (left + pw > window.innerWidth - 8) left = r.left - pw - 10; // flip if no room
        } else {
            left = 16; top = window.innerHeight - ph - 80;
        }
        if (left < 8) left = 8;
        if (top < 8) top = 8;
        if (top + ph > window.innerHeight - 8) top = window.innerHeight - ph - 8;
        pop.style.left = left + 'px';
        pop.style.top = top + 'px';
        pop.style.bottom = 'auto';
    }

    function _renderStations() {
        var list = document.getElementById('lofi-station-list');
        if (!list) return;
        list.innerHTML = LOFI_STATIONS.map(function (s, i) {
            return '<div class="lofi-station-row' + (i === _station ? ' active' : '') + '" onclick="window._lofiPick(' + i + ')">'
                 +   '<i class="ph ' + (i === _station && _playing ? 'ph-speaker-high' : 'ph-music-note') + '" style="color:#a29bfe;font-size:1.1rem;"></i>'
                 +   '<div style="flex:1;"><div style="color:white;font-size:0.9rem;font-weight:600;">' + s.name + '</div>'
                 +     '<div style="color:var(--text-muted);font-size:0.74rem;">' + s.genre + '</div></div>'
                 +   (i === _station ? '<i class="ph ph-check-circle" style="color:#00CEC9;"></i>' : '')
                 + '</div>';
        }).join('');
    }

    function _setStatus(msg) {
        var el = document.getElementById('lofi-status');
        if (el) el.textContent = msg || '';
    }

    function _updateSleepLabel() {
        var el = document.getElementById('lofi-sleep-label');
        if (!el) return;
        if (_sleepMin <= 0) { el.textContent = ''; return; }
        var left = Math.max(0, _sleepDeadline - Date.now());
        var m = Math.floor(left / 60000), s = Math.floor((left % 60000) / 1000);
        el.textContent = m + ':' + (s < 10 ? '0' : '') + s + ' left';
    }

    function _syncUI() {
        var name = document.getElementById('lofi-np-name');
        var genre = document.getElementById('lofi-np-genre');
        var btn = document.getElementById('lofi-play-btn');
        var disc = document.getElementById('lofi-disc');
        if (name)  name.textContent = LOFI_STATIONS[_station].name;
        if (genre) genre.textContent = LOFI_STATIONS[_station].genre;
        if (btn)   btn.innerHTML = _playing ? '<i class="ph ph-pause"></i>' : '<i class="ph ph-play"></i>';
        if (disc)  disc.className = 'ph ph-vinyl-record' + (_playing ? ' spin' : '');
        var vol = document.getElementById('lofi-volume');
        if (vol && document.activeElement !== vol) vol.value = _volume;
        var rows = document.querySelectorAll('.lofi-sleep-btn');
        rows.forEach(function (b) { b.classList.toggle('active', parseInt(b.getAttribute('data-min'), 10) === _sleepMin); });
        _renderStations();
        if (_playing) _setStatus('');
    }

    // ─── public API ──────────────────────────────────────────────────
    var _popOpen = false;
    function _onDocClick(e) {
        var pop = document.getElementById('lofi-popover');
        var item = document.getElementById('lofi-menu-item');
        if (!pop) return;
        if (pop.contains(e.target)) return;          // click inside the player
        if (item && item.contains(e.target)) return; // the sidebar item handles its own toggle
        window.closeLofiPlayer();
    }
    window.openLofiPlayer = function () {
        _buildPopover();
        var pop = document.getElementById('lofi-popover');
        if (pop) pop.style.display = 'block';
        _popOpen = true;
        _positionPopover();
        _syncUI();
        _updateSleepLabel();
        setTimeout(function () { document.addEventListener('click', _onDocClick, true); }, 0);
        window.addEventListener('resize', _positionPopover);
    };
    window.closeLofiPlayer = function () {
        var pop = document.getElementById('lofi-popover');
        if (pop) pop.style.display = 'none'; // music keeps playing — host lives on <body>
        _popOpen = false;
        document.removeEventListener('click', _onDocClick, true);
        window.removeEventListener('resize', _positionPopover);
    };
    window.toggleLofiPlayer = function () {
        if (_popOpen) window.closeLofiPlayer();
        else window.openLofiPlayer();
    };

    window._lofiTogglePlay = _toggle;
    window._lofiPrev = _prev;
    window._lofiNext = _next;
    window._lofiSkip = _skipSong;
    window._lofiPick = _pick;
    window._lofiVol = _setVolume;
    window._lofiSleep = _setSleep;
})();

// ─── Companion personality dropdown init ────────────────────────────
document.addEventListener('DOMContentLoaded', function() {
    setTimeout(function() {
        var sel = document.getElementById('companion-personality-select');
        if (sel) {
            sel.value = localStorage.getItem('companion_personality') || 'default';
            sel.addEventListener('change', function() {
                localStorage.setItem('companion_personality', this.value);
                if (typeof showToast === 'function') showToast('Companion personality updated!', 'success');
            });
        }
    }, 800);
});

